    \includegraphics[width=0.9\linewidth]{p3.pdf}
    \caption{A unit interval graph consisting of $6$ vertices}\vspace{-0.1in}
    \label{fig:pic3}
\end{figure}

\subsection{Dynamic programming algorithm}
{\bf Preprocessing:} We sort the end-points of the intervals in the set $\cal I$, and name the intervals as $v_i=[a_i,b_i]$, $i=1,\dots,n$, according to the increasing order of their right end-points. For each interval $v_i=[a_i,b_i]$, we store the following information: 
\begin{enumerate}
    \item $x(i)=$ Number of $b_j$'s ($j\neq i$) between $a_i$ and $b_i$,
    \item $y(i)=$ Number of $a_j$'s ($j\neq i$) between $a_i$ and $b_i$, 
    \item $z(i)=$ Number of $a_j$'s ($j\neq i$) between $b_{i-1}$ and $b_i$,
    \item $r_a(i)= max\{a_j| a_i\leq a_j<b_i\}$, and
    \item $r_b(i)= b_j$, where $j$ is such that $r_a(i)=a_j$.
\end{enumerate}


{\bf Algorithm:} For a fixed $b_i$, $i\in\{1,\dots,n\}$, and a fixed integer $\ell$ ($\ell\leq k)$, let us define three functions $f$, $g$ and $h$ as follows,
\begin{itemize}
    \item[$\bullet$] $f(b_i,\ell) = \max \{|N[S_\ell]|: S_\ell\subseteq\{v_1,\dots, v_i\}, |S_\ell|=\ell, v_i\in S_\ell$\} (* max dominated {\em nbd} size of an $\ell$-set $S_\ell$, where $S_\ell\subseteq\{v_1,\dots,v_i\}$ and $v_i\in S_\ell$ *), 
    \item[$\bullet$] $g(b_i,\ell)= \max \{ |N[S_\ell]|: S_\ell\subseteq\{v_1,\dots, v_i\}, |S_\ell|=\ell, v_i\notin S_\ell, v_i\in N[S_\ell ]$\} (* max dominated {\em nbd} size of an $\ell$-set $S_\ell\subseteq\{v_1,\dots,v_i\}$, when $v_i\not\in S_\ell$, $v_i\in N[S_\ell]$ *), 
    \item[$\bullet$] $h(b_i,\ell)= \max \{ |N[S_\ell]|: S_\ell\subseteq\{v_1,\dots, v_i\}, |S_\ell|=\ell, v_i\notin S_\ell, v_i\notin N[S_\ell]$\}  (* max dominated {\em nbd} size of an $\ell$-set $S_\ell\subseteq\{v_1,\dots,v_i\}$, when $v_i\not\in S_\ell$, $v_i\not\in N[S_\ell]$ *).
\end{itemize}

The maximum dominated neighborhood size ({\em nbd size}) of a $k$-set is \\
$\max\{f(b_n,k),g(b_n,k),h(b_n,k)\}$.

We find the values of the functions $f$, $g$, and $h$ recursively using dynamic programming. We initialize these functions for $b_1$ as 

\begin{itemize}
\item[$\bullet$] $f(b_1,1)=1+y(1)$ and $f(b_1,j)=-\infty$ for $j=0,2,3, \ldots, k$. 
\item[$\bullet$] $g(b_1,j)=-\infty$ for all $j=0,1,2,3, \ldots, k$.
\item[$\bullet$]  $h(b_1,0)=0$ and $h(b_1,j)=-\infty$ for $j=1,2,3, \ldots, k$.
\end{itemize}
We process $b_i$, $i=1,2,\ldots, n$ in this order. For each $b_i$, we compute $f(b_i,l)$, $g(b_i,l)$ and $h(b_i,l)$, for $l=0,1,2,\ldots, k$, and proceed to compute the $f,g,h$ functions for $b_{i+1}$. For each $b_i$, $f(b_i,0)=g(b_i,0)=-\infty$ (since these are undefined), and $h(b_i,0)=0$. Also, for each $b_i$, we set $f(b_i,1)=1+y(i)+x(i)$. The recursive formulae for finding the values of the functions $f$, $g$, and $h$ are stated below.    
\begin{itemize}
\item[$\bullet$] $f(b_i,l)= \max\{ T_1,T_2,T_3\}$, where
    $$T_1=1+\max_{\forall b_j<a_i, r_b(j)<a_i}\{(f(b_j,l-1)+y(i)+x(i))\}$$
    $$T_2=1+\max_{\forall b_j<a_i, r_b(j)=b_\lambda>a_i}\{f(b_j, l-1)+y(i)+ i-1-\lambda \}$$
    $$T_3=\max_{\forall b_j \in (a_i,b_i)} \{f(b_j,l-1)+z(j+1)+z(j+2)+\ldots +z(i-1)+z(i)\}$$ 
\item[$\bullet$] $g(b_i,l)= \max_{\forall b_j \in (a_i,b_i)} \{f(b_j,l)\}$  
\item[$\bullet$] $h(b_i,l)= \max_{\forall b_j<a_i} \{f(b_j,l)\}$ 
\end{itemize}

Note that, if there does not exist any $b_j\in(a_i,b_i)$ in the recursion formula of $g(b_i,l)$, then the value of $g(b_i,l)=-\infty$ is set, where $l\in\{1,2,\dots ,k\}$. Similarly, when there does not exist any $b_j$ satisfying $b_j<a_i$ in the recursion formula of $h(b_i,l)$, then $h(b_i,l)=-\infty$ is set.

{\bf Justifications of the formulae:}

$\mathbf{f(b_i,l)}$: For the function $f$, the interval $v_i$ is to be chosen, so we have the following three possibilities,

\begin{itemize}
    \item $\mathbf{T_1}$: In this case, $v_i$ is not already dominated by the last chosen vertex $v_j$, so 1 is added. Here, additionally, because $r(b_j)<a_i$, we have to add $x(i)$ (number of intervals that ends in $[a_i,b_i]$) and $y(i)$ (number of intervals that starts in $[a_i,b_i]$), which are not dominated by any other previously chosen interval. 

    \item $\mathbf{T_2}$: Here also, $v_i$ was not dominated by $v_j$, so 1 is added. Now, since $r(b_j)=b_\lambda \in (a_i,b_i)$, choosing $v_i$ will newly dominate $y(i)$ (number of intervals that starts in $[a_i,b_i]$), and $(i-1-\lambda)$  (the number of intervals that ends in $(b_\lambda,b_i)$) nodes, which are not dominated by the previous chosen interval $v_j=[a_j,b_j]$. 

\item $\mathbf{T_3}$:  Here, the endpoint $b_j$ of the last chosen interval $v_j$, lies in $[a_i,b_i]$; thus, $v_i$ is already dominated by $v_j$. So unlike $T_1$ and $T_2$, $1$ is not added. As $a_j<a_i$, whatever end-points and start-points exist inside $[a_i,b_j]$, their corresponding intervals are already dominated and have been counted in $f(b_j,l-1)$. So, we need to consider the part $[b_j,b_i]$. In between $b_j$ and $b_i$, the only possible endpoints are $b_{j+1},b_{j+2},\dots,b_{i-1},b_{i}$. But their start points are between $a_j$ and $a_i$. So, they are already dominated by the interval $[a_j, b_j]$ and have been counted before. So, we only need to add the number of intervals having their start point between $b_j$ and $b_i$, which are $z(j+1)+z(j+2)+\dots+z(i-1)+z(i)$. This is because they overlapped with $v_i$ and had not been counted yet. 
\end{itemize}


$\mathbf{g(b_i,l)}$: In this case, the interval $v_i$ is not chosen but was already dominated by a previously chosen interval $v_j$. It is indicated by $b_j$'s range in the $\max$ operation.

$\mathbf{h(b_i,l)}$: The interval $v_i$ is neither chosen nor was dominated by any previously chosen interval $v_j$, and the range of $b_j$ indicates this in the $\max$ operation of the recursion formula. 



\subsection{Processing, correctness and complexity results} 

During the preprocessing, after sorting, we compute $x(i)$, $y(i)$, $z(i)$, $r_a(i)$ and $r_b(i)$ by processing the end-points of the intervals in $\cal I$ in left to right order. We conceptually maintain a queue $Q$ for storing the processed subset of left end-points of the intervals whose right end-points are not yet processed. Practically, we maintain three scalar variables, $Q\_count$ (size of $Q$), $Q\_max$ (maximum element in $Q$), and $Q^r\_max$ (the right-end point of the interval corresponding to $Q\_max$). While processing a left-end point, say $a_j$, we add 1 to $Q\_count$, store $a_j$ in $Q\_max$, and its corresponding $b_j$ in $Q^r\_max$. When a right-end point $b_i$ of an interval $v_i$ is faced, its corresponding left-end point is the first element of $Q$ (as all the intervals are of unit length); it is deleted, or equivalently, $1$ is subtracted from $Q\_count$. Note that, $y(i)$ is the size of $Q$ at this instant and $r_a(i)$ is the maximum element in $Q$; thus we set $y(i)=Q\_count$, $r_a(i)=Q\_max$, and $r_b(i)=Q^r\_max$. If at this instant, $Q$ is empty queue, then set $r_a(i)=a_i$ and $r_b(i)=b_i$. The $z(i)$ values are also computed in the same left-to-right scan by maintaining another scalar variable $z\_count$.  Another right-to-left scan is needed to compute $x(i)$ values for each interval $v_i\in \cal I$. Thus, the preprocessing time complexity is $O(n\log n)$ using $O(1)$ extra space. In dynamic programming, $T_1,T_2$ and $T_3$ are computed as follows: 

\begin{itemize}

\item While computing $f(b_i,l)$, note that $r_b(i) \geq b_i$ for all $i$. Thus, $T_1=1+y(i)+x(i)+\max_{\forall r_b(j)<a_i}f(b_j,l-1) = 1+y(i)+x(i)+T_1'$ (say). We maintain a leaf search height-balanced binary tree $D_1$ on $\{r_b(j), j=1,2,\ldots, n\}$, where each leaf is associated with $f(b_j,l-1)$, and each internal node associated with the maximum of the $f(.,l-1)$ values in the subtree rooted at that node. Thus, we can compute $T_1'=\max_{\forall r_b(j)<a_i}f(b_j,l-1)$ in $O(\log n)$ time using $D_1$. 


\item For computing $T_2$, we need to compute $T_2'=\max_{\forall b_j<a_i, a_i<r_b(j)=b_{\lambda}<b_i}(f(b_j, l-1)-\lambda)$, where $b_\lambda=r_b(j)$. Again, maintaining a similar leaf search height-balanced binary tree $D_2$ on $\{r_b(j),j=1,2,\ldots, n\}$ with each leaf node associated with $(f(b_j,l-1)-\lambda)$, and each internal node associated with the maximum of the $(f(.,l-1)-\lambda)$ values in the subtree rooted at that node, one can compute $T_2'$ in $O(\log n)$ time. Now, $T_2=1+y(i)+i-1+T_2'$ is computed using $T_2'$, obtained earlier. 


\item For computing $T_3$, we use a $D_3$ data structure, which is a height-balanced leaf-search binary tree on $\{b_j, j=1,2,\ldots, n\}$, whose each leaf $b_\alpha$ contains $val_\alpha=f(b_\alpha,l-1) +n_\alpha$, where $n_\alpha$ = number of start-points in the interval $[b_\alpha,b_i]$. Each internal node whose sub-tree contains leaves $\{b_\alpha, \ldots ,b_\beta\}$ represents a $\max$-field containing the maximum of $\{val_\alpha, \ldots, val_\beta\}$. Now, the $T_3$ value for $b_i$ is obtained by searching the $D_3$ data structure for all $b_j$ satisfying $a_i<b_j<b_i$. This also can be done in $O(\log n)$ time. 

\end{itemize}

Thus, the computation of $f(b_i,l)=\max\{T_1, T_2, T_3\}$ needs $O(\log n)$ time using three data structures, each of size $O(n)$, and can be created in $O(n\log n)$ time.  Similarly, $g(b_i,l)$ and $h(b_i,l)$ can also be computed in $O(\log n)$ time using a $O(n)$ size data structure which can be built in $O(n\log n)$ time. Thus, 
\begin{theorem}
The maximum dominating $k$-set problem algorithm for unit interval graphs runs in $O(nk\log n)$ time using data structures of size $O(n)$. 
\end{theorem}

\section{Algorithm for general interval graph}\label{arbint}

Now, we relax the unit-interval assumption. Here, a pair of overlapping intervals in $\cal I$ may either properly overlap or one interval properly contains the other one. We first execute a preprocessing phase based on the following observation.

\begin{observation}
Let $v_i, v_j\in V$ be two vertices in $G$ such that, in $\cal I$,  the interval corresponding to $v_i$ is completely contained in the interval corresponding to $v_j$. Here, if there exists an optimum solution $S_{opt}$ of the maximum dominating $k$-set problem with $v_i\in S_{opt}$ then there exists another optimum solution $S_{opt}'$ of that problem with $v_j\in S_{opt}'$ and $|S_{opt}|=|S_{opt}'|$.    
\end{observation}

\begin{figure}[ht]
    \centering
    \includegraphics[width=0.9\linewidth]{p4.pdf}
    \caption{Here, $[a_1,b_1],[a_2,b_2],[a_3,b_3]$ and $[a_4,b_4]$ are non-deleted intervals, and the rest are marked as deleted intervals. All these intervals lie on the real line (dashed line), but they have been drawn in the two-dimensional plane for visual clarity.}
    \label{fig:pic4}
\end{figure}


Thus, we execute a linear pass to identify the intervals of $\cal I$ which are contained in at least one other interval of $\cal I$. These intervals are marked as deleted (see the intervals drawn with thin lines in Figure \ref{fig:pic4}).

Observe that the graph corresponding to the non-deleted intervals can be represented as a unit interval graph. Thus, we interchangeably use the terms unit interval layout and properly overlapping interval layout.
During this processing, for each non-deleted interval $v_i=[a_i,b_i]$, $i\in\{1,2,\dots ,m\}$ $(m\leq |V|=n)$, we also compute the following information: 

$x_d(i)=$ Number of deleted intervals with only right-end point  in $[a_i,b_i]$,\\
$y_d(i)=$ Number of deleted intervals with only left-end point in $[a_i,b_i]$, \\
$w_d(i)=$ Number of deleted intervals with both the end points in $[a_i,b_i]$.


Also, for each pair of intervals $v_i$ and $v_j$, we find and store $c_d(i,j)=$ number of deleted intervals dominated by both $v_i$ and $v_j$. 


From now onwards, we use $\cal I'$ to denote the undeleted intervals. The end-points of the members in $\cal I$ are stored in a sorted list $\cal L$, where each end-point of an interval $I\in \cal I$ points to its other end-point in $\cal L$. We execute a linear pass among the members in $\cal L$. During this execution, we maintain a balanced leaf-search binary tree $\cal T$. When the left-end point of a member of $\cal I$ is processed, it is inserted in $\cal T$. When the right-end point $b$ of an interval $I=[a,b]$ is processed, we search $a$ in $\cal T$. If at least one entry to the left of $a$ in $\cal T$ exists, then $I$ is fully contained in that interval; $I$ is marked deleted and $a$ is deleted from $\cal T$. 
Thus, in $O(n\log n)$ time we can compute the set ${\cal I}'$ of properly overlapped intervals in the set $\cal I$. The set ${\cal I}\setminus {\cal I}'$ is the set of deleted intervals, which will not be considered in our dynamic programming algorithm for computing the maximum dominating $k$-set. To compute the values of the parameters defined earlier, we create a 2D range tree $\cal R$, whose each element is a 2D point $(\alpha,\beta)$, which corresponds to the two end-points of a deleted interval $[\alpha,\beta]$ ($\in {\cal I}\setminus {\cal I}'$). We consider each interval $I_i=[a_i,b_i] \in {\cal I}'$. Here, (i) $x_d(i)$ = number of $\beta$-points lying in $I_i$ whose $\alpha$-point does not lie in $I_i$, (ii) $y_d(i)$ =  number of $\alpha$-points lying in $I_i$ whose $\beta$-point does not lie in $I_i$, and (iii) $w_d(i)$ = number of points whose both $\alpha$ and $\beta$ values lie in $I_i$. All these three numbers can be computed in $O(\log^2n)$ time.

To compute $c_d(i,j)$, for $v_i,v_j \in {\cal I}'$, we create a bipartite graph $B({\cal I}\setminus {\cal I}', {\cal I}')$. While computing $x_d(i)$, $y_d(i)$ and $w_d(i)$, we have already identified the deleted intervals in ${\cal I}\setminus {\cal I}'$ that are dominated by each interval $I_i \in {\cal I}'$. Those edges are put in the graph $B$. At the end of this processing, we observe each node $u_\theta\in {\cal I}\setminus {\cal I}'$, and add 1 to each cell $c_d(i,j)$ such that $u_\theta$ is adjacent to $v_i,v_j \in {\cal I}'$ (if any such pair exists). Thus, the worst-case time complexity of computing the graph $B$ is $O(n^2)$, and computing $c_d(i,j), v_i,v_j \in {\cal I}'$ is also $O(n^2)$. 

Note that the $m$ intervals of ${\cal I}'$ are properly overlapping intervals. So, this set of $m$ intervals behaves as unit intervals, and computing the functions $x(i)$, $y(i)$, and $r_b(i)$ for $i=1,2,\dots,m$ is as in the previous section. 
Also, the definitions of the functions $f$, $g$, and $h$ remain the same as in the previous section; their recursive formulae are given below. Finally, the maximum dominated neighborhood size of a $k$-set is computed as $\max\{ f(b_m,k),g(b_m,k),h(b_m,k)\}$.

{\bf{Initialization:}} The values of the three functions for $b_1 \in {\cal I}'$ are as follows,

\begin{itemize}
\item[$\bullet$] $f(b_1,1)=1+y(1)+x_d(1)+y_d(1)+w_d(1)$ and $f(b_1,j)=-\infty$ for $j \neq 1$,
\item[$\bullet$] $g(b_1,j)=-\infty$ for all $j=0,1,\ldots, k$, and
\item[$\bullet$] $h(b_1,0)=0$ and $h(b_1,j)=-\infty$ for $j=1,2,\ldots, k$.
\end{itemize}


Also, we have $f(b_i,0)=-\infty$, $g(b_i,0)=-\infty$ and $h(b_i,0)=0$ for all $i\in \{1,2,\dots,m\}$. For all $b_i$, $f(b_i,1)=1+y(i)+x(i)+x_d(i)+y_d(i)+w_d(i)$ is also set in this initialization step.

{\bf{Recursive formulas:}} 

Recursive formulas for finding the values of the functions $f$, $g$, and $h$ are as follows, which are minor tailoring of the formulae presented for unit intervals, and the justification of the tailoring is also mentioned.

\begin{itemize}
\item[$\bullet$] $f(b_i,l)=\max\{T_1, T_2, T_3\}$, where\\
    $T_1=1+\max_{b_j<a_i, r_b(j)<a_i} \{f(b_j,l-1)+y(i)+x(i)+x_d(i)+y_d(i)+w_d(i)-c_d(i,j)\}$, \\
    $T_2= 1+\max_{b_j<a_i, r_b(j)=b_{\lambda}>a_i}\{f(b_j, l-1)+y(i)+i-1-\lambda+x_d(i)+y_d(i)+w_d(i)-c_d(i,j)\}$, and \\
    $T_3=\max_{a_i<b_j<b_i} \{f(b_j,l-1)+z(j+1)+z(j+2)+\dots +z(i-1)+z(i)+x_d(i)+y_d(i)+w_d(i)-c_d(i,j)\}$,\\
\item[$\bullet$] $g(b_i,l)= \max_{a_i<b_j<b_i}\{f(b_j,l)\}$,\\
\item[$\bullet$] $h(b_i,l)= \max_{b_j<a_i}\{f(b_j,l)\}$.
\end{itemize}

If there does not exist any $b_j\in(a_i,b_i)$ in the recursive formula of $g(b_i,l)$, then $g(b_i,l)=-\infty$ is set, where $l\in\{1,2,\dots ,k\}$. Also, when no $b_j$ with $b_j<a_i$ exists in the recursive formula of $h(b_i,l)$, then $h(b_i,l)=-\infty$, where $l\in\{1,2,\dots ,k\}$.

{\bf{Justification of the recursive formulas:}}

When we consider the $m$ non-deleted intervals, which are dominated by the chosen $l$-set, the recursive formulae will be the same as those of the unit interval graph on those $m$ intervals. Below, we show that the count of the dominated deleted intervals by a chosen $l$-set is correct.


As the interval $v_i\in {\cal I}'$ is included in the chosen $l$-set, the number of deleted intervals dominated by  $v_i$ is $x_d(i)+y_d(i)+w_d(i)$; among them $c_d(i,j)$ = number of deleted intervals which are already dominated by the last included interval $v_j=[a_j,b_j]\in {\cal I}'$, was previously counted in $f(b_j,l-1)$. Hence, we added $x_d(i)+y_d(i)+w_d(i)-c_d(i,j)$ in the recursion formula of $f(b_i,l)$, which is precisely the number of newly dominated deleted intervals by $v_i$.


For the functions $g$ and $h$, the $i$-th interval is not included in the $l$-set while processing. Hence, no new deleted interval is dominated. 
Thus, the $O(n^2)$ time preprocessing leads to the following result.

\begin{theorem}
The time complexity for computing the maximum dominating $k$-set problem for the intersection graph of a set of arbitrary intervals is $O(n^2k)$. 
\end{theorem}



\section{Unit square intersection graph where a straight line intersects each square} \label{square}
The partial domination problem is NP-hard for axis-parallel unit square intersection graphs, since the minimum dominating set problem is NP-hard in this class. So, we will explore a special subclass of this class.

Consider the intersection graph of a given set $S=\{s_1,s_2,\dots,s_n \}$ of axis parallel unit squares in $I\!\!R^2$, where all the members of $S$ are intersected by the straight line $L: y=mx+c$, that makes an angle $\theta$ with the positive $x$-axis (i.e., $m=\tan\theta$), where $0\degree \leq \theta\leq 45\degree$. The objective is to compute the maximum dominating $k$-set for the intersection graph of members of $S$. 

\begin{figure}[ht]
    \centering
    \includegraphics[width=0.9\linewidth]{p5.pdf}
    \caption{Here, the width of the required strip is $2AC$.}
    \label{fig:pic5}
\end{figure}

\begin{observation}\label{obx1}
    If $T$ is a strip (region bounded by two parallel lines) which is divided into two equal-width strips by the line $L$, and centers of all the squares in $S$ lie inside $T$, then the minimum width of $T$ is $\sqrt{2}\sin(45\degree+\theta)$,
\end{observation}

\begin{proof}
    Consider Figure \ref{fig:pic5}. Since the input squares are unit squares, we have $AB=\frac{1}{\sqrt{2}}$.

    Now, $\angle CBD=\theta$ and $\angle ABE=45\degree$; implying 
    $\angle ABC=45\degree+\theta$.

     As $\sin (45\degree+\theta)=\sin\angle ABC=\frac{AC}{AB}=\sqrt{2}AC$, we have $AC=\frac{\sin(45\degree+\theta)}{\sqrt{2}}$.

    $\therefore$ Width of the strip  $=2\cdot\frac{\sin(45\degree+\theta)}{\sqrt{2}}=\sqrt{2}\sin(45\degree+\theta)$.
\end{proof}

Since the members in $S$ are axis-parallel and intersected by $L$, here a pair of unit squares in $S$ intersect if and only if they have at least one intersection point inside the strip $T$ of width $\sqrt{2}\sin(45\degree+\theta)$ (see Observation \ref{obx1}).

We now divide the strip $T$ into square-sized boxes of side-length $\sqrt{2}\sin(45\degree+\theta)$ (see Figure \ref{fig:pic6}). As the members in $S$ are unit squares, each $s_i\in S$ may have a non-empty intersection with at most two consecutive boxes in $T$. Thus, at most $2n$ boxes may contain some portion of the squares in $S$. Let us denote these boxes as $T_1, T_2, \dots, T_m$ ($m\leq 2n$). We use $S_i(\subseteq S)$ to denote the squares whose centers lie in $T_i$.  

\begin{figure}[ht]
    \centering
    \includegraphics[width=0.9\linewidth]{p6.pdf}
    \caption{Demonstration of the problem}
    \label{fig:pic6}
\end{figure}

\begin{result} \label{rr} \cite{new1} 
For each $i \in \{1,2,\dots,m\}$, (a) there exists at most $4$ squares of $S$ which can dominate all the squares whose centers lie in $T_i$, and (b) the minimum number of members in $S$ that are needed to dominate all the squares intersecting the box $T_i$ is at most $12$.
\end{result}

Result \ref{rr}(a) leads to the following lemma, which determines the time complexity of our algorithm for the maximum dominating $k$-set problem for $S$.  

\begin{lemma}\label{LLL}
There exists a maximum dominating $k$-set, say $OPT$, where each box $T_i$ contains the centers of at most $11$ members of $OPT$. 
\end{lemma}

\begin{proof}[By contradiction]
Let $OPT$ be an optimum solution to the said problem with at least one box in $T$ having the centers of more than $11$ squares of $OPT$. Let $T_j$ ($j\geq 1$) be the leftmost among such boxes containing the centers of the squares $O_{j} \subseteq OPT$, $|O_j|\geq 12$ (here, $O_j=S_j\cap OPT$). By Result \ref{rr}(a), we can replace/choose at most $4$ squares which can dominate all the squares with center inside $T_j$. Thus, the remaining at least $8$ squares in $O_j$ are used to dominate squares centered inside $T_{j-1} \cup T_{j+1}$.
By Result \ref{rr}(a), instead of these remaining squares of $O_j$, we can take $4$ squares from $S_{j-1}$ and $4$ from $S_{j+1}$ to dominate all the squares centered in $T_{j-1} \cup T_{j+1}$. Also, by pigeonhole principle, among the remaining at least $8$ squares in $O_j$, at least $4$ will contribute in dominating elements of $S_{j-1}$ (or $S_{j+1}$).

Without loss of generality, assume that $O_j'\subseteq O_j$ ($|O_j'|\geq 4$) is used to dominate the squares in $S_{j-1}$. We delete $O_j'$ from $OPT$, and add at most $4$ squares, say $O_j''$ from $S_{j-1}$, centered at four sub-boxes of $T_{j-1}$, in $OPT$ to dominate all the squares in $S_{j-1}$. These, in addition, may dominate some squares in $S_{j-2}$. Thus, we now have $\tilde{O}_{j-1}=O_{j-1}\cup O_j''$, and the total size of $OPT$ is not increased. Also, $|O_j|$ became $<12$. If $|\tilde{O}_{j-1}|\geq 12$, then again, we apply the same technique to delete some squares from $\tilde{O}_{j-1}$ and add the required number ($\leq 4$) squares from $S_{j-2}$ without increasing the initial size of $OPT$. The process continues up to the box $T_1$. If the size of $\tilde{O}_1$ (after adding some new squares) is $\geq 11$, we can replace it by at most $4$ squares. 
Thus, the size of $OPT$ is reduced, maintaining the size of the dominated squares in $S_1\cup \ldots, \cup S_j$ unchanged or increased, while the number of squares in $O_{j+1} \cup \ldots\cup O_m$ remains unchanged. Thus, we have a contradiction that the chosen solution $OPT$ is not optimal.
\end{proof}

Using Lemma \ref{LLL}, we construct a dynamic programming-based algorithm for the maximum dominating $k$-set problem.
\begin{itemize}
    \item $S_i^l$: a subset of $S_i$ of size $l$.
    \item $d(S_i^l)$: set of all squares dominated by $S_i^l$.
    \item $d_c(S_i^{l_1}\cup S_{i+1}^{l_2},S_{i+2}^{l_3})$: set of all squares dominated by both $S_i^{l_1}\cup S_{i+1}^{l_2}$ and $S_{i+2}^{l_3}$.
\end{itemize}
For a specific choice of the tuple $(l_1,l_2,S_{i-1}^{l_3},S_i^{l_4})$, where $l_1$, $l_2$, $l_3$ and $l_4$ are non-negative integers, $S_{i-1}^{l_3}$ is a subset of size $l_3$ of $S_{i-1}$ and $S_i^{l_4}$ is a subset of size $l_4$ of $S_i$, we denote by $N(l_1,l_2,S_{i-1}^{l_3},S_i^{l_4})$ the maximum dominated neighborhood size of a $(l_1+l_2+l_3+l_4)$-set, where $S_{i-1}^{l_3}$ is a subset of $l_3$ elements chosen from $S_{i-1}$, $S_i^{l_4}$ is a subset of $l_4$ elements chosen from $S_i$, a subset of $l_2$ elements is chosen from $S_{i-2}$ and a  subset of $l_1$ elements is chosen from $\cup_{j=1}^{i-3} S_j$ in the $(l_1+l_2+l_3+l_4)$-set.
With these notations, the recursion formula for $N(l_1,l_2,S_{i-1}^{l_3},S_i^{l_4})$ is

$N(l_1,l_2,S_{i-1}^{l_3},S_i^{l_4}) = 
\max \{ N(l_1-a,a,S_{i-2}^{l_2},S_{i-1}^{l_3}) + d(S_i^{l_4}) - d_c(S_{i-2}^{l_2}\cup S_{i-1}^{l_3},S_i^{l_4}): S_{i-2}^{l_2}\subseteq S_{i-2}$ and $|S_{i-2}^{l_2}|=l_2$, and $0\leq a \leq \min\{l_1,11\}$ is an integer$\}$.


Lemma \ref{LLL} says that $l_2,l_3,l_4\leq 11$ for any choice of the tuple $(l_1,l_2,S_{i-1}^{l_3},S_i^{l_4})$. The choice for $l_1$ can be any integer in $\{0,1,\dots,k\}$.

In the preprocessing step of the dynamic programming algorithm, the values of the functions $d$ and $d_c$ are calculated for all the required subsets of $S$. Next, each box $T_i$ is processed for $i=1,2,\dots,m$, in this order. We calculate and store all possible values of $N(l_1,l_2,S_{i-1}^{l_3},S_i^{l_4})$ using the recursion formula. Finally, the optimum maximum dominated neighborhood size $OPT$ of a $k$-set is obtained as 

$OPT = \max \{ N(l_1,l_2,S_{m-1}^{l_3},S_{m}^{l_4}): S_{m-1}^{l_3}\subseteq S_{m-1}$ with $|S_{m-1}^{l_3}|=l_3$, $S_m^{l_4}\subseteq S_m$ with  $|S_m^{l_4}|=l_4$, and $l_1+l_2+l_3+l_4=k, 0\leq l_2, l_3, l_4\leq 11 \}$.

Note that for the initialization of the dynamic programming, we add four dummy boxes $T_{-3},T_{-2},$ $T_{-1}$ and $T_0$ respectively just before the box $T_1$ and initialize $N(0,0,\emptyset,\emptyset)=0$ and all other entries which are undefined are initialized to $-\infty$.


\textbf{Justification of the recursion formula:} 

While processing $T_i$, when we choose $l_4$ elements of the set $S_{i}^{l_4}$ from $i$-th box $T_i$, it dominates $d(S_{i}^{l_4})$ elements. Now, there are only three possibilities,

\begin{enumerate}
    \item None of these $d(S_i^{l_4})$ elements were previously dominated. In this case, the last chosen squares can have centers in at most $T_{i-3}$; not in any later box.

    \item Some of these $d(S_i^{l_4})$ elements were already dominated, but none of the $l_4$ elements of $S_i^{l_4}$ were dominated. In this case, the last chosen squares have centers in the box $T_{i-2}$.

    \item Some of the $l_4$ elements of $S_i^{l_4}$ were already dominated. Here, the last chosen squares have centers in the box $T_{i-1}$.
\end{enumerate}

Correctness follows from the fact that the above three cases have been taken care of in the 
recursion formula.

\textbf{Time complexity:} Calculating $N(l_1,l_2,S_{i-1}^{l_3},S_i^{l_4})$ for a given $(l_1,l_2,S_{i-1}^{l_3},S_i^{l_4})$ requires $O(n^{11})$ time. For each $i$, number of tuples of the form $(l_1,l_2,S_{i-1}^{l_3},S_i^{l_4})$ is $O(kn^{22})$ and there are at most $2n$ possible values of $i$. Hence, the time needed to calculate the function $N$ for all possible arguments is $O(kn^{34})$. Finally, calculating $OPT$ requires $O(n^{11}.n^{11})=O(n^{22})$ time. Hence, the time complexity of the algorithm is $O(kn^{34})+O(n^{22}) = O(kn^{34})$, a polynomial in $n$ (since $k\leq n$).

