\section{Proofs of Statements} \label{appProve}

\subsection{Proof of Theorem \ref{proDBSP}}
\proof{Proof:} Given that $c_u^2 \geq 0$ in constraints (\ref{DBSP:visit}), the null vector $\mathbold{0}$ for $\mathbold{\omega}$ satisfies DBSP$_s$($\boldsymbol{\theta}$) and hence, the feasible domain of DBSP$_s$($\boldsymbol{\theta}$) is not empty. By strong duality, BSP$_s$($\boldsymbol{\theta}$) is either bounded and feasible or infeasible. Given that we assume we have sufficient drones and the definition of $\mcB_s(i)$, we can construct a feasible solution that each flight only serves a customer that satisfies $\alpha_{it}\theta_t > 0$. Therefore, BSP$_s$($\boldsymbol{\theta}$) is bounded and feasible, and so is DBSP$_s$($\boldsymbol{\theta}$).   $\hfill\Box$
\endproof

\subsection{Proof of Proposition \ref{proBound}}
\proof{Proof:} The proof focuses on the origin BMP without (\ref{lowerbound}) because the same argument can be extended to the BMP with more constraints. Recall that $\mathbold{\mu} \geq 0$, $\mathbold{\pi} \leq 0$, $\mathbold{\lambda} \leq 0$, and $\mathbold{\rho} \geq 0$ are the dual variables associated with constraints (\ref{TCF:visit}) -- (\ref{TCF:Capacity}), and (\ref{BMP:ClassicCut}), respectively. Further, $\Gamma$ is the optimal value of the current BMP with the $\theta$ variables and constraints~(\ref{BMP:ClassicCut}) generated so far, and $v_{bs}$ is the reduced cost of an optimal column found in MPS$_{bs}$. By strong duality and definition, we have 
	\begin{equation} \label{eq1}
		\Gamma = \sum_{i \in \mcC} \mu_i + \sum_{b \in \mcB}\sum_{s \in \mcS} \pi_{bs} + \sum_{b \in \mcB} Q^B\lambda_b
	\end{equation}
	\begin{equation}
		v_{bs} = \min_{t \in \mcT_{bs}} \{c_1^t  - \sum_{i \in \mcC}\alpha_{it}\mu_i - \pi_{bs} - \beta_t\lambda_b+ \sum_{\mathbold{\omega}\in \Omega_s}\sum_{i \in \mcC_s} \rho_{\mathbold{\omega}}\alpha_{it}\omega_{ib}\}
	\end{equation}
	By the feasibility of the dual of BMP, the dual constraints regarding $\varphi_s$ for all $s$ in $\mcS$ are
	\begin{equation}
		\sum_{\mathbold{\omega} \in \Omega_s} \rho_{\mathbold{\omega}} \leq 1, ~\forall~ s \in \mcS
	\end{equation}
	Let $Z^*$ and $(\mathbold{\theta}^*, \mathbold{\varphi}^*)$ be the optimal value and optimal solutions of the full BMP with all $\theta$ variables and constraints~(\ref{BMP:ClassicCut}), respectively. By the feasibility of the solution of BMP, we have 
	\begin{equation}	\label{eq3}
		\sum_{s \in \mcS}\sum_{b \in \mcB}\sum_{t \in \mcT_{bs}} \alpha_{it}\theta_t^* \geq 1, ~\forall~ i \in \mcC
	\end{equation}
	\begin{equation}	
		\sum_{t \in \mcT_{bs}} \theta_t^* \leq 1, ~\forall~ b \in \mcB, s \in \mcS
	\end{equation}
	\begin{equation}	
		\sum_{s \in \mcS}\sum_{t \in \mcT_{bs}} \beta_t\theta_t^* \leq Q^B, ~\forall~ b \in \mcB
	\end{equation}
	\begin{equation} \label{eq2}	
		\varphi_s^* \geq \sum_{i \in \mcC_s}\sum_{b \in \mcB_s(i)}\sum_{t \in \mcT_{bs}} \alpha_{it}\omega_{ib}\theta_t^*, ~\forall~ s \in \mcS, \boldsymbol{\omega} \in \Omega_s
	\end{equation}
	Due to (\ref{eq1}) -- (\ref{eq2}), we can deduce that
	\begin{align*}
		Z^* - \Gamma &= \sum_{t \in \mcT} c_1^t\theta_t^* + \sum_{s \in \mcS} \varphi_s^* - (\sum_{i \in \mcC} \mu_i + \sum_{s \in \mcS}\sum_{b \in \mcB} \pi_{bs} + \sum_{b \in \mcB} Q^B\lambda_b)\\
		&\geq \sum_{t \in \mcT} c_1^t\theta_t^* 
		+ \sum_{s \in \mcS}\sum_{\mathbold{\omega} \in \Omega_s}\sum_{i \in \mcC_s}\sum_{b \in \mcB_s(i)}\sum_{t \in \mcT_{bs}} \rho_{\mathbold{\omega}}\alpha_{it}\omega_{ib}\theta_t^* 
		- \sum_{i \in \mcC}\sum_{s \in \mcS}\sum_{b \in \mcB}\sum_{t \in \mcT_{bs}} \alpha_{it}\theta_t^*\mu_i\\ 
		&\quad  - \sum_{t \in \mcT_{bs}} \theta_t^*\pi_{bs} 
		- \sum_{s \in \mcS}\sum_{t \in \mcT_{bs}} \beta_t\theta_t^*\lambda_b\\
		&=\sum_{s \in \mcS}\sum_{b \in \mcB}\sum_{t \in \mcT_{bs}} \theta_t^*(c_1^t + \sum_{\mathbold{\omega} \in \Omega_s}\sum_{i \in \mcC_s} \rho_{\mathbold{\omega}}\alpha_{it}\omega_{ib} - \sum_{i \in \mcC}\alpha_{it}\mu_i - \pi_{bs} - \beta_t\lambda_b)\\
		&\geq \sum_{s \in \mcS}\sum_{b \in \mcB}\sum_{t \in \mcT_{bs}} \theta_t^* v_{bs}\\
		&\geq \sum_{s \in \mcS}\sum_{b \in \mcB: v_{bs} < 0} v_{bs},
	\end{align*}
	which completes the proof. The first inequality is obtained by following \eqref{eq3}-\eqref{eq2} directly. The second inequality is due to the definition of $v_{bs}$. The last inequality follows due to the fact that we focus on $v_{bs} < 0$ and $0\leq\sum_{t\in\mcT_{bs}} \theta_t^*\leq 1$. for all $b$ in $\mcB$ and $s$ in $\mcS$. $\hfill\Box$
\endproof

