\subsection{Channel Model}\label{ssec:channel}
Denote the number of transmit paths from the BS to the $k$-th user as $L_k^t$. As seen in Fig.~\ref{fig_angle}, on the BS side, the elevation and azimuth angles of departure (AoDs) of the $p$-th transmit path from the BS to the $k$-th user are $\theta_{k,p}^t$ and $\phi_{k,p}^t$, respectively, for $1\leq p\leq L_k^t$. The propagation distance difference in the $p$-th transmit path for the $k$-th user between the origin and the position of the $m$-th transmit fluid antenna is \cite{ma2023mimo}
\begin{equation}
\rho_{k,p}^t(\mathbf{t}_m)=x_m \sin \theta_{k,p}^t \cos \phi_{k,p}^t+y_m \cos \theta_{k,p}^t.
\end{equation}
The corresponding transmit field response vector is given by \cite{ma2023mimo}
\begin{equation}
\mathbf{g}_k(\mathbf t) \triangleq\left[e^{\jmath\frac{2\pi}{\lambda}\rho_{k,1}^t(\mathbf{t})},\dots,e^{\jmath\frac{2\pi}{\lambda}\rho_{k,L_t}^t(\mathbf{t})}\right]^T \in \mathbb{C}^{L_k^t\times 1}.
\end{equation}
where $\lambda$ is the signal wavelength. The field response matrix of $M$ transmit fluid antennas is written as
\begin{equation}
\mathbf{G}_k(\bt) \triangleq\left[\mathbf{g}_k\left(\mathbf{t}_1\right), \mathbf{g}_k\left(\mathbf{t}_2\right), \ldots, \mathbf{g}_k\left(\mathbf{t}_M\right)\right] \in \mathbb{C}^{L_k^t \times M}.
\end{equation}
%For the receiver side, the elevation and azimuth angles of arrival (AoAs) of the $q$-th $(1\leq q\leq L_k^r)$ receive path from the BS to the $k$-th user are respectively denoted as $\theta_{k,q}^r$ and $\phi_{k,q}^r$. In the $q$-th receive path from the BS to the $k$-th user, the propagation distance difference between the position of the receive FPA and origin is
%\begin{equation}
%\rho_{k,q}^r(\mathbf{r}_{k})=x_{k} \sin \theta_{k,q}^r \cos \phi_{k,q}^r+y_{k} \cos \theta_{k,q}^r,
%\end{equation}
%and the corresponding phase difference can be obtained as $2\pi\rho_{k,q}^r(\mathbf{r}_{k})/\lambda$. Thus, the receive field response vector can be written as
%\begin{equation}
%\mathbf{f}_k(\mathbf r_k) \triangleq\left[e^{\jmath\frac{2\pi}{\lambda}\rho_{k,1}^r(\mathbf{r}_k)},\dots,e^{\jmath\frac{2\pi}{\lambda}\rho_{k,L_r}^r(\mathbf{r}_k)}\right]^T \in \mathbb{C}^{L_k^r\times 1}.
%\end{equation}
In addition, the path response vector is denoted as $\mathbf{f}_k=[f_{k,1},f_{k,2},\dots,f_{k,L_k^t}]^H\in \mathbb{C}^{L_k^t \times 1}$, which represents the multi-path response coefficients from the BS to the $k$-th user. The channel vector $\mathbf h_k({\mathbf t})$ from the BS with fluid antennas at positions $\bt$ to the $k$-th user with a single FPA is written as \cite{ma2023mimo,xiao2023multiuser}
\begin{equation}
\mathbf h_k({\mathbf t})=\mathbf{G}_k(\bt)^H\mathbf{f}_k .
\end{equation}

\section{Problem Formulation}\label{sec:problem}
In this section, we aim to maximize the minimum weighted SINR by optimizing the precoding matrix $\bP$ and the positions of the transmit fluid antennas $\bt$. To limit the level of EM exposure, we impose the SAR constraint. Moreover, to prevent the mutual coupling effect, a minimum distance $D$ between the transmit fluid antennas is introduced. The SINR balancing problem is formulated as
\begin{equation}
\begin{aligned}
\mathcal{P}_1:\max _{\bP,\bt} 
&\quad\min_{k} \frac{1}{\gamma_k}\operatorname{SINR}_k(\bP,\bt) \\
\text { s. t. } 
%& \quad\sum_k || \mathbf w_{k}||^2 \leq P_t,\\
& \quad\sum_k\mathbf p_{k}^H\bR \mathbf p_{k}  \leq {Q}_0,\\
& \quad{\mathbf t} \in \mathcal{S},\\
&\quad\left\|\mathbf{t}_m-\mathbf{t}_l\right\|_2 \geq D,\quad m,l=1,\dots,M,\quad m\neq l,
\end{aligned}
\end{equation}
where $\gamma_k$ is the weight parameter for the $k$-th user. To find a more tractable formulation, we first introduce an auxiliary variable $\beta_0$ and reformulate the problem $\mathcal{P}_1$ as
\begin{equation}
\begin{aligned}
\mathcal{P}_2:\max _{\bP,\bt,\beta_0} 
&\quad \beta_0 \\
\text { s. t. } 
& \quad \frac{|\mathbf h_k^H(\bt)\mathbf p_{k}|^2}{\sum_{j\neq k}|\mathbf h_k^H(\bt)\mathbf p_{j}|^2+\sigma^2}\geq \beta_0\gamma_k, \quad\forall k,\\
%& \quad\sum_k || \mathbf w_{k}||^2 \leq P_t,\\
& \quad\sum_k\mathbf p_{k}^H\bR \mathbf p_{k}  \leq {Q}_0,\\
& \quad{\mathbf t} \in \mathcal{S},\\
&\quad\left\|\mathbf{t}_m-\mathbf{t}_l\right\|_2 \geq D,\quad m,l=1,\dots,M,\quad m\neq l.
\end{aligned}
\end{equation}

Note that the optimal precoding matrix $\bP$ and the fluid antenna positions $\bt$ of $\mathcal{P}_2$ are equivalent to those of $\mathcal{P}_1$ since the first inequality constraint of $\mathcal{P}_2$ holds with equality at the optimum.

Alternatively, we also consider the SAR minimization problem, which is a closely related problem of $\mathcal{P}_1$. In this problem, we aim to minimize the SAR value under the FAS and SINR constraints, which is given by
\begin{equation}
\begin{aligned}
\mathcal{P}_{3}: \min _{\bP,\bt} 
&\quad\sum_k\mathbf p_{k}^H\bR \mathbf p_{k} \\
\text { s. t.} 
& \quad\frac{|\mathbf h_k^H(\bt)\mathbf p_{k}|^2}{\sum_{j\neq k}|\mathbf h_k^H(\bt)\mathbf p_{j}|^2+\sigma^2}\geq \bar{\gamma}_k=\beta_0\gamma_k, \quad\forall k,\\
%& \quad\sum_k\mathbf w_{k}^H\bR_c \mathbf w_{k}  \leq {Q}_c,\quad c=1,\dots,C,\\
& \quad{\mathbf t} \in \mathcal{S},\\
&\quad\left\|\mathbf{t}_m-\mathbf{t}_l\right\|_2 \geq D,\quad m,l=1,\dots,M,\quad m\neq l,
\end{aligned}
\end{equation}
where $\beta_0$ is the SINR threshold. 

Denote the optimal objective function value of $\mathcal{P}_{2}$ with given $Q_0$ as $\mathcal{P}_{2}\left(Q_0\right)$ and the optimal objective function value of $\mathcal{P}_{3}$ with given $\beta_0$ as $\mathcal{P}_{3}\left(\beta_0\right)$, respectively. In the following lemma, we show the relationship between problem $\mathcal{P}_2$ and problem $\mathcal{P}_3$.

\begin{algorithm}[t]
\caption{Bisection Search Method to Handle Problem $\mathcal{P}_{2}$}
\label{a_1}
 \begin{algorithmic}[1]
%\Require $M$, $N$.
 \State Initialize the accuracy $\varepsilon_1$, the lower bound $\beta_{l}$ and upper bound $\beta_{u}$.
\Repeat
\State Calculate $\beta_0=(\beta_{l}+\beta_{u})/2$.
\State Tackle problem $\mathcal{P}_{3}$.
\If {$\sum_k\mathbf p_{k}^H\bR \mathbf p_{k} \leq Q_0$}
\State Set $\beta_{l}=\beta_0$. 
\Else 
\State Set $\beta_{u}=\beta_0$.
\EndIf
\Until {$|\beta_{l}-\beta_{u}|\leqslant \varepsilon_1$.}
 \end{algorithmic}
\end{algorithm}

\emph{Lemma 1:} The minimum weighted SINR maximization problem $\mathcal{P}_2$ and the SAR minimization problem $\mathcal{P}_3$ have the following relationship:
\begin{align}
\beta_0 & =\mathcal{P}_2\left(\mathcal{P}_{3}\left(\beta_0\right)\right), \label{inverse1}\\
Q_0& =\mathcal{P}_{3}\left(\mathcal{P}_2\left(Q_0\right)\right).\label{inverse2}
\end{align}

\emph{Proof:} Following the approach in \cite{wiesel2005linear}, we begin by proving \eqref{inverse1} by contradiction. Assume the contrary, i.e., $Q$, $\mathbf{P}$, $\bt$ are the optimal value and argument of $\mathcal{P}_{3}(\beta)$, and $\tilde{\beta} \neq \beta$, $\tilde{\mathbf{P}}$, $\tilde{\mathbf{t}}$ are the optimal value and argument of $\mathcal{P}_{2}(Q)$. If $\tilde{\beta}<\beta$, there is a contradiction for the optimality of $\tilde{\mathbf{P}}$ and $\tilde{\mathbf{t}}$ for $\mathcal{P}_{2}(Q)$, since $\mathbf{P}$ and $\mathbf{t}$ are feasible and they provide a larger objective value $\beta$. Otherwise, if $\tilde{\beta}>\beta$, there is a contradiction for the optimality of $\mathbf{P}$ for $\mathcal{P}_{3}(\beta)$, since $\tilde{\beta}>\beta$, and we can always find $c<1$ such that $c \tilde{\mathbf{P}}$ will still be feasible but will result in a smaller objective. The proof of \eqref{inverse2} is similar and is therefore omitted. Thus, the proof is complete.\hfill $\blacksquare$

From \emph{Lemma 1}, if $Q_0=\mathcal{P}_{3}(\beta_0)$, the solutions of $\mathcal{P}_{3}(\beta_0)$ will also be optimal for $\mathcal{P}_{2}(Q_0)$ \cite{wiesel2005linear}. By exploiting \emph{Lemma 1} and the fact that $\mathcal{P}_2$ is quasiconvex over $\beta_0$, a bisection search over $\beta_0$ can be used to handle $\mathcal{P}_2$ after $\mathcal{P}_3$ is tackled \cite{zhang2019specific}, which is detailed in \textbf{Algorithm \ref{a_1}}. Therefore, in the following, we focus on handling problem $\mathcal{P}_{3}$.

The challenges in tackling $\mathcal{P}_{3}$ come from the coupled variables and non-convex constraints. In the sequel, we propose an effective method to decouple $\mathcal{P}_{3}$ into several sub-problems.

\section{Two-Layer Iterative Algorithm}\label{sec:alg}
Here, a two-layer iterative algorithm is proposed to tackle the SAR minimization problem $\mathcal{P}_{3}$. The penalty method is first employed to decouple the precoding matrix $\bP$ and the transmit fluid antenna positions $\bt$ in the SINR constraints. The original SAR minimization problem becomes a two-layer problem where the penalized problem in the inner layer can be handled by the alternating optimization method, and the penalty factor in the outer layer is updated. The overall algorithm for handling problem $\mathcal P_3$ is summarized in Fig.~\ref{fig_algorithm}, which will be detailed below.


\subsection{Problem Transformation}\label{ssec:transform}
To handle the SAR minimization problem $\mathcal{P}_{3}$, we first deal with the non-convex SINR constraints. To decouple the tightly coupled optimizing variables in the constraints, new auxiliary variables $z_{k,j}$ are introduced to represent $\mathbf h_{k}^H(\bt)\mathbf p_{j}$. The SINR constraints can be reformulated as
\begin{align}
\frac{|z_{k,k}|^2}{\sum_{j\neq k}|z_{k,j}|^2+\sigma^2}&\geq \bar{\gamma}_k,~\forall k,\label{sinr1}\\
z_{k,j}&=\mathbf h_{k}^H(\bt)\mathbf p_{j},~\forall k,j.\label{sinr2}
\end{align}
By replacing the original SINR constraints with \eqref{sinr1} and \eqref{sinr2}, the original problem $\mathcal P_3$ is reformulated as
\begin{equation}
\begin{aligned}
\mathcal{P}_{4}: \min _{\bP, \bt,z_{k,j}}
&\quad\sum_k\mathbf p_{k}^H\bR \mathbf p_{k} \\
\text { s. t. }
& \quad\frac{|z_{k,k}|^2}{\sum_{j\neq k}|z_{k,j}|^2+\sigma^2}\geq \bar{\gamma}_k, \quad \forall k,\\
& \quad z_{k,j}=\mathbf h_{k}^H(\bt)\mathbf p_{j},\quad \forall k,j,\\
%& \quad\sum_k\mathbf w_{k}^H\bR_c \mathbf w_{k} \leq {Q}_c,\quad c=1,\dots,C,\\
& \quad{\mathbf t} \in \mathcal{S},\\
&\quad\left\|\mathbf{t}_m-\mathbf{t}_l\right\|_2 \geq D,\quad m,l=1,\dots,M,\quad m\neq l.
\end{aligned}
\end{equation}
Then, we exploit the penalty approach to deal with the equality constraints. The transformed problem $\mathcal{P}_{4}$ can be rewritten as
\begin{equation}
\begin{aligned}
\mathcal{P}_{5}: \min _{\bP,\bt,z_{k,j}}
&\quad\sum_k\mathbf p_{k}^H\bR \mathbf p_{k}+\mu\sum_{k=1}^K\sum_{j=1}^K|\mathbf h_{k}^H(\bt)\mathbf p_{j}- z_{k,j}|^2 \\
\text { s. t. }
& \quad\frac{|z_{k,k}|^2}{\sum_{j\neq k}|z_{k,j}|^2+\sigma^2}\geq \bar{\gamma}_k, \quad k=1, \ldots, K,\\
%& \quad\sum_k\mathbf w_{k}^H\bR_c \mathbf w_{k} \leq {Q}_c,\quad c=1,\dots,C,\\
& \quad{\mathbf t} \in \mathcal{S},\\
&\quad\left\|\mathbf{t}_m-\mathbf{t}_l\right\|_2 \geq D,\quad m,l=1,\dots,M,\quad m\neq l,
\end{aligned}
\end{equation}
where $\mu$ is the penalty factor. Theoretically, the penalty factor $\mu$ needs to be large so that the equality constraints hold. But the penalty term dominates the objective function when $\mu$ is very large, which means the optimization problem is not to minimize the SAR value. Therefore, the penalty factor $\mu$ should be initialized to a very small value and gradually increase \cite{9115725}. In so doing, a high-precision solution satisfying the equality constraints can be obtained.


