\subsubsection{Optimize $\{z_{k,j}\}_{k,j=1}^K$}For given $\bP$ and $\bt$, $\{z_{k,j}\}_{k,j=1}^K$ in problem $\mathcal P_5$ can be optimized by handling
\begin{equation}
\begin{aligned}
\mathcal{P}_{5.2}:  \min _{\{z_{k,j}\}_{k,j=1}^K} 
&\quad\sum_{k=1}^K\sum_{j=1}^K|\mathbf h_{k}^H(\bt)\mathbf p_{j}- z_{k,j}|^2 \\
\text { s. t. } 
& \quad\frac{|z_{k,k}|^2}{\sum_{j\neq k}|z_{k,j}|^2+\sigma^2}\geq \bar{\gamma}_k, \quad k=1, \ldots, K.
\end{aligned}
\end{equation}
Note that the optimization variables in relation to different users $z_{k,j}$, $k=1,2,\dots,K$ can be directly separated in the objective function and SINR constraints. Therefore, by dealing with $K$ independent sub-problems, each with a single SINR constraint, we can handle $\mathcal{P}_{5.2}$. The sub-problem related to the $k$-th user is expressed as
\begin{equation}
\begin{aligned}
\mathcal{P}_{5.3}:  \min _{\{z_{k,j}\}_{j=1}^K} 
&\quad\sum_{j=1}^K|\mathbf h_{k}^H(\bt)\mathbf p_{j}- z_{k,j}|^2 \\
\text { s. t. } 
& \quad\frac{|z_{k,k}|^2}{\sum_{j\neq k}|z_{k,j}|^2+\sigma^2}\geq \bar{\gamma}_k.
\end{aligned}
\end{equation}
Although problem $\mathcal{P}_{5.3}$ is a non-convex problem, the strong duality is demonstrated to hold since it satisfies the Slater's condition \cite{boyd2004convex,9133435}. Then, we resort to the Lagrange duality method. The Lagrangian function of problem ${P}_{5.3}$ can be expressed as follows by denoting the Lagrange multiplier related to the $k$-th SINR constraint as $\zeta_k$. 
\begin{multline}
\mathcal{L}\left(\{z_{k,j}\}_{j=1}^K, \zeta_k\right)=\left(1-\zeta_k\right)\left|z_{k, k}\right|^2
+\sum_{j=1\atop j \neq k}^K\left(1+\zeta_k \bar{\gamma}_k\right)\left|z_{k, j}\right|^2 \\
 -2 \sum_{j=1}^K \operatorname{Re}\left\{\mathbf h_{k}^H(\bt)\mathbf p_{j} z_{k, j}^*\right\}.
\end{multline}
The optimal solution can be obtained by using the first-order optimality condition, which is given by
\begin{equation}
\begin{aligned}
z_{k, k}(\zeta_k) & =\frac{\mathbf h_{k}^H(\bt)\mathbf p_{k}}{1-\zeta_k}, \\
z_{k, j}(\zeta_k) & =\frac{\mathbf h_{k}^H(\bt)\mathbf p_{j}}{1+\zeta_k \bar{\gamma}_k}, \quad 1\leq j\neq k\leq K.\label{dual_xki}
\end{aligned}
\end{equation}
The Lagrange multiplier $\zeta_k$ should satisfy the complementary slackness condition for the SINR constraint, which can be simplified as
\begin{equation}
\begin{aligned}
\zeta_k\left(\frac{|\mathbf h_{k}^H(\bt)\mathbf p_{k}|^2}{(1-\zeta_k)^2}-\sum_{j\neq k}\frac{\bar{\gamma}_k|\mathbf h_{k}^H(\bt)\mathbf p_{j}|^2}{(1+\zeta_k \bar{\gamma}_k)^2}
-\bar{\gamma}_k\sigma^2\right)=0.
\end{aligned}
\end{equation}
If $z_{k, k}(0)$ and $z_{k, j}(0),\forall j \neq k$ satisfy the SINR constraint, then $\zeta_k=0$. Otherwise, we need to find $\zeta_k$ that satisfies the following equality
\begin{equation}
\begin{aligned}
Y(\zeta_k)=&\frac{|\mathbf h_{k}^H(\bt)\mathbf p_{k}|^2}{(1-\zeta_k)^2}-\sum_{j\neq k}\frac{\bar{\gamma}_k|\mathbf h_{k}^H(\bt)\mathbf p_{j}|^2}{(1+\zeta_k \bar{\gamma}_k)^2}
-\bar{\gamma}_k\sigma^2=0.
\end{aligned}
\end{equation}
Since $Y(\zeta_k)$ with respect to $\zeta_k$ is a monotonically increasing function for $\zeta_k\leq 1$, the optimal $\zeta_k$ can be obtained through the bisection search method \cite{9133435}.

\subsubsection{Optimize $\bt$}With fixed $\bP$ and $\{z_{k,j}\}_{k,j=1}^K$, the corresponding transmit fluid antenna positions $\bt$ optimization problem can be expressed as
\begin{equation}
\begin{aligned}
\mathcal{P}_{5.4}:  \min _{\bt} 
&\quad\sum_{k=1}^K\sum_{j=1}^K|\mathbf h_{k}^H(\bt)\mathbf p_{j}- z_{k,j}|^2 \\
\text { s. t. } 
& \quad{\mathbf t} \in \mathcal{S},\\
&\quad\left\|\mathbf{t}_m-\mathbf{t}_l\right\|_2 \geq D,\quad m,l=1,\dots,M,\quad m\neq l.
\end{aligned}
\end{equation}
By expanding the objective function, problem $\mathcal{P}_{5.4}$ is reformulated as
\begin{equation}
\begin{aligned}
\mathcal{P}_{5.5}:  \min _{\bt} 
&\quad\sum_{k=1}^K\sum_{j=1}^K\mathbf h_{k}^H(\bt)\mathbf p_{j}\mathbf p_{j}^H\mathbf h_{k}(\bt)-\\&\quad\quad\quad\quad 2 \operatorname{Re}\left\{\mathbf h_{k}^H(\bt)\mathbf p_{j} z_{k,j}^*\right\}+|z_{k,j}|^2 \\
\text { s. t. } 
& \quad{\mathbf t} \in \mathcal{S},\\
&\quad\left\|\mathbf{t}_m-\mathbf{t}_l\right\|_2 \geq D,\quad m,l=1,\dots,M,\quad m\neq l.
\end{aligned}
\end{equation}

