\begin{algorithm}[t]
\caption{SCA-Based Method to Handle Problem $\mathcal{P}_{5.4}$}
\label{a_3}
 \begin{algorithmic}[1]
 \State Initialize the thresholds $\varepsilon_2$, the iteraton index $n=0$ and fluid antenna positions $\bt$.
\For {m = 1: M}
\Repeat 
\State Obtain $\nabla \bar{q}\left(\bt_m^{(n)}\right)$ according to \eqref{gra1} and \eqref{gra2}.
\State Obtain $\tau_m$ as \eqref{deltam}.
\State Update $\bt_{m}^{(n+1)}$ as \eqref{tmn1}.
\If{$\bt_{m}^{(n+1)}$ does not satisfy \eqref{cons1} or \eqref{cons2}}
\State Update $\bt_{m}^{(n+1)}$ by handling problem $\mathcal{P}_{5.7}$.
\EndIf
\State $n=n+1$.
 \Until{The decrease of the objective value of $\mathcal{P}_{5.4}$ is below a threshold $\varepsilon_2$.}
\EndFor
 \end{algorithmic}
\end{algorithm}

Similar to \cite{ma2023mimo}, the expression of $\tau_m$ is written as
\begin{equation}
\begin{aligned}
\label{deltam}
\tau_m=\sum\limits_{k=1}^K\sum\limits_{j=1}^K\frac{8\pi^2}{\lambda^2}&\left(2\sum\limits_{l\neq m}^M\sum\limits_{p_1=1}^{L_k^t}\sum\limits_{p=1}^{L_k^t}T(p,p_1,k)|[\bW_{j}]_{m,l}|\right.\\
&\left.\quad+[\bW_{j}]_{m, m}\sum\limits_{p_1=1}^{L_k^t}\sum\limits_{p_2=1}^{L_k^t}T(p_2,p_1,k)\right.\\
&\left.\quad+2\sum\limits_{p=1}^{L_k^t}|[\mathbf{f}_k^H]_{p}||[\bar{\bp}_{k,j}]_m|\right).
\end{aligned}
\end{equation}
Then, by ignoring the constant term in \eqref{secondtaylor}, problem $\mathcal{P}_{5.5}$ can be reformulated as 
\begin{subequations}
\begin{align}
\mathcal{P}_{5.6}:\min _{\mathbf{t}_m} 
&\quad \frac{\tau_m}{2} \bt_m^T \bt_m+\left(\nabla \bar{q}\left(\bt_m^{(n)}\right)-\tau_m \bt_m^{(n)}\right)^T \bt_m\label{q2_1}\\
\text { s.t. } 
& \quad{\mathbf t_m} \in \mathcal{S},\label{cons1}\\
&\quad\left\|\mathbf{t}_m-\mathbf{t}_l\right\|_2 \geq D,\quad l=1,\dots,M,\quad l\neq m.\label{cons2} 
\end{align}
\end{subequations}
Note that the objective function \eqref{q2_1} is a convex function. When ignoring the constraints \eqref{cons1} and \eqref{cons2}, the optimal solution of $\bt_m$ is written as
\begin{equation}\label{tmn1}
\bt_{m}^{(n+1)}=-\frac{1}{\tau_m}\nabla \bar{q}\left(\bt_m^{(n)}\right)+\bt_m^{(n)}.
\end{equation}
If $\bt_{m}^{(n+1)}$ satisfies the constraints \eqref{cons1} and \eqref{cons2}, then $\bt_{m}^{(n+1)}$ is the optimal solution of problem $\mathcal{P}_{5.6}$. Otherwise, the first-order Taylor expansion should be exploited to handle the non-convex constraint \eqref{cons2}, which can be written as \cite{ma2023mimo}
\begin{equation}
\begin{aligned}
&\left\|\mathbf{t}_m-\mathbf{t}_l\right\|_2 \\& \geq\left\|\mathbf{t}_m^{(n)}-\mathbf{t}_l\right\|_2+\left(\nabla\left\|\mathbf{t}_m^{(n)}-\mathbf{t}_l\right\|_2\right)^T\left(\mathbf{t}_m-\mathbf{t}_m^{(n)}\right) \\
%&=\left\|\mathbf{t}_m^{(n)}-\mathbf{t}_l\right\|_2+\frac{1}{\left\|\mathbf{t}_m^{(n)}-\mathbf{t}_l\right\|_2}\left(\mathbf{t}_m^{(n)}-\mathbf{t}_l\right)^T\left(\mathbf{t}_m-\mathbf{t}_m^{(n)}\right) \\
&=\frac{1}{\left\|\mathbf{t}_m^{(n)}-\mathbf{t}_l\right\|_2}\left(\mathbf{t}_m^{(n)}-\mathbf{t}_l\right)^T\left(\mathbf{t}_m-\mathbf{t}_l\right),
\end{aligned}
\end{equation}
where $\nabla\left\|\mathbf{t}_m^{(n)}-\mathbf{t}_l\right\|_2$ is the gradient vector of $\left\|\mathbf{t}_m^{(n)}-\mathbf{t}_l\right\|_2$ with respect to $\bt_m^{(n)}$. By applying the first-order Taylor expansion to the non-convex constraint \eqref{cons2}, problem $\mathcal{P}_{5.6}$ can be reformulated as
\begin{subequations}
\begin{align}
\mathcal{P}_{5.7}:\min _{\mathbf{t}_m} 
&\quad \frac{\tau_m}{2} \bt_m^T \bt_m+\left(\nabla \bar{q}\left(\bt_m^{(n)}\right)-\tau_m \bt_m^{(n)}\right)^T \bt_m\\
\text { s.t. } 
&\quad{\mathbf{t}_m} \in \mathcal{S},  \\
&\quad \frac{1}{\left\|\mathbf{t}_m^{(n)}-\mathbf{t}_l\right\|_2}\left(\mathbf{t}_m^{(n)}-\mathbf{t}_l\right)^T\left(\mathbf{t}_m-\mathbf{t}_l\right) \geq D, \nonumber\\&\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad l=1,\dots,M,\quad l\neq m.
\end{align}
\end{subequations}
Since problem $\mathcal{P}_{5.7}$ is a convex problem, it can be tackled by exploiting classical convex optimization techniques. The algorithm to tackle problem $\mathcal{P}_{5.4}$ is detailed in \textbf{Algorithm \ref{a_3}}.

\subsection{Outer Layer}\label{ssec:outer}
To make the equality constraints in $\mathcal{P}_{4}$ hold and minimize the SAR value, the penalty factor $\mu$ should be initialized to a small value and gradually increased using the following update
\begin{equation}\label{increaserho}
\mu=\frac{\mu}{a},
\end{equation}
where $0<a<1$ adjusts the precision of the solutions. 

