\section{Introduction}

\begin{figure}[t]
  \centering\hspace{-7px}
  \includegraphics[width=\linewidth]{figures/frontpage_rgd.pdf}
  \caption{Methodological overview; a decoder reconstructs data from Riemannian manifolds where representations are optimized as model parameters via maximum likelihood.}
