\section{Training details} \label{app:training}
\begin{lstlisting}[caption={\textbf{Pseudocode for training the Riemannian generative decoder. }The necessary changes for learning Riemannian latents rather than Euclidean ones are highlighted with red.}, label={lst:training}]
model.z     := init_z(n, @manifold@) # initialize points on a manifold
model_optim := Adam(model.decoder.parameters())
rep_optim   := @RiemannianAdam@([model.z])

for each epoch:
    rep_optim.zero_grad()
    for each (i, data) in train_loader:
        model_optim.zero_grad()
        z    := model.z[i]
        z    := @@add_noise@@(z, std, @manifold@) # optional regularization
        y    := model(z)
        loss := loss_fn(y, data)
        loss.backward()
        model_optim.step()
    rep_optim.step()
\end{lstlisting}
\begin{lstlisting}[caption={\textbf{Pseudocode for adding geometric noise.} \ls{egrad2rgrad} takes a Euclidean gradient and maps it to the Riemannian gradient in the tangent space using the inverse metric. \ls{retr} retracts a tangent vector back onto the manifold via the exponential map if a closed form is available, otherwise a first‐order approximation. \textsl{geoopt} implements both functions for a wide range of manifolds.}, label={lst:noise}]
def @@add_noise@@(z, std, manifold):
    noise     := sample_normal(shape=z.shape) * std
    rie_noise := manifold.egrad2rgrad(x, noise)
    z_noisy   := manifold.retr(x, rie_noise)
    return z_noisy 
\end{lstlisting}


