    \item \takehiro{\textbf{\javier{Investor} 2: Conservative Income Seeker:} Seeks stable returns, invests in well-established companies, values regular dividend payouts.}
    \item \takehiro{\textbf{\javier{Investor} 3: Risk-taking Value Investor:} Targets undervalued companies with strong long-term potential, tolerates short-term volatility, and invests in cyclical sectors.}
\end{itemize}


