\begin{comment}


\vspace{2mm} \noindent \textbf{Mean Elicitation Accuracy}:

\[
\text{ElicitationAccuracy}(u_i, \hat{u}_i) 
= \frac{1}{n} \sum_{j=1}^n \mathbb{I}\bigl(u_{j,i} = \hat{u}_{j,i}\bigr),
\]
where $\mathbb{I}(\cdot)$ returns $1$ if the preference matches and $0$ otherwise.
Then, we average across all users $(u_1, \dots, u_M)$ to obtain the \textit{mean elicitation accuracy}:
\[
\text{MeanElicitationAccuracy}
= 
\frac{1}{M} \sum_{i=1}^M 
\text{ElicitationAccuracy}(u_i, \hat{u}_i).
\]

\vspace{2mm} \noindent \textbf{Elicitation Success Rate}:
We say the LLM-advisor \textit{successfully} captures user~$i$'s preferences 
if the \textit{majority} of those preferences match (e.g., at least $2$ out of $3$). 
Formally,
\[
\text{SuccessIndicator}(u_i, \hat{u}_i) 
= 
\begin{cases}
1 & \text{if } \text{ElicitationAccuracy}(u_i, \hat{u}_i) \ge \theta,\\
0 & \text{otherwise},
\end{cases}
\]
where $\theta$ is the fraction required for a majority (in our experiment $\theta = 2/3$). 
Over $M$ users, the \textit{Elicitation Success Rate} is
\[
\text{ElicitationSuccessRate}
= 
\frac{1}{M} \sum_{i=1}^M 
\text{SuccessIndicator}(u_i, \hat{u}_i).
\]

\end{comment}

