\section{Modified Riemann-Liouville Derivative}\label{App:RL}
In this section, some useful properties of modified RL are provided:
\begin{equation}
    D^\alpha_\zeta \zeta^\beta= \frac{\Gamma(\beta+1)}{\Gamma(\beta-\alpha+1)} \zeta^{\beta-\alpha},\quad \beta>0\label{eq.A1}
\end{equation}
\begin{equation}
   D^\alpha_\zeta c u(\zeta)=c D^\alpha_\zeta u(\zeta)\label{eq.A2}
\end{equation}

\begin{equation}
    D^{\alpha}_\zeta (u(\zeta)v(\zeta))=u(\zeta) D^{\alpha}_\zeta v(\zeta)+v(\zeta) D^{\alpha}_\zeta u(\zeta)\label{eq.A4}
\end{equation}
\begin{align}
    D^{\alpha}_\zeta u[v(\zeta)] &= u'_v(v) D^\alpha_\zeta v, \label{eq:A.5} \\
    &= D^\alpha_v u(v) (v'(\zeta))^\alpha. \label{eq:A6}
\end{align}

 Where c is a constant. The function ~\( u(\zeta) \) are non-differentiable in equation ~\ref{eq.A4} and ~\ref{eq:A.5} but becomes differentiable in \ref{eq:A6}. Similarly,~ \( v(\zeta) \) is non-differentiable in \ref{eq.A4}. Meanwhile, ~\( u(v) \) is differentiable in ~\ref{eq:A.5} but non-differentiable in ~\ref{eq:A6} \cite{jumarie2010approach}.The equations ~\ref{eq.A4}-~\ref{eq:A6} are derived directly from $D^\alpha_\zeta ~u(\zeta)\cong \Gamma(\alpha+1) D_\zeta u(\zeta)$.
Using these relations, the modified RL derivative of one-paramerer Mittag-Leffler function is calculated as
\begin{equation}
\begin{split}
   &\mathcal{D}^\alpha_x E_\alpha(i x^\alpha)=\sum_{k=0}^{\infty}\frac{\mathcal{D}^\alpha_x(i^k x^{\alpha k})}{\Gamma(\alpha k+1)}= \\&\sum_{k=1}^{\infty}\frac{i^k \Gamma(\alpha k+1) x^{\alpha(k-1)}}{\Gamma(\alpha k+1) \Gamma(\alpha(k-1)+1)}= \\&\sum_{s=0}^{\infty} \frac{i^{s+1} x^{\alpha s}}{\Gamma(\alpha s+1)}=i E_\alpha (i x^\alpha) \label{Mittag} 
\end{split}
\end{equation}
In a similar manner, using \eqref{eq:A6}, we have
\begin{equation}
\begin{aligned}
    \mathcal{D}^{\alpha}_\chi E_\alpha\left(i \left(\frac{w \chi^2}{2}\right)^\alpha\right)  
    &= \sum_{k=0}^{\infty} 
    \frac{i^k ~ \mathcal{D}^\alpha_\chi \left(\frac{w \chi^2}{2}\right)^{\alpha k}}
    {\Gamma(\alpha k +1)} \\
    &= w^\alpha \chi^\alpha \sum_{k=1}^{\infty} 
    \frac{i^k \left(\frac{w \chi^2}{2}\right)^{\alpha k-\alpha}}
    {\Gamma(\alpha k -\alpha +1)} \\
    &= i w^\alpha \chi^\alpha \sum_{s=0}^{\infty} 
    \frac{i^s \left(\frac{w\chi^2}{2}\right)^{\alpha s}}
    {\Gamma(\alpha s+1)} \\
    &= i w^\alpha \chi^\alpha 
    E_\alpha\left(i \left(\frac{w \chi^2}{2}\right)^\alpha\right).\label{AA7}
\end{aligned}
\end{equation}

In addition, Jumarie~\cite{jumarie2005representation} derived the following equality for the integral of any continuous function \( f \) with respect to \( d\zeta^\alpha \) 
\begin{equation}
\begin{split}
     \int_{0}^{x} f(\zeta) \, d\zeta^\alpha &= 
    \alpha \int_{0}^{x} (x-\zeta)^{\alpha-1} f(\zeta) \, d\zeta\\
    &=\Gamma(\alpha+1)\mathcal{J}_0 f(x),
    \quad 0<\alpha\leq 1.\label{A7}   
\end{split}
\end{equation}
Moreover, we have the following commutativity property:  
\begin{equation}
    \mathcal{D}^\alpha_t \mathcal{J}^\alpha_0 f(x,t) = \mathcal{J}^\alpha_0 \mathcal{D}^\alpha_t f(x,t).\label{A8}
\end{equation}
where the Riemann–Liouville integral and the Jumarie derivative are taken over the \( x \)- and \( t \)-domains, respectively. This holds because
\begin{equation}
\begin{split}
    \mathcal{D}^\alpha_t \mathcal{J}^\alpha_0 f(x,t) 
    &= \mathcal{D}^\alpha_t \left( \frac{1}{\Gamma(\alpha)} \int_{0}^{x} (x-\zeta)^{\alpha-1} f(\zeta,t) \, d\zeta \right) \\ 
    &= \frac{1}{\Gamma(\alpha)} \int_{0}^{x} (x-\zeta)^{\alpha-1} \mathcal{D}^\alpha_t f(\zeta,t) \, d\zeta \\ 
    &= \mathcal{J}^\alpha_0 \mathcal{D}^\alpha_t f(x,t).
\end{split}
\end{equation}


