\subsection{Theoretical Analysis}

The next lemma shows a connection between SVD and  short vectors in lattices. 
\begin{lemma}\label{lemma_SVD_Int}
Let $M\in \R^{m \times (n+1)}$  with  an SVD as in (\ref{eq_SVD}).  Let $k \leq n$ be an index  so that $\sigma_k > \sigma_{k+1}$. 
Then, for any $x \in \Z^n$ with   $\|Mx\|_2 <  \sigma_{k}/2$, there exists $z \in Z_k  = \Span(v_{k+1}, \ldots, v_{n+1})$ so that  $x  = \lfloor z  \rceil$. 
\end{lemma}
\begin{proof}
Decompose $x$ as   $x = z+ w$ where $z \in Z_k$ and $w \in \Span(v_1, \ldots, v_k)$.
We can write $z$ and $w$ as 
\[ z = \sum_{i=k+1}^{n+1} c_i v_i, \quad \quad  w = \sum_{i=1}^{k} c_i v_i\]
where $c_i \in \R$.  Since $V = (v_1, \ldots, v_{n+1})$ is orthonormal, we have  $\|w \|_2^2 = \sum_{i=1}^{k}  |c_i |^2$. Note that 
$Mx  =    \sum_{i=1}^{n+1} c_i\sigma_i  u_i$.
 Since $U = (u_1, \ldots,  u_m)$ is orthonormal, we have
\[ \|Mx \|_2^2 =   \sum_{i=1}^{n+1}  |c_i|^2   \sigma_i^2 \ge   \sum_{i=1}^{k}  |c_i|^2 \sigma_i^2
\ge   \sum_{i=1}^{k}  |c_i|^2 \sigma_k^2 =  \|w\|_2^2 \sigma_k^2.
\]
Since $\|Mx\|_2 <  \sigma_{k}/2$ by assumption,  we have  $\|w\|_2 \sigma_k <  \sigma_{k}/2$, thus $\|w\|_{\infty} \leq \|w\|_2 < 1/2$. 
 As $x \in \Z^n$, we have   $\lfloor z \rceil  = \lfloor x - w \rceil = x$ as claimed. 
\end{proof}


\begin{lemma}\label{Lemma_LWE}
Let $B \in \R^{m \times n}$,  $b \in \R^m$ and $x \in \Z^n$ so that 
$b = Bx + e$ for  $e \in \R^m$ with $\|e \|_2 \leq r$. 
  Suppose $\sigma_n(B) > 2 r$. Then
the BDD algorithm in Figure \ref{Fig01}  finds $x$ correctly. 
\end{lemma}
\begin{proof}
We first need to find good bounds for  the singular values of  $M = (B, -b)$, especially $\sigma_n(M)$ and $\sigma_{n+1}(M)$.
Let $\tilde{x} = \begin{pmatrix} x \\ 1 \end{pmatrix}  \in \R^{n+1}$.  Since  $M \tilde{x} = Bx - b   = -e$, we have $\|M \tilde{x}\|_2 = \|e\|_2 \leq r$, and 
\begin{equation}\label{eq_r}
 \sigma_{n+1}(M) \leq  \frac{\|M \tilde{x}\|_2}{\|\tilde{x}\|_2} \leq \frac{r }{\sqrt{1 + \|x \|_2^2}}  \leq  r. 
\end{equation}

Next we show that  $\sigma_n(M) \ge \sigma_n(B)$.  Let $U_0$ be the subspace of $\R^{n+1}$ of dimension $n$ with the last entry equal to $0$.  
For any $y = \begin{pmatrix} u \cr 0\end{pmatrix} \in U_0$ where $u \in \R^n$, we have
$My = Bu$. Hence 
\[ \sigma_n(B) = \min_{u \in \R^n, \, \|u\|_2 = 1}  \|Bu\|_2 =  \min_{y \in U_0, \, \|y\|_2 = 1}  \|My\|_2.\]
Since 
\[ \sigma_n(M)=  \max_{U \subset \R^{n+1},\,  \dim(U) =n\ }  \min_{y \in U, \, \|y\|_2 =1}  \|My\|_2,\]
we see that $\sigma_n(M) \geq \sigma_n(B)$. 

Since  $\sigma_n(B) > 2r$ by assumprtion,  we have  $\sigma_n(M)  >    2 r  \ge  2 \|M \tilde{x}\|_2$,  thus  (\ref{eq_r}) implies that    $\sigma_n(M)  >     \sigma_{n+1}(M)$. 
We can apply Lemma \ref{lemma_SVD_Int} to any SVD of  $M$:  $M = U \Sigma V^T$ with  $k =n$ and $Z_k = \Span(v_{n+1})$  where $v_{n+1}$ is the last column of $V$. This means that 
$\tilde{x} = \lfloor cv_{n+1}  \rceil$ for some $c  \in \R$. Let $v_{n+1} = (z_1, \ldots, z_{n+1})^T$. Since the last entry of $\tilde{x}$ is $1$,  we just need to run through
 real numbers $c$ so that $0.5 \leq c z_{n+1} \leq 1.5$ that gives difference integer vectors  
  $\tilde{x} = \lfloor c\cdot v_{n+1} \rceil$, and the number of such $c$ is bounded by $n \|v_{n+1}\|_{\infty}/|z_{n+1}|$.  
In our algorithm and computer experiments, we simply take $c$ to be $1/z_{n+1}$.  
\end{proof}


\begin{theorem}\label{thm03}
 Let  $m$ and $n$ be integers with $ m =n \beta$ where $ \beta >1$ is a constant. Suppose
  \[r >0, \quad  0< \epsilon< 1-\sqrt{\beta^{-1}},\quad  \sigma  >  \frac{2 r }{(1-\sqrt{\beta^{-1}} -\epsilon)\sqrt{m}}.\] 
% $12(1 + \sqrt{4/3}) r/ \sqrt{n}$   
Let $\chi_{\sigma}$  be  the Gaussian distribution  $N(0,\sigma^2)$ on $\R$ with variance  $\sigma^2$. 
For a random $B \in \R^{m \times n}$, where each entry  is an independent sample from   $\chi_{\sigma}$,  and for any vector $b \in \R^m$ with $d(b, L(B)) \leq r$, 
the BDD algorithm in Figure \ref{Fig01} runs in polynomial time and finds $x \in \Z^n$  so that $d(b,Bx) \leq r$ with probability 
at least  $1 - e^{-\epsilon^2 m/2}$, where the success probability is over the randomness of $B$. 
\end{theorem}

\begin{proof}
First, note that SVD can be computed in polynomial time \cite{DGH18,Golub2013}, hence our BDD algorithm runs in polynomial time.
Next, we need to examine the distribution of  the singular values of $B$. The well-known Bai-Yin Law (1993, \cite{BY93}) states that,
for any any probabilistic distribution $\chi$ on $\R$ with $E(\chi) = 0$, variance $E(|\chi|^2) = 1$ and $E(|\chi|^4) < \infty$, if $A$  is an $m \times n$ matrix with entries as i.i.d.\ from $\chi$, then  almost surely, 
\begin{equation}\label{eq_BY}
\lim_{m \to \infty} \frac{\sigma_n(A)}{\sqrt{m}}  =  1- \sqrt{\beta^{-1}}, \quad \quad   \lim_{m \to \infty} \frac{\sigma_1(A)}{\sqrt{m}}  = 1 + \sqrt{\beta^{-1}} .
\end{equation} 
There are more general concentration results, see for example  the book by Tao \cite{Tao12}.
For a Gaussian distribution, there is an effective version of the Bin-Yin Law. 
Suppose   $A$ is an $m \times n$ matrix with entries as i.i.d.\ from $N(0, \frac{1}{m})$. 
Davidson and Szarek (Theorem 2.13, \cite{DS01}) proved the following tail probability: 
\begin{equation}\label{eq_DS}
    P\left[ \sigma_n(A)  \le   1- \sqrt{\beta^{-1}} - t \right] <  e^{-\frac{mt^2}{2}}  \quad \text{ and } 
     P\left[ \sigma_1(A)  \ge  1+ \sqrt{\beta^{-1}} + t \right] <  e^{-\frac{mt^2}{2}}.
\end{equation}


Now back to our proof with $\chi_{\sigma}$ and $B$ as in Theorem \ref{thm03}. 
Let $A = \frac{1}{\sigma\sqrt{m}} B$. Then $A$ has entries  i.i.d.\  from  the Gaussian distribution $N(0, \frac{1}{m})$.  
% For any $0 < \epsilon < \sqrt{4/3} -1\approx 0.1547$,  
We apply the inequality (\ref{eq_DS}) with $A$ and $t = \epsilon$, yielding 
the probability bound:
\[   P\left[ \sigma\sqrt{m} \cdot ( 1- \sqrt{\beta^{-1}} -\epsilon)  \le  \sigma_n(B) \le  \sigma_1(B) \le  \sigma \sqrt{m}\cdot  (1 + \sqrt{\beta^{-1}} +\epsilon)    \right] \ge  1- e^{-\frac{m\epsilon^2}{2}}. \]
By  the assumption on $\sigma$, we have $\sigma_n(B) > 2r$ with probability at least $ 1- e^{-\frac{m\epsilon^2}{2}}$. 
The rest of the proof is completed by  applying  Lemma \ref{Lemma_LWE}.
\end{proof}

{\bf Proof of Theorem \ref{thm02}}.  We show Theorem \ref{thm02} as a special case of Theorem \ref{thm03}. Indeed, let $\beta= 4/3$,  $r = \sqrt{n}$, and $\chi_{\sigma}$ a sub-Gaussian with variance $\sigma^2$ with $\sigma \geq  17$.  Noting  that  $1-\sqrt{3/4}  \approx 0.13397$, we let  $\epsilon = 0.03$. Then  $17>  2 \sqrt{\beta^{-1}}/ (1-\sqrt{\beta^{-1}} - \epsilon)  \approx  16.66$, hence 
\[ \sigma \geq 17   >  \frac{2r }{(1-\sqrt{\beta^{-1}} -\epsilon)\sqrt{m}}.\]
Then  Theorem \ref{thm03} says that, for a random $B \in \R^{m \times n}$, where each entry  is an independent sample from   
$\chi_{\sigma}$,  and for any vector $b \in \R^m$ with $d(b, L(B)) \leq r$, 
the BDD algorithm in Figure \ref{Fig01}  finds $x \in \Z^n$  so that $d(b,Bx) \leq r$ with probability 
at least  $1 -e^{-0.0045m}$.  This proves Theorem \ref{thm02}.


For a general subGaussian distribution, the following version of the Bin-Yin Law  is due to Rudelson and Vershynin (Theorem 1.1, \cite{RV09}). %, Ver18}.
Let $\chi$ be any sub-Gaussian distribution on $\R$ with variance $1$.   
Suppose   $A$ is an $m \times n$ matrix with entries as i.i.d.\ from $\chi$. 
Then, for every $\epsilon > 0$ and $\beta = m/n >1$, we have
\begin{equation}\label{eq_RV}
    P\left[ \frac{\sigma_n(A)}{\sqrt{m}}   \le  \epsilon (1-\sqrt{\beta^{-1}} )  \right] \le  (c_1\epsilon)^{m-n+1} +  e^{-c_2m},
\end{equation}
where $c_1, c_2>0$ are constants depending only  on  the distribution $\chi$. 
This bound and the above proof of Theorem \ref{thm03} immediately lead to the following theorem.

\begin{theorem}\label{thm04}
 Let  $m$ and $n$ be integers with $ m =n \beta$ where  $\beta >1$ is a constant. Suppose
  \[r >0, \quad  \epsilon>0,\quad  \sigma >  \frac{2 r }{\epsilon  (1-\sqrt{\beta^{-1}})\sqrt{m}}.\] 
Let $\chi_{\sigma}$  be  a subGaussian distribution on $\R$ with variance  $\sigma^2$. 
For a random $B \in \R^{m \times n}$, where each entry  is an independent sample from   $\chi_{\sigma}$,  and for any vector $b \in \R^m$ with $d(b, L(B)) \leq r$, 
the BDD algorithm in Figure \ref{Fig01} runs in polynomial time and finds $x \in \Z^n$  so that $d(b,Bx) \leq r$ with probability 
at least  $1-(c_1\epsilon)^{m-n+1} -  e^{-c_2m}$, where the success probability is over the randomness of $B$ and  
$c_1, c_2>0$ are constants depending only  on  the distribution $\chi_{\sigma}$. 
\end{theorem}

Theorem \ref{thm02b} in the introduction is a special case of Theorem \ref{thm04} when $\epsilon = 1/(2c_1)$ and $r = \sqrt{n}$. 
Determining optimal values for the constants $c_1$ and $c_2$ remains an open challenge. However, we note that Hsu, Kakade, and Zhang (Lemma A.1 in \cite{HKZ12}) derived an explicit bound on the largest singular value  $\sigma_1(B)$ with explicit  constants.  Their method could be used to derive explicit  bounds for the smallest singular value $\sigma_n(B)$. 
We direct readers to their paper for further technical details. In the subsequent section, we present computational experiments to evaluate the success probabilities, demonstrating that the practical performance of our BDD algorithm  significantly surpasses the theoretical predictions provided by these bounds.



\section{Computer Experiments on the LWE Problem over Real Numbers} \label{sec4}


We evaluate the performance of the BDD algorithm in solving the learning with errors (LWE) problem over real numbers, studied by Bootle et al.\  \cite{BDE18}.  
For any $\gamma>0$, let $U_{\gamma}$ denote the uniform distribution on the real interval $[-\gamma, \gamma]$, which is sub-Gaussian with parameter $\gamma$ and variance $\frac{\gamma^2}{3}$.   
Let $\beta >1$,  $\theta >0$  and $\gamma_0>0$ be constants, and
\begin{equation}\label{eq_mg}
 m= \lceil \beta n\rceil, \quad \gamma_1 =\theta  \gamma_0.
 \end{equation}
% Note that this $\beta$ is the inverse of the $\beta$ from previous sections, since  it is a  more convenient measure for  the sample size $m$ compared to $n$ (the size of secret information).
 The LWE problem over real numbers is to find $x \in \Z^n$, given $B \in \R^{m \times n}$  and  $b \in \R^m$, such  that
\begin{equation}\label{eq_lwe2}
 b = Bx + e, 
 \end{equation}
where each entry of $B$  is an independent sample from $U_{\gamma_1}$ and 
 each entry of $e$ is an an independent sample from $U_{\gamma_0}$.    Bootle et al.\  \cite{BDE18} proved that this problem can be solved by the least square solution when $m$ is sufficiently large. They studied the LWE problem over reals for more general subGaussian distributions and gave an explicit bound on $m$ in their Theorem 4.5, which says that  the ratio $\beta= m/n$ should be  at least $C_1=2^8\log 9$. 


  We would like to demonstrate that our SVD method works well for the case $\gamma_0 < \gamma_1$. It works not just  when the ratio $\beta=m/n$ is large, but also for small $\beta$, say $\beta  \leq 2$.  
 We used the Multiprecision Computing Toolbox for MATLAB \cite{mct23} for computing SVD.
 In our computer experiments, we generate sample data $(B,b)$ satisfying (\ref{eq_lwe2}) as follows. For any given $(n, \beta, \gamma_0, \theta)$, 
 we calculate $m$ and $\gamma_1$ as defined in (\ref{eq_mg}), select $x$ uniformly from $\{0, 1\}^n$, and generate each entry of $B$ and $e$ as an independent sample from $U_{\gamma_1}$ and $U_{\gamma_0}$, respectively. We then rescale $(B, b)$ so that $\gamma_0 = 1$. 
 For each  $(n, \beta,  \theta)$  in Table \ref{data1}, we generated 1000 random samples of $(B, b)$, recording the number of successful runs where the BDD algorithm correctly recovered $x$. The success probability is calculated as the number of successful runs divided by 1000. Results in the "Prob" column show that, for $\theta = 2$ (or higher) and $\beta \geq 1.2$, the BDD algorithm achieves at least a 97\% success rate, and for $\beta = 1.5$ (or higher) with $\theta \geq 1.1$, the success rate is at least 95\%. These findings suggest that the LWE problem over real numbers can be solved efficiently on average.


