\subsection{Asymptotic properties}\label{secIIc}
%In this section we provide the asymptotic properties of the proposed estimators under 

Let us consider the two standard scenarios: (i) $N\rightarrow\infty$ and $T$ fixed; (ii) $N\rightarrow\infty$ and $T\rightarrow\infty$. For the latter case, we first recall the definition of a strongly mixing sequence. 

Let $\{\zeta_t\}$ be a strictly stationary process and $\mathcal{F}_{t'}^t$ denotes a $\sigma$-algebra of events generated by the random variables $(\zeta_{t'},\ldots,\zeta_t)$ for $t'\leq t$. Following \citet{ROSENBLATT:1956}, a process is said to be strongly mixing or $\alpha$-mixing if
\[
\alpha(\tau)=\sup_{t'\in\mathcal{N}}\{|P(A\cap B)-P(A)P(B)|:A\in\mathcal{F}_{-\alpha}^{t'},B\in\mathcal{F}_{t'+\tau}^{-\infty}\}\rightarrow0,\quad\textrm{as}
\quad T\rightarrow\infty  \ .
\]

For the sake of presentation, we introduce now the following notation: $B_x(w_0)=E[x_{it}|w_{it}=w_0]$, $\Phi_{\epsilon}(\chi_{it},\chi_{it'})=E(\epsilon_{it}\epsilon_{it'}|\chi_{it},\chi_{it'})$, and $\Omega_x=E[\{x_{it}-B_x(w_{it})\}\{x_{it}-B_x(w_{it})\}^{\prime}]$, for $\chi_{it}=(x_{it},w_{it})$. For the univariate kernel $k(\cdot)$, we denote $\mu_2=\int u^2k(u)du$, $\nu_0=\int k^2(u)du$, and $\nu_2=\int u^2k^2(u)du$, where $\mu_2$, $\nu_0$, and $\nu_2$ are scalars different from zero. Further, for a real matrix \textbf{A}, let $\|A\|=tr^{1/2}(A^{\prime}A)$. For a vector $\textbf{v}$, let $\|\textbf{v}\|$ denote its Euclidean norm. Also, let $D_g(w)$ and $\mathcal{H}_g(w)$ be the $d_w\times 1$ first-order derivative vector and the $d_w\times d_w$ Hessian matrix of $g(\cdot)$ with respect to $w$, respectively. Similarly, let $D_{\rho}(w)$ be the $d_w\times1$ first-order derivative vector of $\rho(w)$. % with respect to $w$.

Then, to show $\sqrt{N}$-consistency of $\widehat \beta$ as $N$ tends to infinity and $T$ is fixed, we suppose

\begin{assumption}\label{asumA1}
The univariate kernel function $k(\cdot)$ is a symmetric, non-negative, and bounded probability density function with compact support which satisfies the Lipschitz condition, $\int k(v)dv=1$, and $\int vk(v)dv=0$. 
\end{assumption}
%
\begin{assumption}\label{asumA2}
Let $\{(x_{it},w_{it},u_{it},\eta_{it}),i\geq1,t\geq 1\}$ be a set of independent and identically distributed ($i.i.d.$) random variables across the $i$ index for each fixed $t$. Also, for fixed $i$, the process $(x_{it},w_{it},u_{it},\eta_{it})$ is strictly stationary and ergodic over $t$. Furthermore, $u_{it}$ and $\eta_{it}$ are independent.
\end{assumption}

\begin{assumption}\label{asumA3}
Let $\varrho_{it} =(u_{it}, \eta_{it})$ and $\chi_{it} = (w_{it},x_{it})$. 
$\exists$ %There exists
$\gamma>0$, such that  $E(\left|\varrho_{it}|^{4+\gamma}\right|\chi_{it})<\infty$,
$\forall$ %for all 
$i$ and $t$. Also, $E|\ddot{x}_{\kappa,it}\varrho_{it}|^{2(1+\gamma)}<\infty$, where $\ddot{x}_{it}=x_{it}-B_x(w_{it})$ and $\kappa=1,\ldots,d_x$.
\end{assumption}
%
\begin{assumption}\label{asumA4}
\hfill
\vspace{-0.4cm}
\begin{itemize}
\item[a)] $w_{it}$ has compact support, $\mathbb{W}$, and its density function, $\rho_w(\cdot)$, is Lipschitz continuous and bounded away from zero, i.e., $\rho_w(w)>0$ for each $w \in \mathbb{W}$.
\item[b)] The functions $\rho_w(\cdot)$ and $g(\cdot)$ have bounded continuous derivatives up to the second order. Also, $B_x(w)$ has continuous second derivatives with respect to $w$ for $w\in\mathbb{W}$.
\end{itemize}
\end{assumption}
%
\begin{assumption}\label{asumA5}
The matrix $\Omega_x$ is nonsingular. There exists $\gamma^{\prime}>2$ such that 
\[
\sup_{w\in\mathbb{W}}\{E[\|x_{it}\|^{2\gamma'}|w_{it}=w]\}<\infty, 
\]
and $N^{(2\varepsilon-1)}h_w\rightarrow\infty$ for some $\varepsilon<1-(2+\gamma')^{-1}$.
\end{assumption}
%
\begin{assumption}\label{asumA6}
$h_w\rightarrow0$ and $NTh_w^{d_w}\rightarrow\infty$ as $N\rightarrow\infty$ and $T$ is fixed.
\end{assumption}

These assumptions are fairly standard for local linear estimation in panel data models with $T$ fix. In particular, Assumptions \ref{asumA1}, \ref{asumA4} a), and \ref{asumA5} are sufficient to show the uniform convergence of a kernel-type regression estimator (see \citet{MACK_SILVERMAN:1982}). 

We can also show the $\sqrt{NT}$-consistency of $\widehat \beta$ when both $N$ and $T$ tend to infinity. In order to do so, we replace Assumptions \ref{asumA2}, \ref{asumA3}, and \ref{asumA6} by the following ones:

\begin{assumption}\label{asumB1}
Let $\{(x_{it},w_{it},u_{it},\eta_{it}),i\geq1,t\geq 1\}$ be a set of independent and identically distributed ($i.i.d.$) random variables across the $i$ index for each fixed $t$. For each fixed $i$, the process $(x_{it},w_{it},u_{it},\eta_{it})$ is $\alpha$-mixing with $\sum_{\tau=1}^{T-1}[\alpha(\tau)]^{\gamma/(1+\gamma)}<\infty$ for some $\gamma>0$. Also, the mixing coefficient satisfies the condition $\alpha(\tau)=O(\tau^{-\vartheta})$, where $\vartheta=(2+\gamma)(1+\gamma)/\gamma$. Furthermore, $u_{it}$ and $\eta_{it}$ are independent.
\end{assumption}

\begin{assumption}\label{asumB2}
For $\ddot{x}_{it}=x_{it}-B_x(w_{it})$, $\max_{t\leq T}E|\ddot{x}_{\kappa,it}\varrho_{it}|^{2(1+\gamma)}<\infty$, for $\varrho_{it} = (u_{it}, \eta_{it})$, where $\kappa=1,\ldots,d_x$ and $\gamma>0$.
\end{assumption}

\begin{assumption}\label{asumB3}
As $(N,T)\rightarrow\infty$, $h_w\rightarrow0$ and $NTh_w^{d_w}\rightarrow\infty$.
\end{assumption}

To obtain the asymptotic distribution of the nonparametric estimator (\ref{eqII6}) we add

\begin{assumption}\label{asumD1}
As $(N,T)\rightarrow \infty$, $NT^{(\vartheta+1)/\vartheta}h_w^{d_w(2+\gamma)/(1+\gamma)}\rightarrow\infty$ for $\gamma>0$ and $\vartheta=(2+\gamma)(1+\gamma)/\gamma$.
\end{assumption}

The following theorems collect the main asymptotic properties of the estimator of the parameter of interest, $\beta$. Detailed proofs of them can be found in the Appendix A.
\begin{theorem}\label{theo1}
\hfill
\begin{itemize}
\item[(i)] Under Assumptions \ref{asumA1}-\ref{asumA6}, if $N\rightarrow\infty$ and $T$ is fixed, we have
\begin{eqnarray*}
\sqrt{NT}\left(
\widehat{\beta}-\beta\right)\overset{d}{\to}\mathcal{N}(0,\Omega_x^{-1}\Sigma_{1,\epsilon}\Omega_x^{-1}),
\end{eqnarray*}
where $\Sigma_{1,\epsilon}=\frac{1}{T}\sum_{t=1}^T\sum_{t'=1}^T\Phi_{\epsilon}
(\chi_{it},\chi_{it'})\Omega_x$.
\item[(ii)] Under Assumptions \ref{asumA1}, \ref{asumA4}-\ref{asumA5}, and \ref{asumB1}-\ref{asumB3}, if $N$ and $T$ tend to infinity, we have
 \begin{eqnarray*}
\sqrt{NT}\left(
\widehat{\beta}-\beta\right)\overset{d}{\to}\mathcal{N}(0,\Omega_x^{-1}\Sigma_{2,\epsilon}\Omega_x^{-1}),
\end{eqnarray*}
where $\Sigma_{2,\epsilon}=\displaystyle\plim_{T\rightarrow\infty}\frac{1}{T}\sum_{t=1}^T\sum_{t'=1}^T
\Phi_{\epsilon}(\chi_{it},\chi_{it'})\Omega_x$.
\end{itemize}
\end{theorem}

\begin{theorem}\label{theo2}
\hfill
\begin{itemize}
\item[(i)] Under Assumptions \ref{asumA1}-\ref{asumA6}, if $\sqrt{NTh_w^{(d_w+8)}}=O(1)$, as $N\rightarrow\infty$ and $T$ is fixed, % we have
\begin{eqnarray*}
\sqrt{NTh_w^{d_w}}\left(\widehat{g}(w;h_w)-g(w)-\frac{h_w^2\mu_2^{d_w}}{2}tr\{
\mathcal{H}_{g}(w)\}\right)\overset{d}{\to}\mathcal{N}\left(0,
\frac{\nu_0^{d_w}\Psi_{1,\epsilon}}{\rho_w(w)}\right)
\end{eqnarray*}
where $\Psi_{1,\epsilon}=\frac{1}{T}\sum_{t=1}^T\sum_{t'=1}^TE(\epsilon_{it}
\epsilon_{it'}|w_{it},w_{it'})$.
\item[(ii)] Under Assumptions \ref{asumA1}, \ref{asumA4}-\ref{asumA5}, \ref{asumB1}, and \ref{asumB3}-\ref{asumD1}, if $\sqrt{NTh_w^{(d_w+8)}}=O(1)$, as $N$ and $T$ tend to infinity, we have
\begin{eqnarray*}
\sqrt{NTh_w^{d_w}}\left(\widehat{g}(w;h_w)-g(w)-\frac{h_w^2\mu_2^{d_w}}{2}tr\{
\mathcal{H}_{g}(w)\}\right)\overset{d}{\to}\mathcal{N}\left(0,
\frac{\nu_0^{d_w}\Psi_{2,\epsilon}}{\rho_w(w)}\right)
\end{eqnarray*}
where $\Psi_{2,\epsilon}=\displaystyle\plim_{T\rightarrow\infty}\frac{1}{T}\sum_{t=1}^T\sum_{t'=1}^TE(\epsilon_{it}
\epsilon_{it'}|w_{it},w_{it'})$.
\end{itemize}
\end{theorem}


