\section{Validation, Bootstrap and Extensions}\label{secIII}
\setcounter{equation}{0}

Above we have shown that Assumptions \ref{asumAA1} and \ref{asumAA2} are sufficient to identify the parameters of interest in model (\ref{eqI1a}).
Since Assumption \ref{asumAA1} is the basic one, it would be desirable to have a testing device that checks the credibility of the crucial second one. 

\subsection{A Nonparametric Specification Test}
%Our aim here is to test for Assumption \ref{asumAA2} while maintaining Assumption \ref{asumAA1}. 

Testing Assumption \ref{asumAA2} is equivalent to testing the  hypothesis 
\begin{equation}\label{h0}
H_0: \  E\left(\left. \epsilon_{it} \right|\chi_{it}\right)  = 0 \quad \textrm{a.s}
%\end{equation} against the alternative \begin{equation}\label{h1}
   \qquad  \mbox{ against alternative }  \qquad 
H_1: \  E\left(\left. \epsilon_{it} \right|\chi_{it}\right)  \ne 0 \quad \textrm{a.s}.
\end{equation}

This is because by Assumption \ref{asumAA1}, $E\left(\left.u_{it}\right|\chi_{it}\right)=0$, but if Assumption \ref{asumAA2} is not fulfilled, $E\left(\left.\eta_{it}\right|\chi_{it}\right) \ne 0$. Thus, the alternative encompasses all the possible departures from the null model. Let $\rho_{\chi}\left(\chi_{it}\right)$ be the probability density function of $\chi \in \mathbb{R}^d$, where $d=d_x+d_w$. Under $H_0$, since $E\left(\left. \epsilon_{it} \right|\chi_{it}\right)  = 0$, we have
\begin{equation}
E\left[\epsilon_{it}E\left(\left.\epsilon_{it}\right|\chi_{it}\right)\rho_{\chi}\left(\chi_{it}\right)\right] = 0,
\end{equation}
whereas under $H_1$, since $E\left(\left.\epsilon_{it}\right|\chi_{it}\right) =
E\left[\left.m_0\left(\lambda_i,f_t\right)\right|\chi_{it}\right] - g(w_{it}) \ne 0$, we have
\begin{eqnarray}
\nonumber  E\left[\epsilon_{it}E\left(\left.\epsilon_{it}\right|\chi_{it}\right)\rho\left(\chi_{it}\right)\right] & = & E\left\{\left[E\left(\left.\epsilon_{it}\right|\chi_{it}\right)\right]^2\rho\left(\chi_{it}\right)\right\}  \\
\nonumber  & = & E\left\{\left[ E\left(\left.m_0\left(\lambda_i,f_t\right)\right|\chi_{it}\right) - g(w_{it})\right]^2\rho_{\chi}\left(\chi_{it}\right)\right\}  \ > \ 0 \ .
\end{eqnarray}

A sample analogue of $E\left[\epsilon_{it}E\left(\left.\epsilon_{it}\right|\chi_{it}\right)\rho_{\chi}\left(\chi_{it}\right)\right]$ is
%\begin{equation}\label{eqvn}
    %V_{NT} = \frac{1}{T^2N^2h^d}\sum^N_{i=1}\sum^N_{\scriptsize{\begin{array}{c} j=1 \\ j\ne i \\ \end{array}}} \sum^T_{t=1}\sum^T_{s=1} K_{it,js} \widehat{\epsilon}_{it}\widehat{\epsilon}_{js},
%\end{equation}
\begin{equation}\label{eqvn}
    V_{NT} = \frac{1}{T^2N^2h^d}\sum^N_{i=1}\sum_{j\neq i}^N \sum^T_{t=1}\sum^T_{s=1} K_{it,js} \widehat{\epsilon}_{it}\widehat{\epsilon}_{js}  \ ,
\end{equation}
where again we use a product kernel, namely
\[
K_{it,js} = K\left(\frac{\chi_{it}-\chi_{js}}{h}\right); \quad K(v) = \prod^m_{l=1}k(v_l)
\]
with $h$ being the bandwidth, and $\widehat{\epsilon}_{it}$ the residuals, i.e., $\widehat{\epsilon}_{it} = y_{it} - x^{\prime}_{it}\widehat{\beta}- \widehat{g}(w_{it};h_w)$.

To derive asymptotic properties of $V_{NT}$, the following assumptions are used.
\begin{assumption}\label{aa1}
Let $\delta_1 > 4$,  $\left(E\left|\varrho_{it}\right|^{\delta_1}\right)^{1/\delta_1} < \infty$. Given $i$, $\alpha_{\varrho}(\tau)$ is the $\alpha$-mixing coefficient of $\left\{\varrho_{it}: t\ge 1\right\}$ such that $\sum^{\infty}_{\tau=1}\tau\alpha_{\varrho}\left(\tau\right)^{(\delta_1-4)/\delta_1}<\infty$.
\end{assumption}

%\begin{assumption}\label{aa3}
%    $E\left(x_{it}x^{\prime}_{it}\right) < \infty$, %$E\left(z_{t}z^{\prime}_{t}\right) < \infty$
%    and $E\left(x_{it}z^{\prime}_{t}\right) < \infty$,
%    for $i=1,\cdots,N$ and $t=1,\cdots,T$.
%\end{assumption}
%\begin{assumption}\label{aa4}
%    $E\left(u^2_{it}x_{it}x^{\prime}_{it}\right) < \infty$, $E\left(u^2_{it}z_{t}z^{\prime}_{t}\right) < \infty$
%    and $E\left(u^2_{it}x_{it}z^{\prime}\right) < \infty$,
%    for $i=1,\cdots,N$ and $t=1,\cdots,T$.
%\end{assumption}
Then the asymptotic distribution under the null and the power of our test are given by the following theorems.
%
\begin{theorem}\label{theo5}
    Under Assumptions \ref{asumA1}, \ref{asumA4}-\ref{asumA5}, \ref{asumB1}, \ref{asumB3}-\ref{asumD1} and \ref{aa1}, if $h \rightarrow 0$, $NTh^d\rightarrow \infty$ and
    $\left(NT\right)^{d/d+4}h^{d/2}\left(\mathrm{log}NT\right)^{4/d+4}\rightarrow 0$, as $N$ and $T$ tend to infinity, then under the null hypothesis (\ref{h0}), we have
    \begin{equation}\label{eqad}
        NTh^{d/2}V_{NT}/\widehat\upsilon_0 \overset{d}{\to}\mathcal{N} \left(0,1\right),
    \end{equation}
    where
%\begin{equation}\label{eqavv}
%\widehat\upsilon^2_0 = \frac{2}{N^2T^2h^d}\sum^N_{i=1}\sum^N_{\scriptsize{\begin{array}{c} j=1 \\ j\ne i \\ \end{array}}} \sum^T_{t=1}\sum^T_{s=1}K^2_{it,js}\widehat{\epsilon}^2_{it}\widehat{\epsilon}^2_{js} ,
%\end{equation}
\begin{equation}\label{eqavv}
\widehat\upsilon^2_0 = \frac{2}{N^2T^2h^d}\sum^N_{i=1}\sum_{j\neq i}^N \sum^T_{t=1}\sum^T_{s=1}K^2_{it,js}\widehat{\epsilon}^2_{it}\widehat{\epsilon}^2_{js}
\end{equation}
is a consistent estimator of the asymptotic variance of $NTh^{d/2}V_{NT}$, i.e.,
  \begin{equation}\label{eqav}
      \upsilon^2_0 = \lim_{T\rightarrow\infty}\frac{2}{T^2h^{d}}\sum^T_{t=1}\sum^T_{s=1}E\left(K^2_{1t,2s}\epsilon^2_{1t}\epsilon^2_{2s}\right).
  \end{equation}
\end{theorem}

\begin{theorem}\label{theo6}
    Under Assumptions \ref{asumA1}, \ref{asumA4}-\ref{asumA5}, \ref{asumB1}, \ref{asumB3}-\ref{asumD1} and \ref{aa1}, if $h \rightarrow 0$, $NTh^d\rightarrow \infty$, and
    $\left(NT\right)^{d/d+4}h^{d/2}\left(\mathrm{log}NT\right)^{4/d+4}\rightarrow 0$, as $N$ and $T$ tend to infinity, then under the alternative $H_1$, we have
    \begin{equation}\label{eqad2}
       \textrm{Pr}\left\{NTh^{d/2}V_{NT}/\widehat{\upsilon}_0 \ge \delta_{NT}\right\} \rightarrow 1,
    \end{equation}
where $\delta_{NT}$ is any non-stochastic positive sequence such that $\delta_{NT} = o\left(NTh^{d/2}\right)$.
\end{theorem}

While on a first glimpse this seems to be an extremely strong result, indicating one could fully validate by a data-driven specification test the key identification condition, some caution is recommended. 
In fact, it is known that this type of identification conditions cannot be fully tested; instead one resorts to tests that give or rest credibility to the condition in question. In our case, for instance, it is not hard to see that under $H_1$, the power of our test hinges on the parts of $\eta$ that are either nonlinear in $x$ or reflect interactions between $x$ and $w$.  
Specifically, the stronger these are emphasized, the easier we reject, else we may not. This tells us how and when we can detect violations of Assumption \ref{asumAA2}. 


\subsection{Bootstrap and Bandwidth}
The asymptotic results for our estimators and test statistic are very helpful in showing consistency and convergence rate, and to better understand its statistical behavior. Nevertheless, it is less helpful for doing further inference in finite samples because estimates of those first-order asymptotic bias and variance are quite poor approximates in practice. A commonly employed remedy are resampling methods. This suggests using the so-called wild bootstrap, see \cite{MAMMEN:1992}. Apart from being consistent for statistics based on local estimators like ours, it accounts for potential heteroscedasticity and allows us to accommodate nonparametric dependence structures in the error term. Recall that we only require independence for given $t$ but not between errors referring to the same individual.

First calculate $\widehat{\beta}$ and $\widehat{g}(w_{it})$ for all $w_{i,t}$ of the sample, obtaining residuals $\widehat{\epsilon}_{it}$.
Next, for the given sample of regressors $\{ \chi_{it} = (x'_{it},w'_{it})' \}_{i=1,t=1}^{N,T}$, generate bootstrap output samples $\{ y_{it}^{*,b} \}_{i=1,t=1}^{N,T}$ by drawing $\vartheta_i^b \stackrel{i.i.d.}{\sim} N(0,1)$ for $b=1,\ldots,B$ and setting
\begin{eqnarray}\label{eqboot}
 y_{it}^{*,b} &:=&  x'_{it}\widehat{\beta} + \widehat{g}(w_{it}) +
 \widehat{\epsilon}_{it} \vartheta_i^b \ .
\end{eqnarray}
It is easy to see that $E[\widehat{\epsilon}_{it} \vartheta_i^b] =0$, $Cov[\widehat{\epsilon}_{it} \vartheta_i^b, \widehat{\epsilon}_{js} \vartheta_j^b] = Cov[\widehat{\epsilon}_{it},\widehat{\epsilon}_{js}]$, for all $i$ and $j=1,\ldots,N$, $t$ and $s=1,\ldots,T$, i.e., the first two moments and dependence is maintained in the bootstrap. Third, calculate $\widehat{\beta}^{*,b}$ and $\widehat{g}^{*,b}(w_{it})$ for all bootstrap samples $b=1,\ldots,B$. Their sample means and variances give the bootstrap estimates of bias and variance of our estimators.

In the same way one can calculate bootstrap p-values for the test by comparing $V_{NT}/\widehat{\upsilon}_0$ with its bootstrap analogs $V_{NT}^{*,b}/\widehat{\upsilon}_0^{*,b}$. Note that the bootstrap samples are generated under the null hypothesis such that the bootstrap analogs follow approximately the finite sample distribution of $V_{NT}/\widehat{\upsilon}_0$ under $H_0$. Consequently, the p-value is the proportion of bootstrap statistics bigger than the original one.

For bootstrap tests, it is often recommended to employ in (\ref{eqboot})
residuals $\widehat{\epsilon}_{it}$ obtained under the alternative. On the one hand, it is supposed this increased the power of the test, but in practice, this tends to produce over-rejection  \citep{SPERLICH:2014}. In our case, it is not even clear what a good predictor of residuals under the alternative could be. Therefore we stick to the former, more common practice of using the residuals obtained under $H_0$.

Regarding the bandwidth choice for estimation, it is to be noted that from a theoretical point of view, there does not exist a 'generally optimal' bandwidth since what is 'optimal' depends on the specific objective. More precisely, for estimating $\widehat{\beta}$ a different bandwidth is optimal than for estimating $\widehat{g}(w_{it})$, and both are different from the optimal testing bandwidths, not to mention the bandwidths optimal for generating the bootstrap samples \citep{SPERLICH:2014}. If the null hypothesis is non- or semiparametric, as it is in our case, then it can become quite tedious to calibrate the test along all those different bandwidth choices as it is noted in \citet{RODRIGUEZ-POO_SPERLICH_VIEU:2015}. In practice, we should be pragmatic and prefer a method that delivers reasonable estimates and provides a well-functioning test procedure. Consequently, we abstain here from the search for optimal bandwidths but propose a simple and computationally attractive solution. Then, it is helpful to recall that typically, the main interest is in $\beta$, not in function $g(\cdot)$. With this focus in mind, it turns out (see our simulations) that Silverman's rule-of-thumb, though invented for density estimation, is very useful in this context. When using for $k(\cdot )$ the Epanechnikov kernel, then the proposed bandwidth is $h_{w}=2.345\widehat{\sigma}_w(NT)^{-1/5}$, with $\widehat{\sigma}_w$ being the sample standard deviation of $w_{it}$. For more sophisticated bandwidth selection procedures, e.g., to estimate $g(\cdot )$ in an optimal way, we refer to the review of \cite{KOEHLER_SCHINDLER_SPERLICH:2014}.

