\textbf{Proof of Theorem \ref{theo1}:} Write (\ref{eqI1a}) in vectorial form and plug the resulting expression in (\ref{eqII5}), the expression to analyze the asymptotic properties of $\widehat{\beta}$ becomes
\begin{eqnarray}\label{eqA1}
\sqrt{NT}\left(
\widehat{\beta}-\beta\right)=[(NT)^{-1}\widetilde{X}^{\prime}\widetilde{X}]^{-1}\frac{1}{\sqrt{NT}}\widetilde{X}^{\prime}(I_{NT}-S)\left[m_0(\lambda,F)+U\right].\qquad
\end{eqnarray}
%
Using the results in Lemma S3.1 and the Law of Large Numbers (LLN), $(NT)^{-1}\widetilde{X}^{\prime}\widetilde{X}\overset{p}{\to}\Omega_x$ and the numerator term to be analyzed can be written as
\begin{eqnarray}\label{eqA2}
(NT)^{-1/2}\widetilde{X}^{\prime}(I_{NT}-S)\left[m_0(\lambda,F)+U\right]= \frac{1}{\sqrt{NT}}\sum_{i=1}^N\sum_{t=1}^T\{x_{it}-B_x(w_{it})\}\epsilon_{it}+o_p(1),\qquad
\end{eqnarray}
where $\epsilon_{it}=m_0\left(\lambda_i,f_t\right)-g(w_{it})+u_{it}$. Under Assumptions \ref{asumA1}-\ref{asumA3}, and using the properties of the law of iterated expectations (LIE), it is easy to show that
\begin{align*}
&E[(NT)^{-1/2} \sum_{it}\{x_{it}-B_x(w_{it})\}\epsilon_{it}] = 0
\qquad \text{ and } \\
&Var[(NT)^{-1/2}\sum_{it}\{x_{it}-B_x(w_{it})\}\epsilon_{it}]=\Sigma_{1,\epsilon}.
\end{align*}
%
Therefore, using the above results we can conclude that
\begin{eqnarray}\label{eqA3}
Var\left[\sqrt{NT}\left(
\widehat{\beta}-\beta\right)\right]=\Omega_x^{-1}\Sigma_{1,\epsilon}\Omega_x^{-1}\{1+o_p(1)\}.
\end{eqnarray}
%
To finish the proof of the theorem we have to consider the asymptotic distribution of the stochastic term of (\ref{eqA1}). When $T$ is fixed, we use the Lindeberg-Feller Central Limit Theorem (CLT) for $i.i.d.$ random variables so we can conclude
\begin{eqnarray}\label{eqA4}
\sqrt{NT}\left(
\widehat{\beta}-\beta\right)\overset{d}{\to}\mathcal{N}(0,\Omega_x^{-1}\Sigma_{1,\epsilon}\Omega_x^{-1}).
\end{eqnarray}
%
On its part, considering the case in which $T\rightarrow\infty$, we employ the Cram\'er-Wold device. Let $\varpi_{At}=N^{-1/2}\sum_{i=1}^N\imath^{\prime}\ddot{X}_{i\cdot}\epsilon_{i\cdot}$ for any unit vector in $\imath\in\mathbb{R}^{d_x}$, where $\ddot{X}_{i\cdot}$ is a $T\times d_x$ matrix whose $t$-th element is such as $\ddot{x}_{it}=x_{it}-B_x(w_{it})$, and let $\epsilon_{i\cdot}\equiv(\epsilon_{i1},\ldots,\epsilon_{iT})$ be a $T\times 1$ vector. Then we can write
\begin{eqnarray*}
(NT)^{-1/2}\sum_{i=1}^N\sum_{t=1}^T\{x_{it}-B_x(w_{it})\}\epsilon_{it}=T^{-1/2}\sum_{t=1}^T\varpi_{At}.
\end{eqnarray*}
%
By Assumption \ref{asumB1}, $\{x_{it}-B_x(w_{it})\}\epsilon_{it}$ is a $\mathbb{R}^{d_x}$-stationary $\alpha$-mixing sequence, and by Assumptions \ref{asumA3}-\ref{asumA4} and \ref{asumB1}-\ref{asumB3}, the Theorem $1.5$ of \citet{BOSQ:1998}, pag.$34$, gives
\begin{eqnarray*}
Var\left(\frac{1}{\sqrt{T}}\sum_{t=1}^T\varpi_{At}\right)
=\plim_{T\rightarrow\infty}\frac{1}{T}\imath^{\prime}E[\ddot{X}_{i\cdot}\epsilon_{i\cdot}\epsilon_{i\cdot}^{\prime}\ddot{X}_{i\cdot}^{\top}]\imath+o_p(1) \ .
\end{eqnarray*}
A direct application of the CLT for strongly mixing processes (see Theorem $1.7$ in \citet{BOSQ:1998}, pag. $36$) gives
\begin{eqnarray*}
\frac{1}{\sqrt{T}}\sum_{t=1}^T\varpi_{At}\overset{d}{\to}\mathcal{N}(0,\imath^{\top}\Sigma_{2,\epsilon}\imath)\quad\textrm{as}\quad N,T\rightarrow\infty.
\end{eqnarray*}
%
Finally, combining the above results with the Slutsky theorem concludes the proof.
 \hfill$\square$\\

\textbf{Proof of Theorem \ref{theo2}}
Writing (\ref{eqI1a}) in vectorial form, and replacing the resulting expression in (\ref{eqII6}), the Taylor expansion gives
\begin{eqnarray}\label{eqA5}
\nonumber&&\sqrt{NTh_w^{d_w}}\{\widehat{g}(w;h_w)-g(w)\}\\
\nonumber&&-\sqrt{NTh_w^{d_w}}(1,0_{d_w})[\mathcal{W}^{\prime}K_w\mathcal{W}]\mathcal{W}^{\prime}K_w[Q_w(w)+\mathcal{R}_w(w)-X(\widehat{\beta}-\beta)]\\
&&=\sqrt{NTh_w^{d_w}}(1,0_{d_w})[\mathcal{W}^{\prime}K_w\mathcal{W}]\mathcal{W}^{\prime}K_w\epsilon,
\end{eqnarray}
where $Q_w(w)=\frac{1}{2}[(w_{11}-w)^{\prime}\mathcal{H}_g(w)(w_{11}-w),\ldots,(w_{NT}-w)^{\prime}\mathcal{H}_m(w)(w_{NT}-w)]^{\prime}$, $\mathcal{R}_w(w)$ is the residual term of the Taylor expansion, and $\epsilon\equiv(\epsilon_{11},\ldots,\epsilon_{NT})$ is a $NT\times 1$ vector. In the following, we prove that the terms on the left-hand side of (\ref{eqA5}) contribute to the asymptotic bias, whereas the term on the right-hand side is asymptotically normal.

Focusing on the behavior of the inverse term, and following a similar proof scheme as in \citet{SOBERON_MUSOLESI_RODRIGUEZ-POO:2023} or \citet{CAI_LI:2008}, under Assumptions \ref{asumA1}-\ref{asumA4} it can be  shown
\begin{eqnarray}\label{eqA6}
(NT)^{-1}\mathcal{W}^{\prime}K_w\mathcal{W}=\left(\begin{array}{cc}
\rho_w(w)+o_p(1) &h_w^2\mu_2^{d_w}D_{\rho}(w)+o_p(h_w^2)\\
h_w^2\mu_2^{d_w}D_{\rho}(w)+o_p(h_w^2) &h_w^2\mu_2^p\rho_w(w)I_{d_w}+o_p(h_w^2)
\end{array}\right), 
\end{eqnarray}
with $I_{d_w}$ the $d_w\times d_w$ identity matrix, and $D_{\rho}(w)$ the vector of first-order derivatives of $\rho_w$.

Similarly, following the proof for Lemma B2 in \citet{SOBERON_MUSOLESI_RODRIGUEZ-POO:2023}, and with $\sqrt{NT}$-consistency of $\widehat{\beta}$, using the Cram\'er-Wold device it can be shown that the asymptotic bias of $\widehat{g}(w;h_w)$ is of the form
\begin{eqnarray}\label{eqA7}
\nonumber&&\sqrt{NTh_w^{d_w}}(1,0_{d_w})[\mathcal{W}^{\prime}K_w\mathcal{W}]\mathcal{W}^{\prime}K_w[Q_w(w)+\mathcal{R}_w(w)-X(\widehat{\beta}-\beta)]\\
&&=\frac{\mu_2^{d_w}}{2}tr\{h_w^2\mathcal{H}_g(w)\}+O_p(h_w^2)+o_p\left(\frac{1}{\sqrt{NTh_w^{d_w}}}\right)  .
\end{eqnarray}
%
Considering now the variance term of $\widehat{g}(w;h_w)$, under Assumptions \ref{asumA1}-\ref{asumA3}, and using the LIE, it can be proved $E[(NT)^{-1}\mathcal{W}^{\prime}K_w\epsilon]=0$ and
\begin{eqnarray}\label{eqA8}
\nonumber &&NTh_w^{d_w}Var[(NT)^{-1}\mathcal{W}^{\prime}K_w\epsilon]\\
&&=\left(\begin{array}{cc}
\nu_0^{d_w}\rho_w(w)\frac{1}{T}\sum_{tt'}E(\epsilon_{it}\epsilon_{it'}|w_{it},w_{it'}) &O_p(h_w^{d_w})\\
O_p(h_w^{d_w}) &h_w^2\nu_2^{d_w}\rho_w(w)\frac{1}{T}\sum_{tt'}E(\epsilon_{it}\epsilon_{it'}|w_{it},w_{it'})    \end{array}\right).  \qquad\quad  
\end{eqnarray}
%
Using (\ref{eqA6}) and (\ref{eqA8}), the Slutsky theorem enables us to conclude that the variance term of $\widehat{g}(w;h_w)$ when $T$ is fixed and $N\rightarrow\infty$, is
\begin{eqnarray}\label{eqA9}
Var\{\widehat{g}(w;h_w)\} = \frac{\nu^{d_w}\Psi_{1,\epsilon}}{NT^2h_w^{d_w}\rho_w(w)}\{1+o_p(1)\} ,
\end{eqnarray}
and the corresponding variance for $N$ and $T$ large is such that
\begin{eqnarray}\label{eqA10}
Var\{\widehat{g}(w;h_w)\} = \frac{\nu^{d_w}\Psi_{2,\epsilon}}{NTh_w^{d_w}\rho_w(w)}\{1+o_p(1)\}  .
\end{eqnarray}
%
To conclude the asymptotic properties of $\widehat{g}_w(w;h_w)$ we need to establish  asymptotic normality for $\sqrt{NTh_w^{d_w}}(NT)^{-1}\mathcal{W}^{\prime}K_w\epsilon$. To this end, when $T$ is fixed and $N\rightarrow\infty$ we employ the Minkowski inequality to check that the Lyapunov condition holds, and the first part of Theorem \ref{theo2} is proved. Finally, when $N$ and $T$ are large, then we follow a similar proof scheme as in \citet{SOBERON_MUSOLESI_RODRIGUEZ-POO:2023}. Therefore, by employing the Cram\'er-Wold device and the Doob's small-black and large-block technique for $\alpha$-mixing processes, we can conclude that the second part of Theorem \ref{theo2} is proven too.
 \hfill$\square$\\

\textbf{Proof of Theorem \ref{theo5}} \label{secA}
The test statistic (\ref{eqvn}) can be rewritten as
\begin{equation}\label{eqa1}
    V_{NT} = \frac{1}{N^2T^2h^d}\sum^N_{i=1}\sum^N_{ j=1, j\ne i }\widehat{\epsilon}_{i\cdot}^{\prime} \mathbf{K}_{ij}\widehat{\epsilon}_{j\cdot},
\end{equation}
where, for $i=1,\cdots,N$ and $j=1,\cdots,N$, $\widehat{\epsilon}_{i\cdot}= \left(\widehat{\epsilon}_{i1},\cdots,\widehat{\epsilon}_{iT} \right)^{\prime}$ and
\begin{equation*}
\mathbf{K}_{ij} = \left(\begin{array}{ccc}
    K_{i1,j1} & \cdots & K_{i1,jT} \\
   \vdots  &  \cdots  &  \vdots \\
    K_{iT,j1} & \cdots & K_{iT,jT}
\end{array}\right).
\end{equation*}
Then, if we substitute (\ref{eqI1b}) into $\widehat{\epsilon}_{i\cdot} = y_{i} - X_{i\cdot}\widehat{\beta} - \widehat{g}(w_{i\cdot};h_w)$ we obtain $\widehat{\epsilon}_{i\cdot} = \epsilon_{i\cdot}  - \left\{ \widehat{g}(w_{i\cdot};h_w) - g(w_{i\cdot}) \right\}
- X_i(\widehat{\beta}-\beta)$, where $\widehat{g}(w_{i\cdot};h_w) = \left(\widehat{g}(w_{i1};h_w),\cdots,\widehat{g}(w_{iT};h_w)\right)^{\prime}$,  
$g(w_{i\cdot}) = \left(g(w_{i1}),\cdots,g(w_{iT})\right)^{\prime}$,
$\epsilon_{i\cdot} = \left(\epsilon_{i1},\cdots,\epsilon_{iT}\right)^{\prime}$, and $X_{i\cdot}$ is a $T\times d_x$ matrix, for $i=1,\cdots,N$.

The statistic (\ref{eqvn}) can be decomposed into the following six parts:
\begin{eqnarray*}
    V_{NT} =  \frac{1}{N^2T^2h^d}\sum^N_{i=1}\sum_{j\neq i}^N\widehat{\epsilon}_{i\cdot}^{\prime} \mathbf{K}_{ij}\widehat{\epsilon}_{j\cdot}    &=&  % \\ & = &
    \frac{1}{N^2T^2h^d}\sum^N_{i=1}\sum_{j\neq i}^N\epsilon_{i\cdot}^{\prime} \mathbf{K}_{ij}\epsilon_{j\cdot} \\
    & + & (\widehat\beta-\beta)^{\prime}\left\{\frac{1}{N^2T^2h^d}\sum^N_{i=1}\sum_{j\neq i}^N X^{\prime}_i\mathbf{K}_{ij}X_j\right\}(\widehat\beta-\beta) \\
    & + & \frac{1}{N^2T^2h^d}\sum^N_{i=1}\sum_{j\neq i}^N \left(\widehat{g}(w_{i\cdot};h_w)-g(w_{i\cdot})\right)^{\prime}\mathbf{K}_{ij}\left(\widehat{g}(w_{j\cdot};h_w)-g(w_{j\cdot})\right) \\
    & - & \frac{2}{N^2T^2h^d}\sum^N_{i=1}\sum_{j\neq i}^N \epsilon^{\prime}_{i\cdot} \mathbf{K}_{ij}X_{j\cdot}(\widehat\beta-\beta) \\
    & - & \frac{2}{N^2T^2h^d}\sum^N_{i=1}\sum_{j\neq i}^N\epsilon^{\prime}_{i\cdot} \mathbf{K}_{ij}\left(\widehat{g}(w_{j\cdot};h_w)-g(w_{j\cdot})\right) \\
    & - & 2(\widehat\beta-\beta)^{\prime}\left\{\frac{1}{N^2T^2h^d}\sum^N_{i=1}\sum_{j\neq i}^NX^{\prime}_i \mathbf{K}_{i,j} \left(\widehat{g}(w_{j\cdot};h_w)-g(w_{j\cdot})\right)\right\} .
    \end{eqnarray*}
Hence, $V_{NT}$ can be rewritten as
\begin{equation}
    V_{NT} \equiv V_{1,NT} + V_{2,NT} + V_{3,NT} - 2V_{4,NT} - 2V_{5,NT} - 2V_{6,NT}.
\end{equation}
Under the null, we will show that $NTh^{d/2}V_{1,NT}$, conditional on $f_1,\cdots,f_T$, is normally distributed, and $NTh^{d/2}V_{l,NT} = o_p(1)$ for $l=2,\cdots,6$. By applying Lemmas 3.2 and 3.3 from the Supplement we obtain the desired result.
%
\hfill$\square$\\

\textbf{Proof of Theorem \ref{theo6}} \label{secB}

Following the same lines as in the proof of Theorem \ref{theo5}, 
\begin{eqnarray*}
    V_{NT} & = & \frac{1}{N^2T^2h^d}\sum^N_{i=1}\sum_{j\neq i}^N\widehat{\epsilon}_{i\cdot}^{\prime} \mathbf{K}_{ij}\widehat{\epsilon}_{j\cdot} \\
    & = & \frac{1}{N^2T^2h^d}\sum^N_{i=1}\sum_{j\neq i}^N\epsilon_{i\cdot}^{\prime} \mathbf{K}_{ij}\epsilon_{j\cdot} + o_p(1/NTh^{d/2})
    \equiv  % \\ & \equiv &
    V_{1,NT} + o_p(1/NTh^{d/2})  .
\end{eqnarray*}
%
Recall that
\begin{eqnarray*}
TV_{1,NT} & = & \frac{N-1}{N}\left\{\frac{2}{N(N-1)}\sum^N_{i=1}\sum_{i<j}^N \frac{1}{Th^d} \epsilon_{i\cdot}^{\prime} \mathbf{K}_{ij}\epsilon_{j\cdot}\right\}   \equiv  % \\ & \equiv &
\frac{N-1}{N}\mathbb{U}_N  ,
\end{eqnarray*}
where
\begin{equation}
    \mathbb{U}_N = \frac{2}{N(N-1)} \sum^N_{i=1}\sum_{i<j}^N\mathbb{H}_{NT}\left(\zeta_i,\zeta_j\right),
\end{equation}
for $\zeta_i = \left(\chi_i,\epsilon_i\right)$ for $i=1,\cdots,N$, and
\begin{eqnarray}
    \mathbb{H}_{NT}\left(\zeta_i,\zeta_j\right) & = & \frac{1}{Th^d} \epsilon_{i\cdot}^{\prime} \mathbf{K}_{ij}\epsilon_{j\cdot}      = % \\  & = &
    \frac{1}{Th^d} \sum^T_{t=1}\sum^T_{s=1}K_{it,js}\epsilon_{it}\epsilon_{js}.
\end{eqnarray}
%
Like in the proof of Theorem \ref{theo5}, we execute the analysis conditional on the factors $\mathcal{D}_f=\left\{f_t: t=1,\cdots,T\right\}$. By doing so, we get independence among different cross-sectional units.

From the proof of Theorem \ref{theo5} we have that
\[
E_{\mathcal{D}_f}\left[\left\|\mathbb{H}_{NT}\left(\zeta_i,\zeta_j\right)\right\|^2\right] = O\left(\frac{1}{h^d}\right) = O\left(\frac{N}{Nh^d}\right) = o(N) ,
\]
because $Nh^d\rightarrow \infty$. Then, applying Lemma 3.1 of \citet{POWELL_STOCK_STOKER:1989} we obtain
\[
\mathbb{U}_N = E_{\mathcal{D}_f}\left[\mathbb{H}_{NT}\left(\zeta_i,\zeta_j\right)\right] + o_p(1)  .
\]
%
Since
\begin{eqnarray*}
E\left[\left.\mathbb{H}_{NT}\left(\zeta_i,\zeta_j\right)\right|\zeta_i\right]
& = & \frac{1}{Th^d}\sum^T_{t=1}\sum^T_{s=1}\epsilon_{it}E\left[K\left(\frac{\chi_{it}-\chi_{js}}{h_1}\right)E\left(\left.\epsilon_{js}\right|\chi_{js}\right)\right] \\
& = & \sum^T_{t=1}\epsilon_{it}\left\{E\left(\left.m_0\left(\lambda_i,f_t\right)\right|\chi_{it}\right)-g\left(w_{it}\right)\right\}\rho_{\chi}\left(\chi_{it}\right),
\end{eqnarray*}
one has
\begin{eqnarray*}
E_{\mathcal{D}_f}\left[\mathbb{H}_{NT}\left(\zeta_i,\zeta_j\right)\right] & = &
E_{\mathcal{D}_f}\left[E\left[\left.\mathbb{H}_{NT}\left(\zeta_i,\zeta_j\right)\right|\zeta_i\right]\right] \\
& = & \sum^T_{t=1}E_{\mathcal{D}_f}\left[\left\{E\left(\left.m_0\left(\lambda_i,f_t\right)\right|\chi_{it}\right)-g\left(w_{it}\right)\right\}^2\rho_{\chi}\left(\chi_{it}\right)\right]  .
\end{eqnarray*}
%
Therefore, under $H_1$,
\[
V_{1,NT} = \frac{1}{T}\sum^T_{t=1}E_{\mathcal{D}_f}\left[\left\{E\left(\left.m_0\left(\lambda_i,f_t\right)\right|\chi_{it}\right)-g\left(w_{it}\right)\right\}^2\rho_{\chi}\left(\chi_{it}\right)\right] + o_p(1).
\]
\hfill$\square$\\


