\section{Proof of Proposition \ref{lq_control}}\label{app:hjb}


\noindent The unconstrained HJB equation in Section \ref{sec:3} Proposition \ref{lq_control} is  given by:
\begin{equation}\label{HJB_proof}
\partial_t \bar{V}+\inf _{\bar{b}\in \mathcal{R}} \left\{\alpha_t  (m-x)\partial_X \bar{V} +\bar{b}\partial_{I}\bar{V}+\frac{1}{2} \sigma_t^2 x \cdot(\Xmax - x)\partial_{XX} \bar{V}+(x- \bar{b}-M_t)^2 + c_1 \bar{b}^2+ c_2 ({\iota}-I_m)^2\right\}=0, 
\end{equation}  
with terminal condition  $\bar{V}(T,x,\iota) = \mathcal{P} (\iota - I_{\text{target}})^2$. Since the value function is quadratic in $x, \iota$ with interaction terms, we can derive an analytical formulation for the optimal control and $\bar{V}$. 

The first-order condition of $\bar{b}$ in \eqref{HJB_proof} is:
\begin{equation}\label{bbar}
    \bar{b} = \kappa (x-M_t) - \frac{\kappa}{2} (\partial_{I} \bar{V}),
\end{equation}
where $\kappa = \frac{1}{1+c_1}$.
Plugging back into \eqref{HJB_proof} yields
\begin{align*}
    &\partial_t \bar{V} 
    + \alpha_t(m-x) \partial_X \bar{V} 
    + \left[\kappa (x-M_t) - \frac{\kappa}{2} \partial_{I} \bar{V}\right] \partial_{I} \bar{V} 
    + \frac{1}{2}\sigma_t^2 x \cdot(\Xmax - x)\partial_{XX} \bar{V} 
     + \\ & \quad \left[(x-M_t) - \kappa (x-M_t) + \frac{\kappa}{2} \partial_{I} \bar{V} \right]^2 
     + c_1 \left[\kappa (x-M_t) - \frac{\kappa}{2} (\partial_{I} \bar{V})\right]^2 
    + c_2 (\iota-I_m)^2 = 0.
\end{align*}
Expanding and simplifying  we end up with 
\begin{align*}
    \partial_t \bar{V} 
    + \left(1- \kappa \right)(x-M_t)^2 
    + c_2 (\iota-I_m)^2 
    - \alpha_t (x-m) \partial_{X} \bar{V} 
    + \kappa (x-M_t) \partial_I \bar{V} 
    - \frac{\kappa}{4} \left(\partial_{I} \bar{V}\right)^2 
    + \frac{1}{2}\sigma_t^2 \partial_{XX} \bar{V}=0.
\end{align*}
We rewrite $x-M_t = (x-m) + (m-M_t)$ to yield:
\begin{align*}
\partial_t \bar{V} &+ (1 - \kappa)(x - m)^2 + 2(1 - \kappa)(m - M_t)(x - m) + (1 - \kappa)(m - M_t)^2 \\
&+ c_2(\iota - I_m)^2 - \alpha_t(x - m)\partial_X V + \kappa(x - m)\partial_I \bar{V} + \kappa(m - M_t)\partial_I V \\
&- \frac{\kappa}{4}(\partial_I \bar{V})^2 + \frac{1}{2}\sigma_t^2 x \cdot(\Xmax - x)\partial_{XX} \bar{V} = 0.
\end{align*}

We solve the PDE by proposing the ansatz
\begin{equation}\label{v_ansatz}
\begin{aligned}
\bar{V}(t, x, \iota) &= P_1(t)(\iota - I_m)^2 + P_2(t)(\iota - I_m)(x - m) + P_3(t)(x - m)^2 \\
&\quad + P_4(t)(\iota - I_m) + P_5(t)(x - m) + P_6(t)
\end{aligned}
\end{equation}
for functions of time $P_j(t), j=1,\ldots, 6$ to be determined. Substituting back and gathering terms we get 


\begin{align*}
&\dot{P_1}(t)(\iota - I_m)^2 + \dot{P_2}(t)(\iota - I_m)(x-m) + \dot{P_3}(t)(x-m)^2 + \dot{P_4}(t)(\iota - I_m) + \dot{P_5}(t)(x-m) + \dot{P_6}(t) \\
&+ (1-\kappa)(x-m)^2 + 2(1-\kappa)(m-M_t)(x-m) + (1-\kappa)(m-M_t)^2 + c_2(\iota - I_m)^2 \\
& - \alpha_t(x-m)\left[P_2(t)(\iota - I_m) + 2P_3(t)(x-m) + P_5(t)\right] \\
& + \kappa(x-m)\left[2P_1(t)(\iota - I_m) + P_2(t)(x-m) + P_4(t)\right] \\
& + \kappa(m-M_t)\left[2P_1(t)(\iota - I_m) + P_2(t)(x-m) + P_4(t)\right] \\
& - \frac{\kappa}{4}\left(2P_1(t)(\iota - I_m) + P_2(t)(x-m) + P_4(t)\right)^2   + \sigma_t^2P_3(t) x \cdot(\Xmax - x) = 0.
\end{align*}

Since the basis $\{(x-m)^2,(x-m)(\iota - I_m),(\iota - I_m)^2, (x-m),(\iota - I_m),1\}$ is linearly independent, we must have the respective coefficients identically zero, which yields the system of Riccati ODEs for $P_1(t),\ldots, P_6(t)$ on $t \in [0,T]$ in \eqref{eq:ricatti}.

The terminal condition of the ODEs above are found by matching with terminal cost $g(\iota) = \mathcal{P}(\iota- \iota_{
\text{target}})^2$. By solving the ODEs , we get the analytical form of our value function \eqref{v_ansatz}. See \citeA{Drissi_2022} for resolvability of differential Riccati systems. The optimal control is of the form:

\begin{equation}\label{bbar_riccati}
    \bar{b}(t,x,\iota) = \kappa (x-M_t) -\kappa P_1(t) (\iota - I_m) -\frac{\kappa}{2}P_2(t) (x-m) -\frac{\kappa}{2}P_4(t).
\end{equation}

\begin{remark} When $I_{target} = I_{m}$ and $\tilde{m}_k = m$, the linear terms in $\bar{V}$ disappear as $P_4$ and $P_5$ become degenerate. The solution to the optimal control problem in this case can be found in Section \ref{ssec:4.5}. When $M_t = m$ only, the linear term with respect to $(x-m)$ in $\bar{V}$ disappears. However, in the case $\iota_{target} = \iota_{m}$ only, none of the terms simplify due to the presence of $\kappa(m - M_t)\partial_I V$ in the PDE.
\end{remark}


