    \centering
    \includegraphics[width=6cm]{fig1.pdf}
    \caption{Geometry of the stationary wave crest of linear radiation outside the Mach cone. The group velocity $\nabla_{\bk}\omega(\bk)$ of the wave is compensated by the flow velocity $\bu$. The angle $\eta$ determines the direction of the wave vector $\bk$ and $\textbf{r}$ is the radius-vector of the point $P(x,y)$.}
    \label{fig1}
\end{figure}

It is clear that the stationary wave pattern can only be generated by a supersonic flow $M>1$ (or $u_0> c_0$), when the corresponding component of the flow velocity can compensate for wave propagation. A typical wave crest is shown in Fig.~\ref{fig1} for the flow incoming from the right. In a stationary wave generated by the flow past an obstacle, the wave vector is equal to the gradient of the phase $\theta$ of the wave, whereas the frequency must be equal to zero:	
\begin{equation} \label{eq9}
    \mathbf{k} = \nabla \theta,  \quad  G(k_y, k_x) = \omega = 0.
\end{equation}
Consequently, the equality of the cross-derivatives gives the equation	
\begin{equation} \label{eq10}
    \frac{\partial k_y}{\partial x} = \frac{\partial k_x}{\partial y}.
\end{equation}
The function $k_x = f(k_y)$ is defined in implicit form by the second Eq.~(\ref{eq9}), so we can rewrite Eq.~(\ref{eq10}) as an equation for $k_y$:
\begin{equation} \label{eq11}
\frac{\partial k_y}{\partial x} - f'(k_y) \frac{\partial k_y}{\partial y} = 0.
\end{equation}
It is known as the Hopf equation and its theory is well developed (see, e.g., Ref.~\cite{whitham-75}). It is clear that $k_x$ and $k_y$ are constant along characteristic curves which satisfy the equation
\begin{equation} \label{eq12}
    \frac{d y}{d x} = -f'(k_y).
\end{equation}
We are interested in the wave pattern far enough from a small obstacle, so we can take an obvious self-similar solution of this equation with characteristics stemming from the origin,
\begin{equation}\label{eq13}
    \frac{y}{x} = -f'(k_y).
\end{equation}
Then the definition of the derivative of the function defined implicitly yields
%	Moreover, we can compare the solution obtained in Eq.\eqref{eq13}, with the differential of $G(\bar{k}_y, \bar{k}_x(\bar{k}_y))$ with respect to $\bar{k}_y$,
%	\begin{equation} \label{eq14}
%		\frac{dG}{d\bar{k}_y} = \frac{\partial G}{\partial \bar{k}_y} + f'(\bar{k}_y) \frac{\partial G}{\partial \bar{k}_x} = 0,
%	\end{equation}
%	isolating $f'(\bar{k}_y)$ in Eq.~\eqref{eq14} and  substituting the result into \eqref{eq13}, we find the relation,
\begin{equation}
    \frac{y}{x} = \frac{\partial G / \partial k_y}{\partial G / \partial k_x}.
\end{equation}
At last, according to the definition of the angles in Fig.~\ref{fig1}, we have $y/x = \tan{\xi}$, and then straightforward algebra (see Ref.~\cite{gegk-07}) yields
\begin{equation}
	\tan{\xi} = \frac{\left( 2M^2 - 1 - \tan^2\eta \right) \tan\eta}{\left( M^2 + 1 \right)\tan^2\eta - \left( M^2 - 1 \right)}.
\end{equation}
Consequently, Eq.~(\ref{eq9}) gives the expression
\begin{equation}\label{eq16b}
  k=2\sqrt{M^2\cos^2\eta-1}
\end{equation}
for the wave number.
%Returning to Fig.~\ref{fig1}, we obtain the value of $\tan\mu$ from the dispersive relation in polar coordinates,
%\begin{equation}
%    \mathcal{G}(k, \eta) = M k \cos\eta + k\sqrt{1 +\frac{k^2}{4}},
%\end{equation}
%this gives the relation:

Another convenient parameter $\mu$ (see Fig.~\ref{fig1}) can be found from the relation
\begin{equation} \label{eq16}
    \tan\mu = %\frac{1}{k}\frac{\partial \mathcal{G} / \partial \eta}{\partial \mathcal{G} / \partial k} = 
    \frac{2M^2}{k^2} \sin2\eta.
\end{equation}
where $\xi + \mu + \eta = \pi$. The line of a constant phase can be obtained by integration the wave vector \eqref{eq9},
\begin{equation}\label{eq18}
    \theta = \int_0^r \mathbf{k} \cdot d\mathbf{r}.
\end{equation}
Since the wave vector is a gradient of the phase, the path of the integration can be chosen arbitrarily, and it is convenient integrate along the line with $\xi=\mathrm{const}$, so we get
\begin{equation}
    \theta = k r \cos\mu,
\end{equation}
where $r$ is the modulus of the radius vector. Then with the use of Eqs.~(\ref{eq16b}) and (\ref{eq16}) we find that the modulus of the radius vector can be expressed as a function of $\eta$,
\begin{equation}\label{eq19}
    r = \frac{4 \theta}{k^3} \sqrt{M^2(M^2 - 2)\cos^2\eta + 1}.
\end{equation}
At last, we obtain a parametric form of the line of a constant phase as
\begin{align}
    x &= -r \cos\xi = -\frac{4\theta}{k^3}\left( 1 - M^2\cos2\eta \right) \cos\eta, \nonumber \\
    y &= r \sin\xi = \frac{4\theta}{k^3}\left( 2M^2\cos^2\eta - 1 \right) \sin \eta.
\end{align}	

To obtain the equation for wave crests in notation of the LHY equation, 
we performed the inverse of the transformation \eqref{eq7}. According to the definition in Eq.~\eqref{eq18} we find that the transformation of the phase satisfies the relation $\theta \rightarrow\theta/c_0$, so 
\begin{align} \label{eq21}
    x &= \frac{4  c_0^2 \theta}{k^3 } \left[ M^2\cos2\eta - 1 \right] \cos\eta, \nonumber \\
    y &= \frac{4  c_0^2 \theta }{k^3}\left[ 2M^2\cos^22\eta - 1 \right] \sin\eta.
\end{align}	
In the last equation, we maintain the Mach number $M$ to simplify the notation. The angle $\eta$ varies in the interval
\begin{equation}
 -\arccos \left( \frac{1}{M} \right) \leq \eta \leq \arccos \left( \frac{1}{M} \right).
\end{equation}
These formulas show that this linear ``ship-wave'' pattern is located outside the Mach cone
which corresponds to the lines with $\eta=\pm\arccos(1/M)$.

%In this work, the analytical theory of linear waves formed outside the Mach cone of a supersonic flow past an obstacle in an LHY quantum fluid is developed based on Kelvin’s original method for studying linear waves generated by a ship in deep water~\cite{whitham-75, johnson-97}. Similarly to Kelvin's theory, the positions of stationary wave fronts are determined directly from the dispersion relation, obtained by linearizing the hydrodynamic system~\eqref{eq4}, and assuming that, in the stationary regime, $\omega(\mathbf{k}) = 0$. Where $\omega$ and $\mathbf{k}$ are the dispersion relation and the wavevector, respectively.	

\section{Oblique solitons in LHY fluid flow past an obstacle}


Another wave pattern observed within the Mach cone consists of two oblique dark solitons located symmetrically with respect to the $x$-axis, as is shown in Fig.~\ref{fig2}. In this section, we propose an analytical theory of this wave pattern. It is clear that these oblique solitons are developed from the ``shadow'' behind the obstacle and they attain a stationary form far enough from the obstacle. Therefore, we first find this stationary form assuming infinite length of a soliton. Such a soliton can be considered as a 1D solution of the generalized nonlinear Schr\"{o}dinger equation, so that its velocity is directed normally to the soliton's dip.

\subsection{DARK SOLITONS IN A 1D LHY FLUID}

\begin{figure}[t]
	\centering
	\includegraphics[width=6cm]{fig2.pdf}
	\caption{Geometry of dark oblique solitons inside the Mach cone.}
	\label{fig2}
\end{figure}

The soliton solution can be found following the general theory developed in Ref.~\cite{kamchatnov-24, ks-09}. The 1D LHY equation has the form
\begin{equation}\label{eq23}
    i \frac{\prt \psi}{\prt t} = -\frac{1}{2}\frac{\prt^2 \psi}{\prt \tilde{x}^2} + |\psi|^3 \psi, 	
\end{equation}
where it is assumed that $\tilde{x}$ is a coordinate normal to the soliton. We suppose for simplicity that the soliton moves with constant velocity $V$ through the condensate at rest. We make again the Madelung transformation
\begin{equation} \label{eq24}
    \psi(\tilde{x}, t) = \sqrt{\rho(\tilde{x}, t)}e^{i\int \tilde{u}(\tilde{x})\,d\tilde{x}},
\end{equation}
and obtain the hydrodynamic-like system
\begin{align} \label{eq25}
    \frac{\partial \rho}{\partial t} + \frac{\prt (u \rho)}{\prt \tilde{x}}  = 0,\nonumber \\
    \frac{\partial u}{\partial t} + u \frac{\prt u}{\prt \tilde{x}} + \frac{3}{2}\sqrt{\rho} 
    \frac{\prt \rho}{\prt \tilde{x}} =  \frac{\prt }{\prt \tilde{x}}  
    \left[ \frac{1}{4\rho}\frac{\prt^2 \rho}{\prt \tilde{x}^2} - 
    \frac{1}{8\rho^2}\left(\frac{\prt \rho}{\prt \tilde{x}} \right)^2 \right].
\end{align}
The standard assumption that the variables $\rho$ and $u$ only depend on the variable $\xi = \tilde{x} - Vt$ transforms this system to two ordinary differential equations which must satisfy the boundary condition 
\begin{equation} \label{eq26}
    u \rightarrow u_0, \quad \rho \rightarrow \rho_0\quad \text{ for }\quad |\xi| \rightarrow \infty,
\end{equation}
that is the soliton excitation is localized and the condensate is at rest far enough from the soliton.

Integration of the first equation of the system~\eqref{eq25} gives at once
\begin{equation}\label{eq27}
    u(\rho) = V \left( 1 - \frac{\rho_0}{\rho} \right).
\end{equation}
Then the second equation yields
\begin{equation} \label{eq28}
    \frac{1}{4\rho}\frac{d^2 \rho}{d \xi^2} - \frac{1}{8\rho^2}\left(\frac{d \rho}{d \xi}\right)^2 = 
    \rho^{\frac{3}{2}} - \rho_0^{\frac{3}{2}} + \frac{V^2}{2}\left( \frac{\rho_0^2}{\rho^2}  -  1 \right).
\end{equation}
This equation can be transformed with the use of the identity 
\begin{equation}\label{eq29}
    \frac{1}{4\rho}\frac{d^2 \rho}{d \xi^2} - \frac{1}{8\rho^2}\left(\frac{d \rho}{d \xi}\right)^2 = 
    \frac{1}{2\sqrt{\rho}}\frac{d^2}{d\xi^2} \left(\sqrt{\rho}\right),
\end{equation}
so that, after multiplication of Eq.\eqref{eq28} by $d (\sqrt{\rho}) / d\xi$ and easy integration, we get
\begin{equation}\label{eq30}
	\frac{d \rho}{d \xi} = \pm 2 \sqrt{R(\rho)},
\end{equation}
where
\begin{equation} \label{eq31}
	R(\rho) = 2\rho \left( \frac{3}{5} \rho_0^{\frac{5}{2}} - \rho_0^{\frac{3}{2}}\rho  + 
\frac{2}{5}\rho^{\frac{5}{2}} \right) - V^2\left( \rho_0 - \rho \right)^2.
\end{equation}
The dark soliton solution corresponds to $\rho$ changing between the two roots of $R(\rho)$, where $R(\rho)\geq0$, so these roots represent the maximal $\rho_0$ and minimal $\rho_m$ values of the density, respectively. In the center of the soliton we have ($\xi \rightarrow \xi_0$) $\rho \rightarrow \rho_m$, so integration of Eq.~\eqref{eq31} gives us the dependence $\rho=\rho(\xi)$ in implicit form,
\begin{equation} \label{eq.31}
    \xi (\rho) = \xi_0 \pm \frac{1}{2}\int_{\rho_m}^{\rho} \frac{d\rho}{\sqrt{R(\rho)}}.
\end{equation}
The relationship between the velocity $V$ of the soliton and the minimal value of the density $\rho_m$ at the soliton's center can be found directly from the equation $R(\rho_m) = 0$,
\begin{equation}
    V^2 = \frac{2\rho_m \left( \frac{3}{5} \rho_0^{\frac{5}{2}} + \frac{2}{5} 
    \rho_m^{\frac{5}{2}} - \rho_0^{\frac{3}{2}} \rho_m \right)}{(\rho_m - \rho_0)^2}.
\end{equation}


\subsection{OBLIQUE DARK SOLITON IN A QUASI-2D SYSTEM}

To extend our theory to the quasi-2D oblique dark soliton, we change the reference frame to the one where the obstacle is located at the origin of the coordinate system and the condensate flows from the right with the flow velocity $u_0<0$. We suppose that the soliton's dip lies along $y'$-axis rotated by the angle $\alpha$ with respect to the first reference frame,
\begin{equation} \label{eq33}
    x' = x \cos\alpha - y\sin\alpha \text{, \quad and \quad } y' = x \sin\alpha - y\cos\alpha.
\end{equation}
In this rotated coordinate system the flow velocity has the components $u'_0 = (u_0 \cos \alpha, u_0 \sin \alpha)$, and the soliton's velocity is compensated by the normal component of the flow velocity, so the soliton becomes stationary. %As requiered in the theory above, it is more convenient to change to the referencial where the condesate is ''quite'' far from the dark soliton. This change is done by the transformation
%\begin{equation}\label{eq34}
%    \tilde{x} = x' - u_0 \cos{(\alpha)} t \text{, \quad } \tilde{y} = y' - u_0 \sin{(\alpha)}t.
%\end{equation}
This means that $V = -u_0\cos\alpha$ and we get the oblique soliton solution in the form
\begin{equation}
	x \cos\alpha - y\sin\alpha = \pm \frac{1}{2}\int_{\rho_m}^{\rho} \frac{d\rho}{\sqrt{R(\rho)}},
\end{equation}
where we took into account that the soliton stems from the origin where the obstacle is located, so $\xi_0=0$. Then, for a given value of $x$, the soliton's profile in $y$-direction is given by the formula
\begin{equation} \label{eq37}
    y(\rho, x)  =  x \cot \alpha \pm \frac{1}{2\sin \alpha}\int_{\rho_m}^{\rho} \frac{d\rho}{\sqrt{R(\rho)}}.
\end{equation}
The angle $\alpha$ is influenced by several parameters, including the flow velocity and the obstacle’s size and geometry. Its calculation lies beyond the predictive scope of our analytical approach. In our study, $\alpha$ was determined numerically using the relation $\alpha = \arctan(x_0/y_0)$, where $x_0$ and $y_0$ denote the coordinates of some point in the center of the soliton line.

