\section{Ranking Algorithm Pseudo-code}
\label{sec:algo}

\begin{algorithm}[H]
\caption{Ranking algorithm}
\label{alg:rank}
\KwData{Model \( f \), Diff-Ex Generator \( G \), Number of samples \( n_{samples} \), Number of directions \( n_{dirs} \), Alpha \( \alpha \), Threshold \( \tau \), Max coordinates \( M \)}
\KwResult{Best coordinates \( C \) and directions \( D \)}

Initialize empty lists \( C \leftarrow [] \), \( D \leftarrow [] \)\;
Initialize used coordinates \( U \leftarrow \emptyset \)\;
Sample \( n_{samples} \) images from the dataset pertaining to a particular class\;

\While{length(\( C \)) < \( M \)}{
    \( max\_effect \leftarrow 0 \), \( best\_coordinate \leftarrow \texttt{None} \), \( best\_direction \leftarrow \texttt{None} \)\;

    \For{each image batch \( B \) of size BS from the remaining images}{
        Encode \( B \) to obtain the semantic space:\;
        \( z_{sem} \leftarrow G.encode(B) \)\;

        Encode the stochastic latent code:\;
        \( x_T \leftarrow G.encode\_stochastic(B, z_{sem}) \)\;

        \For{each latent direction \( k \in \{1, 2, \dots, n_{dirs}\} \) and \( k \notin U \)}{
            Modify latent codes:\;
            \( z_{pos} \leftarrow edit(z_{sem}, \alpha, k, +1) \)\;
            \( z_{neg} \leftarrow edit(z_{sem}, \alpha, k, -1) \)\;

            Generate positive and negative images:\;
            \( I_{pos} \leftarrow G.render(x_T, z_{pos}) \)\;
            \( I_{neg} \leftarrow G.render(x_T, z_{neg}) \)\;

            Compute the average probability change for target class \( c \):\;
            \( \Delta_{pos} \leftarrow p_{\theta}(I_{pos} \mid c) - p_{\theta}(B \mid c) \)\;
            \( \Delta_{neg} \leftarrow p_{\theta}(I_{neg} \mid c) - p_{\theta}(B \mid c) \)\;

            \If{\( \Delta_{pos} > max\_effect \)}{
                \( best\_coordinate \leftarrow k \)\;
                \( best\_direction \leftarrow +1 \)\;
                \( max\_effect \leftarrow \Delta_{pos} \)\;
            }
            \If{\( \Delta_{neg} > max\_effect \)}{
                \( best\_coordinate \leftarrow k \)\;
                \( best\_direction \leftarrow -1 \)\;
                \( max\_effect \leftarrow \Delta_{neg} \)\;
            }
        }
    }

    Append \( best\_coordinate \) to \( C \)\;
    Append \( best\_direction \) to \( D \)\;
    Add \( best\_coordinate \) to \( U \)\;
    Update remaining images by removing sufficiently explained ones (low probability change)\;
    Decrease threshold: \( \tau \leftarrow \min(\tau, max\_effect) \)\;
}
\Return Best coordinates \( C \) and directions \( D \)\;
\end{algorithm}
