\section{$\v$-numbers of powers of complete intersection ideals}{\label{section3}}
In this section, we show that for a complete intersection monomial ideal $I=\langle u_1,\ldots,u_r\rangle$, $\v(I^n)=\v_P(I^n)=n\alpha(I)+\v(I)-\alpha(I)$ for all $P\in\Ass(I)$ and  $n\geq 1$ where $\v(I)=\sum\limits_{i=1}^r \deg u_i-r$. As mentioned in the introduction, this result is recently proved in \cite{FM}. Here, we provide an alternative proof and  in the process, we show that every monomial $m\in S$ satisfying $(I:m)=P$ for some  $P\in\Ass(I)$, belongs to a fixed principal  monomial ideal $\langle g_P\rangle$ in $S$ depending on $P$ and $\deg g_P=\deg g_Q$ for all $P,Q\in \Ass(I)$.
\\Let $I$ be a monomial complete intersection ideal of $\height(I)=r$ and $\mathcal G(I)=\{u_1,\ldots,u_r\}$. We recall some well-known results on complete intersection monomial ideals that we use in our proofs. 
	\begin{enumerate}
\item[$(i)$] $\{u_1,\ldots,u_r\}$ is a monomial regular sequence and $\gcd(u_i,u_j)=1$ for all $i\neq j$.
\item[$(ii)$] Let $I=Q_1\cap\cdots\cap Q_s$ be the unique irredundant decomposition of $I$ where $Q_i$ are monomial ideals generated by pure powers of variables for all $1\leq i\leq s$. Then $\sqrt{Q_i}\neq \sqrt{Q_j}$ for all $i\neq j$ and $\sqrt{Q_i}=r$ for all $1\leq i\leq s$.
\item[$(iii)$] For all $n\geq 1$, $I^{(n)}=I^n$. Since $I$ is generated by a regular sequence, the graded associated ring of $I$, $\gr(I)=\bigoplus\limits_{j\geq 0}I^j/I^{j+1}$, is isomorphic to a polynomial ring over $S/I$. Hence $I^j/I^{j+1}$ is a free $S/I$-module for all $j\geq 0$. Therefore using the short exact sequence of $S$-modules
$$0\longrightarrow I^j/I^{j+1}\longrightarrow S/I^{j+1}\longrightarrow S/I^{j}\longrightarrow 0,$$  for all $j\geq 1$, we get
	\begin{enumerate}
\item[$(a)$] $\Ass(S/I^2)=\Ass(S/I)$, 
\item[$(b)$] $\Ass(S/I)\subset\Ass(S/I^3)\subset\Ass(S/I^2)\cup \Ass(S/I)=\Ass(S/I)$ and continuing this process, we have $\Ass(S/I^n)=\Ass(S/I)$ and hence $I^{(n)}=I^n$ for all $n\geq 1$.
\end{enumerate}	
\end{enumerate}	
\begin{Lemma}\label{In:u=I}
	Let $I=\langle u_1,\ldots u_r\rangle$ be a complete intersection monomial ideal in $S$. Then for any integers $b_i\geq 0$ for $1\leq i\leq r$ with $\sum_{i=1}^r b_i\leq n$,
	 $\displaystyle(I^n: u_1^{b_1}\cdots u_r^{b_r})=I^{n-\sum\limits_{i=1}^r b_i}$. 
\end{Lemma}
\begin{proof}
	We first show that $(I^n:u_i)=I^{n-1}$ for all $n\geq 1$ and $1\leq i\leq r$. Since $u_i\in I$, we have $I^{n-1}\subseteq (I^n:u_i)$ for all $1\leq i\leq r$. We show that $(I^n:u_i)\subseteq I^{n-1}$. Suppose $f\in (I^n:u_i)$, then $fu_i\in I^n$. Therefore $fu_i= h u_1^{c_1}\cdots u_r^{c_r}$ for some monomial $h\in S$ and $\sum\limits_{j=1}^r c_j=n$ with $c_j\geq 0$ for $1\leq j\leq r$.  Since $\gcd(u_i,u_j)=1$ for $i\neq j$, we have $u_i\mid h u_i^{c_i}$. If $c_i=0$, then $f=\displaystyle \frac{h}{u_i} u_1^{c_1}\cdots u_r^{c_r}\in I^n\subset I^{n-1}$.  If $c_i\geq 1$, then $f= h u_1^{c_1}\cdots u_i^{c_i-1}\cdots u_r^{c_r}\in I^{n-1}$.  Therefore $(I^n:u_i)=I^{n-1}$ for all $n\geq 1$ and $1\leq i\leq r$.  
	 Repeating this process $b_i$ times we get $(I^n: u_i^{b_i})=I^{n-b_i}$.
	Using this repeatedly, we get 
	$(I^n: u_1^{b_1}\cdots u_r^{b_r})=(I^{n-b_1}:u_2^{b_2}\cdots u_r^{b_r})=\cdots=(I^{(n-\sum\limits_{i=1}^{r-1} b_i)}:u_r^{b_r})=I^{n-\sum\limits_{i=1}^r b_i}.$
\end{proof}
In \cite[Proposition 3.10]{SS}, using polarization and \cite[Proposition 3.9]{JV}, Saha and Sengupta showed that if $I=\langle u_1,\ldots u_r\rangle$ is a complete intersection monomial ideal then $\v(I)=\sum\limits_{i=1}^r \deg u_i-r$.  In the following result, we provide an alternative proof of this by explicitly constructing a monomial $f$ satisfying $(I:f)=P$ and $\deg f=\v(I)$ that also shows that $\v(I)=\v_P(I)$ for all $P\in \Ass(I)$. The proof also provides a method to compute $\v$-numbers of primary ideals.
\begin{Proposition}{\label{idealcase}}
Let $I=\langle u_1,\ldots u_r\rangle$ be a  monomial ideal and $P=\langle y_1,\ldots,y_r\rangle$ be any associated prime of $I$ where $y_1,\ldots,y_r\in\{x_1,\ldots,x_m\}$. 
	\begin{enumerate}
\item[$(1)$] Suppose $I$ is a complete intersection ideal and $\displaystyle f={\prod\limits_{i=1}^r {u_i}}/{\prod\limits_{i=1}^r{y_i}}.$ Then $(I:f)=P$ and
$\v(I)=\v_P(I)=\sum\limits_{i=1}^r \deg u_i-r$.  
\item[$(2)$] Suppose $I$ is a $P$-primary monomial ideal and $I=\bigcap\limits_{i=1}^s Q_i$ is the unique irredundant decomposition of $I$ where $Q_i$ is a monomial ideal generated by pure powers of variables for all $1\leq i\leq s$. Then $\v(I)=\min\{\v(Q_i): 1\leq i\leq s\}$.
		\end{enumerate}
\end{Proposition}	
\begin{proof}
	$(1)$ Suppose $I$ is a complete intersection ideal.  Without loss of generality, we assume $y_i\in\supp(u_i)$ for all $1\leq i\leq r$. Since $\gcd(u_i,u_j)=1$ for all $i\neq j$, we have $\displaystyle\gcd(u_j,\prod\limits_{i=1}^r\frac{u_i}{y_i})=\frac{u_j}{y_j}$ and hence $\displaystyle \frac{u_j}{\gcd(u_j,f)}={y_j}$. Therefore by the property $(P3)$, we have $(I:f)=P.$ Therefore $\v_P(I)\leq \deg f=\sum\limits_{i=1}^r \deg u_i-r$.

	Let $g$ be a monomial such that $(I:g)=P$ and $\deg g=\v_P(I)$. Then for all $1\leq i\leq r$, $$g\in (I:P)=\bigcap\limits_{i=1}^r (I:y_i)=\bigcap\limits_{i=1}^r\langle u_1,\dots,u_{i-1},\frac{u_i}{y_i},{u_{i+1}}\dots,u_r\rangle\subset \langle u_1,\dots,u_{i-1},\frac{u_i}{y_i},{u_{i+1}}\dots,u_r\rangle.$$
	Since $g\notin I$, we have $u_i\nmid g$ for all $1\leq i\leq r$. Therefore $\displaystyle \frac{u_i}{y_i}\mid g$ for all $1\leq i\leq r$. Since $\displaystyle \gcd(\frac{u_i}{y_i},\frac{u_j}{y_j})=1$ for all $i\neq j$, we have $f\mid g$. Therefore $\v_P(I)=\deg g\geq \deg f$. Hence for all $P\in\Ass(R/I)$, $\displaystyle\v(I)=\v_P(I)=\deg f=\sum\limits_{i=1}^r \deg u_i-r$. 

	$(2)$ By \cite[Proposition 6.1.7]{MAVill}, $Q_i=\langle y_1^{\alpha_{i_1}},\ldots,y_r^{\alpha_{i_r}}\rangle$ with $\alpha_{1_l}\geq 1$ for all $1\leq l\leq r$ and $1\leq i\leq s$ . Let $\v(Q_t)=\min\{\v(Q_i): 1\leq i\leq s\}$ and $g=\prod\limits_{j=1}^ry_j^{\alpha_{t_j}-1}$. Then by part $(1)$, we have $(Q_t:g)=P$ and $\v(Q_t)=\deg g$. Since $Q_t\nsubseteq Q_i$ for any $i\neq t$, there exists $j\in\{1,\ldots r\}$ such that $\alpha_{i_j}<{\alpha_{t_j}}$. Thus  $g\in Q_i$ and $(Q_i:g)=R$ for $i\neq t$. Therefore $(I:g)=P$ and $\v(I)\leq \deg g=\v(Q_t)$.

	Let $f\in S$ be a monomial such that $(I:f)=P$ and $\deg f=\v(I)$. Now $P=(I:f)=\bigcap\limits_{i=1}^s (Q_i:f)=(Q_j:f)$ for some $j\in\{1,\ldots,s\}$. Thus $\v(Q_t)\geq \v(I)=\deg f\geq \v(Q_j)\geq \v(Q_t)$. Therefore $\v(I)=\min\{\v(Q_i): 1\leq i\leq s\}$.
\end{proof}	
