Now we prove the main result of this section.
\begin{Theorem}\label{ci}
	Let $I=\langle u_1,\ldots u_r\rangle$ be a complete intersection monomial ideal in $S$ and $P=\langle y_1,\dots,y_r\rangle$ be any associated prime of  $I$ where $y_1,\ldots,y_r\in\{x_1,\ldots,x_m\}$. Let $\displaystyle g={\prod\limits_{i=1}^r {u_i}}/{\prod\limits_{i=1}^r{y_i}}.$
	\begin{enumerate}
\item[$(1)$] If $m$ is a monomial such that $(I^n:m)=P$ then $\displaystyle g\mid m$ and $\displaystyle\deg{\frac{m}{g}}\geq (n-1)\alpha(I).$
\item[$(2)$] For all $n\geq 1$, $\v(I^n)=\v_P(I^n)=n\alpha(I)+\v(I)-\alpha(I)$ where $\v(I)=\sum\limits_{i=1}^r \deg u_i-r$.  
\end{enumerate}		
	\end{Theorem}	
\begin{proof}
	Without loss of generality, we assume that $\deg u_1=\alpha(I)$ and $y_i\in\supp(u_i)$ for all $1\leq i\leq r$. 

	$(1)$ Let $m$ be a monomial such that $(I^n:m)=P$. Fix any $i\in\{1,\ldots,r\}$. Then $my_i=h u_1^{b_1}\cdots u_r^{b_r}\in I^n$ for some monomial $h\in S$ with $\sum\limits_{j=1}^r b_j=n$. Since $(y_i,u_j)=1$ for $i\neq j$, $b_i=0$ implies  $\prod\limits_{j=1}^r u_j^{b_j}\mid m$ and hence $m\in I^n$ which contradicts that $(I^n:m)=P$. Therefore $b_i\geq 1$ and $\displaystyle  m=h \frac{u_i}{y_i} u_1^{b_1}\cdots u_i^{b_i-1}\cdots u_r^{b_r}$. Hence $\displaystyle \frac{u_i}{y_i}\mid m$. Thus $\displaystyle \frac{u_j}{y_j}\mid m$ for all $1\leq j\leq r$. Since $\displaystyle\gcd(\frac{u_i}{y_i},\frac{u_j}{y_j})=1$ for $i\neq j$, we have $g\mid m$. 

	Let $m=ug$ for some monomial $u\in S$. We show that $\deg u\geq (n-1)\alpha(I)$. Note that $m=ug\in(I^n:y_1)$. By Lemma \ref{In:u=I}, $\displaystyle  u\prod\limits_{i=2}^r\frac{u_i}{y_i}\in((I^n:y_1):\frac{u_1}{y_1})=(I^n:u_1)=I^{n-1}.$ Hence $\displaystyle  u\prod\limits_{i=2}^r\frac{u_i}{y_i}= h' u_1^{c_1}\cdots u_r^{c_r}$ for some monomial $h'\in S$ with $\sum\limits_{i=1}^r c_i=n-1$. By Lemma \ref{In:u=I}, we get,  $$\displaystyle  P=(I^n:m)=(I^n: u\prod\limits_{i=1}^r\frac{u_i}{y_i})=(I^n:h' u_1^{c_1}\cdots u_r^{c_r}\frac{u_1}{y_1})=((I^n:u_1^{c_1}\cdots u_r^{c_r}):h'\frac{u_1}{y_1})=(I:h'\frac{u_1}{y_1}).$$ Therefore by Proposition \ref{idealcase}, we get $\deg h' +\deg u_1-1\geq \v(I)=\sum\limits_{i=1}^r \deg u_i -r$. 
Since $\displaystyle  u\prod\limits_{i=2}^r\frac{u_i}{y_i}= h' u_1^{c_1}\cdots u_r^{c_r}$ with $\sum\limits_{i=1}^r c_i=n-1$ and $\deg u_i\geq \alpha(I)$ for all $1\leq i\leq r$, we get
	\begin{eqnarray*}
	\deg u&=&\deg h' +\sum\limits_{i=1}^r c_i\deg u_i -\sum\limits_{i=2}^r(\deg u_i -1)\\& \geq& \sum\limits_{i=1}^r \deg u_i -r-\deg u_1+1 +(n-1)\alpha(I)-\sum\limits_{i=2}^r\deg u_i +(r-1) \geq (n-1)\alpha(I).\end{eqnarray*}

	$(2)$ By Proposition \ref{idealcase} and part $(1)$  of the result, we get \begin{eqnarray*}\v_P(I^n)&\geq& (n-1)\alpha(I)+\deg(\prod\limits_{i=1}^r \frac{u_i}{y_i})=(n-1)\alpha(I)+\sum\limits_{i=1}^r\deg u_i -r\\&=&(n-1)\alpha(I)+\v(I)=n\alpha(I)+\v(I)-\alpha(I).\end{eqnarray*}

Let $\Ass(I)=\{P=P_1,\ldots,P_s\}$ and $Q_i$ is the corresponding $P_i$-primary component of $I$. Then 
 $I^{(n)}=I^n=\bigcap\limits_{i=1}^sQ_i^n$ for all $n\geq 1$. 	Let $u_i=x_{i_1}^{\alpha_{i_1}}\cdots x_{i_{t_i}}^{\alpha_{i_{t_i}}}$ for all $1\leq i\leq r$. Without loss of generality, we assume that $y_i=x_{i_1}$ for all $1\leq i\leq r$. Let $\beta_i$ denote $\alpha_{i_1}$ for all $1\leq 1\leq r$. Then $Q_1=\langle x_{i_1}^{\alpha_{i_1}}:1\leq i\leq r\rangle=\langle y_{1}^{\beta_{1}},\ldots,y_{r}^{\beta_{r}}\rangle$ is the corresponding $P=\langle x_{i_1}:1\leq i\leq r\rangle=\langle y_{1},\ldots,y_{r}\rangle$-primary component of $I$. 
