				\item[$(2)$] Let $I=P+J$ be a monomial ideal in $S$ where $P$ is a prime monomial ideal and $\mathcal G(P)$, $\mathcal G(J)$ are the sets of monomials with a disjoint set of variables. Then by \cite[Theorem 2.1]{MT}, $\overline I=P+\overline J$. Further using \cite[Theorem 4.1]{FM}, we get $\v_{P+Q}(\overline I)=\v(P)+\v_Q(\overline  J)=\v_Q(\overline  J)$.
				\end{enumerate}
