		\begin{enumerate}
			\item[$(1)$] $\lceil(L+c)A-s\rceil>\lceil(L-1+c)A-s\rceil$
			\item[$(2)$] $\lceil(L+c)A-s\rceil\geq (L-t)+\lceil(c+t)A-s\rceil$ for all $1\leq t\leq L$.
		\end{enumerate}
	\end{Lemma}
	\begin{proof}
		$(i)$ Since $(L+c)A-s>(L-1+c)A-s+1$ we get the required result. 
\\$(ii)$ We use induction on $L$. If $L=1$, then $t=1$ and
		$\lceil(L+c)A-s\rceil=\lceil(1+c)A-s\rceil=(L-1)+\lceil(c+1)A-s\rceil$.
	Suppose $L\geq 2$ and $\lceil(j+c)A-s\rceil\geq (j-t)+\lceil(c+t)A-s\rceil$ for all $1\leq t\leq j$ and $1\leq j\leq L-1$. Then for all $1\leq t\leq j$, using part $(1)$ and the induction hypothesis, we get 
	\begin{eqnarray*}
