	Motivated by the above result, we compute the $\v$-numbers associated to the integral closure filtrations of the edge ideal of a weighted oriented graph whose underlying graph is a complete bipartite graph. For more details about complete bipartite graphs and weighted oriented graphs, see \cite[Section 2]{AS} and \cite{GMBV} respectively.
	\begin{Corollary}\label{WOG}
		Let $K_{p_1,p_2}$ be a complete bipartite graph with the vertex set $V=V_1\sqcup V_2$ where $V_1=\{x_1,\dots,x_{p_1}\}$ and $V_2=\{y_1,\dots,y_{p_2}\}$. Let $D=((V(D),E(D),w)$ be a weighted oriented graph whose underlying graph is $K_{p_1,p_2}$ such that $E(D)=\{(x_i,y_j)\mid 1\le i\le p_1,1\le j\le p_2\}$. Then $\v(\overline{I(D)^n})=n\alpha(I(D))-1$ for all $n\geq 1$. 
	\end{Corollary}	
	\begin{proof}
	Let $\beta_j=w(y_j)$ for all $1\le j\le p_2$. Note that the edge ideal of $D$ is $$I(D)=\langle x_iy_j^{\beta_j}\mid 1\le i\le p_1,1\le j\le p_2\rangle=\langle x_1,\dots,x_{p_2}\rangle \cap\langle y_1^{\beta_1},\dots,y_{p_2}^{\beta_{p_2}}\rangle.$$ Let $P=\langle x_1,\dots,x_{p_1}\rangle$, $J=\langle y_1^{\beta_1},\dots,y_{p_2}^{\beta_{p_2}}\rangle$ and $\sqrt{J}=Q=\langle y_1,\dots,y_{p_2}\rangle$. Since $P$ and $J$ are generated by monomials with a disjoint set of variables, for all $n\ge 1$, we have 
		$$I(D)^n=(P\cap J)^n=(PJ)^n=P^nJ^n=P^n\cap J^n=I(D)^{(n)}$$  where the last equality follows from \cite[Theorem 3.7]{CEHH}. Therefore by \cite[Theorem 4.1]{GMBV}, we have $\overline{I(D)^n}=\overline{P^n}\cap\overline{J^n}=\overline{P^n}\overline{J^n}$ for all $n\geq 1$. Therefore by \cite[Theorem 2.2]{FM}, $\v(\overline{I(D)^n})=\min\{\v_P(\overline{P^n})+\alpha(\overline {J^n}),\v_Q(\overline{J^n})+\alpha(\overline {P^n})\}$ for all $n\geq 1$. Since by Remark \ref{powers},  $\overline{P^n}=\overline{\langle x_1^n,\dots,x_{p_2}^n\rangle}$ and $\overline{J^n}=\overline{\langle y_1^{n\beta_1},\dots, y_{p_2}^{n\beta_{p_2}}\rangle}$, we have $\alpha(\overline {P^n})=n$ and $\alpha(\overline {J^n})=n\alpha(J)$. Now by Theorem \ref{gen}, we have $\v_P(\overline{P^n})=n-1$ and $\v_P(\overline{J^n})\geq n\alpha(J)-1$. Hence $\v(\overline{I(D)^n})=n\alpha(J)+n-1=n(\alpha(J)+1)-1=n\alpha(I(D))-1$.
		\end{proof}	
		\begin{Remark}{\em
