In the final part of our study, we analyze the $\v$-numbers of integral closure filtartions of complete intersection ideals. As a starting point, we prove the following two foundational results.
\begin{Proposition}{\label{ht2}}
	 Let $I=\langle u_1,u_2\rangle$ be a complete intersection ideal in $S$. Let $u_1=x_{i_1}^{\alpha_1}\cdots x_{i_r}^{\alpha_r}$ and $u_2=x_{j_1}^{\beta_1}\cdots x_{j_l}^{\beta_l}$  with $\alpha_{s},\beta_{q}\geq 1$ for all $1\le s\le r$ and $1\le q\le l$. Let $P=\langle x_{i_p},x_{j_t}\rangle \in\Ass(I)$ and  $f=\prod\limits_{s=1}^{r}x_{i_s}^{b_s}\prod\limits_{q=1}^{l}x_{j_q}^{c_q}$ be a monomial such that $(\overline{I^n}:f)=P$. Then the following hold.
	\begin{enumerate}
		\item[$(i)$] $b_p=n\alpha_p-m$ for some $1\leq m\leq n\alpha_p$ and $\displaystyle c_t=\lceil\frac{m\beta_t}{\alpha_p}\rceil-1$.
		\item[$(ii)$] $\displaystyle c_j\geq\frac{m\beta_j}{\alpha_p}$ for all $1\leq j\leq l $ and $j\neq t$.
		\item[$(iii)$] $\displaystyle b_i> n\alpha_i-\frac{m\alpha_i}{\alpha_p}  $ for all $1\leq i\leq r$ and $i\neq p$. In particular, if $\alpha_p=\max\{\alpha_j:1\leq j\leq r\}$ and $x_{i_p}\in\mathcal G(P)$ then $\displaystyle b_i\geq  n\alpha_i-m+1$ for all $i\neq p$.
	\end{enumerate}
	\end{Proposition}
	\begin{proof}
		Let  $I=\bigcap\limits_{i=1}^h Q_i$ be a minimal irreducible decomposition of $I$. Then 
		$I^{(n)}=I^n=\bigcap\limits_{i=1}^hQ_i^n$ for all $n\geq 1$. Therefore by \cite[Theorem 4.1]{GMBV}, ${\overline{I^n}}=\bigcap\limits_{i=1}^h{\overline{Q_i^n}}$ for all $n\geq 1$. We denote $x_{i_s}$ by $x_s$ and $x_{j_q}$ by $y_q$ for all $1\leq s\leq r$ and $1\leq q\leq l$. Thus $P=\langle x_p,y_t\rangle$ and $f=\prod\limits_{i=1}^{r}x_i^{b_i}\prod\limits_{j=1}^{l}y_j^{c_j}$. The $P$-primary component of ${\overline{I^n}}$ is $Q=\langle x_p^{\alpha_p},y_t^{\beta_t}\rangle$.
		\\Now $P=(\overline{I^n}:f)=\bigcap\limits_{i=1}^h(\overline{Q_i^n}:f)\subseteq(\overline{Q_i^n}:f)$. If $f\notin \overline{Q_i^n}$, then $P\subset (\overline{Q_i^n}:f)\subseteq \sqrt{Q_i}$ for all $Q_i$. Since $\overline{Q_i^n}$ is $\sqrt{Q_i}$-primary  and $P\nsubseteq \sqrt{Q_i}$ for all $Q_i\neq Q$, we have $f\in\overline{Q_i^n}$ for all $Q_i\neq Q$ and $(\overline{Q^n}:f)=(\overline{I^n}:f)=P$. 
		\\  $(i)$ Since $f\notin \overline{Q^n}$, we have $b_p=n\alpha_p-m$ for some $1\leq m\leq n\alpha_p$ and by Remark \ref{powers} and Lemma \ref{membership}, we get $\displaystyle\frac{n\alpha_p-m}{n\alpha_p}+\frac{c_t}{n\beta_t}<1$. Hence $\displaystyle c_t<\frac{m\beta_1}{\alpha_p}$. Since $fy_{t}\in \overline{Q^n}$, we have $\displaystyle\frac{n\alpha_p-m}{n\alpha_p}+\frac{c_t+1}{n\beta_t}\geq 1$. Then $\displaystyle c_t+1\geq \frac{m\beta _t}{\alpha_p}$. Since $c_t\in\mathbb{Z}_{>0}$ and $\displaystyle c_t+1\geq \frac{m\beta_t}{\alpha_r}>c_t$, we have $\displaystyle c_t+1=\lceil\frac{m\beta_t}{\alpha_p}\rceil$ and hence $\displaystyle c_t=\lceil\frac{m\beta_t}{\alpha_p}\rceil-1$.
		\\$(ii)$ Fix $j\neq t$ and let $Q'=\langle x_p^{\alpha_p},y_j^{\beta_j}\rangle$. Then $f\in \overline{Q'^n}$. Hence, by Remark \ref{powers} and Lemma \ref{membership}, we have $\displaystyle\frac{n\alpha_p-m}{n\alpha_p}+\frac{c_j}{n\beta_j}\geq 1 $ and  $\displaystyle c_j\geq \frac{m\beta_j}{\alpha_p}$. 
		\\$(iii)$ Fix $i\neq p$ and let $Q'=\langle x_i^{\alpha_i},y_t^{\beta_t}\rangle$. Then $f\in\overline{Q'^n}$. Therefore, by Remark \ref{powers} and Lemma \ref{membership}, we get $\displaystyle\frac{b_i}{n\alpha_i}+\frac{1}{n\beta_t}(\lceil\frac{m\beta_t}{\alpha_p}\rceil-1)\geq 1$ and $$\displaystyle\frac{b_i}{n\alpha_i}\geq 1-\frac{1}{n\beta_t}(\lceil\frac{m\beta_t}{\alpha_p}\rceil-1)>1-\frac{1}{n\beta_t}(\frac{m\beta_t}{\alpha_p})=1-\frac{m}{n\alpha_p}.$$ Thus $\displaystyle b_i>n\alpha_i-\frac{m\alpha_i}{\alpha_p}$. If $\alpha_p=\max\{\alpha_j:1\leq j\leq r\}$ then 
		$b_i> n\alpha_i-m$. Hence $b_i\geq n\alpha_i-m+1$ for all $i\neq p$.
		\end{proof}	
	\begin{Proposition}{\label{ICCI}}
		Let $I=\langle u_1,\dots,u_r\rangle$ be a complete intersection monomial ideal in $S$ with $u_i=x_{i_1}^{\alpha_{i_1}}\cdots x_{i_{t_i}}^{\alpha_{i_{t_i}}}$ with $\alpha_{i_j}\geq 1$ for all $1\le i\le r$ and $1\le j\le t_i$.  If for any $j\in\{1,\ldots,r\}$, $|\supp(u_j)|=1$ then consider $\prod\limits_{p=2}^{t_j}x_{j_p}^{\alpha_{j_p}}=1$. Consider the primary component $Q=\langle x_{1_1}^{\alpha_{1_1}},\dots,x_{r_1}^{\alpha_{r_1}}\rangle$  of $I$ with $P=\sqrt{Q}$.  Let $$\displaystyle f=x_{1_1}^{n\alpha_{1_1}-1}x_{l_1}^{\lceil\frac{\alpha_{l_1}}{\alpha_{1_1}}\rceil-1}\prod\limits_{j=2}^{t_1}x_{1_j}^{n\alpha_{1_j}}\prod\limits_{i\in A}\prod\limits_{j=2}^{t_i} x_{i_j}^{\lceil\frac{\alpha_{i_j}}{\alpha_{1_1}}\rceil}$$ where $\alpha_{l_1}=\max\{\alpha_{i_1}\mid 1\le i\le r \}$ and $A=\{i\mid 2\le i\le r\text{ and } |\supp(u_i)| \geq2\}$.
		Then $(\overline{I^n}:f)=P$.
		\end{Proposition}	
		\begin{proof}
			Let  $I=\bigcap\limits_{i=1}^s Q_i$ be a minimal irreducible decomposition of $I$.  Then 
	$I^{(n)}=I^n=\bigcap\limits_{i=1}^sQ_i^n$ for all $n\geq 1$ and by \cite[Theorem 4.1]{GMBV}, ${\overline{I^n}}=\bigcap\limits_{i=1}^s{\overline{Q_i^n}}$ for all $n\geq 1$. We first show that if $Q_i\neq Q$ then $f\in\overline{Q_i^n}$. 
%	\\Let $\alpha_{l_1}=\max\{\alpha_{i_1}\mid 1\le i\le r \}$ and $B=\{2,\ldots,r\}\setminus A$. Consider the monomial $\displaystyle f=x_{1_1}^{n\alpha_{1_1}-1}x_{l_1}^{\lceil\frac{\alpha_{l_1}}{\alpha_{1_1}}\rceil-1}\prod\limits_{j=2}^{t_1}x_{1_j}^{n\alpha_{1_j}}\prod\limits_{i\in A}\prod\limits_{j=2}^{t_i} x_{i_j}^{\lceil\frac{\alpha_{i_j}}{\alpha_{1_1}}\rceil}$.
	\\
	\textbf{Case 1}: Suppose $x_{1_1}^{\alpha_{1_1}}\notin Q_i$. Then $|\supp(u_1)|\geq 2$ and there exists $x_{1_j}$ for some $2\le j\le t_1$ such that $x_{1_j}^{\alpha_{1_j}}\in Q_i$. Since $x_{1_j}^{n\alpha_{1_j}}\in\overline{Q_i^n}$ and $x_{1_j}^{n\alpha_{1_j}}\mid f$, we have $f\in\overline{Q_i^n}$. 
	\\ \textbf{Case 2}: Suppose $x_{1_1}^{\alpha_{1_1}}\in Q_i$. Since $Q_i\neq Q$, we have $A\neq\{\emptyset\}$ and there exists $x_{p_j}^{\alpha_{p_j}}\in Q_i\setminus Q$ for some $p\in A$ and $2\le j\le t_p$. Note that,  $$\displaystyle\frac{n\alpha_{1_1}-1}{n\alpha_{1_1}}+\frac{1}{n\alpha_{p_j}}(\lceil\frac{\alpha_{p_j}}{\alpha_{1_1}}\rceil)\geq 1-\frac{1}{n\alpha_{1_1}}+\frac{1}{n\alpha_{1_1}}=1.$$ Therefore by Remark \ref{powers} and Lemma \ref{membership}, $\displaystyle x_{1_1}^{n\alpha_{1_1}-1}x_{p_j}^{\lceil\frac{\alpha_{p_j}}{\alpha_{1_1}}\rceil}\in\overline{Q_i^n}$. Since $\displaystyle x_{1_1}^{n\alpha_{1_1}-1}x_{p_j}^{\lceil\frac{\alpha_{p_j}}{\alpha_{1_1}}\rceil}$ divides $f$, we have $f\in\overline{Q_i^n}$. 
	\\Now we show that $(\overline{Q^n}:f)=P$. Let $f_1=x_{1_1}^{n\alpha_{1_1}-1}x_{l_1}^{\lceil\frac{\alpha_{l_1}}{\alpha_{1_1}}\rceil-1}$. Since $x_{i_j}\notin P$ for all $1\leq i\leq r$ and $2\le j\le t_i$, it suffices to show that $(\overline{Q^n}:f_1)=P$. Since $$\displaystyle\frac{n\alpha_{1_1}-1}{n\alpha_{1_1}}+\frac{1}{n\alpha_{l_1}}(\lceil\frac{\alpha_{l_1}}{\alpha_{1_1}}\rceil-1)<1-\frac{1}{n\alpha_{1_1}}+\frac{1}{n\alpha_{l_1}}\frac{\alpha_{l_1}}{\alpha_{1_1}}=1,$$ by Remark \ref{powers} and Lemma \ref{membership}, we get $f_1\notin\overline{Q^n}$. Thus $\Ass(R/(\overline{Q^n}:f_1))=\Ass(R/\overline{Q^n})=\{P\}$. Since $\alpha_{l_1}\geq\alpha_{i_1}$ for all $1\le i\le r$, we have
	\begin{eqnarray*}
	\displaystyle\frac{n\alpha_{1_1}-1}{n\alpha_{1_1}}+\frac{1}{n\alpha_{l_1}}(\lceil\frac{\alpha_{l_1}}{\alpha_{1_1}}\rceil-1)+\frac{1}{n\alpha_{i_1}} &\geq&\displaystyle\frac{n\alpha_{1_1}-1}{n\alpha_{1_1}}+\frac{1}{n\alpha_{l_1}}(\frac{\alpha_{l_1}}{\alpha_{1_1}}-1)+\frac{1}{n\alpha_{i_1}}\\&\geq& 1-\frac{1}{n\alpha_{1_1}}+\frac{1}{n\alpha_{1_1}}-\frac{1}{n\alpha_{l_1}}+\frac{1}{n\alpha_{i_1}}\geq 1.	\end{eqnarray*}
	Hence, by Remark \ref{powers} and Lemma \ref{membership}, we have $f_1x_{i_1}\in\overline{Q^n}$ for all $1\le i\le r$ and $P\subset (\overline{Q^n}:f_1)$. Therefore $(\overline{I^n}:f)=(\overline{Q^n}:f)\bigcap (\bigcap\limits_{Q_i\neq Q}(\overline{Q_i^n}:f))=P$. 
		\end{proof}	
	We need the following technical lemma to prove the next result.
\begin{Lemma}\label{b>bmoda}
	Let $a,b\in\mathbb{Z}_>0$. Then $\displaystyle b\geq\lceil\frac{b}{a}\rceil+1$ if and only if $b\geq 2$ and $a\geq 2$.
\end{Lemma}
\begin{proof} Suppose $\displaystyle b\geq\lceil\frac{b}{a}\rceil+1$. If $a=1$ then $b=\displaystyle\lceil\frac{b}{a}\rceil$ which is a contradiction. Thus $a\geq 2$. Since $b>0$, we have $\displaystyle\lceil\frac{b}{a}\rceil\geq 1$ and hence $b\geq 2$. Conversely, suppose $a,b\geq 2$. Since $\displaystyle b-\frac{b}{a}\geq b-\frac{b}{2}=\frac{b}{2}\geq 1$, we have $\displaystyle b\geq \lceil\frac{b}{a}\rceil+1$.
\end{proof}
With the preceding developments, we are now ready to prove the final main result of our study.
	\begin{Theorem}\label{uppbndcompleteint}
	Let $I=\langle u_1,\dots,u_r\rangle$ be a complete intersection monomial ideal in $S$ with $\deg u_1=\alpha(I)$. Then the following hold.
	\begin{itemize} 
		\item[$(1)$] 
		\begin{enumerate}
			\item[$(i)$] $\v(\overline{I^n})\leq\v(I^n)$ for all $n\geq 1$.
			\item[$(ii)$] If $u_1$ and $u_t$ are not squarefree for some $2\le t\le r$, then $\v(\overline{I^n})\le\v(I^n)-1$ for all $n\geq 1$.
		\end{enumerate}	
%		$\v(\overline{I^n})\leq\v(I^n)$ for all $n\geq 1$.
%		Moreover, if $u_1$ and $u_t$ are not squarefree for some $2\le t\le r$, then $\v(\overline{I^n})+1\le\v(I^n)$ for all $n\geq 1$.
		\item[$(2)$] Suppose $r=2$, $u_1=(x_{i_1}\cdots x_{i_q})^\alpha$ and $u_2=x_{j_1}^{\beta_1}\cdots x_{j_l}^{\beta_r}$ with $1\leq \alpha\leq\beta_1\leq\cdots\leq\beta_l$ and $q\leq l$. Then  for all $n\geq 1$ and $P\in \Ass(\overline{I^n})$, $$\displaystyle\v(\overline{I^n})=\v_P(\overline{I^n})=n\alpha(I)+\sum\limits_{j=1}^l\lceil\frac{\beta_j}{\alpha}\rceil-2.$$ In particular, if $\alpha=1$ then  $\v(I^n)=\v(\overline{I^n})$ for all $n\geq 1$.
		\item[$(3)$] Suppose $r=2$, $u_1=(x_{i_1}\cdots x_{i_q})^\alpha$ and $u_2=(x_{j_1}\cdots x_{j_q})^\alpha$. Then for all $n\geq 1$, $$\reg(S/\overline{I^n})=\v(\overline{I^n})=n\alpha(I)+q-2.$$
		\item[$(4)$] Suppose $r=2$, $u_1=x_{i_1}^\alpha$ and $u_2=x_{j_1}^{\beta_1}\cdots x_{j_l}^{\beta_l}$ with $l\geq 2$ and $\deg u_2=\alpha$. Then $\v(\overline{I^n})\geq n\alpha(I)$ for all $n\geq 1$. Moreover, if there exists $j$ with $2\beta_j\geq \alpha$ then $\v(\overline{I^n})=n\alpha(I)$ for all $n\geq 1$.
		\item[$(5)$] For any integer $a\geq 1$, there exists a height two equigenerated complete intersection monomial ideal $I$  such that $\reg(S/\overline{I^n})-\v(\overline{I^n})=a-1$ for all $n\geq 1$.
	\end{itemize}
\end{Theorem}
\begin{proof}
	$(1)$ $(i)$ By Proposition \ref{ICCI}, we get, $\v(\overline{I^n})\le\v_P(\overline{I^n})\le \deg f$ where $f$ is the monomial in Proposition \ref{ICCI} and $P\in\Ass(\overline{I^n})$. Thus, by Theorem \ref{ci},  for all $n\geq 1$, we have  \begin{eqnarray*}
	\displaystyle \v(I^n)-\deg f&=&n\alpha(I)+\sum\limits_{i=2}^r \deg u_i-r -(n\alpha(I)-1+\lceil\frac{\alpha_{l_1}}{\alpha_{1_1}}\rceil-1+\sum\limits_{i\in A}\sum\limits_{j=2}^{t_i}\lceil\frac{\alpha_{i_j}}{\alpha_{1_1}}\rceil)\\ &=& \sum\limits_{i=2}^r\sum\limits_{j=1}^{t_i}\alpha_{i_j}-r+1-\sum\limits_{i\in A}\sum\limits_{j=2}^{t_i}\lceil\frac{\alpha_{i_j}}{\alpha_{1_1}}\rceil-\lceil\frac{\alpha_{l_1}}{\alpha_{1_1}}\rceil+1\\ &=&\sum\limits_{i=2}^r\alpha_{i_1}+\sum\limits_{i\in A}\sum\limits_{j=2}^{t_i}(\alpha_{i_j}-\lceil\frac{\alpha_{i_j}}{\alpha_{1_1}}\rceil)-(r-1)-\lceil\frac{\alpha_{l_1}}{\alpha_{1_1}}\rceil+1\\ &\geq& \sum\limits_{i=2}^r \alpha_{i_1}-(r-1)-\lceil\frac{\alpha_{l_1}}{\alpha_{1_1}}\rceil+1. 
\end{eqnarray*}
If $\alpha_{l_1}=\alpha_{1_1}$, then $1-\displaystyle\lceil\frac{\alpha_{l_1}}{\alpha_{1_1}}\rceil=0$. Since $\sum\limits_{i=2}^r\alpha_{i_1}-(r-1)\geq 0$, we have $\v(I^n)\geq \deg f$. If $\alpha_{l_1}>\alpha_{1_1}$, then 
$\displaystyle\v(I^n)-\deg f\geq \sum\limits_{\substack{i=2\\ i\ne l}}^{r}\alpha_{i_1}-(r-2)+\alpha_{l_1}-\lceil\frac{\alpha_{l_1}}{\alpha_{1_1}}\rceil\geq 0.$
Thus $\v(\overline{I^n})\le\v(I^n)$ for all $n\geq 1$. 
\\$(ii)$ Suppose $u_1$ and $u_t$ are not squarefree for some $2\le t\le r$. Without loss of generality, we assume that $\alpha_{1_1}\geq 2$ and $\alpha_{t_1}\geq 2$. %By Proposition \ref{ICCI}, we get, $\v(\overline{I^n})\le\v_P(\overline{I^n})\le \deg f$ where $f$ is the monomial in Proposition \ref{ICCI}. 
Therefore, for all $n\geq 1$, we have $$\v({I^n})-\v(\overline{I^n})\geq \v({I^n})-\deg f\geq \displaystyle\sum\limits_{i=2}^{r}\alpha_{i_1}-(r-2)-\lceil\frac{\alpha_{l_1}}{\alpha_{1_1}}\rceil.$$
  If $\alpha_{l_1}>\alpha_{1_1}\geq 2$, then by Lemma \ref{b>bmoda}, $\displaystyle\alpha_{l_1}-\lceil\frac{\alpha_{l_1}}{\alpha_{1_1}}\rceil\geq 1$. Thus, for all $n\geq 1$, we have $$\v(I^n)-\deg f\geq \sum\limits_{i=2}^r \alpha_{i_1}-(r-2)-\lceil\frac{\alpha_{l_1}}{\alpha_{1_1}}\rceil=\sum\limits_{\substack{i=2\\ i\ne l}}^{r}\alpha_{i_1}-(r-2)+\alpha_{l_1}-\lceil\frac{\alpha_{l_1}}{\alpha_{1_1}}\rceil\geq1.$$ 
Suppose $\alpha_{l_1}=\alpha_{1_1}\geq 2$. Then for all $n\geq 1$, we have  
\begin{eqnarray*}\v(I^n)-\deg f\geq \sum\limits_{i=2}^r \alpha_{i_1}-(r-2)-\lceil\frac{\alpha_{l_1}}{\alpha_{1_1}}\rceil&=&\sum\limits_{\substack{i=2\\ i\ne t}}^{r}\alpha_{i_1}-(r-2)+\alpha_{t_1}-\lceil\frac{\alpha_{l_1}}{\alpha_{1_1}}\rceil \\ &\geq& (r-2)-(r-2)+2-1=1.\end{eqnarray*} 
$(2)$ We denote $x_{i_p}$ by $x_p$ and $x_{j_t}$ by $y_t$ for all $1\leq p\leq q$ and $1\leq t\leq l$. Note that  $I=\bigcap\limits_{\substack{1\leq i\leq q\\1\leq j\leq l}} Q_{ij}$ is a minimal irreducible decomposition of $I$ where $Q_{ij}=\langle x_i^\alpha,y_j^{\beta_j}\rangle$. By \cite[Theorem 4.1]{GMBV}, ${\overline{I^n}}=\bigcap\limits_{\substack{1\leq i\leq q\\1\leq j\leq l}}{\overline{Q_{ij}^n}}$ for all $n\geq 1$ and and $\Ass({\overline{I^n}})=\{P_{ij}=\sqrt{Q_{ij}}: 1\leq i\leq q, 1\leq j\leq l\}$ for all $n\geq 1$.  By Remark \ref{powers}, $\overline{Q_{ij}^n}=\overline{\langle x_i^{n\alpha},y_j^{n\beta_j}\rangle}$. We show that $\v_{P_{ij}}(\overline{I^n})=qn\alpha+\sum\limits_{t=1}^l\lceil\frac{\beta_j}{\alpha}\rceil-2$ for all $1\leq i\leq q$ and $1\leq j\leq l$. Note that by Proposition \ref{ICCI}, we have 
$\v_{P_{ij}}(\overline{I^n})\leq qn\alpha+\sum\limits_{t=1}^l\lceil\frac{\beta_t}{\alpha}\rceil-2$.
\\Let $g=\prod\limits_{p=1}^{q}x_{p}^{b_p}\prod\limits_{t=1}^{l}y_{t}^{c_t}$ be a monomial such that $(\overline{I^n}:g)=P_{ij}$. Then by Propossition \ref{ht2}, $b_i=n\alpha-m$ for some $1\leq m\leq n\alpha$, $\displaystyle c_j=\displaystyle\lceil\frac{m\beta_j}{\alpha}\rceil-1$, $\displaystyle c_t\geq\lceil\frac{m\beta_t}{\alpha}\rceil$ for all $1\leq t\leq l $ and $t\neq j$, and $b_p\geq n\alpha-m+1$ for all $1\leq p\leq l $ and $p\neq i$. Therefore
 \begin{eqnarray*}
 	\deg g&\geq& (n\alpha-m)+\sum\limits_{\substack{p=1\\ p\neq i}}^q (n\alpha-m+1)+\displaystyle\lceil\frac{m\beta_j}{\alpha}\rceil-1+\sum\limits_{\substack{t=1\\ t\neq j}}^l \frac{m\beta_t}{\alpha}\rceil\\&=& qn\alpha-qm+(q-1)+\sum\limits_{t=1}^l\lceil\frac{m\beta _t}{\alpha}\rceil-1\\&= &qn\alpha-qm+(q-2)+\sum\limits_{t=1}^l\lceil\frac{m\beta_t}{\alpha}\rceil\\&\geq & qn\alpha-q(m-1)-2+l(m-1)+\sum\limits_{t=1}^l\lceil\frac{\beta_t}{\alpha}\rceil\\&= &qn\alpha+\sum\limits_{t=1}^l\lceil\frac{\beta_t}{\alpha}\rceil-2+(l-q)(m-1)\geq qn\alpha+\sum\limits_{t=1}^l\lceil\frac{\beta_t}{\alpha}\rceil-2
 \end{eqnarray*} where the fourth inequality follows from Lemma \ref{ceil} ( taking $L=m$, $A=\beta_t/\alpha$, $t=1$ and $c=s=0$). Hence $\displaystyle\v_{P_{ij}}(\overline{I^n})=n\alpha(I)+\sum\limits_{j=1}^l\lceil\frac{\beta_j}{\alpha}\rceil-2.$
 \\The last part follows from the Theorem \ref{ci}.
 \\$(3)$ By Remark \ref{powers}, note that $\overline {I^n}=\overline{\langle (x_{i_1}\cdots x_{i_q})^{n\alpha}, (x_{j_1}\cdots x_{j_q})^{n\alpha} \rangle}=\overline{\langle x_{i_1}\cdots x_{i_q}, x_{j_1}\cdots x_{j_q} \rangle^{n\alpha} }$. Consider the squarefree equigenerated complete intersection ideal $J=\langle x_{i_1}\cdots x_{i_q}, x_{j_1}\cdots x_{j_q} \rangle$. Then by \cite[Theorem 1.4.6]{HH}, $\overline{J^{n\alpha}}=J^{n\alpha}$ and by \cite[Lemma 4.4]{BHT}, we have $\reg(J^{n\alpha})=qn\alpha+(q-1)$. Therefore $\reg(S/\overline{I^n})=nq\alpha+q-2=\v(\overline{I^n})$ where the last equality follows from part $(2)$.
\\$(4)$ We denote $x_{i_1}$ by $x$ and $x_{j_q}$ by $y_q$ for all $1\leq q\leq l$. Then $\overline{I^n}={\overline{\langle x^{n\alpha}, y_1^{n\beta_1}\cdots y_l^{n\beta_l}\rangle}}$ by Remark \ref{powers} . Note that $I=\bigcap\limits_{i=1}^l Q_i$ is a minimal irreducible decomposition of $I$ where $Q_i=\langle x^\alpha,y_i^{\beta_i}\rangle$. By \cite[Theorem 4.1]{GMBV}, ${\overline{I^n}}=\bigcap\limits_{i=1}^l{\overline{Q_i^n}}$ for all $n\geq 1$ and $\Ass({\overline{I^n}})=\{P_i=\sqrt{Q_i}: 1\leq i\leq l\}$ for all $n\geq 1$. By Remark \ref{powers}, $\overline{Q_i^n}=\overline{\langle x^{n\alpha},y_i^{n\beta_i}\rangle}$ for all $1\leq i\leq l$. We show that $\v_{P_i}({\overline{I^n}})\geq n\alpha$ for all $n\geq 1$ and $1\leq i\leq l$. Let $f=x^c\prod\limits_{j=1}^{l}y_j^{c_j}$ and $(\overline{I^n}:f)=P_i$. Then by Proposition \ref{ht2}, we have $c=n\alpha-m$ for some $1\leq m\leq n\alpha$, $\displaystyle c_i=\lceil\frac{m\beta_i}{\alpha}\rceil-1$ and $c_j\geq \frac{m\beta_j}{\alpha}$  for all $j\neq i$. Hence \begin{eqnarray*}\displaystyle c+\sum\limits_{j=1}^l c_j\geq n\alpha-m+\sum\limits_{\substack{j=1\\ j\ne i}}^{l}\frac{m\beta_j}{\alpha}+\lceil\frac{m\beta_i}{\alpha}\rceil-1&=&n\alpha-m+\frac{m(\alpha-\beta_i)}{\alpha}+\lceil\frac{m\beta_i}{\alpha}\rceil-1\\&=&n\alpha-\frac{m\beta_i}{\alpha}+\lceil\frac{m\beta_i}{\alpha}\rceil-1.\end{eqnarray*} 
Now we show that $\alpha$ does not divide $m\beta_i$. Suppose $\alpha$ divides $m\beta_i$. Since $fx\in \overline{I^n}$, using Remark \ref{powers} and
Lemma \ref{membership}, we have $$\displaystyle1\leq \frac{c+1}{n\alpha}+\frac{c_i}{n\beta_i}=\frac{n\alpha-m+1}{n\alpha}+\frac{\frac{m\beta_i}{\alpha}-1}{n\beta_i}=1+\frac{1}{n\alpha}-\frac{1}{n\beta_i}<1$$ which is a contradiction (where the last inequality follows as $l\geq 2$ and hence $\sum\limits_{j=1}^l\beta_j=\alpha$ implies $\beta_i<\alpha$). Therefore $\displaystyle\lceil\lceil\frac{m\beta_i}{\alpha}\rceil-\frac{m\beta_i}{\alpha}-1 \rceil=0$ and hence $$\displaystyle c+\sum\limits_{j=1}^l c_j\geq n\alpha+\lceil\lceil\frac{m\beta_i}{\alpha}\rceil-\frac{m\beta_i}{\alpha}-1 \rceil= n\alpha.$$ This implies $\v_{P_i}(\overline{I^n})\geq n\alpha$ for all $1\leq i\leq r$ and $n\geq 1$. 
\\Suppose there exists $j\in\{1,\ldots,r\}$ with $2\beta_j\geq \alpha$. Consider the monomial $\displaystyle g=xy_j^{n\beta_j-1}\prod\limits_{\substack{i=1\\i\neq j}}^{l}y_i^{n\beta_i}$. Note that $g\in \overline{Q_i^n}$ for all $i\neq j$. Since $\displaystyle  \frac{1}{n\alpha}+\frac{n\beta_j-1}{n\beta_j}=1-\frac{\alpha-\beta_j}{n\alpha\beta_j}<1$ (as $l\geq 2$ and hence $\alpha>\beta_j$), by Remark \ref{powers} and Lemma \ref{membership}, we have $g\notin \overline{Q_j^n}$. Note that $gy_j\in \overline{Q_j^n}$. Since $\displaystyle  \frac{2}{n\alpha}+\frac{n\beta_j-1}{n\beta_j}=1+\frac{2\beta_j-\alpha}{n\alpha\beta_j}\geq 1,$ again using Remark \ref{powers} and Lemma \ref{membership}, we have $gx\in \overline{Q_j^n}$. Hence $P_j\subseteq (\overline{Q_j^n}:g)\neq R$ and $\Ass(R/(\overline{Q_j^n}:g))=\Ass(R/\overline{Q_j^n})=\{P_j\}$. Thus $P_j= (\overline{Q_j^n}:f)$. Therefore $(\overline{I^n}:g)=(\overline{Q_j^n}:g)\bigcap (\bigcap\limits_{Q_i\neq Q_j}(\overline{Q_j^n}:g))=P_j$. Hence $\v_{P_j}(\overline{I^n})\leq \deg g=n\alpha$. Thus $\v(\overline{I^n})=n\alpha$ for all $n\geq 1$.
\\$(5)$ Let $\alpha$ be an integer such that $\alpha\geq 2a+1$. Consider the ideal $I=\langle x_1^\alpha, x_{a+2}^{\alpha-a}\prod\limits_{j=2}^{a+1}x_j \rangle$ in the polynomial ring $S=\mathbb C[x_1,\ldots,x_{a+2}]$. Then using part $(4)$, we have $\v(\overline{I^n})=n\alpha$ for all $n\geq 1$. By \cite[Example 3.2]{Hoa}, we have $\reg(S/\overline{I^n})=n\alpha+a-1$ for all $n\geq 1$ and thus we get the required result.  
\end{proof}
As a consequence, we obtain the following.
\begin{Corollary}
For any integer $q\geq 0$, there exist  an equigenerated complete inetersection monomial ideal $I$ and a non-equigenerated complete inetersection monomial ideal $J$ such that for all $n\geq 1$, $$\v(I^n)-\v(\overline{I^n})=q=\v(J^n)-\v(\overline{J^n})=q.$$ 
\end{Corollary}	
\begin{proof}
	Let $S=K[x_1,\ldots,x_m]$ be a polynomial ring over a field $K$ with $m\geq 2$. Consider the ideal $I=\langle x_i^{q+1},x_j^{q+1}\rangle$ with $i\neq j$. Then by Theorem \ref{ci} and part $(2)$ of Theorem \ref{gen}, we have $\v(I^n)-\v(\overline{I^n})=n(q+1)+(q+1)-2-(n(q+1)+1-2)=q$ for all $n\geq 1$.
	\\Now we construct the non-equigenerated ideal $J$. Suppose $q=0$. Then the result follows from part $(2)$ of Theorem \ref{uppbndcompleteint}. Let $q\geq 1$.
	Consider the polynomial ring $S=K[x_1,\ldots,x_q,y_1,\ldots,y_q]$ where $K$ is a field and the monomial ideal $J=\langle (x_1\cdots x_q)^2, (y_1\cdots y_q)^3\rangle$. Then by Theorem \ref{ci} and part $(2)$ of Theorem \ref{uppbndcompleteint}, for all $n\geq 1$, we get $\v(J^n)-\v(\overline{J^n})=2nq+3q-2-(2nq+2q-2)=q$.
\end{proof}	


