\section{Introduction}

For a given sequence of positive numbers $\{a_0,$
$a_1,\ldots,a_{N-1}\}$ (in what follows we assume $a_0=1$) and
real numbers $\{b_1, b_2,\ldots,b_N \}$, we denote by $A$ the
finite Jacobi matrix given by
\begin{equation}
\label{Jac_matr}
A=\begin{pmatrix} b_1 & a_1 & 0 & 0 & 0 &\ldots \\
a_1 & b_2 & a_2 & 0 & 0 &\ldots \\
\ldots &\ldots  &\ldots &\ldots & \ldots &\ldots \\
\ldots &\ldots  &\ldots &a_{N-2} & b_{N-1} &a_{N-1}\\
\ldots &\ldots &\ldots &\ldots & a_{N-1} &b_N
\end{pmatrix}.
\end{equation}
Let $u=(u_1,\ldots,u_N)\in \mathbb{R}^N$ and $T>0$ be fixed. With
the matrix $A$ we associate the dynamical system:
\begin{equation}
\label{DynSyst}
\begin{cases}
u_{tt}(t)-Au(t)=F(t),\quad t>0,\\
u(0)=u_t(0)=0,
\end{cases}
\end{equation}
where the vector function $F(t)=(f(t),0,\ldots,0)$, $f\in
L_2(0,T)$ is interpreted as a \emph{boundary control}. The
solution of (\ref{DynSyst}) is denoted by $u^f$. With the system
(\ref{DynSyst}) we associate the \emph{response operator} acting
by the rule
\begin{equation}
\label{RespJM} \left(R^Tf\right)(t)=u^f_1(t),\quad 0<t<T.
\end{equation}
The forward and inverse problems for the system (\ref{DynSyst})
and for the special case of this system, the finite
Krein-Stieltjes string, were the subjects of \cite{MM3,MM4}, where
as a main tool we used the Boundary control method \cite{B07,B08}.
In this paper we would like to demonstrate one more application of
the Boundary control method, namely the construction of the de
Banges space associated with (\ref{DynSyst}).

De Branges spaces play an important role in the inverse spectral
theory of first order canonical systems, see for example
\cite{DBr,DMcK,RR}. In \cite{MM6,MM7} the authors shows how to use
the Boundary control method to associate de Branges spaces with
different dynamical systems. Note that our approach differs from
the classical one and potentially admits the generalization to
multidimensional systems. The algorithm proposed in \cite{MM7,MM6}
is as follows: fixing some finite time $t=T$ one denote by
$\mathcal{F}^T$ the set of controls acting on the time interval
$(0,T)$ and introduces the \emph{reachable set} of the dynamical
system at this time:
\begin{equation*}
U^T:=\{u^f(T)\,|\,f\in \mathcal{F}^T\}.
\end{equation*}
Then one applies the Fourier transform $\mathbb{F}$ associated
with the operator $A$ to elements from $U^T$ and get a linear
manifold $\mathbb{F}U^T$. Then this linear manifold is equipped
with the norm defined by the \emph{connecting operator}, which
resulted in the de Branges space associated with the initial
dynamical system. In the considered in \cite{MM6,MM7} models the
dynamical systems have different properties in respect to the
\emph{boundary controllability}: the system associated with the
Schr\"odinger operator is exactly controllable from the boundary,
the system associated with the one-dimensional Dirac operator is
not controllable, but the controllability restores after some
trick associated with doubling the state of the system, the
discrete system associated with a finite Jacobi matrix is boundary
controllable, but the time in the model considered was discrete,
see also \cite{MM11} for the case of semi-infinite matrix. The
peculiarity of the system (\ref{DynSyst}) is the lack of the
boundary controllability, and in opposite to all systems
considered in \cite{MM7,MM11}, the speed of the wave propagation
in (\ref{DynSyst}) is infinite. Nevertheless we will show that the
method from \cite{MM6,MM6} works, and using it one can construct
de Branges space associated with $A$.

In the second section we provide the necessary information on the
solution of the forward and inverse problems for (\ref{DynSyst})
from \cite{MM4}. In the third section we remind the reader some
useful definitions and construct the de Branges space associated
with (\ref{DynSyst}).




\section{Dynamical system, forward problem, Krein equations.}

The following Cauchy problem for the difference equation
\begin{equation}
\label{Cauchy}
\begin{cases}
a_1\phi_2+b_1\phi_1=\lambda\phi_1,\\
a_n\phi_{n+1}+a_{n-1}\phi_{n-1}+b_n\phi_n=\lambda \phi_n,\quad
n=2,\ldots,N,\\
\phi_1=1,
\end{cases}
\end{equation}
determines the set of polynomials
$\{1,\phi_2(\lambda),\ldots,\phi_N(\lambda),\phi_{N+1}(\lambda)\}$.
Let $\lambda_1,\ldots,\lambda_{N}$ be the roots of the equation
$\phi_{N+1}(\lambda)=0$, it is known \cite{AH} that they are real
and distinct. We denote by $(\cdot,\cdot)$ the scalar product in
$\mathbb{R}^N$ and introduce the vectors and the coefficients by
the rules:
\begin{equation*}
\varphi(\lambda)=\begin{pmatrix} \phi_1(\lambda)\\
\cdot\\ \cdot\\ \phi_{N}(\lambda)\end{pmatrix},\quad\varphi_k=\begin{pmatrix} \phi_1(\lambda_k)\\
\cdot\\ \cdot\\ \phi_{N}(\lambda_k)\end{pmatrix},\quad
\rho_k=\left(\varphi_k,\varphi_k\right),\quad k=1,\ldots,N.
\end{equation*}
Thus $\varphi_k$ are non-normalized eigenvectors of $A$,
corresponding to eigenvalues $\lambda_k$:
\begin{equation*}
A\varphi_k=\lambda_k\varphi_k,\quad \quad k=1,\ldots,N.
\end{equation*}
We call by \emph{spectral data} and \emph{the spectral function}
$\rho$ the following objects:
\begin{equation*}
\label{measure_JM} \left\{\lambda_i,\rho_i\right\}_{i=1}^{N},\quad
\rho(\lambda)=\sum_{\{k:\lambda_k<\lambda\}}\frac{1}{\rho_k}.
\end{equation*}
%Note the property:
%\begin{equation}
%\label{rho_pr} \sum_{k=1}^N\frac{1}{\rho_k}=1.
%\end{equation}

The standard application of the Fourier method yields
\begin{lemma}
The solution to (\ref{DynSyst}) admits the spectral representation
\begin{equation}
\label{Sol_spec_repr_JM}
u^f(t)=\sum_{k=1}^{N}h_k(t)\varphi_k,\quad
u^f(t)=\int_{-\infty}^\infty\int_0^t
S(t-\tau,\lambda)f(\tau)\,d\tau\varphi(\lambda)\,d\rho(\lambda),
\end{equation}
where
\begin{eqnarray*}
h_k(t)=\frac{1}{\rho_k}\int_0^t
f(\tau)S_k(t-\tau)\,d\tau,\\
S(t,\lambda)=\begin{cases}
\frac{\sin{\sqrt{\lambda}t}}{\sqrt{\lambda}},\quad
\lambda>0,\\
\frac{\operatorname{sh}{\sqrt{|\lambda|}t}}{\sqrt{|\lambda|}},\quad
\lambda<0,\\
t,\quad \lambda=0,
\end{cases},\quad S_k(t)=S(t,\lambda_k).
\end{eqnarray*}
\end{lemma}

We introduce the \emph{outer space} of the system (\ref{DynSyst}),
the space of controls: $\mathcal{F}^T:=L_2(0,T;\mathbb{C})$ with
the scalar product $f,g\in \mathcal{F}^T,$
$\left(f,g\right)_{\mathcal{F}^T}=\int_0^Tf(t)\overline{g(t)}\,dt$.
The \emph{response operator} $R^T: \mathcal{F}^T\mapsto
\mathcal{F}^T$ is introduced by the formula (\ref{RespJM}). Making
use of (\ref{Sol_spec_repr_JM}) implies the representation formula
for $R^T$:
\begin{equation*}
%\label{Resp_def}
\left(R^Tf\right)(t)=u_1^f(t)=\sum_{k=1}^{N}h_k(t)=\int_0^t
r(t-s)f(s)\,ds,
\end{equation*}
where
\begin{equation*}
%\label{resp_func_JM}
r(t)=\sum_{k=1}^{N}\frac{1}{\rho_k}S_k(t),%\quad \sum_{k=1}^N\frac{1}{\rho_k}=1.
\end{equation*}
is called a \emph{response function}. Note that the operator $R^T$
is a natural analog of a dynamic Dirichlet-to-Neumann operator
\cite{B07} in continuous, and \cite{MM7,MM8,MM10} in discrete
cases.

The \emph{inner space} of (\ref{DynSyst}), i.e. the space of
states is $\mathcal{H}^N:=\mathbb{C}^{N}$, indeed for any $T>0$
and $f\in \mathcal{F}^T$, we have that $u^f(T)\in \mathcal{H}^N$.
The scalar product in $\mathcal{H}^N$ is given by
\begin{equation*}
(a,b)_{\mathcal{H}^N}=\sum_{k=1}^N a_k\overline{b_k}.
\end{equation*}
The \emph{control operator} $W^T: \mathcal{F}^T\mapsto
\mathcal{H}^N$ is introduced by the rule:
\begin{equation*}
W^Tf=u^f(T).
\end{equation*}
Due to (\ref{Sol_spec_repr_JM}) we have that
$W^Tf=\sum_{k=1}^{N}h_k(T)\varphi_k$. In \cite{MM3,MM4} the
authors used real inner and outer spaces, but in the complex case
all the results are valid as well.

