\subsection{Krein equations.}
\label{Kr_eq}

By $f_k^T\in \mathcal{F}^T_1$ we denote the controls, driving the
system (\ref{DynSyst}) to prescribed \emph{special states}
\begin{equation*}
d_k\in \mathcal{H}^N, \,d_k=\left(0,\ldots,1,\ldots,0\right),\quad
k=1,\ldots,N.
\end{equation*}
%In other words, $f^T_k$ are the solutions to the equations
%$W^Tf_k^T=d_k$, $k=1\,\ldots,N$. By Lemma \ref{LemmaCont_JM} we
%know that such controls exist and are unique.
It is important that such a controls can be found as the solutions
to the Krein equations:
\begin{theorem}
\label{Krein_Th} The control $f_1^T$ can be found as the solution
to the following equation:
\begin{equation}
\label{Cont_f1_JM} \left(C^Tf_1^T\right)(t)=r(T-t),\quad 0<t<T.
\end{equation}
The controls $f^T_k$,  $k=2,\ldots,N$ satisfy the system:
\begin{equation}
\label{Cont_system_JM}
\begin{cases}
-\left(C^Tf_1^T\right)''=b_1C^Tf^T_1+a_1C^Tf^T_{2},\\
-\left(C^Tf_k^T\right)''=a_{k-1}C^Tf^T_{k-1}+b_kC^Tf^T_k+a_kC^Tf^T_{k+1},\quad
k=2,\ldots,N-1,\\
-\left(C^Tf_N^T\right)''=a_{N-1}C^Tf^T_{N-1}+b_NC^Tf^T_N.
\end{cases}
\end{equation}
%where we set $a_0=a_{N+1}=0.$
\end{theorem}


\section{De Branges space for $A$.}

Here we provide the information on de Branges spaces in accordance
with \cite{DBr,RR}. The entire function $E:\mathbb{C}\mapsto
\mathbb{C}$ is called a \emph{Hermite-Biehler function} if
$|E(z)|>|E(\overline z)|$ for $z\in \mathbb{C}_+$. We use the
notation $F^\#(z)=\overline{F(\overline{z})}$. The \emph{Hardy
space} $H_2$ is defined by: $f\in H_2$ if $f$ is holomorphic in
$\mathbb{C}^+$ and
$\sup_{y>0}\int_{-\infty}^\infty|f(x+iy)|^2\,dx<\infty$. Then the
\emph{de Branges space} $B(E)$ consists of entire functions such
that:
\begin{equation*}
B(E):=\left\{F:\mathbb{C}\mapsto \mathbb{C},\,F \text{ entire},
%\int_{\mathbb{R}}\left|\frac{F(\lambda)}{E(\lambda)}\right|^2\,d\lambda<\infty,
\,\frac{F}{E},\frac{F^\#}{E}\in H_2\right\}.
\end{equation*}
The space $B(E)$ with the scalar product
\begin{equation*}
[F,G]_{B(E)}=\frac{1}{\pi}\int_{\mathbb{R}}{ F(\lambda)}
\overline{G(\lambda)}\frac{d\lambda}{|E(\lambda)|^2}
\end{equation*}
is a Hilbert space. For any $z\in \mathbb{C}$ the
\emph{reproducing kernel} is introduced by the relation
\begin{equation}
\label{repr_ker} J_z(\xi):=\frac{\overline{E(z)}E(\xi)-E(\overline
z)\overline{E(\overline \xi)}}{2i(\overline z-\xi)}.
\end{equation}
Then
\begin{equation*}
F(z)=[J_z,F]_{B(E)}=\frac{1}{\pi}\int_{\mathbb{R}}{J_z(\lambda)}
\overline{F(\lambda)}\frac{d\lambda}{|E(\lambda)|^2}.
\end{equation*}
We observe that a Hermite-Biehler function $E(\lambda)$ defines
$J_z$ by (\ref{repr_ker}). The converse is also true
\cite{DMcK,DBr}:
\begin{theorem}
\label{TeorDB} Let $X$ be a Hilbert space of entire functions with
reproducing kernel such that
\begin{itemize}
\item[1)] For any $\omega\in \mathbb{C}$ the point evaluation is a
bounded functional, i.e. $|f(\omega)|\leqslant C_{\omega}\|f\|_X$,

\item[2)] if $f\in X$ then $f^\#\in X$ and $\|f\|_X=\|f^\#\|_X$,

\item[3)] if $f\in X$ and $\omega\in \mathbb{C}$ such that
$f(\omega)=0$, then $\frac{z-\overline{\omega}}{z-\omega}f(z)\in
X$ and
$\left\|\frac{z-\overline{\omega}}{z-\omega}f(z)\right\|_{X}=\|f\|_{X}$,
\end{itemize}
then $X$ is a de Branges space based on the function
\begin{equation*}
E(z)=\sqrt{\pi}(1-iz)J_i(z)\|J_i\|_X^{-1},
\end{equation*}
where $J_z$ is a reproducing kernel.
\end{theorem}



In the space $L_{2,\,\rho}(\mathbb{R})$ we take the subspace
spanned on the first $N$ polynomials generated by (\ref{Cauchy}):
\begin{equation*}
L_N:=\operatorname{Lin}\{\phi_1(\lambda),\ldots,\phi_N(\lambda)\}.
\end{equation*}
Note that $\phi_1(\lambda),\ldots,\phi_N(\lambda)$ are mutually
orthogonal in $L_{2,\,\rho}(\mathbb{R})$, see \cite{AH}. By $P_N:
L_{2,\,\rho}(\mathbb{R})\to L_{2,\,\rho}(\mathbb{R})$ we denote
the orthogonal projector in $L_{2,\,\rho}(\mathbb{R})$ onto $L_N$
acting by the rule:
\begin{equation*}
P_Na=\sum_{k=1}^N\left(a,\phi_k\right)_{L_{2,\,\rho}(\mathbb{R})}\phi_k(\lambda),\quad
a\in L_{2,\,\rho}(\mathbb{R}).
\end{equation*}
We introduce the Fourier transformation $\mathbb{R}^N\mapsto
L_{2,\,\rho}(\mathbb{R})$ by the formula
\begin{equation*}
(Fb)(\lambda)=\sum_{k=1}^Nb_k\phi_k(\lambda),\quad
b=(b_1,\ldots,b_N)\in \mathbb{R}^N.
\end{equation*}
Note that $F$ is an unitary map between $\mathbb{R}^N$ and $L_N$,
and
\begin{equation*}
b_k=\left(Fb(\lambda),\phi_k(\lambda)\right)_{L_{2,\,\rho}(\mathbb{R})}.
\end{equation*}


In accordance with the general approach proposed in
\cite{MM6,MM7}, we consider the \emph{reachable set} of the
dynamical system ({\ref{DynSyst}}):
\begin{equation*}
U^T:=W^T\mathcal{F}^T=\left\{u^f(T)\,|\, f\in
\mathcal{F}^T\right\}.
\end{equation*}
By the Lemma \ref{LemmaCont_JM} we know that
\begin{equation*}
U^T=W^T\mathcal{F}^T_1.
\end{equation*}
Then for any $f\in \mathcal{F}^T$ we can evaluate
\begin{eqnarray*}
\left(Fu^f(T)\right)(\lambda)=\sum_{k=1}^N
\int_{\mathbb{R}}\int_0^T
S_k(T-\tau,\beta)f(\tau)\,d\tau\phi_k(\beta)\,d\rho(\beta)\phi_k(\lambda)\\
=P_N\int_0^T S(T-\tau,\cdot)f(\tau)\,d\tau.
\end{eqnarray*}
We introduce the linear manifold of Fourier images of the
reachable set:
\begin{equation*}
B_N:=FU^T=\operatorname{Lin}\{\phi_1,\ldots,\phi_N\},
\end{equation*}
thus $B_N$ is a set of polynomials with complex coefficients of
the degree not grater than $N-1$.

The metric in $B_N$ is introduced by the following rule: for
$H,G\in B_N,$ such that $H=P_N\int_0^T
S(T-\tau,\cdot)h(\tau)\,d\tau,$ $G=P_N\int_0^T
S(T-\tau,\cdot)g(\tau)\,d\tau$, where $h,g\in \mathcal{F}^T_1$ we
set
\begin{equation*}
\left(H,G\right)_{B^T}:=\left(C^Th,g\right)_{\mathcal{F}^T}.
\end{equation*}
On the other hand, for $h,g\in \mathcal{F}^T_1$ we can evaluate
using the definition of $C^T$ and Fourier transformation:
\begin{eqnarray*}
%\label{sp_mes}
\left(H,G\right)_{B^T}=(C^Th,g)_{\mathcal{F}^T}=(u^h(T),u^g(T))_{\mathcal{H}^N}=\int_{\mathbb{R}}\left(Fu^h(T)\right)(\lambda)\left(Fu^h(T)\right)(\lambda)\,d\rho(\lambda)\\
=\int_{\mathbb{R}}\left(P_N\int_0^T
S(T-\tau,\cdot)h(\tau)\,d\tau\right)(\lambda) \left(P_N\int_0^T
S(T-\tau,\cdot)g(\tau)\,d\tau\right)(\lambda)\,d\rho(\lambda)\\
=\int_{\mathbb{R}}H(\lambda) G(\lambda)\,d\rho(\lambda)
\end{eqnarray*}
We note that for the systems considered in \cite{MM6,MM7} it was a
certain option in the choosing of the measure $d\rho(\lambda)$ in
the above calculations. Due to the infinite speed of wave
propagation in (\ref{DynSyst}), we do not have this option here.



We set \emph{the special control problem} for the system
(\ref{DynSyst}): to find a control $j_z\in \mathcal{F}^T_1$ which
drives (\ref{DynSyst}) to the prescribed state
\begin{equation*}
u_k^{j_z}(T)=\overline{\phi_k(z)}, \quad k=1,\ldots,N.
\end{equation*}
 at time $t=T$. Due to Theorem \ref{Krein_Th} such a control
 exists and is unique in $\mathcal{F}^T_1$. Then for such a
 control we can evaluate:
 \begin{equation*}
\left(C^Tj_z,g\right)_{\mathcal{F}^T}=\left(u^g(T),u^{j_z}(T)\right)_{\mathcal{H}^N}=\sum_{k=1}^Nu^g_k(T)\phi_k(z)=\left(Fu^g(T)\right)(z).
 \end{equation*}
Thus for
\begin{equation*}
%\label{repr_ker1}
J_z(\lambda):=\left(Fu^{j_z}(T)\right)(\lambda)
\end{equation*}
and $G(\lambda)=\left(Fu^g(T)\right)(\lambda)$ we have that
\begin{equation*}
\left(J_z,G\right)_{B_N}=\left(C^Tj_z,g\right)_{\mathcal{F}^T}=G(z).
\end{equation*}
In other words $J_z(\lambda)$ is a reproducing kernel in $B_N$.


To show that $B_N$ is a de Branges space we use the Theorem
\ref{TeorDB}, all three conditions of which are trivially
satisfied: indeed, for $G\in B_N$ such that $G=P_N\int_0^T
S(T-\tau,\cdot)g(\tau)\,d\tau$, where $g\in \mathcal{F}^T_1$ we
can evaluate:
\begin{eqnarray*}
|G(z)|=\left|(J_z,G)_{B_N}\right|=\left|\left(C^Nj_z,g\right)_{\mathcal{F}^N}\right|\\
\leqslant
\|\left(C^T\right)^{\frac{1}{2}}j_z\|_{\mathcal{F}^N}\|\left(C^N\right)^{\frac{1}{2}}g\|_{\mathcal{F}^N}
=\|\left(C^N\right)^{\frac{1}{2}}j_z\|_{\mathcal{F}^N}\|G\|_{B_N}.
\end{eqnarray*}
Clearly $G^\#$, being a polynomial is entire and
\begin{equation*}
\|G^\#\|_{B_N}=\left(\int_{-\infty}^\infty
\overline{\overline{G(\overline{\mu})}}\,\overline{G(\overline{\mu})}\,d\rho(\mu)\right)^\frac{1}{2}=\|G\|_{B_N}.
\end{equation*}
When $\omega\in \mathbb{C}$ such that $F(\omega)=0$, then
$\frac{z-\overline{\omega}}{z-\omega}F(z)$ is entire function and
\begin{equation*}
\left\|\frac{z-\overline{\omega}}{z-\omega}G(z)\right\|_{B_N}=\left(\int_{-\infty}^\infty
{\overline{\frac{z-\overline{\omega}}{z-\omega}G(z)}}\frac{z-\overline{\omega}}{z-\omega}G(z)\,d\rho(z)\right)^\frac{1}{2}=\|G\|_{B_N}.
\end{equation*}
Thus $B_N$ is a de Branges space.



