\section{Existence of Boundary Zeros} \label{sec:bdyzero}
\subsection{Key Lemmas}\label{sec:lemmas}
In this section, we record some facts about inverses, determinants, and the functions $f^t_A$ defined in \eqref{eqnft} that will be used later.

\begin{lemma}\label{lem:one-one elem of inverse matrix}
If $A$ is a square matrix and $\overline{A}$ is the matrix obtained from $A$ by removing its first row and column, then the $(1,1)$ entry of $A^{-1}$ is given by \[(A^{-1})_{11} = \frac{\det{\overline{A}}}{\det{A}}.\]
\end{lemma}

This is an immediate consequence of the adjugate formula for $A^{-1}.$ We will also require the following. 

\begin{lemma} \label{lem:Detmatrix} Let $M$ be a square matrix, partitioned as 
\[
M=
\left[
\begin{array}{c|c}
A  & B \\
\hline
C & D
\end{array}
\right],\]
where $A$ and $D$ are square matrices and $A^{-1}$ and $D^{-1}$ exist. Then 
\begin{equation}\label{det of partitioned matrix}
    \det(M) = \det(A)\det(D - CA^{-1}B) = \det(D)\det(A - BD^{-1}C).
\end{equation}
\end{lemma}

This is well known and can be found for example in (50) in Example 47 of \cite{Garcia2020}. We lastly record the following fact about the functions $f^t_A$ from \eqref{eqnft}:



\begin{lemma} \label{lem:1} Let $G_A$ be an $n$-vertex graph with $n \ge 3$. Fix $1 < i,j <n$ and let $G_{A'}$ be the graph obtained from $G_A$ by switching $v_i$ and $v_j$. Then for $t \in [0,1),$ $f^t_A = f^t_{A'}$.
\end{lemma}

\begin{proof} Let $U$ be the unitary matrix obtained from the $n \times n$ identity matrix $I$ by switching its $i^{th}$ and $j^{th}$ columns and note that $U^{-1} =U$. Then the adjacency matrices satisfy $A' = U A U$ and the formula for $z_Y$ gives $z_Y = U z_YU$. Thus,
 \[ (A'-z_Y)^{-1} =(UA U-z_Y)^{-1}= U (A - U z_Y U)^{-1} U = U (A - z_Y)^{-1} U.\]
As the application of $U$ does not alter the $(1,1)$ entry of $(A - z_Y)^{-1}$, \eqref{eqnft} implies that $f^t_A =f^t_{A'}.$
\end{proof}


\subsection{Proof of Theorem \ref{thm:1}} \label{subsec:thm1}
This section provides the proof of Theorem \ref{thm:1}. We first establish parts (i) and (ii) as the following proposition. The functions $\beta, \beta^{-1}, f_A, \phi_A,$ and  $p_A$ are defined as in the introduction with $t=0$.




\begin{proposition} \label{prop:Paz1} If $v_1$ and $v_n$ are not path connected, then $p_A \in \mathbb{C}[z_1]$. Furthermore, if $v_1$ is isolated, then $p_A$ is constant and if $v_1$ is not isolated, then $p_A$ is not constant.
\end{proposition} 

\begin{proof} By Lemma \ref{lem:1}, we can reorder the vertices of $G_A$ so that $v_1, \dots, v_m$ are exactly the vertices in the path-connected component of $G_A$ containing $v_1.$ Then $A$ can be partitioned as 
\[A = 
\left[
\begin{array}{c|c}
A_1 & 0 \\
\hline
0 & \star
\end{array}
\right], \ \text{ so } \ (A - z_Y)^{-1} = \left[
\begin{array}{c|c}
(A_1-z_1I)^{-1} & 0 \\
\hline
0 & \star
\end{array}
\right] ,
\]
where $A_1$ is an $m\times m$ matrix, $0$ and $I$ denote the zero and identity matrices of the appropriate size, and $\star$ denotes matrices immaterial to our calculations. From this, it is clear that the $(1,1)$ entry of $(A - z_Y)^{-1}$, and hence $f_A$, depends only on $z_1,$ so $p_A \in \mathbb{C}[z_1]$. 
Furthermore if $m=1$, then $f_A = -\frac{1}{z_1}$, which implies $\phi_A = -z_1$ and $p_A$ is constant. Moreover, the rational inner function form from \eqref{eqn:RIFform} implies that if $f_A$ only depends on $z_1$ and $p_A$ is constant, then $\phi_A = \alpha z_1^k$, for some $\alpha \in \mathbb{T}$, $k \in \mathbb{N}.$ That implies
\[ f_A(z_1) = \beta^{-1} \circ \phi_A \circ \beta   = -i + \frac{2i}{1 + \alpha (-1 + \frac{2i}{i+z_1})^k },\]
and if we expand this around $\infty$ for $z_1$ sufficiently large, we get
\begin{equation} \label{eqn:fAz1} f_A(z_1)= \left(-i + \frac{2 i}{\alpha (-1)^k+1}\right) - \frac{4(-1)^k \alpha k}{(1 + (-1)^k \alpha)^2}\frac{1}{z_1} + \text{higher order terms.}\end{equation}
Meanwhile, we can write $f_A$ using a Neumann series (for sufficiently large $z_1$) as
\[
\begin{aligned}
f_A(z_1) &=(A_1-z_1I)^{-1}_{11} = -\frac{1}{z_1}(I - \tfrac{1}{z_1}A_1 )^{-1}_{11}  \\ 
&= \sum_{n=0}^{\infty} -\frac{1}{z_1^{n+1}} (A_1^n)_{11} = 0 -\frac{1}{z_1} + \text{higher order terms.}\end{aligned}\]
Setting the first coefficient in \eqref{eqn:fAz1} to $0$ and the second to $-1$ implies that $\alpha =-1$ and $k=1$. Thus $f_A = -\frac{1}{z_1}$ is the only function in our paradigm yielding a constant $p_A$. 

Now, assume $v_1$ is not isolated. Thus, $v_1$ is connected to some other vertex $v_j$ and so, there are paths of length $2$ that begin and end at $v_1$. Because $(A^2)_{11}$ is the number of paths of length $2$ that begin and end at $v_1$, we know $(A^2)_{11} \ne 0$. Thus by the above expansion of $f_A$, if $v_1$ is not isolated, then $f_A \ne - \frac{1}{z_1}$, which means $p_A$ is not constant.
\end{proof}

To prove part (iii) of Theorem \ref{thm:1}, we require the following lemma, which gives us an easy way to use $f_A$ to identify when $p_A$ has a boundary zero at $(-1,1)$.

\begin{lemma} \label{lem:2} Define $h_A$ by $h_A(z_1,z_2) = f_A(-\tfrac{1}{z_1}, z_2)$ and write $h_A = \frac{q_1}{q_2},$ where $q_1, q_2$ are polynomials with no common factors. If $q_1(0,0)=0=q_2(0,0)$, then $p_A(-1,1)=0$.
\end{lemma}

\begin{proof} Note that for almost every $(z_1, z_2) \in \mathbb{C}^2$, $\phi_A$ satisfies
\[ 
\begin{aligned}
\phi_A(z_1, z_2) &= \beta \circ h_A\left( \frac{-1}{\beta^{-1}(z_1)}, \beta^{-1}(z_2) \right)\\
&= \frac{ q_2\left( -\tfrac{1}{\beta^{-1}(z_1)}, \beta^{-1}(z_2) \right) +iq_1\left( -\tfrac{1}{\beta^{-1}(z_1)}, \beta^{-1}(z_2) \right)}{q_2\left( -\tfrac{1}{\beta^{-1}(z_1)}, \beta^{-1}(z_2) \right)-iq_1\left( -\tfrac{1}{\beta^{-1}(z_1)}, \beta^{-1}(z_2) \right)}.\end{aligned}\]
Multiply through by the lowest powers of $(z_1-1)$ and $(z_2+1)$ to turn both the numerator and denominator into polynomials and denote those polynomials by $r_A, s_A$. Then
\[ \phi_A(z_1, z_2) = \frac{q_A(z_1, z_2)}{p_A(z_1, z_2)} = \frac{r_A(z_1, z_2)}{s_A(z_1, z_2)},\]
for almost every $(z_1, z_2) \in \mathbb{C}^2.$ By way of contradiction, assume $p_A(-1,1) \ne 0$. By our assumptions, $r_A(-1,1) = 0 = s_A(-1,1),$ which implies that $r_A, s_A$ must share a common, non-constant factor. This implies that $q_1, q_2$ share a common curve of zeros as well and hence, a common factor, which gives the contradiction. \end{proof}




Now we can prove part (iii) of Theorem \ref{thm:1}. 

\begin{proposition}\label{prop:pConn-genZero} If $v_1$ and $v_n$ are path connected, then $p_A \in \mathbb{C}[z_1, z_2]$ depends on $z_2$  and $p_A(-1,1)=0$.
\end{proposition}

\begin{proof} Assume that $v_1$ and $v_n$ are path connected. Define the submatrices $A_1$, $A_2$, $A_3$ and vectors $\alpha, \gamma, \zeta, \eta, b$ of the appropriate size, so that  
\[
A=
\left[
\begin{array}{c|c}
0 & \alpha^T\\
\hline
\alpha & A_1
\end{array}
\right] =
\left[
\begin{array}{c|c}
A_2  & \gamma \\
\hline
\gamma^T & 0
\end{array}
\right]
=
\left[
\begin{array}{c|c|c}
0 & \zeta^T & b \\
\hline
\zeta & A_3 & \eta \\
\hline
b & \eta^T & 0
\end{array}
\right].
\]
Then using Lemma \ref{lem:one-one elem of inverse matrix} and Lemma \ref{lem:Detmatrix}, we obtain
\[ f_A(z_1, z_2) = \frac{\det(A_1 - z_Y)}{\det(A - z_Y)} = \frac{\det(A_3 - z_1  I)(-z_2 - \eta^T(A_3 - z_1I)^{-1}\eta)}{\det(A_2 - z_1  I)(-z_2 - \gamma^T(A_2 - z_1I)^{-1}\gamma)}.\]
With an eye towards using Lemma \ref{lem:2}, replace $z_1$ with $-\tfrac{1}{z_1}$ and multiply by $\frac{z_1^{n-1}}{z_1^{n-1}}$ to obtain
\begin{equation} \label{eqn:hg}
h_A(z_1,z_2):=f_A(-\tfrac{1}{z_1}, z_2) 
=  \frac{z_1 \det(z_1A_3 + I)(-z_2 - z_1\eta^T(z_1A_3 +I)^{-1}\eta)}{\det(z_1A_2 +  I)(-z_2 - z_1\gamma^T(z_1A_2 + I)^{-1}\gamma)}.
\end{equation}
We claim that the factors containing $z_2$ in the numerator and denominator in \eqref{eqn:hg} cannot cancel out. By way of contradiction, assume that they do. Then for all $z_1$,
\[ \gamma^T \left(z_1A_2 +  I\right)^{-1} \gamma  = \eta^T \left(z_1A_3 + I\right)^{-1}\eta. \]
For small $z_1$, the Neumann series for $-z_1 A_1$ and $-z_1A_2$ converge and so, we can conclude
\[ \sum_{m=0}^{\infty} (-z_1)^{m}  \gamma^T A_2^m \gamma   =  \gamma^T \left(z_1A_2 + I\right)^{-1} \gamma  = \eta^T \left(z_1A_3 + I\right)^{-1}\eta = \sum_{m=0}^{\infty} (-z_1)^m \eta^T A_3^m \eta,\]
or more specifically, for all $m \ge 0,$
\begin{equation} \label{eqn:mequal}  \gamma^T A_2^m \gamma  = \eta^T A_3^m \eta.\end{equation}
Setting $m = 0$, this immediately gives $\gamma^T \gamma  = \eta^T \eta$, so $b=0.$ This implies that $v_1$ and $v_n$ are not connected by a single edge. But since they are path connected, $v_1$ must be path connected to some other vertex through a path that does not include $v_n$, such that this intermediate vertex is directly connected to $v_n$. By Lemma \ref{lem:1}, we can assume that this intermediate vertex is $v_{n-1}$.

Let $M$ denote the length of a path between $v_1$ and $v_{n-1}$ in $G_A$ that does not go through $v_n$. By well-known properties of adjacency matrices, $k:=(A_2)^M_{1,n-1}$ gives the number of paths between $v_1$ and $v_{n-1}$ of length $M$ in the graph obtained by removing $v_n$ from $G_A$. Then we can write
\[
A_2^M=
\left[
\begin{array}{c|c}
c & \begin{matrix}\epsilon^T & k \end{matrix} \\
\hline
\begin{matrix} \epsilon \\ k \end{matrix} & B + A_3^M \\
\end{array}
\right],
\]
where $k>0$, $\epsilon$ is a vector, and $B$ is a matrix, both with real, nonnegative entries. Then since $k>0$, $b=0$, and $\eta_{n-2} =1$ because $v_{n-1}$ and $v_n$ are path connected, we have
\[\gamma^T A_2^{2M} \gamma = \eta^T \left(  \begin{bmatrix} \epsilon \\ k \end{bmatrix} \begin{bmatrix}\epsilon^T & k \end{bmatrix} + (B + A_3^M)^2 \right ) \eta >\eta^T A_3^{2M} \eta,\]
which contradicts \eqref{eqn:mequal}.  Thus, the factors in the numerator and denominator that involve $z_2$ in \eqref{eqn:hg} do not cancel. 

Since those factors vanish at $(0,0),$ we can write $h_A = \frac{q_1}{q_2}$ where $q_1$ and $q_2$ are polynomials with no common factors and $q_1(0,0) =0=q_2(0,0).$ Thus, by Lemma \ref{lem:2}, $p_A(-1,1)=0$. Since $p_A(-1,1) =0$, it follows immediately that $p_A$ must have both $z_1$ and $z_2$-dependence, since if $\phi_A$  were one variable, it would be a finite Blaschke product, and those do not have singularities on $\mathbb{T}.$
\end{proof}

\subsection{Boundary zeros for nonzero t}\label{transition}

In this subsection, we track how the location of  boundary zeros of $p_A^t$ depends on the coloring parameter $t$. This allows us to use the $t=0$ case to derive results when $t \in (0,1)$ and in particular, prove Corollary \ref{cor:pt}.

We require this initial lemma. (Note the superscript $n$ in $z_j^n$  and $w_j^n$ below represents an index and not a power.)


\begin{lemma}\label{lem:phi_seq} Let $\phi$ be a rational inner function on $\mathbb{D}^2$ with stable polynomial denominator $p$ (after any common factors are canceled). Then

\begin{enumerate}
    \item[i.] If $p(\tau_1,\tau_2) = 0$ for $(\tau_1,\tau_2) \in \mathbb{T}^2$, then for almost every $\eta \in \mathbb{T}$, there is a sequence $z_n = (z_1^n,z_2^n) \subset \mathbb{T}^2$, with each $z_1^n \ne \tau_1$, each $z_2^n \ne \tau_2$, each $\phi(z_1^n,z_2^n) = \eta$, and $(z_1^n,z_2^n) \rightarrow (\tau_1, \tau_2)$.
    \item[ii.] Assume there are distinct $\eta_1, \eta_2 \in \mathbb{T}$ with corresponding sequences $z_n = (z_1^n,z_2^n) \subset \mathbb{T}^2$ and $w_n = (w_1^n,w_2^n) \subset \mathbb{T}^2$ such that $(z_1^n,z_2^n)$ and $(w_1^n,w_2^n)$ both converge to $(\tau_1,\tau_2) \in \mathbb{T}^2$ and $\phi(z_1^n,z_2^n) = \eta_1$ and $\phi(w_1^n,w_2^n) = \eta_2$ for all $n$. Then $p(\tau_1,\tau_2) = 0$.
\end{enumerate}
\end{lemma}



\begin{proof} For (i), note that since $\phi$ is a rational inner function, $p(\tau_1,\tau_2) = 0$ implies that $\phi$ does not have a continuous unimodular extension to a neighborhood of $(\tau_1, \tau_2)$ in $\mathbb{T}^2$; this would imply that $\phi$ actually extended analytically to a neighborhood of $(\tau_1,\tau_2)$ in $\mathbb{C}^2$, see Theorem 1.5 in \cite{kb13}, which in turn would contradict the fact that the numerator and denominator of $\phi$ have no common factors. Then the statement about level set sequences follows from an application of Corollary 1.7 in \cite{Pascoe17} and the description of these level sets (in terms of non-constant analytic functions for almost every $\eta$) in  Theorem 2.8  in \cite{bps19a}. For (ii), note that the assumptions imply that $\phi$ is discontinuous at $(\tau_1,\tau_2)$ and since $\phi$ is rational, its denominator must vanish at $(\tau_1, \tau_2).$
\end{proof}

Now we study the correspondence between boundary zeros in the $t = 0$ case and in the $t \neq 0$ case. We first study the boundary zero whose existence is often guaranteed by Theorem \ref{thm:1}.
\begin{proposition} \label{thm:7} Using the notation defined earlier, if $p_A(-1,1) = 0$, then $p_A^t(-1,-1) = 0$.
\end{proposition}

\begin{proof} Assume $p_A(-1,1) = 0$. By Lemma \ref{lem:phi_seq}, there exist  distinct $\eta_1, \eta_2 \in \mathbb{T}$ with $\eta_1, \eta_2 \neq -1$ that possess corresponding sequences $z_n = (z_1^n,z_2^n)$ and $ w_n= (w_1^n,w_2^n)$ in  $\mathbb{T}^2$  such that $z_n, w_n \rightarrow (-1,1)$ with $\phi_A(z_1^n,z_2^n) = \eta_1$, $\phi_A(w_1^n,w_2^n) = \eta_2$, and $z_1^n, w_1^n \ne -1$  for each $n$. Recall the definitions of $\beta, \beta^{-1}$ from \eqref{eqn:beta} and
 define sequences $r_n, s_n \subseteq \mathbb{R}^2$ by  $$r_n = (r_1^n,r_2^n) = (\beta^{-1}(z_1^n),\beta^{-1}(z_2^n)) \ \ \text{ and } \ \ s_n = (s_1^n,s_2^n) = (\beta^{-1}(w_1^n),\beta^{-1}(w_2^n))$$
 and note that $r_n, s_n \rightarrow (\beta^{-1}(-1),\beta^{-1}(1)) = (\infty, 0)$, in the sense that the sequences with elements $|\beta^{-1}(r^1_n)|$ and $ |\beta^{-1}(s^1_n)|$ diverge to infinity. Set $t_1 = \beta^{-1}(\eta_1) \in \mathbb{R}$ and $t_2 = \beta^{-1}(\eta_2) \in \mathbb{R}$. Since $f_A = \beta^{-1} \circ \phi_A \circ \beta$, we have $f_A (r_n) = t_1$, $f_A (s_n) =t_2$ for all $n.$

Now we shift these facts to the $t \in (0,1)$ setting.
By the definition from \eqref{eqnft}, we have $$f_A^t(z_1,z_2) = f_A\big(z_1,tz_1 + (1-t)z_2\big).$$ Construct a sequence $\hat{r}_n \subseteq \mathbb{R}^2$ from $r_n$ by 
$$\hat{r}_1^n = r_1^n, \;\;\; \hat{r}_2^n = \frac{1}{1-t}(r_2^n - tr_1^n)$$ 
and  construct $\hat{s}_n$ from $s_n$ in an identical way.
Then  $f_A^t(\hat{r}_n) =  f_A(r_n)=t_1$, $f_A^t(\hat{s}_n) = f_A(s_n)=t_2$ for all $n$, and 
 $\hat{r}_n,\hat{s}_n \rightarrow (\infty,\infty)$.


To convert this to the $\phi_A^t$ setting,  consider the sequences $\hat{z}_n = (\beta(\hat{r}^1_n), \beta(\hat{r}^2_n))$ 
and $\hat{w}_n = (\beta(\hat{s}^1_n), \beta(\hat{s}^2_n))$ in $\mathbb{T}^2.$ Then $\hat{z}_n,\hat{w}_n \rightarrow (-1,-1)$ and $\phi_A^t(\hat{z}_1^n,\hat{z}_2^n) = \eta_1$, $\phi_A^t(\hat{w}_1^n,\hat{w}_2^n) = \eta_2$ for all $n$. An application of Lemma \ref{lem:phi_seq} gives $p_A^t(-1,-1) = 0$, as needed.
\end{proof}

We can now prove Corollary \ref{cor:pt}.

%\begin{theorem} \label{col:1} If in an n-vertex graph $G_A$, vertex $1$ and vertex $n$ are path connected, then $p_A(-1,-1) = 0$ when $t \ne 0$.
%\end{theorem}

\begin{proof} Let vertices $v_1$ and $v_n$ be path connected. Then Theorem \ref{thm:1} immediately implies that $p_A(-1,1)=0$ and so, Proposition \ref{thm:7} tells us that $p_A^t(-1,-1)=0.$

Conversely, if $v_1$ and $v_n$ are not path connected, then arguments identical to those at the beginning of Proposition \ref{prop:Paz1} imply that $f_A^t$ (and hence $\phi_A^t$) only depends on $z_1$. Then $\phi_A^t$ is a finite Blaschke product, which cannot have any boundary singularities, and so its denominator $p_A^t$ cannot have any boundary zeros. 
\end{proof}

It is worth noting that one can also use the previous change-of-variables arguments to move between general boundary zeros of $p_A$ and general boundary zeros of $p_A^t$.


\begin{proposition} \label{thm:8} Using the notation defined earlier, for any $\tau_1,\tau_2 \in \mathbb{T}$ with $\tau_1,\tau_2 \neq -1$, $p_A(\tau_1,\tau_2) = 0$ if and only if $p_A^t(\lambda_1,\lambda_2) = 0$ where $\lambda_1 = \tau_1$ and $\lambda_2 = \beta\left(\dfrac{\beta^{-1}(\tau_2) - t\beta^{-1}(\tau_1)}{1 - t}\right)$.
\end{proposition}

\begin{proof}

The forward direction is proved in a way analogous to that of Proposition \ref{thm:7}.

For the backwards direction, the restriction that $\tau_1, \tau_2 \ne -1$ means that the limits of the sequences $\hat{r}_n, \hat{s}_n$ also determine the limits of the $r_n, s_n$ sequences (since none of the sequences diverge to $\infty$). Then we can simply reverse the steps in the proof Proposition \ref{thm:7}.
\end{proof}











\section{Contact Order} \label{sec:CO}
\subsection{Computing Contact Order} \label{subsec:COdef}
Let $\phi$ be a rational inner function with stable polynomial denominator $p$ and a boundary singularity at $(1,1)$. Recall the definition of $\tilde{p}$ from \eqref{eqn:tildep}.
%Let the bidegree of $p$ be $(m,n)$ and let $\tilde{p}$ denote the reflection of $p$, given by
%\[ \tilde{p}(z_1, z_2) = z_1^mz_2^n \overline{ p\left(\tfrac{1}{\bar{z}_1}, \tfrac{1} {\bar{z}_2} \right)}.\]
%Up to multiplication by a monomial $ \eta z_1^\ell z_2^k$ for $\eta \in \mathbb{T}$ and $\ell, k \in \mathbb{N}$, $\tilde{p}$ is exactly the numerator of $\phi$. 
Then
the contact order of $\phi$ at $(1,1)$ (or equivalently, the contact order of $p$ at $(1,1)$) is a positive even integer $K$ that measures how the zero set of $\tilde{p}$ approaches $(1,1)$ from within the face $\mathbb{T} \times \mathbb{D}$ of the bidisk. Specifically, $K$ is the number satisfying
\[ \inf \{ 1-|z_2|: \tilde{p}(z_1, z_2)=0\} \approx |1-z_1|^K\]
for $z_1\in \mathbb{T}$ and $z_2 \in \mathbb{D}$ both sufficiently close to $1$. More generally, if $\phi$ has a singularity at  $(\tau_1, \tau_2) \in \mathbb{T}^2$, then the contact order of $\phi$ at $(\tau_1, \tau_2)$ is just the contact order of $\psi(z_1, z_2):= \phi(\tau_1 z_1, \tau_2 z_2)$ at $(1,1).$

This bidisk definition translates  to a definition of contact order on the bi-upper half plane $\mathbb{H}^2$. Specifically, recalling the conformal map $\beta: \mathbb{H} \rightarrow \mathbb{D}$ given in \eqref{eqn:beta},
we can define a related polynomial
\begin{equation} \label{eqn:r}
r(w_1, w_2) = (1-iw_1)^m(1-iw_2)^n p \left( \beta(w_1), \beta(w_2)\right).
%q_2(w) &= (1-iw_1)^n(1-iw_2)^m\tilde{p} \left( \beta(w_1), \beta(w_2)\right).
\end{equation}
Then the relationship between $r$, $p$, and $\tilde{p}$ implies that $K$ is also the number satisfying 
\begin{equation} \label{eqn:COdef2} \inf \{ |\IM(w_2)|: r(x_1, w_2)=0\} \approx |x_1|^K,\end{equation}
for $x_1 \in \mathbb{R}$ $w_2 \in -\mathbb{H}$ 
 both sufficiently close to $0$. 

In this paper, the graph construction implies that the highest power of $z_2$ appearing in our rational inner functions  is at most $1$.  When $\phi$ has a singularity on $\mathbb{T}^2$, the highest power of $z_2$ in $p$ (and hence in $\phi$) cannot be $0$ and so must equal $1$. In that case, there is a particularly easy way to evaluate contact order on the bi-upper half plane.

\begin{remark} \label{rem:cor} Let $\deg p  = (n,1)$ and consider $f$ so that $\phi =\beta \circ f \circ \beta^{-1}$. Then, there is a polynomial $Q$ such that
\[
\beta \circ f = \phi \circ \beta = \frac{Q}{r},\]
where $r$ is defined in \eqref{eqn:r} and $Q$ and $r$ have no common factors. 
Clearly, $p(1,1)=0$ implies that $r(0,0)=0$.  Now find polynomials $r_1, r_2 \in \mathbb{C}[w]$ such that
\[ r(w_1, w_2) = r_1(w_1) + w_2 r_2(w_1) = r_2(w_1) \left( w_2 + \frac{r_1(w_1)}{r_2(w_1)}\right).\]
If $r_2(0)=0,$ then  since $r_1(0)=0$, $r$ would vanish along the line $w_1=0$, which cannot happen because $p$ can only have a finite number of zeros on $\mathbb{T}^2$. Thus, $r_2(0) \ne 0$, which means that we can expand the function $\frac{r_1}{r_2}$ in a power series centered at $w_1=0.$ Using \eqref{eqn:COdef2}, we can then conclude that the contact order $K$ of $\phi$ at $(1,1)$ is also the number that satisfies
\[ K = \min \left \{ k\in \mathbb{N}: \IM \Big( \left( \tfrac{r_1}{r_2}\right)^{(k)}(0)\Big) \ne 0\right \}.\]
Alternatively, let $\bar{r}_2$ denote the polynomial whose coefficients are exactly the complex complex conjugates of those of $r_2$. Then for real inputs $x$, we have $\bar{r}_2(x) = \overline{r_2(x)}$ and 
\[\frac{r_1(x)}{r_2(x)} =\frac{ r_1(x) \overline{r_2(x)}}{|r_2(x)|^2},\]
which shows that the contact order $K$ of $\phi$ at $(1,1)$ is also given by 
\[ K = \text{ the order of vanishing at $0$ of } \IM \Big( r_1(x) \overline{r_2(x)} \Big).\]

To compute this quantity in practice, we will start with writing $f=\frac{q_1}{q_2}$ for polynomials $q_1$ and $q_2$. If $q_1$ and $q_2$ have no common factors, then up to a constant factor, $r=q_2-iq_1$. However if $q_1$ and $q_2$ actually have a common factor of the form $m(z_1)$ with $m(0) \ne 0,$ then then order of vanishing of $\IM ( r_1(x) \overline{r_2(x)})$ at $0$ would be unaffected by still letting $r=q_2-iq_1$. Thus, in what follows, we simply require that $q_1$ and $q_2$ not share a common factor of $z_1$ or a factor involving $z_2.$

Additionally, in later theorems, we also encounter $\phi$ with a singularity at $(-1,1)$. As mentioned above, to compute its contact order, we computing the contact order of $\psi(z_1, z_2):= \phi(- z_1, z_2)$ at $(1,1).$ To do this computation, we note that if $\phi \circ \beta = \beta \circ f$, then $\psi \circ \beta = \beta \circ g,$
where $g(w_1, w_2) = f(-1/w_1, w_2).$ This means we can conduct the same argument as above to compute contact order, but with $g = \frac{q_1}{q_2}.$
\end{remark}

There is also a useful way to define contact order in terms of unimodular level sets of $\phi$, see Section $3$ in \cite{bps19a}, which we encode in the following remark:


\begin{remark} \label{rem:CO2} Let $\phi$ have a singularity at $(\tau_1, \tau_2) \in \mathbb{T}^2$. Then for all but a finite number of $\eta \in \mathbb{T}$, the unimodular level set 
\[ \mathcal{C}_\eta = \text{Closure of } \left\{ (z_1, z_2) \in \mathbb{T}^2 : \phi(z_1, z_2) = \eta \right\}\]
near $(\tau_1,\tau_2)$ can be parameterized by $\ell$ analytic functions $g^1_\eta, \dots, g^\ell_\eta$ (where $\ell$ does not depend on $\eta$) in the following way: there is an open neighborhood of $(\tau_1,\tau_2)$ such that all points of $\mathcal{C}_\eta$ in that set are of the form
\[(z_1, g^1_\eta(z_1)), \dots, (z_1, g^\ell_\eta(z_1))\]
 and such points are also in $\mathcal{C}_\eta$.
Then contact order is actually a measure of how these unimodular level sets agree near the singularity $(\tau_1,\tau_2)$ for different $\eta$ values. Specifically, as shown in \cite{bps19a}, for almost every $\eta_1, \eta_2 \in \mathbb{T}$ (called generic values), if we order the parameterizing functions appropriately, then
\[ K = \max_{1\le j \le \ell}\left \{ \text{Order of vanishing of } | g^j_{\eta_1}(z_1) - g^j_{\eta_2}(z_1) | \text{ at } \tau_1 \right\}.\]
In our setting, we generally have $\deg \phi = (n,1)$ for some $n$, which will imply that the number of branches of a generic $C_\eta$ will be $1$, so $\ell=1.$
\end{remark}


\subsection{Contact order and t-values} \label{subsec:COtvalues}
We can now examine the contact orders of zeros of stable polynomials $p_A$ or $p_A^t$ obtained via our construction.
We first establish the following connection between $t$ values and contact order at most related zeros of $p_A$ and $p_A^t$.

\begin{proposition} \label{prop:COt}
Let $\tau_1, \tau_2 \in \mathbb{T} \setminus \{-1\}$. By Proposition \ref{thm:8}, $p_A(\tau_1,\tau_2) = 0$ if and only if $p_A^t(\lambda_1,\lambda_2) = 0$ where 
\[ \lambda_1 = \tau_1 \ \ \text{ and } \ \ \lambda_2 = \beta\left(\dfrac{\beta^{-1}(\tau_2) - t\beta^{-1}(\tau_1)}{1 - t}\right).\]
Then the contact order of $p_A$ at $(\tau_1, \tau_2)$ equals the contact order of $p_A^t$ at $(\lambda_1, \lambda_2).$
\end{proposition}

\begin{proof} The fact that $f_A^t(z_1 ,z_2) = f_A (z_1, t z_1 +(1-t)z_2)$ and the connections between the $f_A, \phi_A$ and $f^t_A, \phi^t_A$ functions give
\[
\begin{aligned}
\phi_A^t (z_1, z_2) &= \phi_A \left( z_1, \beta\big( t \beta^{-1}(z_1) +(1-t) \beta^{-1}(z_2)\big)\right) \\
\phi_A (z_1, z_2) &= \phi_A^t \left( z_1, \beta\Big( \frac{ \beta^{-1}(z_2)-t\beta^{-1}(z_1)}{1-t}\Big)\right) 
\end{aligned}
\]
at every $(z_1,z_2) \in \overline{\mathbb{D}^2}$ with $z_1, z_2 \ne -1$. 

Assume that $p_A(\tau_1, \tau_2)=0$, so $p_A^t(\lambda_1, \lambda_2) =0$. We'll use the unimodular level set definition of contact order from Remark \ref{rem:CO2}. To that end, for each $\eta \in \mathbb{T}$, define
\[ 
\begin{aligned}
\mathcal{C}_\eta &= \text{Closure of } \left\{ (z_1, z_2) \in \mathbb{T}^2 : \phi_A(z_1, z_2) = \eta \right\}, \\
\mathcal{C}^t_\eta &= \text{Closure of } \left\{ (z_1, z_2) \in \mathbb{T}^2 : \phi_A^t(z_1, z_2) = \eta \right\}.
\end{aligned}
\]
Then for every $(z_1, z_2) \in \mathbb{T}^2$ near $(\tau_1, \tau_2)$, we have $(z_1, z_2) \in \mathcal{C}_\eta$ if and only if 
\[\left(z_1, \beta \left( \frac{\beta^{-1}(z_2)-t \beta^{-1}(z_1)}{1-t}\right)\right) \in \mathcal{C}^t_\eta.\]
Choose $\eta_1, \eta_2 \in \mathbb{T}$ generic for both $\phi_A$ and $\phi_A^t$. Because the degrees of $\phi_A$ and $\phi_A^t$ in $z_2$ are $1$, each $\mathcal{C}_{\eta_k}, \mathcal{C}^t_{\eta_k}$  can be parameterized by a single analytic function
 $z_2=g_{\eta_k}(z_1)$ or $z_2=g^t_{\eta_k}(z_1)$ and the relationship between $\mathcal{C}_\eta$ and $\mathcal{C}^t_\eta$ implies that 
\begin{equation} \label{eqn:gteta} g^t_{\eta_k}(z_1) = \beta \left( \frac{\beta^{-1}(g_{\eta_k}(z_1))-t \beta^{-1}(z_1)}{1-t}\right).  \end{equation}
 Let $K$ be the contact order of $\phi_A$ at $(\tau_1,\tau_2)$. Then  
\[
\begin{aligned}
K &= \text{Order of vanishing of } | g_{\eta_1}(z_1) - g_{\eta_2}(z_1) | \text{ at } \tau_1 \\
&= \min \left \{ L: \frac{d^L}{dz_1^L}\left(g_{\eta_1} - g_{\eta_2}\right)|_{z_1=\tau_1}\ne0\right\}\\
& =  \min \left\{L :g^{(L)}_{\eta_1}(\tau_1) \ne  g^{(L)}_{\eta_2}(\tau_1)\right\}.
\end{aligned}
\]
Let $K_t$ be the contact order of $\phi_A^t$ at $(\lambda_1,\lambda_2)$. Then  
\[ 
\begin{aligned}K_t &=  \text{Order of vanishing of } | g^{t}_{\eta_1}(z_1) - g^{t}_{\eta_2}(z_1) | \text{ at } \lambda_1  \\
& =  \min \left \{ L: \left(g^{t}_{\eta_1}\right)^{(L)}(\lambda_1) \ne  \left(g^{t}_{\eta_2}\right)^{(L)}(\lambda_1) \right\}.
\end{aligned}
\]
Using \eqref{eqn:gteta}, $\tau_1, \tau_2 \ne -1$, and $\tau_1 =\lambda_1$, we can see that if
\[g^{(\ell)}_{\eta_1}(\tau_1) =  g^{(\ell)}_{\eta_2}(\tau_1)\]
for $\ell=0, \dots, L-1$, then 
\[\left(g^{t}_{\eta_1}\right)^{(\ell)}(\lambda_1) =  \left(g^{t}_{\eta_2}\right)^{(\ell)}(\lambda_1) \]
for $\ell=0, \dots, L-1$ as well. This immediately implies that $K \le K_t.$
A similar argument (using the converse formulas) gives $K_t \le K$ and completes the proof.
\end{proof}




