Before proving  Theorem \ref{thm:COpaths}, we prove a related lemma. Below, for nonnegative integers $a,b$, we let ${{a} \choose {b}}$ be defined as follows:
\[{{a} \choose {b}} = \frac{a!}{b!(a-b)!} \text{ if } a \ge b \ \ \text{ and }  \ \ {{a} \choose {b}} = 0 \text{ if } a <b.\]
Then we have the following computation.


\begin{lemma} \label{lem:bionomial} Let $a_1, a_2, k \in \mathbb{N}$ with $a_1 >k$ and $a_2 \ge k$. Then $$\sum_{m=0}^{k} {{a_1 - m} \choose {m}}{{a_2 - (k-m)} \choose {k-m}} = \sum_{m=0}^{k} {{a_1 - 1 - m} \choose {m}}{{a_2 + 1 - (k-m)} \choose {k-m}}.$$
\end{lemma}

\begin{proof} For ease of notation, define 
\[
\begin{aligned} \text{Sub}(a_1,a_2,k)&:= \sum_{m=0}^{k} {{a_1 - m} \choose {m}}{{a_2 - (k-m)} \choose {k-m}} \\
&\hspace{.5in} - \sum_{m=0}^{k} {{a_1 - 1 - m} \choose {m}}{{a_2 + 1 - (k-m)} \choose {k-m}}.\end{aligned} \]
%Then, setting $b_1 =a_1- k$ and $b_2 = a_2 -k$, we can see that  $\text{Sub}(a_1,a_2,k) =0$ for all $a_1, a_2, k$ with $a_1 >k$ and $a_2 \ge k$ if and only if $\text{Sub}(b_1 + k,b_2 + k,k)=0$ for all $k, b_1, b_2 \in \mathbb{N}$ with $b_1 \ge 1.$ 
We will prove $\text{Sub}(a_1,a_2,k) =0$ for all $a_1, a_2, k$ with $a_1 >k$ and $a_2 \ge k$ by induction on $k$. For the base case $k=0$, fix any $a_1, a_2 \in \mathbb{N}$ with $a_1 >0$ and $a_2 \ge 0$ and observe that
$$\text{Sub}(a_1,a_2,0) = {{a_1 } \choose {0}}{{a_2 } \choose {0}} - {{a_1 - 1 } \choose {0}}{{a_2 + 1 } \choose {0}} = 1 \cdot 1 - 1 \cdot 1 = 0.$$

For the inductive step, assume that $\text{Sub}(c_1,c_2,k-1) =0$ for all $c_1, c_2 \in \mathbb{N}$ with $c_1 >k-1$ and $c_2 \ge k-1$. Fix $a_1 >k$ and $a_2 \ge k$. We will show  $\text{Sub}(a_1,a_2,k) =0.$ As part of that argument, we use Pascal's formula, which holds for all $j, \ell >0$ (though if $j <\ell$, then the coefficient is $0$):
\begin{equation} \label{eqn:pascal} {{j}\choose{\ell}} = {{j-1}\choose{\ell}} + {{j-1}\choose{\ell-1}}.\end{equation}
Using the formula for $\text{Sub}(a_1,a_2,k)$, extracting one term from each sum, using the Pascal's triangle formula on each sum, and canceling any common terms from the two sums gives:

\begin{align*}
\text{Sub}&(a_1,a_2,k) = \sum_{m=0}^{k} {{a_1 - m} \choose {m}}{{a_2 - (k-m)} \choose {k-m}}\\
&\hspace{.75in}- \sum_{m=0}^{k} {{a_1 - 1 - m} \choose {m}}{{a_2 + 1 - (k-m)} \choose {k-m}} \\
&= {{a_2 - k} \choose k} + \sum_{m=1}^{k} \left( {{a_1 - m - 1}\choose{m}}+ {{a_1 - m - 1}\choose{m-1}}\right) {{a_2 - (k-m)} \choose {k-m}}  \\
& \quad - \sum_{m=0}^{k-1}{{a_1 - m - 1}\choose{m}}\left({{a_2 - (k-m)} \choose {k-m}} + {{a_2 - (k-m)} \choose {k-m-1}}\right) - {{a_1-1-k}\choose{k}}  \\
&= {{a_2-k}\choose{k}} - {{a_1 - 1 - k} \choose k} + {{a_1 - 1 - k} \choose k} - {{a_2-k}\choose{k}} \\
& \quad + \sum_{m=1}^{k}{{a_1 - m - 1}\choose{m-1}}{{a_2 - (k-m)} \choose {k-m}} - \sum_{m=0}^{k-1}{{a_1 - m - 1}\choose{m}}{{a_2 - (k-m)} \choose {k-m-1}}. 
\end{align*}
Canceling terms and re-indexing the first sum gives:
\begin{align*}
\text{Sub}(a_1,a_2,k)&= \sum_{m=0}^{k-1}{{(a_1 - 1) - m - 1}\choose{m}}{{a_2 - (k-1-m)} \choose {k-1-m}}  \\
& \qquad  \qquad - \sum_{m=0}^{k-1}{{a_1 - 1-m}\choose{m}}{{a_2 -1- (k-1-m)} \choose {k-1-m}} \\
&= -\text{Sub}(a_1-1,a_2-1,k-1 ) =0,\end{align*}
by the inductive hypothesis. This completes the proof.
\end{proof}


Now we can prove Theorem \ref{thm:COpaths}:

\begin{proof} Since $v_1$ and $v_n$ are path connected, Theorem $\ref{thm:1}$ implies that $p_{A_n}(-1,1)=0.$ We will use Remark \ref{rem:cor} to show that the contact order of $p_A$ at $(-1,1)$ is $2n-2$. First write
\[ g_{A_n}(z_1, z_2) : = f_{A_n} \left(-\tfrac{1}{z_1}, z_2 \right) = \frac{q_1}{q_2}(z_1, z_2),  \]
where the polynomials $q_1, q_2$ have no common factors of $z_1$ or common factors involving $z_2$ and define $r_1, r_2 \in \mathbb{C}[z]$ so that 
\begin{equation} \label{eqn:r1r2} \left( q_2- i q_1\right) (z_1, z_2) 
= r_1 (z_1) + z_2 r_2(z_1). 
\end{equation}
Then the contact order of $p_{A_n}$ at $(-1,1)$ is the order of vanishing of $\IM(r_1(x) \overline{r_2(x)})$ near $0$. To compute that, let $\widehat{z}_Y$ be the diagonal matrix (of appropriate size) with entries $-\frac{1}{z_1}, -\frac{1}{z_1}, \dots, -\frac{1}{z_1}, z_2$ along the diagonal and observe that for $n >3$,
\begin{equation} \label{eqn:gan}
g_{A_n}(z_1,z_2) = \frac{\det(A_{n-1} - \widehat{z}_Y)}{\det(A_{n} - \widehat{z}_Y)} =  \frac{-z_2\det(A_{n-2} +\frac{1}{z_1}I)-\det(A_{n-3} +\frac{1}{z_1}I) }{-z_2\det(A_{n-1} +\frac{1}{z_1}I)-\det(A_{n-2} +\frac{1}{z_1}I) },\end{equation}
where we used the structure of the $A_n$ matrices. This shows that we will need a formula for
\[ G(n, z_1):=\det(A_n - z_1 I).\]
Direct computation gives $G(1, z_1)=-z_1,$ $G(2, z_1)= z_1^2 - 1$, and the structure of the $A_n$ matrices gives the recursive formula 
\[ G(n,z_1) = -z_1 G(n-1, z_1) - G(n-2, z_1).\]
%$det(A_n - z_1 I) = -z_1 det(A_{n-1}) - det (A_{n-2}), \quad \text{ for } n \ge 3.$
We claim that 
\[ G(n, z_1)=
\begin{cases}\displaystyle
\sum_{m=0}^{\frac{n-1}{2}} {{\frac{n+1}{2}+m}\choose{\frac{n-1}{2}-m}} (-1)^{\frac{n+1}{2}-m}z_1^{2m+1}, & \textrm{for $n$ odd},\\
\displaystyle \sum_{m=0}^{\frac{n}{2}} {{\frac{n}{2}+m}\choose{\frac{n}{2}-m}} (-1)^{\frac{n}{2}-m}z_1^{2m}, & \textrm{ for $n$ even.}
\end{cases}\]
Our earlier formulas imply that this holds for $n=1,2$ and we prove the result via induction for $n \ge 3$. Specifically, we assume that the formula holds for $n=k-2$ and $n=k-1$ and we show that it holds for $n=k$.  Since the cases are almost identical, we show the case when $k$ is odd and leave the case when $k$ is even to the reader. 

Since $k$ is odd, we know $k-1$ is even and $k-2$ is odd. Applying the inductive hypothesis, extracting the last term of the first sum, using Pascal's formula \eqref{eqn:pascal} to combine the two sums, and then adding the final term back in gives
\begin{align*}
G(k, z_1) &= -z_1 G(k-1, z_1) - G(k-2, z_1) \\ 
&= - \sum_{m=0}^{\frac{k-1}{2}} {{\frac{k-1}{2} + m}\choose{\frac{k-1}{2} - m}} (-1)^{\frac{k-1}{2}-m} z_1^{2m+1} 
-\sum_{m=0}^{\frac{k-3}{2}} {{\frac{k-1}{2} + m}\choose{\frac{k-3}{2} - m}} (-1)^{\frac{k-1}{2}-m} z_1^{2m+1}\\
&= \sum_{m=0}^{\frac{k-3}{2}} {{\frac{k+1}{2} + m}\choose{\frac{k-1}{2} - m}} (-1)^{\frac{k+1}{2}-m} z_1^{2m+1} - z_1^{k}\\
&= \sum_{m=0}^{\frac{k-1}{2}} {{\frac{k+1}{2} + m}\choose{\frac{k-1}{2} - m}} (-1)^{\frac{k+1}{2}-m} z_1^{2m+1},
\end{align*}
as needed. 

To study $g_{A_n}$, we consider
\[
\begin{aligned} h(n,z_1):= z_1^n G\left (n,\tfrac{1}{z_1}\right) &=\begin{cases} \displaystyle
\sum_{m=0}^{\frac{n-1}{2}} {{\frac{n+1}{2}+m}\choose{\frac{n-1}{2}-m}} (-1)^{\frac{n+1}{2}-m}z_1^{n - 2m - 1}, & \textrm{for $n$ odd},\\
\displaystyle \sum_{m=0}^{\frac{n}{2}} {{\frac{n}{2}+m}\choose{\frac{n}{2}-m}} (-1)^{\frac{n}{2}-m}z_1^{n - 2m}, & \textrm{for $n$ even}
\end{cases}\\
& =\begin{cases} \displaystyle
\sum_{m=0}^{\frac{n-1}{2}} {{n - m}\choose{m }} (-1)^{m+1 }z_1^{2m}, & \textrm{for $n$ odd,}\\
 \displaystyle \sum_{m=0}^{\frac{n}{2}} {{n - m}\choose{m}} (-1)^{m}z_1^{2m} & \textrm{for $n$ even,}
\end{cases}
\end{aligned}\]
where the second line following by re-indexing the sums (basically replacing $m$ with $\frac{n-1}{2} - m$ for odd cases, and $m$ with $\frac{n}{2} - m$ for even cases). Then from \eqref{eqn:gan}
\begin{align*}
g_{A_n}(z_1,z_2) &= \frac{-z_2G(n-2,-\frac{1}{z_1}) - G(n-3,-\frac{1}{z_1})}{-z_2G(n-1,-\frac{1}{z_1}) - G(n-2,-\frac{1}{z_1})} \\
&= \frac{z_1^{n-1}\big(z_2G(n-2,-\frac{1}{z_1}) + G(n-3,-\frac{1}{z_1})\big)}{z_1^{n-1}\big(z_2G(n-1,-\frac{1}{z_1}) + G(n-2,-\frac{1}{z_1})\big)} \\
&= \frac{z_1 z_2h(n-2,-z_1) + z^2_1 h(n-3,-z_1)}{z_2h(n-1,-z_1) + z_1 h(n-2,-z_1)}\\
&=\frac{z_1z_2 h(n-2,z_1) + z^2_1 h(n-3,z_1)}{z_2h(n-1,z_1) +z_1 h(n-2,z_1)},
\end{align*}
since the powers of $z_1$ in the formula for $h(n,z_1)$ are always even. The numerator and denominator of the above fraction give us $q_1$ and $q_2$; specifically, we can see that they have no common factor involving $z_2$ since $p_{A_n}$ has a zero at $(-1,1)$ and no common factor of $z_1$ since $h(n-1,z_1)$ has a non-zero constant term. Then, we can compute
\[ 
\begin{aligned}\left( q_2- i q_1\right)& (z_1, z_2) 
= z_2 h(n-1,z_1) +z_1 h(n-2,z_1) 
\\ & \hspace{1in} - i\Big( z_1z_2 h(n-2,z_1)  + z^2_1 h(n-3,z_1)\Big) \\
&=\big( z_1 h(n-2,z_1)- iz^2_1 h(n-3,z_1) \big)+z_2\big( h(n-1,z_1) - iz_1 h(n-2,z_1)\big).
\end{aligned}
\]
This gives us $r_1$ and $r_2$ via \eqref{eqn:r1r2} and so, we just need to compute the order of vanishing of 
\[\IM(r_1(x) \overline{r_2(x)}) = x^2 h(n-2,x)h(n-2,x) -x^2h(n-1,x)h(n-3,x),
\]
Note that this requires $n >3$. The cases $n=2,3$ can be easily checked by hand.
As before, we assume that $n$ is odd, since the even case can be handled very similarly.  Then
\begin{align*}
-\IM(r_1(x) \overline{r}_2(x))  
&= x^2\sum_{m=0}^{\frac{n-1}{2}} {{n-1-m}\choose{m}} (-1)^mx^{2m} \sum_{j=0}^{\frac{n-3}{2}} {{n-3-j}\choose{j}} (-1)^jx^{2j} \\
&- x^2 \sum_{m=0}^{\frac{n-3}{2}} {{n-2-m}\choose{m}} (-1)^{m+1} x^{2m} \sum_{j=0}^{\frac{n-3}{2}} {{n-2-j}\choose{j}} (-1)^{j+1}x^{2j} \\
&= x^2\sum_{k=0}^{n-2} c_k x^{2k},
\end{align*}
for coefficients $c_k \in \mathbb{R}$. We claim that all coefficients are $0$, except $c_{n-2}$. First note that
\[c_{n-2} = {{\tfrac{n-1}{2}}\choose{\frac{n-1}{2}}}{{\tfrac{n-3}{2}}\choose{\frac{n-3}{2}}}(-1)^{n-2}  = (-1)^{n-2} = -1. \]
To show that the other coefficients are zero, we consider two cases. First, if $0 \le k \le \frac{n-3}{2},$ then $c_k$ equals
\[ (-1)^{k}\sum_{m=0}^{k} \left( {{n-1-m}\choose{m}}  {{n-3-(k-m)}\choose{k-m}}-
{{n-2-m}\choose{m}}  {{n-2-(k-m)}\choose{k-m}}\right), \]
which is $0$ by Lemma \ref{lem:bionomial}. Meanwhile, if $\frac{n-1}{2} \le k \le n-3$, then we have some restrictions on the terms that appear in the formula for $c_k.$ Namely, one can check that $c_k$ equals $(-1)^k$ times
\[\sum_{m=k-\frac{n-3}{2}}^{\frac{n-1}{2}} \hspace{-.08in} {{n-1-m}\choose{m}}  {{n-3-(k-m)}\choose{k-m}}-\hspace{-.08in} \sum_{m=k-\frac{n-3}{2}}^{\frac{n-3}{2}} \hspace{-.08in} {{n-2-m}\choose{m}}  {{n-2-(k-m)}\choose{k-m}}. \]
However, when $m$ is both outside of the current sum bounds and satisfies $0\le m \le k$, the binomial coefficient formulas in the summands are both well defined and equal zero.  Thus, we can also write the formula for $c_k$ as 
\[ (-1)^{k}\sum_{m=0}^{k} \left( {{n-1-m}\choose{m}}  {{n-3-(k-m)}\choose{k-m}}-
{{n-2-m}\choose{m}}  {{n-2-(k-m)}\choose{k-m}}\right), \]
which is again $0$ by Lemma \ref{lem:bionomial}. This means that for $n$ odd, 
\[\IM(r_1(x) \overline{r_2(x)}) = x^{2n-2}\]
and so the contact order of $p_{A_n}$ at $(-1,1)$ is $2n-2$. An analogous argument gives the result for $n$ even.
\end{proof}



\subsection{Contact Order with Graph Modifications} \label{subsec:GM}

In this section, we investigate Conjecture \ref{con:CO} and prove Theorem \ref{thm:CO2}, which gives three cases that support the conjecture. We split the proof into the three different cases below.

Throughout these proofs we will use the following notation: for an arbitrary $n\times n$ matrix $M$, we let $\overline{M}$ denote the $(n-1) \times (n-1)$ matrix obtained from $M$ by removing its first row and first column, $\underline{M}$ 
denote the $(n-1) \times (n-1)$ matrix obtained from $M$ by removing its last row and last column, and $\overline{\underline{M}}$ denote the $(n-2) \times (n-2)$ matrix obtained from $M$ by removing both its first row and first column and its last row and last column.

For the first case in Theorem \ref{thm:CO2}, let $G_A$ be an $n$-vertex graph (as always, undirected and simple) with the vertices $v_1$ and $v_n$ path connected. We define a new graph $G_{\widehat{A}}$ as the graph we get from $G_A$ by adding a vertex $v_{n+1}$ that is only connected directly to $v_n.$ Specifically, $G_{\widehat{A}}$ has the adjacency matrix  
\begin{equation}\label{eqn:A_hat}
    \widehat{A} = \left[
\begin{array}{c|c}
A & \begin{array}{c} 0 \\ \vdots \\ 0 \\ 1 \end{array} \\
\hline
\begin{array}{ccccc} 0 & \cdots & 0 & 1\end{array} & 0
\end{array}
\right].
\end{equation}
