Then we have the following result.

\begin{theorem} \label{thmCO:i} Let $G_A$ be an $n$-vertex graph with $v_1$ and $v_n$ path connected. Assume that the contact order of $p_A$ at $(-1,1)$ is $K$. 
Then, with $\widehat{A}$ defined in \eqref{eqn:A_hat}, the contact order of $p_{\widehat{A}}$ at $(-1,1)$ is $K+2$.
\end{theorem}




\begin{proof} We will use Remark \ref{rem:cor} to obtain tractable formulas for the contact orders of $p_A$ and $p_{\widehat{A}}$ at $(-1,1)$ that will allow us to compare the two quantities directly. To that end, we consider polynomials $q_1, q_2, \hat{q}_1, \hat{q_2}$ that satisfy
\[ g_A(z_1, z_2) : = f_A \left(-\tfrac{1}{z_1}, z_2 \right) = \frac{q_1}{q_2} \ \ \text{ and } \ \ g_{\widehat{A}}(z_1, z_2) : = f_{\widehat{A}}\left(-\tfrac{1}{z_1}, z_2 \right) = \frac{\hat{q}_1}{\hat{q}_2}  \]
and the pairs $(q_1, q_2)$ and $(\hat{q}_1, \hat{q}_2)$ do not have any common factors of $z_1$ or common factors involving $z_2.$
Then if we define $r_1, r_2, \hat{r}_1, \hat{r}_2 \in \mathbb{C}[z]$ so that they satisfy 
\begin{equation} \label{eqn:qrconn} \left( q_2- i q_1\right) (z_1, z_2) 
= r_1 (z_1) + z_2 r_2(z_1) 
\ \ \text{ and } 
\ \ \left( \hat{q}_2- i \hat{q}_1\right) (z_1, z_2) = \hat{r}_1 (z_1) + z_2 \hat{r}_2(z_1), \end{equation}
$K$ is the order of vanishing of $\IM( r_1(x) \overline{r_2(x)})$ near $0$ and the contact order of $p_{\widehat{A}}$ at $(-1,1)$ is the order of vanishing of $\IM( \hat{r}_1(x) \overline{\hat{r}_2(x)})$ near $0$. 

Now we find formulas for $q_1, q_2, \hat{q}_1, \hat{q_2}$. Let $\widehat{z}_Y$ be the diagonal matrix (of appropriate size) with entries $-\frac{1}{z_1}, -\frac{1}{z_1}, \dots, -\frac{1}{z_1}, z_2$ along the diagonal. Then
\begin{equation}\label{eqn:gAcok} g_A(z_1, z_2) = \frac{\det(\overline{A} - \widehat{z}_Y)}{\det(A - \widehat{z}_Y)} = \frac{ z_1^{n-1} \left( -z_2 \det\left(\overline{\underline{A}} + \tfrac{1}{z_1}I\right) -s_1\left( \tfrac{1}{z_1}\right) \right) }{ z_1^{n-1} \left( -z_2 \det\left(\underline{A} + \tfrac{1}{z_1}I\right) -s_2\left( \tfrac{1}{z_1}\right) \right) },
\end{equation}
where we expanded the determinant using the Laplace expansion method along the last column and last row of $(A- \widehat{z}_Y)$ and $(\overline{A}- \widehat{z}_Y)$ and where $s_1, s_2 \in \mathbb{R}[z]$ satisfy $\deg s_1 \le n-3$ and $\deg s_2 \le n-2$. Then we can take the numerator and denominator of \eqref{eqn:gAcok} to be $q_1, q_2$, since the denominator does not vanish identically when $z_1=0$ (so there is no common factor of $z_1$) and vertices $v_1$ and $v_n$ are path connected (so a factor involving $z_2$ cannot cancel). 

For $g_{\widehat{A}}$, we can use Laplace expansion first along the last row and column to reduce to a formula involving $A$ and then apply Laplace expansion again (in a way analogous to that for $g_A$) to obtain
\[ \begin{aligned} 
  g_{\widehat{A}}(z_1, z_2) &= \frac{\det\left (\overline{\widehat{A}} - \widehat{z}_Y\right)}{\det\left(\widehat{A} - \widehat{z}_Y\right)} = \frac{ -z_2 \det \left(\overline{A} + \tfrac{1}{z_1} I\right) - \det\left(\overline{\underline{A}} +\tfrac{1}{z_1}I\right)}{ -z_2 \det \left(A + \tfrac{1}{z_1} I\right) - \det\left(\underline{A} +\tfrac{1}{z_1} I\right)} \\
&= \frac{ z_1^n\left( z_2 \left( {-} \frac{1}{z_1} \det \left(\overline{\underline{A}} + \tfrac{1}{z_1} I\right) + s_1\left( \frac{1}{z_1} \right) \right) - \det\left(\overline{\underline{A}} +\tfrac{1}{z_1}I\right)\right)}{ z_1^n\left(z_2 \left( {-} \frac{1}{z_1}\det \left(\underline{A} + \tfrac{1}{z_1} I\right) +s_2\left(\frac{1}{z_1}\right) \right) -\det\left(\underline{A} +\tfrac{1}{z_1}I\right)\right)}. \label{eqn:gAcok2}
\end{aligned} \]
As before, we can take the numerator and denominator of the above expression to be $\hat{q}_1, \hat{q}_2$. From this and \eqref{eqn:qrconn}, we can easily identify $r_1, r_2, \hat{r}_1,$ and $\hat{r}_2:$
\[
\begin{aligned}
r_1(z_1)&= -z_1^{n-1} \left( s_2\left( \tfrac{1}{z_1}\right) - i    s_1\left( \tfrac{1}{z_1}\right) \right) \\
r_2(z_1) &=  -z_1^{n-1} \left( \det\left(\underline{A} + \tfrac{1}{z_1}I\right)- i \det\left(\overline{\underline{A}} + \tfrac{1}{z_1}I\right) \right) \\
\hat{r}_1(z_1)&=-z_1^{n}\left( \det\left(\underline{A} +\tfrac{1}{z_1}I\right) - i \det\left(\overline{\underline{A}} +\tfrac{1}{z_1}I\right)\right) \\
\hat{r}_2(z_1)& =z_1^{n}\left( {-} \tfrac{1}{z_1}\det \left(\underline{A} + \tfrac{1}{z_1} I\right) +s_2\left(\tfrac{1}{z_1}\right) - i \left({-} \tfrac{1}{z_1} \det \left(\overline{\underline{A}} + \tfrac{1}{z_1} I\right) + s_1\left( \tfrac{1}{z_1} \right) \right) \right).
\end{aligned}
\]
By assumption, we know for $x \in \mathbb{R}$ near $0$,
\begin{equation} \label{eqn:coks1s2} x^K \approx \IM( r_1(x) \overline{r_2(x)})  = x^{2n-2} \left(s_2\left( \tfrac{1}{x}\right)\det\left(\overline{\underline{A}} + \tfrac{1}{x}I\right) - s_1\left( \tfrac{1}{x}\right) \det\left(\underline{A} + \tfrac{1}{x}I\right)\right).  \end{equation}
Then to compute the contact order of $p_{\widehat{A}}$ at $(-1,1)$, just observe that for $x\in \mathbb{R}$ near $0$,
\[
\begin{aligned}
\IM( \hat{r}_1(x) \overline{\hat{r}_2(x)}) &= -x^{2n} \Big( \det\left(\underline{A} +\tfrac{1}{x}I\right)\left(- \tfrac{1}{x} \det \left(\overline{\underline{A}} + \tfrac{1}{x} I\right) + s_1\left( \tfrac{1}{x} \right) \right) \\
& \qquad -\det\left(\overline{\underline{A}} +\tfrac{1}{x}I\right)\left( -\tfrac{1}{x}\det \left(\underline{A} + \tfrac{1}{x} I\right) +s_2\left(\tfrac{1}{x}\right) \right) \Big) \\
&= x^2x^{2n-2} \left(s_2\left( \tfrac{1}{x}\right)\det\left(\overline{\underline{A}} + \tfrac{1}{x}I\right) - s_1\left( \tfrac{1}{x}\right) \det\left(\underline{A} + \tfrac{1}{x}I\right)\right) \approx x^{2+K},
\end{aligned}
\]
by \eqref{eqn:coks1s2}. \end{proof}

    For the second case in Theorem \ref{thm:CO2}, let $G_A$ be an $n$-vertex graph with $v_1$ and $v_n$ path connected.  Create $G_{\widetilde{A}}$ from $G_A$ by adding a vertex $v_{0}$ that is only connected directly to $v_1$ and then renumbering the vertices to $v_1,\dots, v_{n+1}$. Then $G_{\widetilde{A}}$ has the adjacency matrix  
    \begin{equation}\label{eqn:A_tilde}
        \widetilde{A} = \left[
\begin{array}{c|c}
0 & \begin{array}{cccc} 1 & 0 &\cdots & 0 \end{array} \\
\hline
\begin{array}{c}1 \\ 0 \\ \vdots \\ 0 \end{array} & A
\end{array}
\right].
    \end{equation}
