We then have the following result.

\begin{theorem} \label{thmCO:ii} Let $G_A$ be an $n$-vertex graph with vertices $1$ and $n$ path connected. Assume that the contact order of $p_A$ at $(-1,1)$ is $K$. Then, with $\widetilde{A}$ defined in \eqref{eqn:A_tilde}, the contact order of $p_{\widetilde{A}}$ at $(-1,1)$ is $K+2$.
\end{theorem}




\begin{proof} We proceed as in the proof of Theorem \ref{thmCO:i}. Then from that  proof, we can extract the following useful identities from \eqref{eqn:gAcok} and \eqref{eqn:coks1s2}:
\begin{eqnarray}
\det(\overline{A} - \widehat{z}_Y) &=& -z_2 \det\left(\overline{\underline{A}} + \tfrac{1}{z_1}I\right) -s_1\left( \tfrac{1}{z_1}\right) \label{eqn:detco1} \\
\det(A - \widehat{z}_Y) &=& -z_2 \det\left(\underline{A} + \tfrac{1}{z_1}I\right) -s_2\left( \tfrac{1}{z_1}\right) \label{eqn:detco2} \\
x^K &\approx&   x^{2n-2} \left(s_2\left( \tfrac{1}{x}\right)\det\left(\overline{\underline{A}} + \tfrac{1}{x}I\right) - s_1\left( \tfrac{1}{x}\right) \det\left(\underline{A} + \tfrac{1}{x}I\right)\right), \label{eqn:firstco} 
\end{eqnarray}
for $x \in \mathbb{R}$ near $0$,
where $K$ is the contact order of $p_A$ at $(-1,1)$ and $s_1, s_2, \widehat{z}_Y$ are defined in the proof of Theorem \ref{thmCO:i}.
As in the proof of Theorem \ref{thmCO:i}, we now find polynomials $\tilde{q}_1, \tilde{q}_2$ (with no common factor of $z_1$ or common factor containing $z_2$) such that 
\[g_{\widetilde{A}}(z_1, z_2) : = f_{\widetilde{A}}\left(-\tfrac{1}{z_1}, z_2 \right) = \frac{\tilde{q}_1}{\tilde{q}_2},  \]
write $\tilde{q}_2 -i\tilde{q}_1 = \tilde{r}_1(z_1) + z_2 \tilde{r}_2(z_1)$ for polynomials $\tilde{r}_1, \tilde{r}_2 \in \mathbb{C}[z]$, and compute the order of vanishing of $\IM( \tilde{r}_1(x) \overline{\tilde{r}_2(x)})$ for $x\in \mathbb{R}$ near $0$. 

To that end, observe that using Laplace expansion along the first row and column of $(\widetilde{A}- \widehat{z}_Y)$, $(\overline{\widetilde{A}}- \widehat{z}_Y)$ and then using the formulas \eqref{eqn:detco1} and \eqref{eqn:detco2} will give

\begin{align}
g_{\widetilde{A}}(z_1, z_2) &= \frac{\det\left (\overline{\widetilde{A}} - \widehat{z}_Y\right)}{\det\left(\widetilde{A} - \widehat{z}_Y\right)}
=\frac{\det\left (A- \widehat{z}_Y\right)}{\frac{1}{z_1}\det(A-\widehat{z}_Y) - \det\left(\overline{A}-\widehat{z}_Y\right)} \nonumber\\
&= \frac{-z_2 \det\left(\underline{A} + \tfrac{1}{z_1}I\right) -s_2\left( \tfrac{1}{z_1}\right)}{\frac{1}{z_1}\left(-z_2 \det\left(\underline{A} + \tfrac{1}{z_1}I\right) -s_2\left( \tfrac{1}{z_1}\right)\right) -\left(-z_2 \det\left(\overline{\underline{A}} + \tfrac{1}{z_1}I\right) -s_1\left( \tfrac{1}{z_1}\right) \right)} \nonumber\\
&= \frac{z_1^{n}\left(z_2 \det\left(\underline{A} + \tfrac{1}{z_1}I\right) +s_2\left( \tfrac{1}{z_1}\right)\right)}{z_1^{n}\left(z_2 \left(\frac{1}{z_1}\det\left(\underline{A} + \tfrac{1}{z_1}I\right) -\det\left(\overline{\underline{A}} + \tfrac{1}{z_1}I\right)\right) +
\tfrac{1}{z_1} s_2\left( \tfrac{1}{z_1}\right) - s_1\left( \tfrac{1}{z_1}\right) \right)}. \label{eqn:q1q2final}
\end{align}
We can let the numerator and denominator in \eqref{eqn:q1q2final} be $\tilde{q}_1, \tilde{q}_2$ (there is no common $z_1$ factor since the denominator has a nonzero constant term and no term with $z_2$ can cancel since vertices $v_1$ and $v_{n+1}$ are path connected) and easily find $\tilde{r}_1$ and $\tilde{r}_2$:
\[
\begin{aligned}
\tilde{r}_1(z_1)&= z_1^{n} \left( \tfrac{1}{z_1} s_2\left( \tfrac{1}{z_1}\right) - s_1\left( \tfrac{1}{z_1}\right) -i s_2\left( \tfrac{1}{z_1}\right) \right)\\
\tilde{r}_2(z_1)&=z_1^{n} \left(\tfrac{1}{z_1}\det\left(\underline{A} + \tfrac{1}{z_1}I\right) -\det\left(\overline{\underline{A}} + \tfrac{1}{z_1}I\right)- i\det\left(\underline{A} + \tfrac{1}{z_1}I\right) \right). 
\end{aligned}
\]
Now we can compute the contact order for $p_{\widetilde{A}}$ at $(-1,1)$. Specifically, for $x\in \mathbb{R}$ near $0$,
\[ 
\begin{aligned}
\IM( \tilde{r}_1(x) \overline{\tilde{r}_2(x)}) &= x^{2n} \Big( 
 \left( \tfrac{1}{x} s_2\left( \tfrac{1}{x}\right) - s_1\left( \tfrac{1}{x}\right)\right) \det\left(\underline{A} + \tfrac{1}{x}I\right) 
\\
& \qquad -s_2\left( \tfrac{1}{x}\right) \left(\tfrac{1}{x}\det\left(\underline{A} + \tfrac{1}{x}I\right) -\det\left(\overline{\underline{A}} + \tfrac{1}{x}I\right)\right)  \Big) \\
&= x^2 x^{2n-2} \left(s_2\left( \tfrac{1}{x}\right)\det\left(\overline{\underline{A}} + \tfrac{1}{x}I\right) - s_1\left( \tfrac{1}{x}\right) \det\left(\underline{A} + \tfrac{1}{x}I\right)\right) \approx x^{2+K},
\end{aligned}
\]
where we used \eqref{eqn:firstco}.
Then applying Remark \ref{rem:cor} establishes the claim.
\end{proof}




Let $G_A$ be an $n$-vertex graph such that the only connection between vertex $n$ and the rest of the graph is a single edge between vertex $n-1$ and vertex $n$. Then $G_{A}$ has the adjacency matrix
$$A = \left[
\begin{array}{c|c}
B & \begin{array}{c} 0 \\ \vdots \\ 0 \\ 1 \end{array} \\
\hline
\begin{array}{cccc} 0 & \cdots & 0 & 1\end{array} & 0
\end{array}
\right], $$ for some $(n-1) \times (n-1)$ matrix $B$.

Now, fix $m \ge n+1$.  Relabel vertex $n$ to vertex $m$ and
expand $G_{A}$ to a new graph $G_{\breve{A}}$ by attaching an $(m-n)$-vertex graph to $G_A$ via an edge at vertex $n-1$ (and potentially other edges to the new vertex $m$). This follows Modification (iii) in Theorem \ref{thm:CO2}. Then $G_{\breve{A}}$ has the $m\times m$ adjacency matrix
\begin{equation}\label{eqn:A_breve}
    \breve{A} = \left[\begin{array}{c|c}
B & \begin{array}{cccc} 0 & \cdots & \cdots & 0 \\ \vdots & \ddots & \ddots & \vdots \\ 0 & \cdots & \cdots & 0 \\ * & \cdots & * & 1 \end{array} \\
\hline
\begin{array}{cccc}0 & \cdots & 0 & * \\ \vdots & \ddots & \vdots & \vdots\\ \vdots & \ddots & \vdots & *\\ 0 & \cdots & 0 & 1 \end{array} & C
\end{array}\right],
\end{equation}
 where the asterisks * contain at least one $1$ and are $0$ otherwise, and $C$ is the adjacency matrix of an $(m-(n-1))$-vertex graph $G_C$. This construction for $n=4$ and $m=6$ is illustrated in Figure \ref{fig:attachxgraph} below. The dotted edge indicates that one could also insert an edge between $v_4$ and $v_6$, and the contact order result would still hold.

