\section{Introduction}

A self-similar set in $\mathbb{R}^d$ means the attractor  of an iterated function system (shortly, an IFS), which is a family $\mathcal{F}=\{f_j: 1\le j\le q\}$ consisting of $q\ge2$  contractions of $\mathbb{R}^d$ into itself.  Due  to Hutchinson \cite{Hutchinson81},  there is a unique nonempty compact set $K$ with $K=\bigcup_jf_j(K)$. In deed, if we set $\Phi(X)=\bigcup_jf_j(X)$ for nonempty compact sets $X\subset\mathbb{R}^d$, then $\lim\limits_{n\rightarrow\infty}\Phi^n(X)=K$ under the Hausdorff distance for any compact $X\ne\emptyset$. Here the Hausdorff distance between two nonempty sets $X$ and $Y$ is the infimum of all $\varepsilon>0$ such that $X_\varepsilon=\{z: \exists x\in X\ \text{with}\ |x-z|<\varepsilon\}\supset Y$ and $Y_\varepsilon\supset X$ both hold.  See for instance \cite[\S2.4]{Hutchinson81}.  


\begin{definition}\label{def:attractor}
We  call $\Phi$ the Hutchinson map of $\mathcal{F}$ and  $K$ the attractor of $\mathcal{F}$. If further every $f_j$ is a similitude, we call  $K$  a {\em self-similar set}. 
\end{definition}

Given an IFS $\mathcal{F}=\{f_j: 1\le j\le q\}$ and a sequence $w=i_1i_2\cdots i_n\in\{1,\ldots,q\}^n$, we denote by $f_w$ the $n$-fold composite
$f_{i_1}\circ\cdots\circ f_{i_n}$. For any infinite sequence $\omega=(i_n)_{n\ge1}\in\{1,\ldots,q\}^\infty$, we denote by $\omega_n$ the prefix of 
$\omega$ of length $n\ge1$. Then $\left\{f_{\omega_n}(K): n\ge1\right\}$ is a sequence of nonempty compact sets decreasing to a single point, to be denoted by $x_\omega$. Moreover,  it is also routine to check that 
\[\lim\limits_{n\rightarrow\infty}f_{\omega_n}(y)=x_\omega
\]
holds for all $y\in\mathbb{R}^d$. Let $\mathcal{S}=\mathcal{S}_\mathcal{F}:\{1,\ldots,q\}^\infty$  be the map that sends every $\omega$ to $x_\omega$. 

\begin{definition}\label{def:symbolic_projection}
We call $\mathcal{S}=\mathcal{S}_\mathcal{F}$ the symbolic projection of $\mathcal{F}$ (or of $K$).
\end{definition}

In the sequel, we often consider $d=(u,v)\in\mathbb{Z}^2$ as a vector in $\mathbb{R}^2$ so that every translation $x\mapsto x+d$ 
 with $d\in\mathbb{Z}^2$  is well defined. Similarly, $f_{d,N}(x)=\frac{x+d}{N}$ is a map of $\mathbb{R}^2$ onto itself, for any $N\in\mathbb{Z}_+$ and  $d\in \mathbb{Z}^2$.

\begin{definition}\label{def:FS}
Given $N\ge2$ and $\mathcal{D}\subset\{0,1,\ldots,N-1\}^2$, we call the unique nonempty compact set satisfying $\displaystyle K=\bigcup_{d\in\mathcal{D}}f_{d,N}(K)$ a {\em fractal square} of order $N$. 
\end{definition}

When the order $N\ge2$ is known from the context, we often write $K_\mathcal{D}$ instead of $K$ to emphasize the digit set $\mathcal{D}$.  In the meanwhile, we also write $K(N,\mathcal{D})$, when we want to emphasize the order $N$ and the digit set $\mathcal{D}$ both. 
%Clearly, when the order $N$ is given, the fractal square $K(N,\mathcal{D})$ is completely determined by the digit set $\mathcal{D}$.



Topology of self-similar sets has been a focus of much attention in the study of fractal geometry. For fundamentals of the general theory of fractal geometry, one may refer to  \cite{Falconer90}  and the references therein. For results that center around self-affine tiles or relate to numeration systems, one may refer to \cite{Akiyama-Thuswaldner04}. In this survey,  
we focus on fractal squares  and  quickly review some results and open questions from recent studies. In the special case $\mathcal{D}=\{0,1,\ldots,N-1\}^2$, we have $K(N,\mathcal{D})=[0,1]^2$. So we usually consider  $K(N,\mathcal{D})$ with $\#\mathcal{D}\in[2,N^2-1]$ and concentrate on their topological properties. We will restrict ourselves to the following issues.
\begin{itemize} 
\item[(A)]  To determine whether the number $\pi_0(K)$ of components of $K=K(N,\mathcal{D})$  is finite or (uncountably) infinite and further consider the following.
\item[(A.1)] To determine whether $K$ has local (or global) cut points, if $\pi_0(K)=1$.
\item[(A.2)] To describe the topology of $K$ and of its components, if $\pi_0(K)>1$.
\item[(A.3)] To determine whether  $K$ is totally disconnected. % if $\pi_0(K)$ is infinite.
\vspace{0.382cm}
\item[(B)] To find conditions for some (or all) components of $K$ to  be points, line segments, or non-degenerate continua that contain no line segment.
\item[(B.1)] To determine whether a disconnected $K$ has no point component.
\item[(B.2)] To determine whether all the non-degenerate components  of $K$ are line segments  and whether they form a {\em null sequence}, in the sense that for any constant $C>0$ at most finitely many of them are of diameter $\ge C$.
\vspace{0.382cm}
\item[(C)]To classify all fractal squares in terms of the lambda function $\lambda_K$, that is introduced in \cite{FLY-2022} for any compact set $K\subset\mathbb{R}^2$.\vspace{0.382cm}
\item[(D)]  To classify certain families of fractal squares from a topological viewpoint.

\end{itemize}

\section{To Count the Components of $K(N,\mathcal{D})$}

Fractal squares $K=K(N,\mathcal{D})$ are self-similar sets contained in the unit square $[0,1]^2$. The underlying IFS
\[\mathcal{F}=\left\{f_j(x)=\frac{x+d_j}{N}: 1\le j\le q\right\}
\]
always possesses  three basic properties.  First, the interior $U={\rm Int}\left([0,1]^2\right)$ is an open set such that $f_1(U)\cup\cdots\cup f_q(U)$ is a disjoint union contained in $U$. Thus the well-known {\em open set condition} \cite[(5.2)]{Hutchinson81} is satisfied. Second, the {\bf double} intersection $E_{ij}=f_i(K)\cap f_j(K)$ for any $1\le i<j\le q$ is nonempty {\bf only if} $d_i-d_j$  belongs to
\[
\left\{\pm\left[\begin{array}{c}0\\ 1\end{array}\right], \ \pm\left[\begin{array}{c}1\\ 0\end{array}\right], \
\pm\left[\begin{array}{c}1\\ 1\end{array}\right], \ \pm\left[\begin{array}{c}1\\ -1\end{array}\right]\right\}.\]
Moreover, if  $E_{ij}\ne\emptyset$ then it may consist of finitely many points,  countably many points,  a line segment,  or  a Cantor set together with finitely many (or none) isolated points. Third, the {\bf triple} intersection $E_{ijk}=f_i(K)\cap f_j(K)\cap f_k(K)$ for any $1\le i<j<k\le q$ is either empty or a singleton. In the latter case, it is easy to infer that for all $u\ne v\in\{i,j,k\}$ either $d_u-d_v$ or $d_v-d_u$  is a corner of $[0,1]^2$. Therefore,
\[
\left\{\pm(d_i-d_j),\pm(d_i-d_k),\pm(d_j-d_k)\right\}\ \cap\
\left\{\left[\begin{array}{c}0\\ 0\end{array}\right], \left[\begin{array}{c}1\\ 0\end{array}\right], \ \left[\begin{array}{c}1\\ 1\end{array}\right], \ \left[\begin{array}{c}0\\ 1\end{array}\right]\right\}
\]
has exactly three elements, each of which  belongs to $\mathcal{D}$. On the one hand, a fractal square $K=K(N,\mathcal{D})$ and its components demonstrate very rich properties from a topological point of view. On the other, the connections between those properties and the digit set $\mathcal{D}$ are direct and illustrate a variety of subtleties. A large part of those connections have been well understood, due to recent as well as classical results from the literature.

Let us start from how the digit set $\mathcal{D}$ is related to the number of components in $K=K(N,\mathcal{D})$, to be denoted by $\pi_0(K)$. To do that, we need
a graph that is defined for all self-similar sets.
\begin{definition}\label{def:Hata_Graph}
Let $\mathcal{F}=\{f_i,\ldots,f_q\}$ be an IFS and $K$ the attractor. The first Hata graph $\mathcal{G}_1(\mathcal{F})$ is the one with vertex set $\mathcal{V}_1=\{1,\ldots,q\}$ in which two vertices $i\ne j$ are incident if and only if $f_i(K)\cap f_j(K)\ne\emptyset$. Similarly, for all $k\ge2$ the $k$-th Hata graph  $\mathcal{G}_k(\mathcal{F})$ is the one with vertex set $\mathcal{V}_k=\{1,\ldots,q\}^k$ in which two distinct vertices $u=i_1\ldots i_k$ and $v=j_1\cdots j_k$ are incident if and only if $f_u(K)=f_{i_1}\circ\cdots\circ f_{i_k}(K)$ intersects $f_v(K)=f_{j_1}\circ\cdots\circ f_{j_k}(K)$.
\end{definition}

The graph $\mathcal{G}_1(\mathcal{F})$ is closely related to the connectedness of $K$. Indeed, we have.
\begin{theorem}[{\bf \cite[Theorem 4.6]{Hata85}}]\label{theo:Hata85}
$\mathcal{G}_1(\mathcal{F})$ is connected if and only if $K$ is. In such a case, $K$ is a locally connected cotinuum.
\end{theorem}


If $K=K(N,\mathcal{D})$ is a fractal square, we also write $\mathcal{G}_1(\mathcal{D})$ instead of $\mathcal{G}_1(\mathcal{F})$. Set $\mathcal{D}_1=\mathcal{D}$ and for $j\ge1$ further set   
\begin{eqnarray}\label{eq:approx}
\mathcal{D}_{j+1}&=&N \mathcal{D}_j+\mathcal{D}=\left\{Nd_1+d_2: d_1\in\mathcal{D}_j, d_2\in\mathcal{D}\right\}
\\
K^{(j)}&=&\bigcup_{d\in \mathcal{D}_j}\frac{[0,1]^2+d}{N^j}.
\end{eqnarray}
Call $K^{(j)}$  the {\em $j$-th approximation} of $K$. The sequence $\left\{K^{(j)}: j\ge1\right\}$ decreases to $K$. Moreover, for any $d'\ne d''\in \mathcal{D}$ the common part of $K+d'$ and $K+d''$ is nonempty if and only if $K^{(2)}+d'$ intersects $K^{(2)}+d''$.  Therefore, one can induce a simple characterization of $\mathcal{G}_1(\mathcal{D})$.

\begin{theorem}[{\cite[Theorem 2.2]{Ruan-Wang17}}]\label{theo:compute_Hata}
$\mathcal{G}_1(\mathcal{D})$ has an edge between $d'\ne d''$ if and only if $K^{(2)}+d'$ intersects $K^{(2)}+d''$. Consequently, $K$ is connected if and only if $K^{(3)}$ is.
\end{theorem}

In order to determine whether a fractal square has finitely many components,  one may use the approximations $K^{(n)}(n\ge1)$ instead of $\mathcal{G}_n(\mathcal{D})$. We can rephrase the second part of Theorem \ref{theo:compute_Hata}  as follows.
\begin{theorem}\label{theo:connected_K3}
$\pi_0(K)=1$ if and only if $\pi_0\left(K^{(3)}\right)=1$.
\end{theorem}

