\begin{remark}
Given  $\mathcal{D}\subset\{0,1,\ldots,N-1\}^2$,  $K(N,\mathcal{D})=K(N^j,\mathcal{D}_j)$ for all $j\ge2$. 
\end{remark}

Let $q=\pi_0\left(K^{(1)}\right)$ and denote by $\mathcal{P}_1,\ldots,\mathcal{P}_q$ the components of  $K^{(1)}$. Also denote by $\mathcal{V}^{(1)}_i(1\le i\le q)$ the set of digits $d\in \mathcal{D}$ which are vertices of the subgraph $\mathcal{P}_i$. Further set $K_i^{(1)}$ to be the union of all the translates $\frac{K+d}{N}$ with $d\in\mathcal{V}^{(1)}_i$. 

For the sake of convenience, we let $\alpha_i=\{i\}\times[0,1]$ and $\beta_i=[0,1]\times\{i\}$, where $i=0,1$. In the sequel, we give in several lemmas some   observations that are either immediate or may be obtained by using self-similarity and standard arguments from plane topology.

\begin{lemma}\label{lem:GIFS}
Every homothety $NK_i^{(1)}=\left\{Nx: x\in K_i^{(1)}\right\}(1\le i\le q)$  is a finite union of certain translates of the compact sets $K_j^{(1)}$. Thus $\left\{K_i^{(1)}:1\le i\le q\right\}$ becomes the system of attractors for a graph-directed IFS in the sense of \cite{MauldinWilliams88}.
\end{lemma}

\begin{lemma}\label{lem:sepration_arc}
If no component of $K^{(1)}$ intersects each of the four sides $\alpha_0,\alpha_1,\beta_0,\beta_1$, then one can find either a Jordan arc $\gamma$ in $[0,1]^2\setminus K^{(1)}$ that intersects both $\{0\}\times(0,1)$ and $\{1\}\times(0,1)$ or 
one that intersects both $(0,1)\times\{0\}$ and $(0,1)\times\{1\}$. \end{lemma}

\begin{lemma}\label{lem:points_exist}
If $K^{(1)}$ has a component that is disjoint from one of the four broken lines $\alpha_i\cup\beta_j$ (with $i,j=0,1$) then $K$ has a point component and $\pi_0(K^{(1)})<\pi_0(K^{(2)})$. 
\end{lemma}

\begin{lemma}\label{lem:NS_EW}
If $\pi_0(K^{(1)})=\pi_0(K^{(2)})>1$ then there are two possibilities: (1) every component of $K^{(1)}$ intersects both $(0,1)\times\{0\}$ and $(0,1)\times\{0\}$, (2)  every component of $K^{(1)}$ intersects both $\{0\}\times(0,1)$ and $\{1\}\times(0,1)$. In such cases,  we respectively call 
$\mathcal{D}$ a digit set with the {\bf north-south pattern} and one with the {\bf east-west pattern}.
\end{lemma}

The next result provides further insight, concerning  point components.
\begin{theorem}[{\cite[Theorem 1.1]{Huang-Rao21}}]\label{theo:dimension_drop}
If $K$ has a point component then all its non-degenerate components form a subset $K_c$ whose Hausdorff dimension $\dim_HK_c$ is strictly less than $\dim_HK$.
\end{theorem}

The next result  extends Theorem \ref{theo:connected_K3}. 
\begin{theorem}[{\cite[Theorem 2.6]{CKLY-2025}}]\label{theo:finite_pi0}
If $\pi_0\left(K^{(n)}\right)=\pi_0\left(K^{(n+1)}\right)$ for $n\ge2$ then $\pi_0(K)=\pi_0\left(K^{(n)}\right)$. In particular, if $\pi_0\left(K^{(3)}\right)=1$ (hence  $\pi_0\left(K^{(2)}\right)=1$) then $\pi_0(K)=1$.
\end{theorem}

The  following dichotomy provides a fundamental starting point in exploring the topology of a fractal square.
\begin{theorem}[{\bf \cite{Xiao21}}]\label{theo:Xiao21}
$K$  has either finitely many or uncountably many components.
\end{theorem}

Actually, by combining  Lemmas \ref{lem:points_exist} and \ref{lem:NS_EW} with Theorem \ref{theo:finite_pi0} and  \cite[Theorem 3.3]{CKLY-2025}, one may  strengthen Theorem \ref{theo:Xiao21} in the following way.
\begin{theorem}\label{theo:Xiao21_strengthened}
Every fractal square $K$ falls into just one of two possibilities, either $\pi_0\left(K^{(n)}\right)=\pi_0\left(K^{(n+1)}\right)=\pi_0(K)$ for some $n\ge2$ or  $\pi_0\left(K^{(n)}\right)<\pi_0\left(K^{(n+1)}\right)$ for all $n\ge2$. In the latter case there are just two sub-cases, either $K$ has  uncountably many point components or $K$ is the product of a Cantor set and $[0,1]$.
\end{theorem}

