Clearly, $(1,v^2_2), (v^1_1+c,v^2_2 + (\frac{1}{2} - \delta) c) \in U'$
and $(v^1_1 + (\frac{1}{2}+\delta) c, v^2_2+c), (v^1_1+c,v^2_2+\frac{4}{5} c) \in U''$.
Since $U'$ has positive slope, it follows that all of $v^1$, $v^2$, $w^2$, and $\B_\infty^2$ lie above $U'$.
Moreover, the assumption $w^1_2 \geq v^1_2 + (\frac{1}{2} - \delta) c$ gives that $w^1$ lies above $U'$ as well.
Next, we note that the assumptions $v^1_1, v^2_2 \geq - \frac{c}{2}$, $\delta \in [0,\frac{1}{10}]$, and $c \geq \frac{14}{5}$ yield
\[
    - \frac{1}{5 (\nicefrac{1}{2} - \delta)} (1 - (v^1_1+c)) + v^2_2 + \frac{4}{5} c
    \geq - \frac{1 - \nicefrac{c}{2}}{5 (\nicefrac{1}{2} - \delta)} - \frac{c}{2} + \frac{4}{5} c
    \geq - \frac{2-c}{5} + \frac{3c}{10}
    = \frac{c}{2} - \frac{2}{5}
    \geq 1.
\]
Since $U''$ has negative slope, it follows that $v^1$, $v^2$, and $\B_\infty^2$ lie below $U''$.
Moreover, the assumptions $w^2_1 \leq v^1_1 + (\frac{1}{2} + \delta) c$
and $w^1_2 \leq v^2_2 + (\frac{1}{2} + \delta) c \leq v^2_2 + \frac{4}{5} c$
yield that $w^1$ and $w^2$ lie below $U''$ as well.
Altogether, if we write $u^1$ for the unique intersection point of $U'$ and $U''$,
and $u^2$ for the unique point in $U''$ with $u^2_1 = v^1_1$, then
\[
    S
    \subset \tilde{Q}^2
    := \conv(\{ u^1, u^2, (v^1_1,v^2_2), (1,v^2_2) \}).
\]
Note that $u^2 = (v^1_1,\frac{c}{5 (\nicefrac{1}{2} - \delta)} + v^2_2 + \frac{4}{5} c)$
follows directly from the definition of $U''$.
Similarly, we obtain that $(1,h+v^2_2)$ for $h = \frac{c+v^1_1-1}{5 (\nicefrac{1}{2} - \delta)} + \frac{4}{5} c$
is the unique point in $U''$ with first coordinate $1$.
Additionally, we can find that
\[
    u^1_1
    = v_1^1 + \frac{c (4 c (3 - 4 \delta) + (7 + 4 \delta - 20 \delta^2) (v^1_1-1))}
    {c (9 - 20 \delta + 20 \delta^2) + 4 (v^1_1 - 1)}.
\]
Now, the area of $\tilde{Q}^2$ can be computed to be
\begin{align*}
    |\tilde{Q}^2|
    & = h (1-v^1_1) + \frac{1}{2} (1 - v^1_1) (u^2_2 - v^2_2 - h) + \frac{1}{2} h (u^1_1 - 1)
    \\
    & = \frac{1}{2} h (u^1_1 - v^1_1) + \frac{1}{2} (1-v^1_1) (u^2_2 - v^2_2)
    \\
    & = \frac{c (3 - 4 \delta) + v^1_1 - 1 }{5 (1 - 2 \delta)} \cdot \frac{c (4 c (3 - 4 \delta) + (7 + 4 \delta - 20 \delta^2) (v^1_1-1))}{c (9 - 20 \delta + 20 \delta^2) + 4 (v^1_1 - 1)}
    \\
    & \qquad\qquad - \frac{c (3 - 4 \delta) (v^1_1-1)}{5 (1 - 2 \delta)}
    = \zeta_{c,\delta}(v_1^1).
\end{align*}
Since $-\frac{c}{2} \leq v^1_1$, the claim now follows from \eqref{eq:zeta_dec}.
\end{proof}




\section{Proof of \texorpdfstring{Theorem~\ref{thm:main}}{Theorem 1.1}} \label{sec:main}

We verify two more preliminary lemmas before proving the main theorem.

\begin{lemma} \label{lem:outer_ball}
Let $Q \subset \R^2$ be a proper convex quadrangle such that the midpoints of its edges are the vertices of $\B_\infty^2$.
Then $Q \subset 3 \B_\infty^2$.
\end{lemma}
\begin{proof}
Assume, to the contrary,
that $Q \not\subset 3 \B_\infty^2$.
Then $Q$ must have a vertex $v \notin 3 \B_\infty^2$.
Since the vertices of $\B_\infty^2$ are boundary points of $Q$,
we see that $Q$ is contained in the union of the slabs
$\{ (x_1,x_2) \in \R^2 : -1 \leq x_1 \leq 1 \}$ and $\{ (x_1,x_2) \in \R^2 : -1 \leq x_2 \leq 1 \}$.
In particular, one coordinate of $v$ must have an absolute value of at most $1$.
Therefore, we may assume that $|v_1| \leq 1$ and $v_2 > 3$.

Now, let $u$ and $w$ be the vertices of $Q$ that are connected to $v$ via edges of $Q$.
We may assume
\[
    \frac{v+u}{2} = (1,1)
        \quad \text{and} \quad
    \frac{v+w}{2} = (-1,1).
\]
Then $u_2, w_2 < -1$ and $u_1, -w_1 \geq 1$, where we cannot have both $u_1 = 1$ and $w_1 = -1$.
But then one of $u$ and $w$ has two coordinates with an absolute value larger than $1$,
which is a contradiction.
\end{proof}

\begin{lemma} \label{lem:inner_ball}
Let $v \in \R^2$ with $v \in R \B_\infty^2$ for some $R > 0$.
Then for any $r \in [0,R+1]$, we have
\[
    \left( 1 - \frac{r}{R+1} \right) v + \frac{r}{R+1} \B_\infty^2
    \subset \conv(\{ v \} \cup \B_\infty^2) \cap (v + r \B_\infty^2).
\]
\end{lemma}
\begin{proof}
The triangle inequality yields for any $u \in \B_\infty^2$ that
\begin{align*}
    \left\| \left( 1 - \frac{r}{R+1} \right) v + \frac{r}{R+1} u - v \right\|_\infty
    & = \frac{r}{R+1} \left\| u - v \right\|_\infty
    \\
    & \leq \frac{r}{R+1} (\left\| u \right\|_\infty + \left\| v \right\|_\infty)
    \leq \frac{r}{R+1} (1+R)
    = r.
\end{align*}
This clearly suffices to verify the claim.
\end{proof}

We are now finally ready to verify the initially discussed improvement of the factor $\sqrt{2}$.

\begin{proof}[Proof of Theorem~\ref{thm:main}.]
We reuse the notation introduced in the proof of Proposition~\ref{prop:ismailescu}.
We shall distinguish a few cases where we introduce constants for each individual step.
These constants are chosen explicitly only at the end of the proof to allow us to improve the upper bound on the ratio of areas in the theorem.

First, assume that $|Q'| > c_1 |Q|$ for some $c_1 \geq 1$.
Then \eqref{eq:main_estimate} gives
$\sqrt{c_1} \, |Q| < \sqrt{ |Q| \, |Q'| } \leq \sqrt{2} \, |K|$ and in particular
\begin{equation} \label{eq:estimate1}
    |Q|
    < \frac{1}{\sqrt{c_1}} \sqrt{2} \, |K|.
\end{equation}
For the following considerations, we assume $|Q'| \leq c_1 |Q| = 8 c_1$.

Next, suppose that $x > c_2 y$ for some $c_2 \geq 1$.
Since clearly $y \geq 2$, we have
\[
    |\CO|^2 - |P| \, |Q'|
    = x^2 + 2 xy + y^2 - 4 xy
    = (x-y)^2
    > (c_2 - 1)^2 y^2
    \geq 4 (c_2 - 1)^2.
\]
From $|P| = 4$ and $|Q'| \leq 8 c_1$, it follows that
\begin{align*}
    |\CO|
    & > \sqrt{ |P| \, |Q'| + 4 (c_2 - 1)^2}
    \\
    & = \sqrt{ |P| \, |Q'| \left( 1 + \frac{4 (c_2 - 1)^2}{|P| \, |Q'|} \right) }
    \geq \sqrt{ |P| \, |Q'| \left( 1 + \frac{(c_2 - 1)^2}{8 c_1} \right) }.
\end{align*}
Thus, \eqref{eq:main_estimate} shows
\begin{equation} \label{eq:estimate2}
    |Q|
    \leq \sqrt{2 \, |P| \, |Q'|}
    < \frac{1}{\sqrt{1 + \nicefrac{(c_2-1)^2}{8 c_1}}} \sqrt{2} \, |\CO|
    \leq \frac{1}{\sqrt{1 + \nicefrac{(c_2-1)^2}{8 c_1}}} \sqrt{2} \, |K|.
\end{equation}
From now on, we assume that $x \leq c_2 y$.
Consequently, we have that
\[
    \frac{x^2}{c_2}
    \leq xy
    = |Q'|
    \leq 8 c_1
\]
and in particular $x \leq \sqrt{8 c_1 c_2}$.
Analogously, we may assume that $y \leq \sqrt{8 c_1 c_2}$.

Next, suppose that there exists some $v \in K$ such that $v + r \B_\infty^2$ does not meet $\CO$ for some $r > 0$.
Lemma~\ref{lem:outer_ball} shows that $Q \subset 3 \B_\infty^2$,
so $v \in K \subset Q$ yields in particular $v \in 3 \B_\infty^2$.
Moreover, $\B_\infty^2 = P \subset \CO$ is true as well, which implies $r \leq 2$.
Hence, Lemma~\ref{lem:inner_ball} shows that $K \supset \conv(\{v\} \cup \CO)$
contains a translated copy of $\frac{r}{4} \B_\infty^2$ that does not intersect $\CO$.
Therefore, $|\CO| \leq |Q| = 8$ yields
\[
    \left( 1 + \frac{r^2}{32} \right) |\CO|
    \leq |\CO| + \frac{r^2}{32} |Q|
    = |\CO| + \frac{r^2}{4}
    = |\CO| + \left| \frac{r}{4} \B_\infty^2 \right|
    < |K|,
\]
and by \eqref{eq:main_estimate} further
\begin{equation} \label{eq:estimate3}
    |Q|
    \leq \sqrt{2} \, |\CO|
    < \frac{1}{1 + \nicefrac{r^2}{32}} \sqrt{2} \, |K|.
\end{equation}
From now on, we assume that $v + r \B_\infty^2$ meets $\CO$ for all $v \in K$.
In particular, we have
\[
    K
    \subset \CO + r \B_\infty^2
    \subset (1+r) \CO.
\]

Finally, Lemma~\ref{lem:octagon} shows for any $c_3 \geq \sqrt{8 c_1 c_2} \geq x,y$ and $\delta \in [0,\frac{1}{10}]$
that there exists a quadrangle $\tilde{Q}$ with $\CO \subset \tilde{Q}$ and
\[
    |\tilde{Q}|
    \leq \max \left\{
        \frac{c_3 (c_3 (1 + \delta) + 2 \delta)}{1 + 2 \delta},
        \zeta_{c_3,\delta} \left( -\frac{c_3}{2} \right)
    \right\}.
\]
Since $K \subset (1+r) \tilde{Q}$ and $Q$ is a minimum-area quadrangle containing $K$ with $|Q| = 8$,
we must have
\begin{align*}
    8
    & \leq |(1+r) \tilde{Q}|
    = (1+r)^2 |\tilde{Q}|
    \\
    & \leq (1+r)^2 \max \left\{
        \frac{c_3 (c_3 (1 + \delta) + 2\delta)}{1 + 2 \delta},
        \zeta_{c_3,\delta} \left( - \frac{c_3}{2} \right)
    \right\}
    =: C(c_3,r,\delta).
\end{align*}
Consequently, if $c_1$, $c_2$, $c_3$, $r$, and $\delta$ are chosen such that
$\sqrt{8 c_1 c_2} \leq c_3$ and $C(c_3,r,\delta) < 8$,
then one of the above assumptions must be wrong,
that is, one of \eqref{eq:estimate1}, \eqref{eq:estimate2}, and \eqref{eq:estimate3} must be true.

We now explicitly choose
\begin{align*}
    c_1 & = 1 + 5.3 \cdot 10^{-7},
    \\
    c_2 & = 1 + \sqrt{8 c_1 (c_1 - 1)} < 1 + 2.06 \cdot 10^{-3}, \quad \text{and}
    \\
    r & = \sqrt{32 \left( \sqrt{c_1} - 1 \right)} < 2.913 \cdot 10^{-3},
\end{align*}
in which case the upper bounds in \eqref{eq:estimate1}, \eqref{eq:estimate2}, and \eqref{eq:estimate3} coincide.
We obtain $\sqrt{8 c_1 c_2} < 2.83134 =: c_3$
and choose $\delta = 2.824 \cdot 10^{-2}$.
In this case,
\[
    \frac{c_3 (c_3 + \delta (2+c_3))}{1 + 2 \delta}
    < 7.95359
\]
and with \eqref{eq:zeta_dec} also
\[
    \zeta_{c_3,\delta} \left( - \frac{c_3}{2} \right)
    < 7.95359.
\]
Finally,
\[
    C(c_3,r,\delta)
    < 7.95359 (1+r)^2
    < 7.999996.
\]
In summary, we have found an admissible choice of $c_1$, $c_2$, $c_3$, $r$, and $\delta$,
for which
\[
    \frac{1}{\sqrt{c_1}}
    = \frac{1}{\sqrt{1 + \nicefrac{(c_2-1)^2}{8 c_1}}}
    = \frac{1}{1 + \nicefrac{r^2}{32}}
    < 0.99999974
    = 1 - 2.6 \cdot 10^{-7}.
\]
This concludes the proof as discussed above.
\end{proof}




\section{Concluding Remarks}

We would like to point out the (absurdly) large gap between the conjectured value of $c_4$ by Kuperberg \cite{Ku} (which is the same as the established lower bound by Hong et al.~\cite{H23}) and the upper bound in Theorem~\ref{thm:main}. 
It is clear that there is room for improvement. We note that with careful tweaking of the argument and by distinguishing more cases, one could probably improve the upper bound by some orders of magnitude at the cost of making the paper less readable. However, the size of the gap remains. This reminds us of the packing density of the regular tetrahedron, which has long been known to be less than $1$ as regular tetrahedra do not tile space, see \cite{Ft}*{Section~16.8} for history of the problem and references. However, the best known upper bound is $(1-2.6\cdot 10^{-25})$  by Gravel, Elser, and Kallus \cite{GEK11}, while the best construction, by Chen, Engel, and Glotzer \cite{ChEG10}, yields $0.856347\ldots$, with a huge gap between them. Determining the exact value of $c_4$ is probably not as formidable as that of the packing density of the regular tetrahedron (for which there is not even an explicit conjecture) but being the "simplest" case of a long-standing approximation problem it certainly deserves further attention. 




