\begin{remark}
  This definition of an ipomset is slightly different but equivalent 
  to the definitions given in 
  \cite{DBLP:journals/mscs/FahrenbergJSZ21, DBLP:journals/lmcs/FahrenbergJSZ24}.
  Here we drop the transitivity condition for the event order,
  which allows for a more natural notion of isomorphism.
  We will get back to this issue in Section \ref{se:ipoms-trans}.
\end{remark}

\begin{example}
  \label{ex:n}
  Figure~\ref{fi:n} depicts a concrete ipomset $P=\{x_1, x_2, x_3, x_4\}$ with four events
  labelled by $\lambda(x_1)= \lambda(x_4)=a$, $\lambda(x_2)=b$ and $\lambda(x_3)=c$.
  (We do not show the names of events, only their labels.)
  Its precedence order is given by $x_1<x_2$, $x_3<x_2$ and $x_3<x_4$
  and its event order by $x_1\evord x_3$, $x_1\evord x_4$ and $x_2\evord x_4$.
  The sources are $S=\{x_3\}$ and the targets $T=\emptyset$.
  (We denote these using ``$\ibullet$''.)
  We think of events in $S$ as being already active at the beginning of $P$,
  and the ones in $T$ (here there are none) continue beyond the ipomset~$P$.
\end{example}

A bijection $f:P\to Q$ between concrete ipomsets is an \emph{isomorphism}
if it preserves and reflects the structure;
that is,
\begin{itemize}%[(1)]
\item $f(S_P)=S_Q$, $f(T_P)=T_Q$, $\lambda_Q\circ f=\lambda_P$,
\item $f(x)<_Q f(y)$ iff $x<_P y$, and $x\evord_P y$ iff $f(x)\evord_Q f(y)$.
\end{itemize}
We write $P\simeq Q$ if $P$ and $Q$ are isomorphic.
The following result extends \cite[Lem.\@ 34]{DBLP:journals/mscs/FahrenbergJSZ21}. 

\begin{lemma}
\label{le:UniqueIso}
	There is at most one isomorphism between any two concrete ipomsets.
\end{lemma}

\begin{proof}
	Let $f,g:P\to Q$ be isomorphisms of concrete ipomsets.
	By induction on $n=|P|=|Q|$ we will show that $f=g$. 
	For $n=1$ this is obvious,
	so assume that $n>1$. 
	The set of $<$-minimal elements $P_{\min}$ of $P$
	is totally $\evord$-ordered and thus
	there is a unique $\evord$-minimal element $x_0\in P_{\min}$.
	Similarly, there is a unique $\evord$-minimal element $y_0\in Q_{\min}$.
	Thus, $f(x_0)=g(x_0)=y_0$.
	The restrictions $f\rest {P\setminus\{x_0\}}$ and $g\rest {P\setminus\{x_0\}}$
	are isomorphisms of concrete ipomsets
	$P\setminus \{x_0\}\to Q\setminus\{y_0\}$
	of cardinality $n-1$ and hence they are equal.
	Eventually, $f=g$.
\end{proof}

\begin{definition}
	An \emph{ipomset} is an isomorphism class of concrete ipomsets.
\end{definition}

Thanks to Lemma \ref{le:UniqueIso} we 
can switch freely between ipomsets and their concrete representatives,
which we will do without further notice whenever convenient.
Furthermore, we may always choose representatives in isomorphism classes
such that isomorphisms become equalities:

\begin{lemma}
  \label{le:isoeq}
  For any concrete ipomsets $P$ and $Q$ with $T_P\simeq S_Q$ there exists $Q'\simeq Q$
  such that $T_P=S_{Q'}=P\cap Q'$.
\end{lemma}

\begin{proof}
  Write $P=\{p_1,\dotsc, p_n\}$ such that $T_P=\{p_1,\dotsc, p_k\}$ for some $k\ge 1$.
  (The lemma is trivially true for $T_P=\emptyset$.)
  Let $f: T_P\to S_Q$ be the (unique) isomorphism
  and enumerate $Q=\{q_1,\dotsc, q_m\}$ such that $f(p_i)=q_i$ for $i=1,\dotsc, k$.
  Define $Q'=\{q_1',\dotsc, q_m'\}$ by $q_i'=p_i$ for $i\le k$ and $q_i'=q_i$ for $i>k$,
  together with a bijection $g: Q'\to Q$ given by $g(q_i')=q_i$.
  Then $g$ introduces partial orders $<_{Q'}$ and $\evord_{Q'}$ on $Q'$ by
  $x <_{Q'} y$ iff $g(x) <_Q g(y)$ and $x \evord_{Q'} y$ iff $g(x) \evord_Q g(y)$.
  Setting $S_{Q'}=g(S_Q)$ and $T_{Q'}=g(T_Q)$ ensures that $g$ is an isomorphism and $T_P=S_{Q'}=P\cap Q'$.
\end{proof}

A \emph{pomset} is an ipomset $P$ without interfaces, \ie with $S_P=T_P=\emptyset$.

We introduce discrete ipomsets and some subclasses of these which will be important in what follows:
conclists will be the objects in the \emph{category} of ipomsets to be defined below,
and starters and terminators will be used in ipomset decompositions.

\begin{definition}
  An ipomset $(U, {<}, {\evord}, S, T, \lambda)$ is
  \begin{itemize}
  \item \emph{discrete} if ${<}$ is empty (hence $\evord$ is total);
  \item a \emph{conclist} (short for ``concurrency list'') if it is a discrete pomset ($S=T=\emptyset$);
    \hfill --  $\square$
  \item a \emph{starter} if it is discrete and $T=U$;
    \hfill -- $\St$
  \item a \emph{terminator} if it is discrete and $S=U$; and
    \hfill -- $\Te$
  \item an \emph{identity} if it is both a starter and a terminator.
    \hfill -- $\Id$
  \end{itemize}
  As already indicated above, we denote
  by $\square$ the set of conclists,
  by $\St$ the set of starters, and
  by $\Te$ the set of terminators.
  We write $\Id=\St\cap \Te$,
  $\Omega=\St\cup \Te$, $\St_+=\St\setminus \Id$, and $\Te_+=\Te\setminus \Id$.
\end{definition}

A conclist is, thus, a pomset of the form $(U, \emptyset, \evord, \emptyset, \emptyset, \lambda)$.
% to ease notation, we will generally omit the $\emptyset$.
%
The \emph{source interface} of an ipomset $(P, {<}, {\evord}, S, T, \lambda)$ as above is the conclist $(S,  {\evord\rest{S\times S}}, \lambda\rest{S})$
where ``${}\rest{}$'' denotes restriction;
the \emph{target interface} of $P$ is the conclist $(T, {\evord\rest{T\times T}}, \lambda\rest{T})$.

A starter $\ilo{S}{U}{U}$ is an ipomset which starts the events in $U\setminus S$ and lets all events continue.
Similarly, a terminator $\ilo{U}{U}{T}$ is an ipomset in which all events are already active at the beginning
and the events in $U\setminus T$ are terminated.

We call a starter or terminator \emph{elementary} if $|S| = |P| - 1$, resp.\ $|T| = |P| - 1$, that is, if
it starts or terminates exactly one event.
In the following, a discrete ipomset will be represented by a vertical ordering of its elements following the event order, with elements in the source (resp.\ target) set preceded (resp.\ followed) by the symbol $\ibullet$.
For example, the discrete ipomset 
\[
  (\{x_1, x_2, x_3\}, \emptyset, \{(x_i,x_j)\mid i<j\}, \{x_1, x_2\}, \{x_2, x_3\},\{(x_1, a), (x_2, b), (x_3, c)\})
\]
is represented by $\loset{\ibullet a\pibullet \\ \ibullet b \ibullet \\ \pibullet c \ibullet}$.

The \emph{width} $\wid(P)$ of an ipomset $P$ is the cardinality of a maximal $<$-antichain.
(So, for example, the above ipomset has width $3$.)

We recall the definition of the gluing of ipomsets,
an operation that extends concatenation of words and serial composition of pomsets \cite{DBLP:journals/tcs/Gischer88}.
The intuition is that in a gluing $P*Q$,
the events of $P$ precede those of $Q$, \emph{except} for events which are in the target interface of $P$.
These events are continued in $Q$, across the gluing;
hence we require the target interface of $P$ to be isomorphic to the source interface of $Q$.
The underlying set of $P*Q$ is then given as the union of the two, but counting the continuing events only once.

\begin{definition} 
  \label{de:gluing}
  Let $P$ and $Q$ be two concrete ipomsets with $T_P\simeq S_Q$.
  The \emph{gluing} of $P$ and $Q$ is defined
  as $P*Q=(R, {<}, {\evord}, S, T, \lambda)$ where:
  \begin{enumerate}
  \item $R=(P\sqcup Q)_{x=f(x)}$, the quotient of the disjoint union under the unique isomorphism $f: T_P\to S_Q$;
  \item ${<}=
    \{(i(x), i(y))\mid x<_P y\}
    \cup \{(j(x), j(y))\mid x<_Q y\}
    \cup \{(i(x), j(y))\mid x\in P\setminus T_P, y\in Q\setminus S_Q\}$,
    where $i: P\to R$ and $j: Q\to R$ are the canonical injections;
  \item ${\evord}=(\{(i(x), i(y)\mid x\evord_P y\}\cup \{(j(x), j(y)\mid x\evord_Q y\})$;
  \item $S=i(S_P)$; $T=j(T_Q)$; and
  \item $\lambda(i(x))=\lambda_P(x)$, $\lambda(j(x))=\lambda_Q(x)$.
  \end{enumerate}
\end{definition}

