\begin{lemma}[{%
    \cite[Proposition 3.5]{DBLP:journals/fuin/FahrenbergZ24};
    \cite[Lemma 4]{AMRANE2025115156}}]
  \label{le:ipomsparse}
  Let $P$ be an (interval) ipomset.
  \begin{itemize}
  \item $P$ has a unique sparse step decomposition.
  \item Every dense decomposition $P=P_1*\dotsm*P_n$ has the same length $n$.
  \end{itemize}
\end{lemma}

Showing existence of sparse decompositions is easy
and consists of gluing starters and terminators until no more such gluing is possible; showing uniqueness is more tedious.

We introduce special notations for starters and terminators to more clearly specify the conclists of events which are started or terminated.
For a conclist $U$ and subsets $A,B\subseteq U$ we write 
\begin{itemize}
\item
$\starter{U}{A}=\ilo{U\setminus A}{U}{U}=(U, {\evord}, U\setminus A, U, \lambda)$
and
\item
$\terminator{U}{B}=\ilo{U}{U}{U\setminus B}=(U, {\evord}, U, U\setminus B, \lambda)$.
\end{itemize}
The intuition is that the starter $\starter{U}{A}$ does nothing but start the events in $A=U\setminus S_U$
and the terminator $\terminator{U}{B}$ terminates the events in $B=U\setminus T_U$.
% Then $\id_U=\starter{U}{\emptyset}=\terminator{U}{\emptyset}$; but we will prefer the $\id_U$ notation.

\section{A Categorical View of $\iiPoms$}
\label{se:catiipoms}
The following is clear, see also \cite[Proposition~1]{DBLP:journals/iandc/FahrenbergJSZ22}.

\begin{proposition}
  \label{prop:ipomsetCat}
  Ipomsets form a category $\iPoms$:
  \begin{itemize}
  \item objects are conclists;
  \item morphisms in $\iPoms(U, V)$ are ipomsets $P$ with $S_P=U$ and $T_P=V$;
  \item composition of morphisms is gluing;
  \item identities are $\id_U=\ilo{U}{U}{U}\in \iPoms(U, U)$. 
  \end{itemize}
\end{proposition}

\begin{proof}
  The only statement needing proof is that composition is associative with units $\ilo{U}{U}{U}$,
  and these properties are easily verified for gluing composition on (isomorphism classes of) ipomsets.
\end{proof}

\subsection{Ipomsets with transitive event order}
\label{se:ipoms-trans}

% \ufin{Move to intro:\\
% Above and in other works \cite{DBLP:journals/mscs/FahrenbergJSZ21,DBLP:journals/lmcs/FahrenbergJSZ24,DBLP:journals/fuin/FahrenbergZ24,AMRANE2025115156}	a transitively closed event order is used.
% In particular, its essential part is necessary in order to define gluing composition, see below.
% Further, a central tool in the language theory of HDAs
% (which we, however, do not need here)
% are so-called track objects,
% which provide an embedding of ipomsets into HDAs which essentially needs the (transitive) event order;
% see \cite{DBLP:journals/mscs/FahrenbergJSZ21} for details.
% However, from a logical perspective, isomorphic ipomsets may not be logically equivalent, due to the non-essential part of event order, and may  therefore fail to satisfy the same formula.}

Our definition of ipomsets is different from the ones used in
\cite{DBLP:journals/mscs/FahrenbergJSZ21, DBLP:journals/lmcs/FahrenbergJSZ24},
which require event order to be transitive.
Here we make precise the relation between the two definitions.

A \emph{concrete ipomset with transitive event order} is a structure
$(P, {<}, {\evord}, S, T, \lambda)$ as in Definition \ref{de:ipoms},
except that $\evord$ is required to be a strict partial order,
and the requirement on the union of $<$ and $\evord$ is reduced to demanding that
\emph{at least one} of the following holds for every $x,y\in P$:
\[x<y,\qquad y<x,\qquad x\evord y,\qquad y\evord x,\qquad x=y.\]

Any ipomset as of Definition \ref{de:ipoms} may be turned into one with transitive event order
by transitively closing $\evord$, \ie
mapping $(P, {<}, {\evord}, S, T, \lambda)$ to
\begin{equation*}
  F((P, {<}, {\evord}, S, T, \lambda)) = (P, {<}, {\evord^+}, S, T, \lambda).
\end{equation*}
Conversely, any ipomset with transitive event order may be turned into the other type
by removing the \emph{inessential} part of $\evord$,
\ie mapping $(P, {<}, {\evord}, S, T, \lambda)$ to
\begin{equation*}
  G((P, {<}, {\evord}, S, T, \lambda)) = (P, {<}, {\evord'}, S, T, \lambda)
\end{equation*}
with ${\evord'}={\evord}\cap {\not<}\cap {\not>}$.
% \ufsb{}{attn switched $F$ and $G$}

The definitions of isomorphism and subsumption of ipomsets with transitive event order
have to take into account that some of the event order may be inessential in the sense above,
changing item \ref{en:subsu.evord} of Definition \ref{de:subsu} to demand that
\begin{itemize}
\item if $x\evord_P y$, $x\not< y$, and $y\not< y$, then $f(x)\evord_Q f(y)$.
\end{itemize}
Once this is in place, the mappings $F$ and $G$ above extend to an isomorphism of categories
between $\iiPoms$ and the category of isomorphism classes of ipomsets with transitive event order.
The two notions are, thus, equivalent.


