Let $\Psip:\Coh\to \iPoms$ be the functor induced by the inclusion $\bOmega\hookrightarrow \iPoms$:
\begin{equation*}
  \Psip(U)=U,\qquad \Psip(P)=P.
\end{equation*}
Then $\Psip(P_1\dots P_n)=P_1*\dots*P_n$.
The following is straightforward.

\begin{lemma}
  If $P_1\dots P_n\sim Q_1\dots Q_m$, then $\Psip(P_1\dotsc P_n)=\Psip(Q_1\dots Q_m)$. 
\end{lemma}

Thus $\Psip$ induces a functor $\Psi:\Cohsim\to \iPoms$; we show below that $\Psi$ is an isomorphism of categories.
See Figure~\ref{fi:ipomscohphipsi} for an overview of the introduced structures and mappings.

A \emph{step sequence} \cite{conf/apn/AmraneBCF24} is a morphism in $\Cohsim$,
that is, an equivalence class of coherent words under $\sim$.
% It is shown in \cite{DBLP:journals/fuin/FahrenbergZ24} that every ipomset may be decomposed into a step sequence:
We redevelop the facts about step decompositions from Section \ref{se:ipomsets-step} in terms of step sequences.

\begin{lemma}
  \label{le:stepdecomp}
  For every $P\in \iPoms$ there exists $w\in \Cohsim$ such that $\Psi(w)=P$.
\end{lemma}

\begin{proof}
  This is the same as saying that every ipomset has a step decomposition.
\end{proof}

A word $P_1\dots P_n\in \Coh$ is \emph{dense} if all its elements are elementary, \ie start or terminate precisely one event.
It is \emph{sparse} if proper starters and terminators are alternating,
that is, for all $i=1,\dots, n-1$, $(P_i,P_{i+1}) \in (\St_+ \times \Te_+) \cup (\Te_+ \times \St_+)$.
By convention, identities $\id_U\in \Coh$ are both dense and sparse.
We let $\DCoh, \SCoh\subseteq \Coh$ denote the subsets of dense, resp.\ sparse coherent words.

\begin{lemma}
  \label{le:sparseuniq}
  Every step sequence contains exactly one sparse coherent word.
\end{lemma}

\begin{proof}
  Let $P_1\dotsm P_n\in\Coh$
  be a representative of a step sequence having minimal length.
  If $P_i$ and $P_{i+1}$ are both starters or both terminators, 
  then $P_1\dotsm P_{i-1}(P_iP_{i+1})P_{i+2}\dotsm P_n$
  is a shorter representative: a contradiction.
  Thus, $P_1\dotsm P_n\in\Coh$ is sparse.

  If $Q_1\dotsm Q_m\sim P_1\dotsm P_n$ is another sparse representative,
  then
  \[
    P_1*\dotsm*P_n=P=Q_1*\dotsm*Q_m
  \]
  are both sparse decompositions of $P$,
  and by Lemma \ref{le:ipomsparse} they are equal.
\end{proof}

\begin{example}
  The unique sparse step sequence corresponding to the ipomset in Figure~\ref{fi:n} is
  \begin{equation*}
    % P =
    \bigloset{ \pibullet  a \ibullet \\ \ibullet c \ibullet} 
    \bigloset{\ibullet a \ibullet \\ \ibullet c\pibullet }
    \bigloset{\ibullet a \ibullet \\ \pibullet a \ibullet}
    \bigloset{\ibullet a\pibullet  \\ \ibullet a \ibullet}
    \bigloset{\pibullet  b \ibullet \\ \ibullet a \ibullet}
    \bigloset{ \ibullet b \\ \ibullet a}:
  \end{equation*}
  it first starts the first $a$, then terminates $c$,
  then starts the second $a$,
  terminates the first $a$,
  then starts $b$ and finally terminates both $b$ and the second $a$.
  The corresponding dense step sequences are
  \begin{align*}
    % P =
    & \bigloset{\pibullet  a \ibullet \\ \ibullet c \ibullet} 
    \bigloset{\ibullet a \ibullet \\ \ibullet c\pibullet }
    \bigloset{\ibullet a \ibullet \\ \pibullet a \ibullet}
    \bigloset{\ibullet a\pibullet  \\ \ibullet a \ibullet}
    \bigloset{\pibullet  b \ibullet \\ \ibullet a \ibullet}
    \bigloset{ \ibullet b\pibullet  \\ \ibullet a \ibullet}
    \bigloset{\ibullet a} \\
    {}={}
    & \bigloset{\pibullet  a \ibullet \\ \ibullet c \ibullet} 
    \bigloset{\ibullet a \ibullet \\ \ibullet c\pibullet }
    \bigloset{\ibullet a \ibullet \\ \pibullet a \ibullet}
    \bigloset{\ibullet a\pibullet  \\ \ibullet a \ibullet}
    \bigloset{\pibullet  b \ibullet \\ \ibullet a \ibullet}
    \bigloset{ \ibullet b \ibullet \\ \ibullet a\pibullet }
    \bigloset{\ibullet b},
  \end{align*}
  which differ only in the order in which $b$ and $a$ are terminated at the end.
\end{example}

Using Lemmas \ref{le:stepdecomp} and \ref{le:sparseuniq},
we may now define a functor $\Phi: \iPoms \to \Cohsim$ which will serve as inverse to $\Psi$.
First, for $P\in \iPoms$ let $\Phip(P)\in \Coh$ be its unique sparse step decomposition;
this defines a mapping $\Phip: \iPoms\to \Coh$.
Now define $\Phi$ by $\Phi(P)=[\Phip(w)]_\sim$.

\begin{theorem}
  \label{th:genipoms}
  $\Phi$ is a functor, $\Psi \circ \Phi = \Id_{\iPoms}$, and $\Phi \circ \Psi = \Id_{\Cohsim}$.
  Hence $\Phi: \iPoms\leftrightarrows \Cohsim: \Psi$ is an isomorphism of categories.
\end{theorem}

\begin{proof}
  We have $\Phi(\id_U)=[\Phip(\id_U)]_\sim=[\Id_U]_\sim=\id_U$ using the relations (\ref{eq:sim-stepseq}).
  Let $P, Q\in\iPoms\setminus\Id$ be ipomsets such $T_P=S_Q$ 
  and $P=P_1*\dotsm*P_n$ and $Q=Q_1*\dotsm*Q_m$ the unique sparse decompositions.
  If $P_n$ is a starter and $Q_1$ is a terminator or vice versa,
  then $P*Q=P_1*\dotsm*P_n*Q_1*\dotsm*Q_m$ is sparse, so that
  \[
    \Phip(P*Q)=P_1\dotsm P_nQ_1\dotsm Q_m
    =
    \Phip(P)\Phip(Q).
  \]
  If $P_n$ and $Q_1$ are both starters or both terminators, then
  \[
    P*Q=P_1*\dotsm*P_{n-1}*(P_n*Q_1)*Q_2*\dotsm*Q_m
  \]
  is a sparse decomposition, hence
  \[
    \Phip(P*Q)=
    P_1\dotsm P_{n-1}(P_n*Q_1)Q_2\dotsm Q_m
    \sim
    P_1\dotsm P_{n-1}P_nQ_1Q_2\dotsm Q_m
    =
    \Phip(P)\Phip(Q).
  \]
  In both cases, $\Phi(P*Q)=[\Phip(P*Q)]_\sim=[\Phip(P)\Phip(Q)]_\sim=[\Phip(P)]_\sim[\Phip(Q)]_\sim=\Phi(P)\Phi(Q)$.	
  The case when $P$ or $Q$ is an identity can be handled in a similar way.
  As a consequence, $\Phi$ is a functor.

  The composition $\Psip\Phip$ is clearly the identity on $\iPoms$
  so $\Psi\Phi$ is also an identity.
  For $P_1\dotsm P_n\in \Coh$, 
  $\Phip\Psip(P_1\dotsm P_n)$ is the unique sparse representative
  of $P_1\dotsm P_n$.
  In particular, $P_1\dotsm P_n\sim \Phip\Psip(P_1\dotsm P_n)$ and then $\Phi\Psi=\Id_{\Coh_\sim}$.
\end{proof}

Given that $\Cohsim$ and $\iPoms$ are isomorphic,
we will often confuse the two
and, for example, write $[w]_\sim$ instead of $\Psip(w)=\Psi([w]_\sim)$ for $w\in\Coh$.

\begin{corollary}
  The category $\iPoms$ is generated by the directed multigraph $\bOmega$ using gluing composition,
  under the identities \eqref{eq:sim-stepseq}.
\end{corollary}

\section{Subsumptions in Step Sequences}
\label{se:step-subsumptions}

In this section,
we extend the equivalence between ipomsets and step sequences from Theorem~\ref{th:genipoms}
to also cover subsumptions.

Define a partial preorder on $\DCoh$ generated by
\begin{alignat}{2}
  \starter{(U\setminus b)}{a}\cdot \starter {U} {b}
  &\preceq
  \starter{(U\setminus a)}{b}\cdot \starter {U} {a}
  \qquad &&(a\ne b)
  \label{eq:subselm.stst} \\
  \terminator {U} {b}\cdot \terminator{(U\setminus b)}{a}
  &\preceq
  \terminator {U} {a}\cdot \terminator{(U\setminus a)}{b}
  \qquad &&(a\ne b)
  \label{eq:subselm.tete} \\
  \terminator {(U \setminus a)} b \cdot \starter {(U \setminus b)} a
  &\preceq
  \starter U a \cdot \terminator U b
  \qquad &&(a\ne b)
  \label{eq:subselm.stte} \\
  w\preceq w' &\implies v w y\preceq v w' y
  \notag
\end{alignat}
These relations swap elements of coherent words,
taking care of adjusting them to preserve coherency.
Transpositions of type \eqref{eq:subselm.stst} and \eqref{eq:subselm.tete}
swap subsequent starters, resp.\ subsequent terminators;
these are, in fact, equivalences.
Transpositions of type \eqref{eq:subselm.stte} swap a starter with a terminator,
introducing a proper subsumption.

\begin{lemma}
  \label{le:subselm-sound}
  For any $w, w'\in \DCoh$, $w\preceq w'$ implies $[w]_\sim\subseq [w']_\sim$.
\end{lemma}

\begin{proof}
  The three elementary cases above all define subsumptions,
  and by Lemma \ref{le:subsglue} gluing preserves subsumptions.
\end{proof}

\begin{remark}
  In the context of HDAs,
  \cite{DBLP:journals/tcs/Glabbeek06}
  defines a notion of \emph{adjacency} for paths
  which consists of precisely the analogues of the transformations that we define above.
  Adjacency is then used to define \emph{homotopy} of paths,
  which is the equivalence closure of adjacency.
  Taking only the reflexive and transitive closure,
  we will instead use it to define subsumptions.
  % On paths, homotopy is the symmetric and transitive closure of subsumption.
\end{remark}

