Our goal is now to show an inverse to Lemma \ref{le:subselm-sound},
showing that subsumptions of ipomsets are generated by the elementary transpositions
\eqref{eq:subselm.stst}, \eqref{eq:subselm.tete} and \eqref{eq:subselm.stte}.
% For every dense decomposition $P=P_1\dotsc P_n$
% let $j_i:P_i\to P$ denote the canonical inclusion.

For $w=P_1\dotsm P_n$ and $p\in P=[w]_\sim$ define
\begin{align*}
  \xst_w(p) &=
  \begin{cases}
    \min\{i\mid p\in P_i\} & \text{for $p\not\in S_P$},\\
    -\infty & \text{for $p\in S_P$},
  \end{cases} \\
  \xen_w(p) &=
  \begin{cases}
    \max\{i\mid p\in P_i\} & \text{for $p\not\in T_P$},\\
    +\infty & \text{for $p\in T_P$}.
  \end{cases}
  % \xst(p) &=
  % \begin{cases}
  %   \inf\{j\mid p\in \im(j_i)\} & \text{for $p\not\in S_P$},\\
  %   -\infty & \text{for $p\in S_P$},
  % \end{cases} \\
  % \xen(p) &=
  % \begin{cases}
  %   \sup\{j\mid p\in \im(j_i)\} & \text{for $p\not\in T_P$},\\
  %   +\infty & \text{for $p\in T_P$}.
  % \end{cases}
\end{align*}
The next lemma shows that $(\xst_w,\xen_w)$ is a ``bijective'' interval representation of $P$.

\begin{lemma}
  We have
  $\xst_w(P)\cap \xen_w(P)=\emptyset$,
  and for every $i=1,\dotsc, n$ there is precisely one $p\in P$ with $\xst_w(p)=i$ or $\xen_w(p)=i$.
\end{lemma}

\begin{proof}
  Every $P_i$ is either a starter or a terminator, hence $\xst_w(P)\cap \xen_w(P)=\emptyset$.
  Further, every $P_i$ is elementary, implying the second claim.
\end{proof}

We may hence define a function $\phi_w:\{1,\dotsc,n\}\to P$
that tells which event starts or terminates at a given place,
given by $\phi_w(i)=p$ if $\xst_w(p)=i$ or $\xen(p)=i$.

% \begin{lemma}
%   Let $u,v\in \DCoh$.
%   If $P=[u]_\sim$, $Q=[v]_\sim$ and $P\subseq Q$, then $u$ and $v$ have the same length.\ufsb{}{This is Lemma \ref{le:ipomsparse}}
% \end{lemma}

\begin{lemma}
  \label{le:subselm-complete}
  If $P\subseq Q$, $P=[u]_\sim$, and $Q=[v]_\sim$, then $u\preceq v$.
\end{lemma}

\begin{proof}
  Let $u=P_1\dotsc P_n$ and $v=Q_1\dotsc Q_n$
  ($u$ and $v$ have the same length by Lemma \ref{le:ipomsparse}).
  Consider some cases:
  \begin{enumerate}
  \item
    $P_1$ is a starter.
    Let $p=\phi_u(1)$ be the event started at $P_1$, then $p\notin S_P=S_Q$.
    Let $m=\xst_v(p)$.
    Assume that there is $j\in \{1,\dotsc, m-1\}$ such that $Q_j$ is a terminator,
    then with $q=\phi_v(j)$ we would have $q<_Q p$ but $q\not<_P p$: a contradiction to $P\subseq Q$.

    Hence all of $Q_1\dotsc, Q_m$ are starters,
    so we can use transpositions of type \eqref{eq:subselm.stst}
    to move $Q_m$ to the very beginning of $v$.
    Now $P_1=Q_1$,
    and we can use induction on $P_2\dotsm P_n$ and $Q_2\dotsm Q_n$.

    % Otherwise, let $m\in\{0,\dotsc, n-1\}$ be such that
    % all of $Q_1,\dotsc,Q_m$ are starters and $Q_{m+1}$ is a terminator.

    % Assume $i=\xst_v(p)>m$, then $m\le n-2$ and $i\ge m+2$.
    % Now with $q=\phi_v(m+1)$ we would have $q<_Q p$ but $q\not<_P p$: a contradiction.
    % Hence $i\le m$, so $p$ is started within an initial sequence of starters in $v$,
    % and we can again use transpositions of type \eqref{eq:subselm.stst}
    % to move $Q_i$ to the very beginning of $v$.
  \item
    $Q_1$ is a terminator.
    This uses a dual argument to the one above,
    showing that $u$ must begin with a sequence of terminators,
    one of which terminates $\phi_v(1)$,
    and then using transpositions of type \eqref{eq:subselm.tete}
    to move that terminator to the very beginning.
  \item
    $P_1$ is a terminator and $Q_1$ is a starter.
    Let $p=\phi_u(1)$ be the event terminated at $P_1$, then $p\in S_P=S_Q$ and $p\notin T_P=T_Q$.
    Let $k=\xen_v(p)$ be the index at which $p$ is terminated in $v$.

    None of $Q_1,\dotsc, Q_{k-1}$ start or terminate $p$,
    so we can use transpositions of type \eqref{eq:subselm.tete} or \eqref{eq:subselm.stte}
    (from right to left)
    to move $Q_k$ to the beginning of $v$.
    Now $P_1=Q_1$,
    and we can again use induction on $P_2\dotsm P_n$ and $Q_2\dotsm Q_n$.
  \end{enumerate}
\end{proof}

\begin{example}
  Let $P = \loset{a \\ b}$, $Q = ab$,
  and $b\ibullet \loset{\pibullet a \ibullet \\ \ibullet b \ibullet} \loset{\ibullet a \ibullet \\ \ibullet b \pibullet } \ibullet a$
  and $a\ibullet\, \ibullet a b\ibullet\, \ibullet b$
  be dense step sequences corresponding to $P$ resp.\ $Q$.
  %
  An example of a sequence as in Lemma \ref{le:subselm-complete} that underlines the fact that $Q \subs P$ is
  \begin{equation*}
  \begin{array}{r@{\,}c@{\,}c@{\,}c@{\,}c}
    w_1 &= b\ibullet &\loset{\pibullet a \ibullet \\ \ibullet b \ibullet} &\loset{\ibullet a \ibullet \\ \ibullet b\pibullet } &\ibullet a, \\
    w_2 &= a\ibullet &\loset{\ibullet a \ibullet \\ \pibullet b \ibullet} &\loset{\ibullet a \ibullet \\ \ibullet b\pibullet } &\ibullet a, \\
    w_3 &=  a\ibullet &\loset{\ibullet a \ibullet \\ \pibullet b \ibullet} &\loset{\ibullet a \pibullet \\ \ibullet b\ibullet} &\ibullet b, \\
    w_4 &=  a\ibullet\, &\ibullet a& b\ibullet\, &\ibullet b.
  \end{array}
  \end{equation*}
\end{example}

