\begin{theorem}
  \label{th:subsumption}
  For $P, Q\in \iPoms$, the following conditions are equivalent.
\begin{enumerate}
\item
	$P\subseq Q$.
\item
	$v\preceq w$ for all $v,w\in\DCoh$ such that $[v]_\sim = P$, $[w]_\sim=Q$.
\item
	$v\preceq w$ for some $v,w\in\DCoh$ such that $[v]_\sim = P$, $[w]_\sim=Q$.	
\end{enumerate}  
\end{theorem}

\begin{proof}
	Implication 1.\;$\Rightarrow$ 2.\@ is Lemma \ref{le:subselm-complete},
	2.\;$\Rightarrow$ 3.\@ follows by the existence of dense step decompositions,
	and 3.\;$\Rightarrow$ 1.\@ is Lemma \ref{le:subselm-sound}.
\end{proof}

% \begin{corollary}
