\begin{corollary}
  Every subsumption $P\subseq Q$ is a composition of elementary 
  subsumptions of the form 
  $P'*\terminator {(U \setminus a)} b * \starter {(U \setminus b)} a *P''
  \subs
  P'*\starter U a * \terminator U b*P''$.
\end{corollary}

\begin{proof}
  This follows from Lemma \ref{le:subselm-complete} and the definition of $\preceq$.
  (Relations \eqref{eq:subselm.stst} and \eqref{eq:subselm.tete}
  can be skipped since they induce
  % trivial subsumptions.)
  isomorphisms.)
\end{proof}

