The \emph{language} of an HDA $\hda{H}$ is
\begin{equation*}
  \Lang(\hda{H}) = \{\ev(\alpha)\mid \alpha \text{ accepting path in } \hda{H}\} \subseteq \iPoms.
\end{equation*}
Languages of HDAs are closed under subsumption \cite{DBLP:journals/lmcs/FahrenbergJSZ24}:
whenever $P\subseq Q\in L(\hda{H})$, then also $P\in L(\hda{H})$.
This motivates the following definition of language.

For a subset $\mcal S\subseteq \iiPoms$ we let
\begin{equation*}
  \mcal S\down=\{P\in \iiPoms\mid \exists Q\in \mcal S: P\subseq Q\}
\end{equation*}
denote its (downward) closure under subsumptions.
% \mfsb{}{should we say "(downward) closure" instead?}
%
% Note that $(A\cup B)\down=A\down\cup B\down$ for all $A, B\subseteq \iiPoms$,
% but for intersection this does \emph{not} hold;
% for example it may happen that $A\cap B=\emptyset$ but $A\down\cap B\down\ne \emptyset$.
%
A \emph{language} is a subset $L\subseteq \iiPoms$ for which $L\down=L$.

A language is \emph{regular} if it is the language of a finite HDA.
A language is \emph{rational} if it is constructed from $\emptyset$, $\{\id_\emptyset\}$ and discrete ipomsets
using $\cup$, $*$ and $^+$ (Kleene plus)~\cite{DBLP:journals/lmcs/FahrenbergJSZ24}.
These operations have to take subsumption closure into account; in particular,
\begin{equation*}
	L_1 * L_2 = \{P*Q\mid P\in L_1, Q\in L_2\}\down.
\end{equation*}

\begin{theorem}[\cite{DBLP:journals/lmcs/FahrenbergJSZ24}]
  \label{th:kleene}
  A language is regular if and only if it is rational.
\end{theorem}

The \emph{width} of a language $L$ is $\wid(L)=\sup\{\wid(P)\mid P\in L\}$.
\begin{lemma}[\cite{DBLP:journals/lmcs/FahrenbergJSZ24}]
	\label{lem:finitewidth}
	Any regular language has finite width.
\end{lemma}


\subsection{ST-automata} 
\label{sse:st-a}

We now introduce ST-automata and the translation from HDAs to these structures.
Recall that $\Omega=\St\cup \Te$ denotes the set of starters and terminators over $\Sigma$.

\begin{definition}
  \label{de:staut}
  An \emph{ST-automaton} is a structure $A=(Q, E, I, F, \lambda)$
  consisting of sets $Q$, $E\subseteq Q\times \Omega\times Q$, $I, F\subseteq Q$,
  and a function $\lambda: Q\to \square$ such that
  for all $(q, \ilo{S}{U}{T}, r)\in E$, $\lambda(q)=S$ and $\lambda(r)=T$.
\end{definition}

This is thus a plain automaton (finite or infinite) over $\Omega$,
with an additional labeling of states with conclists that is consistent with the labeling of edges.
(But note that the alphabet $\Omega$ is infinite.)

\begin{remark}
  \label{re:staomega}
  Equivalently, an ST-automaton may be defined as a directed multigraph $G$
  together with a graph morphism $\ev: G\to \bOmega$
  and initial and final states $I$ and $F$.
  This definition would be slightly more general than the one above,
  given that it allows for multiple edges with the same label between the same pair of states.
\end{remark}

A \emph{path} in an ST-automaton $A$ is defined as usual, as
an alternating sequence $\pi=(q_0, e_1, q_1,\dots, e_n, q_n)$
of states $q_i$ and transitions $e_i$ such that $e_i=(q_{i-1}, P_i, q_i)$ for  every $i=1,\dots, n$
and some sequence $P_1,\dots, P_n\in \Omega$.
The path is \emph{accepting} if $q_0\in I$ and $q_n\in F$.
The \emph{label} of $\pi$ as above is
$\ell(\pi)=[\id_{\lambda(q_0)} P_1 \id_{\lambda(q_1)}\dots P_n \id_{\lambda(q_n)}]_\sim$.
That is, to compute $\ell(\pi)$ we collect labels of states and transitions,
but then we map the so-constructed coherent word to its step sequence.

The \emph{language} of an ST-automaton $A$ is
\begin{equation*}
  \Lang(A) = \{\ell(\pi)\mid \pi \text{ accepting path in } A\} \subseteq \Cohsim.
\end{equation*}
% \aasb{}{Are we saying that when we accept a coherent word, we accept all its $\sim$-class even if the corresponding paths are not present in the ST-automaton ?}
Contrary to languages of HDAs, languages of ST-automata may not be closed under subsumption, see below.

\subsection{From HDAs to ST-automata}
\label{sse:hda-sta-translations}

We now define the translation from HDAs to ST-automata.
In order to relate it to their languages,
we extend the pair of functors $\Phi: \iPoms\leftrightarrows \Cohsim: \Psi$
to the power sets the usual way:
\begin{equation*}
  \Phi(\mcal{S}) = \{\Phi(P)\mid P\in \mcal{S}\}, \qquad
  \Psi(\mcal{S}) = \{\Psi(w)\mid w\in \mcal{S}\}.
\end{equation*}

To a given HDA $\hda{H}=(\cell{H}, \bot, \top)$ we associate an ST-automaton $\ST(\hda{H})=(Q, E, I, F, \lambda)$ as follows:
\begin{itemize}
\item $Q=\cell{H}$, $I=\bot$, $F=\top$, $\lambda=\ev$, and
\item $E=\{(\delta_A^0(q), \starter{\ev(q)}{A}, q)\mid A\subseteq \ev(q)\}
  \cup \{(q, \terminator{\ev(q)}{A}, \delta_A^1(q))\mid A\subseteq \ev(q)\}$.
\end{itemize}
That is, the transitions of $\ST(\hda{H})$ precisely mimic the starting and terminating of events in $\hda{H}$.
(Note that lower faces in $\hda{H}$ are inverted to get the starting transitions.)

