\begin{theorem}
	\label{th:MSOeq}
	\begin{enumerate}
		\item For every sentence $\phi \in \MSOP$ and every $k$, there exists
		a sentence $\widehat \phi \in \MSOW$ over $\Omegaswb^*$ such that
		$L(\widehat \phi) = \Psip^{-1}(L(\phi)_{\le k})$.
		\item For every $k$ and every  sentence $\phi \in \MSOW$ over $\Omegaswb^*$,
		there exists a sentence $\overline \phi \in \MSOP$
		such that $L(\overline \phi) = \Psip(L(\phi) \cap \SCoh)$.
	\end{enumerate}
\end{theorem}

In addition, the constructions are effective. 
By passing through ST-automata and classical automata, we obtain the following corollary.

\begin{corollary}
  \label{cor:MSOdef}
  Let $L \subseteq \iiPoms_{\le k}$.
  The following are equivalent:
  \begin{enumerate}
  \item $L$ is $\MSOP$-definable;
  \item $\Phip(L)$ is $\MSOW$-definable;
  \item $\Phi(L)$ is $\MSOW$-definable.
  \end{enumerate}
  % Then $L$ is $\MSOP$-definable iff $\Phip(L)$ is $\MSOW$-definable iff $\Phi(L)$ is $\MSOW$-definable.
\end{corollary}

\begin{remark}
    The reader familiar with MSO transductions (see e.g.\ \cite{DBLP:books/daglib/0030804}) may notice that the next two subsections essentially show that $\Psip$ and  $\Phip$ can be defined through MSO transductions (see in particular Lemmas~\ref{lem:baserel}, \ref{lem:compare} and \ref{lem:StTe(x)Def}).
\end{remark}


\subsection{From $\iiPoms_{\le k}$ to $\Coh_{\le k}$}

Here, we prove the first item of Theorem~\ref{th:MSOeq}.
For now, we restrict ourselves to words without any occurrence of the empty 
ipomset $\id_{\emptyset}$.
Our goal is to prove the following:

\begin{lemma}
	\label{lem:msodec}
	For every $\phi \in \MSOP$ and every $k$, there exists 
	$\widehat \phi \in \MSOW$ such that for all
	$w \in (\Omegaswb \setminus \{\id_\emptyset\})^+ $, we have
	$w \models \widehat \phi$ if and only if $w \in \Coh$ and 
	$\Psip(w) \models \phi$.
\end{lemma}

Prior to proving the lemma, we introduce some notation.
We want  a word $P_1\dots P_n$ of $(\Omegaswb \setminus \{\id_\emptyset\})^+$ to satisfy $\widehat \phi$ if and only if the gluing composition $P = P_1 \comp \cdots \comp P_n$ is a model for $\phi$.
Thus $\widehat \phi$ must accept only coherent words. This is $\MSOW$-definable by:
\[
\texttt{Coh}_k  \eqdef \exists z\, \forall x\, \forall y.\, x \psucc y \implies \!\!\bigvee_{D_1 D_2 \in \Coh \cap \smash{\Omegaswb^2}}\!\! D_1(x) \land D_2(y).
\]
That is, the word is non-empty ($\exists z$) and discrete ipomsets of $\Omegaswb$ at consecutive positions $x$ and $y$ may be glued.

Hence,  $\widehat{\phi}$ will be the conjunction of $\texttt{Coh}_k$ and an $\MSOW$ formula $\phi'$ which we will build by induction on $\phi$.
To construct $\phi'$, the intuition is that, given an ipomset $P$ and a coherent word $w = P_1\dots P_n \in (\Omegaswb \setminus \{\id_\emptyset\})^+$ such that $\Psip(w) =P$, an event $e$ of $P$  may appear in several consecutive  $<$-positions $1 \leq \ell_1,\dots,\ell_m \leq n$ in $w$ and, in each $<$-position $\ell_j$, it occurs once in some $\evord$-position $i_j$.
The goal in $\phi'$ is to select some convenient interval of pairs $(\ell_j,i_j)$ when $\phi$ selects $e$.

More formally, let $w = P_1\dots P_n \in \Coh_{\le k}$ and $P= P_1 * \dots * P_n$.
Let $E = \{1,\ldots,n\} \times \{1,\ldots,k\}$.
Our construction is built on a partial function $\evt\colon E \to P$ defined as follows:
if $P_\ell$ consists of events $e_1 \evord \cdots \evord e_r$, then for every $i \le r$, $\evt(\ell,i) = e_i$.
Our first step towards proving Lemma~\ref{lem:msodec} is to show that all
atomic predicates $x = y$, $x < y$, $a(x)$, etc.\ of $\MSOP$
can be translated into formulas in $\MSOW$:

\begin{lemma}\label{lem:baserel}
	For every $k \in \Nat$ and $1 \le i,j \le k$, one can define
	$\MSOW$ formulas
	$\phidom(x,i)$,
	$(x,i) \newSim (y,j)$,
	$(x,i) < (y,j)$,
	$(x,i) \evord (y,j)$,
	$a(x,i)$,
	$\srci(x,i)$,
	and $\tgti(x,i)$, such that for all $w \in \Coh_{\le k}$ with $\Psip(w) = (P,<_P,\evord_P,S_P,T_P,\lambda_P)$ and for any valuation $\nu$ over $w$:
	\[
	\begin{aligned}
		w & \models_\nu \phidom(x,i)
		&& \quad\text{if and only if}\qquad \evt(\nu(x),i) \text{ is defined} \\
		w & \models_\nu (x,i) \newSim (y,j)
		&& \quad\text{if and only if}\qquad \evt(\nu(x),i) = \evt(\nu(y),j) \\
		w & \models_\nu (x,i) < (y,j)
		&& \quad\text{if and only if}\qquad \evt(\nu(x),i) <_P \evt(\nu(y),j) \\
		w & \models_\nu (x,i) \evord (y,j)
		&& \quad\text{if and only if}\qquad \evt(\nu(x),i) \evord_P \evt(\nu(y),j) \\
		w & \models_\nu a(x,i)
		&& \quad\text{if and only if}\qquad \lambda_P(\evt(\nu(x),i)) = a \\
		w & \models_\nu \srci(x,i)
		&& \quad\text{if and only if}\qquad \evt(\nu(x),i) \in S_P \\
		w & \models_\nu \tgti(x,i)
		&& \quad\text{if and only if}\qquad \evt(\nu(x),i) \in T_P .
	\end{aligned}
	\]
\end{lemma}
\begin{proof}
	The formula $\phidom(x,i)$ simply checks that the discrete ipomset labeling
	$x$ is of size at least $i$:
	\[
		\phidom(x,i) \eqdef \bigvee_{D \in \Omega_{\le k} \setminus \Omega_{\le i-1}} D(x).
	\]
	Let us now define the formula $(x,i) \newSim (y,j)$.
	Let $w = P_1\dots P_n$.
	Notice that an event $e \in P$ may occur in several consecutive
	$P_\ell$'s within $w$.
	So the formula $(x,i) \newSim (y,j)$ is meant to determine
	when $\evt(\ell,i) = \evt(\ell',j)$ for some positions $\ell,\ell'$ within $w$.
	We first consider the case where $\ell' = \ell+1$.
	For all $i',j' \le k$, let $M_{i',j'} = \{\discrete_1\discrete_2 \in \Omega_{\leq k}^2 \mid \evt(1,i') = \evt(2,j') \}$, and
	\[
	\glue i j (x,y) \eqdef x \psucc y \land \!\!\bigvee_{\discrete_1\discrete_2 \in M_{i,j}}\!\! \discrete_1(x) \land \discrete_2(y).
	\]
	Then $w \models_\nu \glue i j (x,y)$ if and only if $\nu(y) = \nu(x)+1$
	and $\evt(\nu(x),i) = \evt(\nu(y),j)$.
	We can then define $\newSim$ as a kind of reflexive transitive closure
	of these relations:
	\begin{multline*}
		(x,i) \newSim (y,j) \eqdef
		\forall X_1, \ldots, X_k.\, 
		\Big( x \in X_i \land \textstyle \bigwedge_{i,j \le k} \forall x,y.\, \\
		x \in X_i \land ((x,i) = (y,j) \lor \glue i j (x,y) \lor \glue j i (y,x)) \implies y \in X_j
		\Big)
		\implies y \in X_j,
	\end{multline*}
	where $(x,i) = (y,j)$ stands for the formula $x = y$ when $i = j$ and false otherwise.

	We rely on the formula $(x,i) \newSim (y,j)$ to define $(x,i) < (y,j)$ and $(x,i) \evord (y,j)$.

	Notice that given two events $e,e'$ in $P$,
	$e < e'$ iff for all $P_\ell$ and $P_{\ell'}$ in which $e$ and $e'$
	occur, we have $\ell < \ell'$. In other terms, iff for all $(\ell,i')$ and 
	$(\ell',j')$ such that $\evt(\ell,i') = e$ and $\evt(\ell',j') = e'$,
	we have $\ell < \ell'$. This can be expressed as follows:
	\[
	(x,i) < (y,j) \eqdef  \bigwedge_{1 \le i',j' \le k}\! \forall x',y'.
	\big( (x',i') \newSim (x,i) \land (y',j') \newSim (y,j) \big) \implies x' < y'.
	\]

	To define $(x,i) \evord (y,j)$, notice that $e \evord e'$ in $P$ when they appear 
	together in one $P_\ell$ in this order, that is, if there exists $\ell,i',j'$
	such that $i'$ is smaller than $j'$ and $\evt(\ell,i') = e$, $\evt(\ell,j') = e'$. This leads us to
	\[
	(x,i) \evord (y,j)
	\eqdef \bigvee_{1 \le i' < j' \le k}\! \exists z\, 
	(z,i') \newSim (x,i) \land (z,j') \newSim (y,j).
	\]

	For the unary predicates, we let
	\[
	a(x,i) \eqdef \bigvee_{\discrete \in \Omega_{a,i}} \discrete(x) \, ,
	\qquad
	\srci(x,i) \eqdef \bigvee_{\discrete \in \Omega_{\srci,i}} \discrete(x) \, ,
	\qquad
	\tgti(x,i) \eqdef \bigvee_{\discrete \in \Omega_{\tgti,i}} \discrete(x) \, ,
	\]
	where $\Omega_{a,i}$ (resp.~$\Omega_{\srci,i}$, resp.~$\Omega_{\tgti,i}$)
	is the (finite) set of all $\discrete \in \Omegaswb$ with events 
	$e_1 \evord \cdots \evord e_r$ such that $r \ge i$ and 
	$\lambda_D(e_i) = a$ (resp.~$e_i \in S_\discrete$, resp.~$e_i \in T_\discrete$).
\end{proof}

Let us now see how to use these base formulas in a translation
from $\MSOP$ to $\MSOW$ and prove Lemma~\ref{lem:msodec}.
As mentioned before, $\widehat{\phi}$ will be the conjunction of
$\texttt{Coh}_k$ and an $\MSOW$ formula $\phi'$ which we build
by induction on $\phi$.
Since we proceed by induction, we have to consider formulas $\phi$ that contain
free variables.
We construct $\phi'$ so that its free first-order variables are the same as $\phi$,
and it has second-order variables $X_1,\ldots,X_k$ for every free second-order 
variable $X$ of $\phi$.
In addition, every first-order variable of $\phi'$ is paired to some
$i \in \{1,\ldots,k\}$ by a function $\tau$, given as a parameter in the
translation.
Intuitively, we want to replace $x$ with the pair $(x,\tau(x))$, and $X$
with the union $\bigcup_{1 \le i \le k} \{(x,i) \mid x \in X_i\}$.
The next lemma expresses this more precisely, and Example~\ref{ex:msotohda}
illustrates it.

\begin{lemma}
	For every $\MSOP$ formula $\phi$ and function $\tau$ from
	the free first-order variables of $\phi$ to $\{1,\ldots,k\}$, one can construct
	a formula $\phi'_\tau \in \MSOW$ such that for every $w \in \Coh_{\le k}$
	and $P = \Psip(w)$, 
	\[
	P \models_\nu \phi \quad\text{if and only if}\quad
	w \models_{\nu'} \phi'_\tau
	\]
	for any valuations $\nu$ and $\nu'$ satisfying the following conditions:
	\begin{enumerate}
		\item $\evt(\nu'(x),\tau(x)) = \nu(x)$ and 
		\item $\bigcup_{1 \le i \le k} \{\evt(e,i) \mid e \in \nu'(X_i)\} 
		= \nu(X)$.
	\end{enumerate}
\end{lemma}

\begin{proof}
	We make use of the formulas from Lemma~\ref{lem:baserel}:
%	\aain{
%		Do we need $x = y$ atomic formula ? 
%		I think that $(x,i) \newSim (x,i)$ does not hold.
%	}
%	\mfin{Fixed the definition of $\newSim$, now it does.
%	But it's true that we don't really need it as $x=y$ is equivalent to
%	$x \not < y \land y \not < x \land x \not \evord y \land y \not \evord x$.}
	\begin{align*}
		(x = y)'_\tau & \eqdef (x,\tau(x)) \newSim (y,\tau(y)) \\
		(x < y)'_\tau & \eqdef (x,\tau(x)) < (y,\tau(y)) \\
		(x \evord y)'_\tau & \eqdef (x,\tau(x)) \evord (y,\tau(y)) \\
		a(x)'_\tau & \eqdef a(x,\tau(x)) \\
		\srci(x)'_\tau & \eqdef \srci(x,\tau(x)) \\
		\tgti(x)'_\tau & \eqdef \tgti(x,\tau(x)).
	\end{align*}	
	The function~$\tau$ emerges in the case $\phi = \exists x.\, \psi$,
	where we let
	\[
	\phi'_\tau \eqdef \bigvee_{1 \le i \le k} \exists x.\, \phidom(x,i) \land \psi'_{\tau[x \mapsto i]}.
	\]
	For the second-order part, we let
	\begin{align*}
		(\exists X.\, \psi)'_\tau
		& \eqdef \exists X_1,\ldots, X_k.\, \psi'_\tau \land \bigwedge_{1 \le i \le k} \forall x.\, x \in X_i \implies \phidom(x,i) \\
		(x \in X)'_\tau
		& \eqdef \bigvee_{1 \le j \le k} \exists y\, (x,\tau(x)) \newSim (y,j) \land y \in X_j.
	\end{align*}
	Finally, when $\phi$ is $\psi_1 \lor \psi_2$ or $\neg \psi$, then we let $\phi'$ be $\psi'_1 \lor \psi'_2$ or $\neg \psi'$, respectively.
\end{proof}



