We have now proven Lemma~\ref{lem:msodec}. The first assertion of Theorem~\ref{th:MSOeq} follows almost directly:
\begin{proposition}
	For every sentence $\phi \in \MSOP$ and every $k$, there exists
	a sentence $\widehat \phi \in \MSOW$ such that
	$L(\widehat \phi) = \Psip^{-1}(L(\phi)_{\le k})$.
\end{proposition}
\begin{proof}
	Let $L = \{w \in (\Omegaswb \setminus \{\id_\emptyset\})^+ \cap \Coh \mid \Psip(w) \models \phi \}$.
	By Lemma~\ref{lem:msodec}, we have $\widehat \phi' \in \MSOW$   such that $L = L(\widehat{\phi}')$.
	That is $L$ is a regular language of finite words.
	Thus $L' = (L \shuffle \id_\emptyset^\ast) \cap \Coh$
	and $L'' = L' \cup \id_\emptyset^\ast$ are effectively regular.
	(Here $L_1 \shuffle L_2$ denotes the shuffle of $L_1$ and $L_2$, that is, all interleavings of words in $L_1$ and $L_2$.)
	Finally, note that the question whether $\id_\emptyset \models \phi$ is decidable.
	We conclude by picking an $\MSOW$ sentence $\widehat{\phi}$ for $L'$ (if $\id_\emptyset \not \models \phi$) or $L''$ (if $\id_\emptyset \models \phi$) by the classical B\"uchi-Elgot-Trakhtenbrot theorem.
\end{proof}
As a consequence:
\begin{corollary}
	$\widehat \phi$ is $\sim$-invariant and $\widetildeL(\widehat \phi) = \Phi(L(\phi)_{\le k})$.
\end{corollary}

\subsection{From $\Coh_{\le k}$ to $\iiPoms_{\le k}$}\label{sec:HDAs-to-MSO}

In this section we prove the second assertion of Theorem~\ref{th:MSOeq}, claiming that there exists an $\MSOP$ sentence satisfied by the ipomsets obtained by gluing the sparse coherent words satisfying some $\MSOW$ sentence.

Our construction relies on the uniqueness of the sparse step decomposition (Lemma~\ref{le:ipomsparse}) $\bar\Phi(P)$, and the $\MSOP$-definability of the relations: ``event $x$ is started/terminated before event $y$ is started/terminated in $\bar\Phi(P)$" (Lemma~\ref{lem:compare} below).

More formally, let $P \in \iiPoms$ and $P_1 \ldots P_n = \bar\Phi (P)$.
Recall that this means that $P = P_1 \comp \cdots \comp P_n$ and $P_i$
alternates between starters and terminators.
Also recall the notation for starts and terminations of events of Section \ref{se:step-subsumptions}:
given $e \in P \setminus S_P$, $\xstart e$ is the (unique) step where $e$ is started in the decomposition.
% , \ie the minimal $i$ such that $e \in P_i$.
For $e \in P \setminus T_P$, $\xend e$ is the (unique) step where $e$ is terminated.
For $x\in S_P$, $\xstart x = -\infty$, and for $x\in T_P$, $\xend x = +\infty$.

\label{pg:xstart}

\begin{example}
	\label{ex:stend}
	\quad
	Proceeding with Example~\ref{ex:msotohda},
	let
	$w_2 = P_1\dots P_6=
	\loset{\hphantom{\ibullet} a \ibullet \\ \ibullet c \ibullet} 
	\loset{\ibullet a \ibullet \\ \ibullet c \hphantom{\ibullet}}
	\loset{\ibullet a \ibullet \\ \hphantom{\ibullet} d \ibullet}
	\loset{\ibullet a \hphantom{\ibullet}\\ \ibullet d \ibullet}$
	$\loset{\hphantom{\ibullet} a \ibullet \\ \ibullet d \ibullet}
	\loset{ \ibullet a \\ \ibullet d } = \bar\Phi(P)$ (see also Example~\ref{ex:paths}).
	We have $\xstart {e_3} = -\infty, \xstart {e_1} = 1, \xstart {e_4} = 3$ and $\xstart {e_2} = 5$.
	Also, $\xend {e_3} = 2, \xend {e_1} = 4$ and $\xend {e_2} = \xend {e_4} = 6$.
	Further, $P_1$ contains $e_1$ since $\xstart {e_1} = 1$ and $e_3$ because $\xstart {e_3} \le 1 \le \xend {e_3}$;
	$P_4$ contains $e_1$ since $\xend {e_1} =4$ and $e_4$ because $\xstart {e_4} \le 4 \le \xend {e_4}$. 
\end{example}

Our construction relies on the following observation:

\begin{remark}\label{rem:keyObs}
  When $P_1 \ldots P_n = \bar\Phi (P)$ for some $P \in \iiPoms \setminus \Id$,
  then each starter $P_i$ contains precisely all~$e \in P$ such that $\xstart e \le i < \xend e$.
  That is, all events which are started before, at $P_i$ or never started, and are terminated after $P_i$ or never terminated. 
  In particular, $P_i$ starts all $e$ such that $\xstart e = i$.
  When it is a terminator, $P_i$ contains precisely all~$e \in P$ such that $\xstart e < i \le \xend e$, and terminates all $e$ such that $\xend e = i$.
  Note that $\xstart e<\xend e$ for all $e\in P$.
\end{remark}

These relations are $\MSOP$-definable. We first encode in the following lemma some of them:
\begin{lemma}
	\label{lem:compare}
	For $f,g \in \{\xst,\xen\}$ and ${\bowtie} \in \{{<}, {>}\}$,
	the relations $f(x) \bowtie g(y)$ are $\MSOP$-definable.
\end{lemma}

\begin{proof}
	We first define $\xend x < \xstart y$ as the formula $x < y$, together with
	$\xstart x < \xend y \eqdef \lnot (\xend y < \xstart x)$.
	Because starters and terminators alternate in the sparse step decomposition,
	we can then let
	\begin{align*}
		\xstart x < \xstart y
		& \eqdef  \big(\srci(x) \land \lnot \srci(y)\big) \lor
		\big(\exists z.\, \xstart x < \xend z \land \xend z < \xstart y\big) \\
		\xend x < \xend y
		& \eqdef \big(\tgti (y) \land \lnot \tgti (x)\big) \lor  \big(\exists z.\, \xend x < \xstart z \land \xstart z < \xend y\big)
	\end{align*}
	where $\srci(x) \land \lnot \srci(y)$  notably holds when both $x$ and $y$ are minimal in an ipomset $P$, and $y$ is started while $x$ is a source.
	Similarly  $\tgti (y) \land \lnot \tgti (x)$ holds in particular when both $x$ and $y$ are maximal, $x$ is terminated while $y$ is a target. 
%	For $=$, we have:
%	\begin{align*}
%		\xstart x = \xstart y
%		& \eqdef \lnot (\xstart x < \xstart y) \land \lnot (\xstart y  < \xstart x) \land \lnot \srci(x) \land \lnot \srci(y) \\
%		\xend x = \xend y
%		& \eqdef \lnot (\xend x < \xend y) \land \lnot (\xend y  < \xend x) \land \lnot \tgti(x) \land \lnot \tgti(y) \, .
%	\end{align*}
\end{proof}

