	observe that $P \models \xstart {e_3} <  \xstart {e_1}$ even if $e_3$ and $e_1$ are minimal and both occur in $P_1$.
	We have also that $P \not\models \xstart {e_1} <  \xstart {e_3}$, $P \models \xstart {e_1} <  \xstart {e_2}$, $P \not\models \xend {e_2} <  \xend {e_4}$ and $P \models \xend {e_3} <  \xend {e_4}$.	
	Observe that $P\models \xstart {e_1} < \xend {e}$ for all $e \in P$.
\end{example}
%}{changed!}

Then, using Lemma~\ref{lem:compare}, one can encode each step of $\Phip(P)$ with $\MSOP$: 
\begin{lemma}\label{lem:StTe(x)Def}
	For all $D \in \Omegaswb \setminus \Id$, there are $\MSOP$-formulas $D_\xst(x)$ and $D_\xen(x)$
	such that for all $P \in \iiPoms_{\le k}$ with $P_1 \ldots P_n = \Phip (P)$
	and valuations $\nu(x) = e \in P$, we have
	\begin{itemize}
		\item $P \models_\nu D_\xst(x)$ if and only if $\xstart e \neq - \infty$ and $P_{\xstart e} = D$;
		\item $P \models_\nu D_\xen(x)$ if and only if $\xend e \neq + \infty$ and $P_{\xend e} = D$.
	\end{itemize}
\end{lemma}

\begin{proof}
	We give the definition of $D_\xst(x)$, the one for $D_\xen(x)$
	is similar.
	We obviously set $D_\xst(x) \eqdef \bot$ when $D \notin \St_+$.
	Now assume $D \in \St_+$.
	Let $d_1 \evord \cdots \evord d_\ell$ the events in~$D$, and $a_i$
	the label of $d_i$.
	We first define a formula $\phi(x,x_1,\ldots,x_\ell)$ which is true when
	$x_1,\ldots,x_\ell$ are precisely the events occurring in the $\xstart x^{\text{th}}$ step of $\Phip(P)$ (see Remark~\ref{rem:keyObs}):
%	\[
%	\phi(x,x_1,\ldots,x_\ell) \eqdef
%	\lnot \srci(x) \land \forall y.
%	\Big( \xstart y \le \xstart x < \xend y \Big) \iff
%	\left( \bigvee_{1 \le i \le \ell} y = x_i \right) \, .
%	\]
	\begin{multline*}
          \qquad
          \phi(x,x_1,\ldots,x_\ell) \eqdef {} \\
          \lnot \srci(x) \land \forall y.
          \Big( \lnot (\xstart x < \xstart y) \land (\xstart x < \xend y) \Big) \iff
          % \left(
          \bigvee_{1 \le i \le \ell} y = x_i
          % \right)
          .
          \qquad
	\end{multline*}
%}
	Note that the condition $\lnot \srci(x)$ is here to ensure that $\xstart x \neq -\infty$.
	Note also that, given that $D$ is a starter, for any $i$, $d_i \in T_D$.
	We also need to ensure that sources of $D$ are preserved, \ie to know among $x_1,\dots,x_\ell$ which ones are started strictly before $x$.
	For all $i \in \{1,\ldots,\ell\}$, we let
%	\[
%	\psi_i(x,y) \eqdef
%	\begin{cases}
%		\xstart  y = \xstart x & \text{if } d_i \in T_D \setminus S_D \\
%		\xstart y < \xstart x < \xend y & \text{otherwise}
%	\end{cases}
%	\]
%	\mfin{Version without = (and removing the redundancy with the previous formula)
	\[
	\psi_i(x,y) \eqdef
	\begin{cases}
	\xstart y < \xstart x & \text{if } d_i \in S_D \\
	\lnot (\xstart y < \xstart x )& \text{otherwise }
	\end{cases}
	\]
%	}
	Then, we use these formulas to specify which events should be started 
	together with $x$ in $D$ or not.
	We then define
	\[
	D_\xst(x) \eqdef
	\exists x_1, \ldots, x_\ell.\, 
	\phi(x,x_1,\ldots,x_\ell) \land
	\bigwedge_{1 \le i \le \ell} a_i(x_i) \land \psi_i(x,x_i) \land
	\bigwedge_{1 \le i < \ell} x_i \evord x_{i+1}.
	\] 
\end{proof}


The following lemma proves the second part of Theorem~\ref{th:MSOeq} when identities are not taken into account.

\begin{lemma}\label{prop:WtoPlabels}
	For every sentence $\phi \in \MSOW$,
	there exists a sentence $\overline \phi \in \MSOP$ 
	such that $L(\overline \phi) \cap \iiPoms_{\le k} \setminus \Id= \Psip(L(\phi) \cap \SCoh \setminus \Id)$.
\end{lemma}

\begin{proof}
	The key idea is that, given a sparse step decomposition
	$w = P_1 \dots P_n \in \Omegaswb^+ \setminus \Id$, every $P_i$ within $w$ contains some event $e$ which is either started or terminated in $P = \Psip(w)$.
	Thus, we associate to every position $i \in \{1,\ldots ,n\}$  a pair $(e,b)$ where $e \in P$ and $b \in \{\xst,\xen\}$ indicates whether we are looking for a starter or a terminator.
	The other events of $P$ are captured by the formulas of Lemma~\ref{lem:StTe(x)Def} and the other conditions are obtained inductively.


	More formally, we proceed similarly to the translation in the previous section.
	For every function $\tau$ from free first-order variables to $\{\xst,\xen\}$ 
	and every $\MSOW$ formula $\phi$, 
	we define $\overline \phi_\tau$ as follows:
	\begin{align*}
		\overline{\exists x.\, \phi}_\tau
		& := (\exists x.\, \lnot \srci(x) \land \overline{\phi}_{\tau[x \mapsto \xst]}) \lor 
		(\exists x.\, \lnot \tgti(x) \land \overline{\phi}_{\tau[x \mapsto \xen]}) \\
		\overline {x < y}_\tau
		& := \tau(x)(x) < \tau(y)(y) \quad \text{(see Lemma~\ref{lem:compare})} \\
		\overline {P(x)}_\tau
		& := P_{\tau(x)}(x) \quad \text{(see Lemma~\ref{lem:StTe(x)Def})} \\
		\overline{\exists X.\, \phi}_\tau
		& := \exists X_\xst, X_\xen. \, (\forall x.\, x \in X_\xst \implies \lnot \srci(x)) \land (\forall x.\, x \in X_\xen \implies \lnot \tgti(x)) \land \overline{\phi}_\tau \\
		\overline{x \in X}_\tau & := x \in X_{\tau(x)} \\
		\overline{\phi \lor \psi}_\tau & := \overline{\phi}_\tau \lor \overline{\psi}_\tau \\
		\overline{\lnot \phi}_\tau & := \lnot \overline{\phi}_\tau.
	\end{align*}
\end{proof}

Again, the second assertion of Theorem~\ref{th:MSOeq} follows almost directly:
\begin{proposition}
	For every sentence $\phi \in \MSOW$,
	there exists a sentence $\overline \phi \in \MSOP$
	such that $L(\overline \phi) = \Psip(L(\phi) \cap \SCoh)$.
\end{proposition}
\begin{proof}
	Recall that the sparse step decomposition of an identity is the identity itself.
	In addition, it is decidable whether an identity satisfies $\phi$ and there are finitely many identities in $\Omegaswb$.
	Moreover, identities are trivially $\MSOP$-definable.
	%Thus $\overline{\phi}$ is the disjunction of the $\MSOP$ formula from Lemma~\ref{prop:WtoPlabels} with the $\MSOP$ formulas that hold for the identities satisfying $\phi$.
	Let $\psi_1$ be the disjunction of the $\MSOP$ formulas that hold for the identities satisfying $\phi$, and $\psi_2$ the formula obtained from Lemma~\ref{prop:WtoPlabels}.
	Notice that Lemma~\ref{prop:WtoPlabels} doesn't specify what $\psi_2$ evaluates to on identities or on ipomsets of width $> k$, so it could be satisfied by ipomsets that we want to exclude.
	However, the set $\iiPoms_{\le k} \setminus \Id$ is easily definable in $\MSOP$ by
	\[
		\psi_3 \eqdef (\exists x. \lnot \srci(x) \lor \lnot \tgti(x)) \land \forall x_1,\ldots, x_{k+1}.\, 
		\bigvee_{1 \le i,j \le k+1} x_i < x_j.
	\]
	We then let $\overline \phi = \psi_1 \lor (\psi_2 \land \psi_3)$.
\end{proof}
In addition, as an immediate corollary, we have:
\begin{corollary}
	For every $\sim$-invariant sentence $\phi \in \MSOW$, 
	$L(\overline \phi) = \Psip(L(\phi) \cap \Coh) = \Psi(\widetilde L(\phi))$.
\end{corollary}

\subsection{A B\"uchi-Elgot-\!Trakhtenbrot theorem}
\label{sec:buchi}



Recall that  languages of HDAs have bounded width and are closed
under subsumption, unlike $\MSOP$-definable languages (see Example~\ref{ex:notwb}).
Therefore, we can only translate an $\MSOP$ formula into
an equivalent HDA if it has these two properties.
We have the following.

\begin{theorem}
	\label{th:main}
	Let $L \subseteq \iiPoms$.
	\begin{enumerate}
        \item If $L$ is $\MSOP$-definable, then $L_{\le k}\down$ is regular for all $k \in \Nat$.
        \item If $L$ is regular, then it is $\MSOP$-definable. 
	\end{enumerate}
	Moreover, the constructions are effective in both directions.
\end{theorem}

\begin{proof}
	Assume that $L$ is $\MSOP$-definable.
	Then by Theorem~\ref{th:MSOeq}, $\Psi^{-1}(L_{\le k})$ is also 
	$\MSOW$-definable.
	By the standard B\"uchi-Elgot-Trakhtenbrot and Kleene theorems,
	we can construct a rational expression $E$ over $\Omegaswb$ such
	that $L(E) = \Psi^{-1}(L_{\le k})$.
	By replacing concatenation of words by gluing composition in $E$ (see \cite[Proposition~21]{DBLP:journals/lmcs/FahrenbergJSZ24} or \cite[Lemmas~28-31]{DBLP:journals/corr/abs-2503-07881} for a detailed construction),
	we get that $L_{\le k}\down$ is rational and thus effectively regular by 
	Theorem~\ref{th:kleene}.

