\subsection{Frobenius-norm-based Estimation (Fro-CVX)}
\label{subsect:Fro-CVX_3D}
In addition to the TT algorithm, Fro-CVX represents another widely-adopted approach for sensor network localization. This method transforms the localization problem into a convex optimization framework based on the Frobenius norm \cite{cao_sensor_2006,so_theory_2007,cao_formation_2011}. 

Consider $n$ points $\boldsymbol{p}_i\in\mathbb{R}^3,i=1,\ldots,n$. Denote the position matrix $P\in\mathbb{R}^{3\times n}$ of the points as 
\begin{equation}
P=\begin{bmatrix} \boldsymbol{p}_1 & \boldsymbol{p}_2 & \cdots & \boldsymbol{p}_n \end{bmatrix},
\label{eq:PositionMatrix_3D}
\end{equation} the estimated position matrix $\hat{Q}\in\mathbb{R}^{3\times n}$ as 
\begin{equation}
\hat{P}=\begin{bmatrix} \boldsymbol{\hat{p}}_1 & \boldsymbol{\hat{p}}_2 & \cdots & \boldsymbol{\hat{p}}_n \end{bmatrix},
\label{eq:EstimatedPositionMatrix_3D}
\end{equation} and the corresponding EDM $E\in\mathbb{R}^{n\times n}$ as 
\begin{equation}
[E_{P}]_{(i,j)}=\|\boldsymbol{p}_i-\boldsymbol{p}_j\|^2=\boldsymbol{p}_{i}^{\top}\boldsymbol{p}_i-2\boldsymbol{p}_{i}^{\top}\boldsymbol{p}_{j}+\boldsymbol{p}_{j}^{\top}\boldsymbol{p}_j,
\label{eq:EDM_3D}
\end{equation} where $[E_{P}]_{(i,j)}$ is the $(i,j)$-th element of $E_{P}$ \cite{dattorro_convex_2019}. 
%Obviously, $E$ is a nonnegative symmetric matrix. 

To localize a sensor $T$ with four sensors on agent $A$, we have the measured distance matrix and the real EDM of the target in the form 
        % \begin{equation}
        $$\hat{E}_{P_T}=\begin{bmatrix}
          F_{P} & \hat{\boldsymbol{e}}_{Q} \\ \hat{\boldsymbol{e}}_{Q}^{\top} & 0
        \end{bmatrix},
        E_{P_T}(\boldsymbol{p}_T)=\begin{bmatrix}
          F_{P} & \boldsymbol{e}_{Q}(\boldsymbol{p}_T) \\ \boldsymbol{e}_{Q}^{\top}(\boldsymbol{p}_T) & 0
        \end{bmatrix},$$
        % \label{eq:DM_Point_3D}
        % \end{equation}
        where $$\hat{\boldsymbol{e}}_{Q}=\begin{bmatrix}
        \hat{d}_{A_1T}^2 & \hat{d}_{A_2T}^2 & \hat{d}_{A_3T}^2 & \hat{d}_{A_4T}^2 \end{bmatrix}^{\top},$$
        $${\boldsymbol{e}_{Q}}(\boldsymbol{p}_T)=\begin{bmatrix}
        {d}_{A_1T}^2 (\boldsymbol{p}_T) & d_{A_2T}^2 (\boldsymbol{p}_T) & d_{A_3T}^2 (\boldsymbol{p}_T) & d_{A_4T}^2 (\boldsymbol{p}_T) \end{bmatrix}^{\top}$$ 
        are respectively from the measurement and from the real distance function with $d_{A_iT}(\boldsymbol{p}_T)$ defined in Eq. (\ref{eq:d_AiT_3D}). $F_{P}$ is known \textit{a priori} from the sensor configuration as  
    \begin{equation}
F_{P}=\begin{bmatrix}0&d_{12}^2&d_{13}^2&d_{14}^2\\d_{21}^2&0&d_{23}^2&d_{24}^2\\d_{31}^2&d_{32}^2&0&d_{34}^2\\d_{41}^2&d_{42}^2&d_{43}^2&0\end{bmatrix},
    \label{eq:F_P}
    \end{equation}

        with $d_{ij}=\|\boldsymbol{p}_i-\boldsymbol{p}_j\|,i,j=1,\ldots,4$.

To localize an agent $B$, we have the measured distance matrix and the real EDM of the target agent in the form 
    % \begin{equation}
    $$\hat{E}_{P_B}=\begin{bmatrix} F_{P} & \hat{E}_{P,AB} \\ \hat{E}_{P,AB}^{\top} & F_{P} \end{bmatrix},$$
    % \label{eq:DM_Agent_3D}
    % \end{equation}
    and 
    % \begin{equation}
    $$E_{P_B}(\boldsymbol{\beta}_B)=\begin{bmatrix} F_{P} & E_{P,AB}(\boldsymbol{\beta}_B) \\ E_{P,AB}^{\top}(\boldsymbol{\beta}_B) & F_{P} \end{bmatrix},$$
    % \label{eq:E_QII_betaB_3D}
    % \end{equation}
    where the (i,j)-th element of $\hat{E}_{P,AB}$ is $\hat{E}_{P,AB}(i,j)=\hat{d}_{A_iB_j}^2$ from the measurement and the (i,j)-th element of $E_{P,AB}(\boldsymbol{\beta}_B)$ is $E_{P,AB}(\boldsymbol{\beta}_B)(i,j)=d_{A_iB_j}^2 (\boldsymbol{\beta}_B)$ from the real distance function with $d_{A_{i}B_{j}}(\boldsymbol{\beta}_{{B}})=\|\boldsymbol{p}_{A_i}-\boldsymbol{p}_{B_j}(\boldsymbol{\beta}_{{B}})\|,i,j=1,2,3,4$. $F_{P}$ is defined in Eq. (\ref{eq:F_P}) and $\boldsymbol{p}_{B_j}(\boldsymbol{\beta}_{{B}})$ defined in Eq. (\ref{eq:q_Bj_3D}).
    % $$\hat{E}_{P,AB}=\begin{bmatrix}
