    % {d}_{A_2B_1}^2 (\boldsymbol{\beta}_B) & {d}_{A_2B_2}^2 (\boldsymbol{\beta}_B) & {d}_{A_2B_3}^2 (\boldsymbol{\beta}_B) & {d}_{A_2B_4}^2 (\boldsymbol{\beta}_B) \\ 
