\boldsymbol{\hat{\beta}}_B=\arg\min\limits_{\boldsymbol{\beta}_B}\sum\limits_{i,j\in\{1,2,3,4\}}\left(\hat{d}_{A_iB_j}^2-d_{A_iB_j}^2(\boldsymbol{\beta}_{{B}})\right)^2.
 \label{eq:Fro-CVX_Case_II_3D_equi}
