Let $G^{0}_{P}=(P^{0})^{\top} P^{0}$ and denote the first column of $E_{P}$ as $\boldsymbol{e}_{P,1}$. Since $[G^{0}_{P}]_{(i,i)}=\|\boldsymbol{p}^{0}_{i}\|^2=[E_{P}]_{(i,1)}$, we obtain $\boldsymbol{e}_{P,1}=\mathrm{diag}(G_{P}^0)$. From Eq. (\ref{eq:G_EDM_3D}), we can derive:

\begin{equation}
 G^{0}_{P}=(P^{0})^{\top} P^{0}=-\frac{1}{2}(E_{P}-\mathbf{1}\boldsymbol{e}_{P,1}^{\top}-\boldsymbol{e}_{P,1}\mathbf{1}^{\top}).
 \label{eq:G^0_3D}
 \end{equation} 

Given that $G^{0}_{P}$ is positive semi-definite, we can solve for $P^{0}$ using eigenvalue decomposition \cite{strang_linear_2019}:

\begin{equation}
\begin{aligned}
G^{0}_{P} &= \begin{bmatrix} U_{1}^{0\top} & U_{2}^{0\top}\end{bmatrix} \mathrm{diag}(\Lambda_{3},0_{n-3}) \begin{bmatrix} U_{1}^0 \\ U_{2}^0\end{bmatrix} \\
&= \begin{bmatrix} \Lambda_{3}^{\frac{1}{2}}U_{1}^0\end{bmatrix}^{\top} \begin{bmatrix} \Lambda_{3}^{\frac{1}{2}}U_{1}^0\end{bmatrix}=(P^{0})^{\top}P^{0},
\end{aligned}
\label{eq:P^{0}_3D}
\end{equation}
