The proposed methodology is systematically formalized through two dedicated algorithms:
\begin{itemize}
    \item Algorithm \ref{alg:EDM_basedPoint_3D}: EDMT implementation for individual sensor localization.
    \item Algorithm \ref{alg:EDM_basedAgent_3D}: EDMT-jointly framework for integrated agent localization.
\end{itemize}
% We summarize our proposed EDMT to localize a sensor and EDMT-jointly to localize an agent in the following Algorithm \ref{alg:EDM_basedPoint_3D} and Algorithm \ref{alg:EDM_basedAgent_3D}, respectively. 


\begin{algorithm}
\caption{3D EDMT for sensor localization}
\label{alg:EDM_basedPoint_3D}
\begin{algorithmic}
\Require {Sensor configuration $\boldsymbol{p}_{A_i}=\boldsymbol{p}_{i}$, measured distances $\hat{d}_{A_iT}$, where $i=1,\ldots,4$ }
\Ensure {The estimate $\boldsymbol{\hat{p}}_{T}$ of ${\boldsymbol{p}}_{T}$}
\State $[\hat{E}]_{(k,k)} \gets 0,k=1,\ldots,5$
\State $[\hat{E}]_{(i,j)} \gets \|\boldsymbol{p}_i-\boldsymbol{p}_j\|^2,i,j=1,2,3,4,i\neq j$
\State $[\hat{E}]_{(i,5)} \gets \hat{d}_{A_T}^2,i=1,\ldots,5$
\State $[\hat{E}]_{(5,j)} \gets \hat{d}_{A_jT}^2,j=1,\ldots,5$
\State $P_A\gets\begin{bmatrix} \boldsymbol{p}_{A_1} & \boldsymbol{p}_{A_2} & \boldsymbol{p}_{A_3}& \boldsymbol{p}_{A_4}\end{bmatrix}$\;

\If{$\hat{E}\notin \mathbb{EDM}^{5}$ or $\mathrm{rank}(-V^{\top}\hat{E}V)> 3$, where $V=I-\frac{1}{5}\mathbf{1}\mathbf{1}^{\top}$}
  \State {diagonal decomposition: $$-V^{\top}\hat{E}V=T\mathrm{diag}(\lambda_1,\lambda_2,\lambda_3,\lambda_4,\lambda_5)T^{\top}$$, where $T$ is orthogonal, $\lambda_1\geq\lambda_2\geq\lambda_3\geq\lambda_4\geq\lambda_5$\;
  \State $B=T\mathrm{diag}(\lambda_1^{+},\lambda_2^{+},\lambda_3^{+},0,0)T^{\top}$, where $\lambda_1^{+}= \max\{\lambda_1,0\},\lambda_2^{+}= \max\{\lambda_2,0\},\lambda_3^{+}= \max\{\lambda_3,0\}$\;
  \State $E=-(B-\boldsymbol{b}\mathbf{1}^{\top}-\mathbf{1}\boldsymbol{b}^{\top}),\boldsymbol{b}=\frac{1}{2}\mathrm{diag}(B)$\;}
\Else 
  {\ $E=\hat{E}$\;}
\EndIf
\State $G^{0}=-\frac{1}{2}(E-\mathbf{1}\boldsymbol{e}_1^{\top}-\boldsymbol{e}_1\mathbf{1}^{\top})$\; 
\State Eigenvalue decomposition of $G^{0}$: $G^{0}=\begin{bmatrix}U_1^{0\top} & U_2^{0\top}\end{bmatrix}\mathrm{diag}(\Lambda_2,0_2)\begin{bmatrix}U_1^{0\top} & U_2^{0\top}\end{bmatrix}^{\top}$\; 
\State Compute the special position matrix: $P^{0}=\Lambda_{2}^{\frac{1}{2}}U_1^0=\begin{bmatrix}\boldsymbol{p}_1^0 & \boldsymbol{p}_2^0 & \boldsymbol{p}_3^0 & \boldsymbol{p}_4^0 & \boldsymbol{p}_5^0\end{bmatrix}$\; 
\State Compute the translation vector: $\boldsymbol{t}=\frac{1}{4}\sum_{i=1}^{4}(\boldsymbol{p}_i^0-\boldsymbol{p}_i)$\; 
\State Compute the translated position matrix: $Q^1=P^{0}-\boldsymbol{t}\mathbf{1}_5^{\top}=\begin{bmatrix}\boldsymbol{p}_1^1 & \boldsymbol{p}_2^1 & \boldsymbol{p}_3^1 & \boldsymbol{p}_4^1 & \boldsymbol{p}_5^1\end{bmatrix}$\; 
\State Compute the rotation matrix: $\mathbf{R}_1=V_1U_1^{\top}$, where $U_1,V_1$ are from the SVD $P_A\begin{bmatrix}\boldsymbol{p}_1^1 & \boldsymbol{p}_2^1 & \boldsymbol{p}_3^1 & \boldsymbol{p}_4^1 \end{bmatrix}^{\top}=U_1S_1V_1^{\top}$\; 
\State Compute the target position: $\boldsymbol{\hat{p}}_{T}=\mathbf{R}_1\boldsymbol{p}^{1}_{5}$.
\end{algorithmic}
\end{algorithm}

\begin{algorithm}
\caption{3D EDMT-jointly for agent localization}
\label{alg:EDM_basedAgent_3D}
\begin{algorithmic}
\Require {Sensor configuration $\boldsymbol{p}_{A_i}=\boldsymbol{p}_{i},i=1,\ldots,4$, measured distances $\hat{d}_{A_iB_j},i,j=1,\ldots,4$ }
\Ensure {The estimate $\boldsymbol{\hat{p}}_{B_j}$ of ${\boldsymbol{p}}_{B_j},j=1,\ldots,4$, the estimate $\boldsymbol{\hat{p}}_{B}$ of centroid ${\boldsymbol{p}}_{B}$, and the estimate $\hat{\theta}_{B}$ of ${\theta}_{B}$}
\State $[\hat{E}]_{(k,k)} \gets 0,k=1,\ldots,8$
\State $[\hat{E}]_{(i,j)}\gets\|\boldsymbol{p}_i-\boldsymbol{p}_j\|^2,i,j=1,\ldots,4$ 
\State $[\hat{E}]_{(4+i,4+j)} \gets \|\boldsymbol{p}_i-\boldsymbol{p}_j\|^2,i,j=1,\ldots,4$
\State $[\hat{E}]_{(i,4+j)}\gets\hat{d}_{A_iB_j}^2,i,j=1,\ldots,4$ 
\State $[\hat{E}]_{(4+j,i)}\gets\hat{d}_{A_iB_j}^2,i,j=1,\ldots,4$

\State $P_A \gets \begin{bmatrix} \boldsymbol{p}_{A_1} & \boldsymbol{p}_{A_2} & \boldsymbol{p}_{A_3}\end{bmatrix}$\;

\If{$\hat{E}\notin \mathbb{EDM}^{8}$ or $\mathrm{rank}(-V^{\top}\hat{E}V)> 3$, where $V=I-\frac{1}{8}\mathbf{1}\mathbf{1}^{\top}$}
  \State {diagonal decomposition: $-V^{\top}\hat{E}V=T\mathrm{diag}(\lambda_1,\lambda_2,\ldots,\lambda_8)T^{\top}$, where $T$ is orthogonal, $\lambda_1\geq\lambda_2\geq\ldots\geq\lambda_8$\;
  \State $B=T\mathrm{diag}(\lambda_1^{+},\lambda_2^{+},\lambda_3^{+},0,0)T^{\top}$, where $\lambda_1^{+}= \max\{\lambda_1,0\},\lambda_2^{+}= \max\{\lambda_2,0\},\lambda_3^{+}= \max\{\lambda_3,0\}$\;
  \State $E=-(B-\boldsymbol{b}\mathbf{1}^{\top}-\mathbf{1}\boldsymbol{b}^{\top}),\boldsymbol{b}=\frac{1}{2}\mathrm{diag}(B)$\;}
\Else 
  {\ $E=\hat{E}$\;}
\EndIf
\State $G^{0}=-\frac{1}{2}(E-\mathbf{1}\boldsymbol{e}_1^{\top}-\boldsymbol{e}_1\mathbf{1}^{\top})$\; 
\State Eigenvalue decomposition of $G^{0}$: $G^{0}=\begin{bmatrix}U_1^{0\top} & U_2^{0\top}\end{bmatrix}\mathrm{diag}(\Lambda_2,0_4)\begin{bmatrix}U_1^{0\top} & U_2^{0\top}\end{bmatrix}^{\top}$\; 
\State Compute the special position matrix: $P^{0}=\Lambda_{3}^{\frac{1}{2}}U_1^0=\begin{bmatrix}\boldsymbol{p}_1^0 & \boldsymbol{p}_2^0 & \cdots & \boldsymbol{p}_8^0\end{bmatrix}$\; 
\State Compute the translation vector: $\boldsymbol{t}=\frac{1}{4}\sum_{i=1}^{4}(\boldsymbol{p}_i^0-\boldsymbol{p}_i)$\; 
\State Compute the translated position matrix: $Q^1=P^{0}-\boldsymbol{t}\mathbf{1}_8^{\top}=\begin{bmatrix}\boldsymbol{p}_1^1 & \boldsymbol{p}_2^1 & \cdots & \boldsymbol{p}_8^1\end{bmatrix}$\; 
\State Compute the rotation matrix: $\mathbf{R}_1=V_1U_1^{\top}$, where $U_1,V_1$ are from the SVD $P_A\begin{bmatrix}\boldsymbol{p}_1^1 & \boldsymbol{p}_2^1 & \boldsymbol{p}_3^1 \end{bmatrix}^{\top}=U_1S_1V_1^{\top}$\; 
\State Compute the target agent vertexes: $\boldsymbol{\hat{p}}_{B_1}=\mathbf{R}_1{\boldsymbol{p}}^{1}_{5}$, $\boldsymbol{\hat{p}}_{B_2}=\mathbf{R}_1{\boldsymbol{p}}^{1}_{6}$, $\boldsymbol{\hat{p}}_{B_3}=\mathbf{R}_1{\boldsymbol{p}}^{1}_{7}$, and $\boldsymbol{\hat{p}}_{B_4}=\mathbf{R}_1{\boldsymbol{p}}^{1}_{8}$, the position matrix $\hat{Q}_B=\begin{bmatrix}\boldsymbol{\hat{p}}_{B_1} & \boldsymbol{\hat{p}}_{B_2} & \boldsymbol{\hat{p}}_{B_3} & \boldsymbol{\hat{p}}_{B_4}\end{bmatrix}$, the target centroid $\boldsymbol{\hat{p}}_{B}=\frac{1}{4}\sum_{i=1}^{4}(\boldsymbol{\hat{p}}_{B_i})$\; 
\State Compute the target yaw, pitch, and roll angles: $\hat{\psi}_B=\arctan\frac{-\mathbf{R}_{12}}{\mathbf{R}_{11}},\hat{\theta}=\arctan\frac{\mathbf{R}_{13}}{\mathbf{R}_{23}^2+\mathbf{R}_{33}^2}, \hat{\gamma}=\arctan\frac{-\mathbf{R}_{23}}{\mathbf{R}_{33}}$, where $\mathbf{R}=V_2U_2^{\top}$, $V_2,U_2$ are from the SVD $P_A(\hat{Q}_B-\boldsymbol{\hat{p}}_{B}\mathbf{1}^{\top})^{\top}=U_2S_2V_2^{\top}$\;
\end{algorithmic}
\end{algorithm}

